// V30: Large UI/localisation data lives beside the EXE instead of inside the
// monolithic Go source. This reduces main.go parsing/type-checking work on every update.
func staticAssetSearchPaths(name string) []string {
	seen := map[string]bool{}
	paths := make([]string, 0, 2)
	if exe, err := os.Executable(); err == nil {
		if abs, err := filepath.Abs(exe); err == nil {
			p := filepath.Join(filepath.Dir(abs), name)
			seen[strings.ToLower(filepath.Clean(p))] = true
			paths = append(paths, p)
		}
	}
	if wd, err := os.Getwd(); err == nil {
		p := filepath.Join(wd, name)
		key := strings.ToLower(filepath.Clean(p))
		if !seen[key] {
			paths = append(paths, p)
		}
	}
	return paths
}

func loadStaticStringMap(name string) map[string]string {
	for _, path := range staticAssetSearchPaths(name) {
		data, err := os.ReadFile(path)
		if err != nil || len(data) == 0 {
			continue
		}
		out := map[string]string{}
		if json.Unmarshal(data, &out) == nil && len(out) > 0 {
			return out
		}
	}
	return map[string]string{}
}

