type savedBotSchedules struct {
	Cron1     savedCron                  `json:"cron1"`
	Cron2     savedCron                  `json:"cron2"`
	Transport savedTransportScheduleV183 `json:"transport,omitempty"`
}

func scheduleConfigPath() string {
	return filepath.Join(botDataDir, "schedules.json")
}

func loadBotScheduleConfig(id int) (savedBotSchedules, bool) {
	// V411: SQLite is the authoritative scheduler store. schedules.json is read only
	// as a one-time migration source for older builds.
	if db, err := suiteOpenStateDB(); err == nil && db != nil {
		var raw string
		if err := db.QueryRow(`SELECT schedule_json FROM bot_schedules WHERE bot_id=?`, id).Scan(&raw); err == nil {
			var cfg savedBotSchedules
			if json.Unmarshal([]byte(raw), &cfg) == nil {
				return cfg, true
			}
		}
	}

	scheduleFileMu.Lock()
	defer scheduleFileMu.Unlock()
	data, err := os.ReadFile(scheduleConfigPath())
	if err != nil {
		return savedBotSchedules{}, false
	}
	all := map[string]savedBotSchedules{}
	if json.Unmarshal(data, &all) != nil {
		return savedBotSchedules{}, false
	}
	cfg, ok := all[strconv.Itoa(id)]
	return cfg, ok
}

func saveAllScheduleConfigs() error {
	// One writer owns the complete multi-BOT snapshot. The snapshot is committed in
	// one SQLite transaction so scheduler state, run counters, due time and transfer
	// safety ledger cannot be torn across independent JSON writes.
	scheduleFileMu.Lock()
	defer scheduleFileMu.Unlock()

	sessionMu.RLock()
	bots := make([]*BotSession, 0, len(sessions))
	for _, bot := range sessions {
		bots = append(bots, bot)
	}
	sessionMu.RUnlock()

	all := make(map[int]savedBotSchedules, len(bots))
	for _, bot := range bots {
		bot.mu.Lock()
		all[bot.ID] = savedBotSchedules{
			Cron1: savedCron{
				Interval: bot.CronInterval, MaxRuns: bot.CronMaxRuns, Command: bot.CronCommand,
				Running: bot.CronRunning, RunCount: bot.CronRunCount, NextDue: bot.CronNextDue,
			},
			Cron2: savedCron{
				Interval: bot.Cron2Interval, MaxRuns: bot.Cron2MaxRuns, Command: bot.Cron2Command,
				Running: bot.Cron2Running, RunCount: bot.Cron2RunCount, NextDue: bot.Cron2NextDue,
			},
			Transport: savedTransportScheduleV183{
				Interval: bot.TransferInterval, MaxRuns: bot.TransferMaxRuns,
				SourceCommand: bot.TransferSourceCommand, DestinationCommand: bot.TransferDestinationCommand,
				SourceBox: bot.TransferSourceBox, SourceBoxConfigured: bot.TransferSourceBoxConfigured,
				DestinationBox: bot.TransferDestinationBox, DestinationBoxConfigured: bot.TransferDestinationBoxConfigured,
				Pending: transportCopyBatchV183(bot.TransferPending), PendingTotal: bot.TransferPendingTotal,
				Running: bot.TransferRunning, RunCount: bot.TransferRunCount, NextDue: bot.TransferNextDue,
			},
		}
		bot.mu.Unlock()
	}

	db, err := suiteOpenStateDB()
	if err != nil {
		return err
	}
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	rollback := true
	defer func() {
		if rollback {
			_ = tx.Rollback()
		}
	}()
	for botID, cfg := range all {
		raw, err := json.Marshal(cfg)
		if err != nil {
			return err
		}
		if _, err = tx.Exec(`INSERT INTO bot_schedules(bot_id,schedule_json,updated_at_ns) VALUES(?,?,?)
			ON CONFLICT(bot_id) DO UPDATE SET schedule_json=excluded.schedule_json,updated_at_ns=excluded.updated_at_ns`,
			botID, string(raw), time.Now().UnixNano()); err != nil {
			return err
		}
	}
	if err = tx.Commit(); err != nil {
		return err
	}
	rollback = false
	return nil
}

