func processingNewLotLedgerV412(source, final string) processingLotLedgerV412 {
	return processingLotLedgerV412{Version: 1, LotID: fmt.Sprintf("lot-%d", time.Now().UnixNano()), Active: true, Phase: "source_locked", SourceItem: strings.TrimSpace(source), FinalItem: strings.TrimSpace(final), SourcePlanned: processingAutomationBoxBatchV317, SourceRemaining: processingAutomationBoxBatchV317, UpdatedAt: time.Now()}
}

func processingPersistLotLedgerV412(bot *BotSession, ledger processingLotLedgerV412) error {
	if bot == nil {
		return errors.New("加工 BOT 不存在")
	}
	ledger.Version = 1
	ledger.UpdatedAt = time.Now()
	bot.mu.Lock()
	bot.ProcessLotLedger = ledger
	bot.mu.Unlock()
	if err := saveHelperProcessingConfig(bot); err != nil {
		return err
	}
	return nil
}

// V420: lightweight SQLite-only processing checkpoint. SQLite is authoritative on
// restart, so write-ahead trade checkpoints do not need to rewrite the legacy JSON
// compatibility mirror before every helper trade. Normal confirmed checkpoints still
// use saveHelperProcessingConfig and therefore refresh the mirror as before.
func saveHelperProcessingCheckpointV420(bot *BotSession) error {
	if bot == nil {
		return errors.New("BOT 不存在")
	}
	bot.mu.Lock()
	cfg := savedHelperProcessingConfig{
		PurchaseOutputMode:           bot.purchaseOutputModeLocked(),
		PurchaseOutputBox:            bot.PurchaseOutputBox,
		PurchaseOutputBoxConfigured:  bot.PurchaseOutputBoxConfigured,
		ProcessSourceBox:             bot.ProcessSourceBox,
		ProcessSourceBoxConfigured:   bot.ProcessSourceBoxConfigured,
		ProcessFirstExchange:         strings.TrimSpace(bot.ProcessFirstExchange),
		ProcessTradeDelayMS:          normaliseProcessingTradeDelayMSV372(bot.ProcessTradeDelayMS),
		ProcessSecondTradeDelayMS:    normaliseProcessingTradeDelayMSV372(bot.ProcessSecondTradeDelayMS),
		ProcessReturnEnabled:         bot.ProcessReturnEnabled,
		ProcessMachinePos:            bot.ProcessMachinePos,
		ProcessMachinePosConfigured:  bot.ProcessMachinePosConfigured,
		ProcessReturnCount:           bot.ProcessReturnCount,
		ProcessReturnOwedUnits:       bot.ProcessReturnOwedUnits,
		ProcessReturnOwedItem:        strings.TrimSpace(bot.ProcessReturnOwedItem),
		ProcessReturnCheckpointPhase: strings.TrimSpace(bot.ProcessReturnCheckpointPhase),
		ProcessSecondExchange:        strings.TrimSpace(bot.ProcessSecondExchange),
		ProcessSecondCarryItem:       strings.TrimSpace(bot.ProcessSecondCarryItem),
		ProcessSecondCarryCount:      bot.ProcessSecondCarryCount,
		ProcessOutputBox:             bot.ProcessOutputBox,
		ProcessOutputBoxConfigured:   bot.ProcessOutputBoxConfigured,
		ProcessOutputBoxFullNotified: bot.ProcessOutputBoxFullNotified,
		ProcessLotLedger:             bot.ProcessLotLedger,
	}
	bot.mu.Unlock()
	raw, err := json.Marshal(cfg)
	if err != nil {
		return err
	}
	db, err := suiteOpenStateDB()
	if err != nil {
		return err
	}
	_, err = db.Exec(`INSERT INTO processing_state(bot_id,state_json,updated_at_ns) VALUES(?,?,?)
		ON CONFLICT(bot_id) DO UPDATE SET state_json=excluded.state_json,updated_at_ns=excluded.updated_at_ns`, bot.ID, string(raw), time.Now().UnixNano())
	return err
}

func processingPrepareTradeCheckpointV420(bot *BotSession, stage, material, outputItem string, materialBefore, outputBefore, need, expectedOut int) error {
	if bot == nil {
		return errors.New("加工 BOT 不存在")
	}
	stage = strings.ToLower(strings.TrimSpace(stage))
	bot.mu.Lock()
	ledger := bot.ProcessLotLedger
	if !ledger.Active {
		bot.mu.Unlock()
		return errors.New("加工批次尚未建立，拒絕送出未受保護的交易")
	}
	ledger.Version = 1
	ledger.UpdatedAt = time.Now()
	switch stage {
	case "first":
		ledger.Phase = "first_trade_pending"
		ledger.FirstTradePending = true
		ledger.FirstTradeInputBefore = materialBefore
		ledger.FirstTradeOutputBefore = outputBefore
		ledger.FirstTradeNeed = need
		ledger.FirstTradeExpectedOut = expectedOut
		ledger.FirstTradeOutputItem = strings.TrimSpace(outputItem)
	case "second":
		ledger.Phase = "second_trade_pending"
		ledger.SecondTradePending = true
		ledger.SecondTradeInputBefore = materialBefore
		ledger.SecondTradeOutputBefore = outputBefore
		ledger.SecondTradeNeed = need
		ledger.SecondTradeExpectedOut = expectedOut
		ledger.SecondTradeOutputItem = strings.TrimSpace(outputItem)
	default:
		bot.mu.Unlock()
		return fmt.Errorf("未知加工交易階段 %q", stage)
	}
	bot.ProcessLotLedger = ledger
	bot.mu.Unlock()
	if err := saveHelperProcessingCheckpointV420(bot); err != nil {
		return fmt.Errorf("交易送出前 checkpoint 寫入失敗: %w", err)
	}
	return nil
}

func processingClearTradePendingFieldsV420(ledger *processingLotLedgerV412, stage string) {
	if ledger == nil {
		return
	}
	switch strings.ToLower(strings.TrimSpace(stage)) {
	case "first":
		ledger.FirstTradePending = false
		ledger.FirstTradeInputBefore = 0
		ledger.FirstTradeOutputBefore = 0
		ledger.FirstTradeNeed = 0
		ledger.FirstTradeExpectedOut = 0
		ledger.FirstTradeOutputItem = ""
	case "second":
		ledger.SecondTradePending = false
		ledger.SecondTradeInputBefore = 0
		ledger.SecondTradeOutputBefore = 0
		ledger.SecondTradeNeed = 0
		ledger.SecondTradeExpectedOut = 0
		ledger.SecondTradeOutputItem = ""
	}
}

// processingPendingTradeResultV420 reconciles an interrupted helper trade against
// the authoritative backpack. A trade is considered committed only when both sides
// prove the exact configured batch. If the input/output identity is the same, only
// a non-zero deterministic net count can prove it; otherwise the state is left
// blocked instead of guessing and replaying a possibly committed transaction.
func processingPendingTradeResultV420(bot *BotSession, material, outputItem string, materialBefore, outputBefore, need, expectedOut int) (committed bool, produced int, ambiguous bool, detail string) {
	material = strings.TrimSpace(material)
	outputItem = strings.TrimSpace(outputItem)
	if bot == nil || need <= 0 || expectedOut <= 0 || material == "" || outputItem == "" {
		return false, 0, true, "checkpoint 缺少可驗證交易數量或物品"
	}
	materialAfter := helperOutputInventoryCountV159(bot, material)
	outputAfter := helperOutputInventoryCountV159(bot, outputItem)
	if processingSameTradeItemV396(bot, material, outputItem) {
		netExpected := expectedOut - need
		netActual := materialAfter - materialBefore
		if netExpected > 0 && netActual >= netExpected {
			return true, expectedOut, false, fmt.Sprintf("same_item net=%d expected=%d", netActual, netExpected)
		}
		if netExpected < 0 && netActual <= netExpected {
			return true, expectedOut, false, fmt.Sprintf("same_item net=%d expected=%d", netActual, netExpected)
		}
		if netExpected != 0 && netActual == 0 {
			return false, 0, false, "same_item inventory unchanged"
		}
		return false, 0, true, fmt.Sprintf("same_item 無法唯一判定：before=%d after=%d need=%d out=%d", materialBefore, materialAfter, need, expectedOut)
	}
	spent := materialBefore - materialAfter
	gained := outputAfter - outputBefore
	if spent >= need && gained >= expectedOut {
		verified := gained
		if verified > expectedOut {
			verified = expectedOut
		}
		return true, verified, false, fmt.Sprintf("spent=%d gained=%d", spent, gained)
	}
	// V423 migration: V420-V422 could save outputBefore using a polluted family
	// alias, so dirt and coarse_dirt both recorded the same pre-trade total. After
	// variant-aware matching, exact input consumption plus the full expected output
	// currently present is sufficient to recover that one write-ahead transaction.
	if spent >= need && outputAfter >= expectedOut &&
		materialBefore == outputBefore &&
		!processingSameTradeItemV396(bot, material, outputItem) {
		return true, expectedOut, false, fmt.Sprintf(
			"legacy_alias_checkpoint_repaired spent=%d output_now=%d expected=%d before=%d",
			spent, outputAfter, expectedOut, outputBefore,
		)
	}
	if spent <= 0 && gained <= 0 {
		return false, 0, false, fmt.Sprintf("unchanged spent=%d gained=%d", spent, gained)
	}
	return false, 0, true, fmt.Sprintf("部分變動無法唯一判定：spent=%d/%d gained=%d/%d", spent, need, gained, expectedOut)
}

func processingReconcilePendingTradesV420(ctx context.Context, bot *BotSession, firstReq helperTradeRequirement, firstOut helperTradeOutput, hasSecond bool, secondReq helperTradeRequirement, secondOut helperTradeOutput) (processingLotLedgerV412, error) {
	if bot == nil {
		return processingLotLedgerV412{}, errors.New("加工 BOT 不存在")
	}
	bot.mu.Lock()
	ledger := bot.ProcessLotLedger
	bot.mu.Unlock()
	if !ledger.Active || (!ledger.FirstTradePending && !ledger.SecondTradePending) {
		return ledger, nil
	}
	processingSetStageV159(bot, "中斷交易對帳", "讀取伺服器背包，確認上次中斷前的交易到底有沒有成交")
	processingRefreshInventoryAfterTradeV170(ctx, bot)

	changed := false
	if ledger.FirstTradePending {
		outItem := strings.TrimSpace(ledger.FirstTradeOutputItem)
		if outItem == "" {
			outItem = strings.TrimSpace(firstOut.Item)
		}
		need := ledger.FirstTradeNeed
		if need <= 0 {
			need = firstReq.Count
		}
		expected := ledger.FirstTradeExpectedOut
		if expected <= 0 && firstOut.CountExplicit {
			expected = firstOut.Count
		}
		committed, produced, ambiguous, detail := processingPendingTradeResultV420(bot, firstReq.Item, outItem, ledger.FirstTradeInputBefore, ledger.FirstTradeOutputBefore, need, expected)
		if ambiguous {
			return ledger, fmt.Errorf("上次第一階交易中斷後狀態不明（%s）；已停止避免重複兌換", detail)
		}
		if committed {
			ledger.SourceRemaining -= need
			if ledger.SourceRemaining < 0 {
				ledger.SourceRemaining = 0
			}
			ledger.SourceConsumed += need
			ledger.FirstTradeCount++
			ledger.FirstProduced += produced
			ledger.IntermediateItem = outItem
			ledger.Phase = "first_trade_recovered"
			logCollectDiagnostic(bot, "processing_first_trade_recovered_v420", detail)
		} else {
			ledger.Phase = "first_trade_not_committed"
			logCollectDiagnostic(bot, "processing_first_trade_not_committed_v420", detail)
		}
		processingClearTradePendingFieldsV420(&ledger, "first")
		changed = true
	}

	if ledger.SecondTradePending {
		if !hasSecond {
			return ledger, errors.New("上次有第二階未決交易，但目前第二兌換已取消；拒絕猜測")
		}
		outItem := strings.TrimSpace(ledger.SecondTradeOutputItem)
		if outItem == "" {
			outItem = strings.TrimSpace(secondOut.Item)
		}
		need := ledger.SecondTradeNeed
		if need <= 0 {
			need = secondReq.Count
		}
		expected := ledger.SecondTradeExpectedOut
		if expected <= 0 && secondOut.CountExplicit {
			expected = secondOut.Count
		}
		committed, produced, ambiguous, detail := processingPendingTradeResultV420(bot, secondReq.Item, outItem, ledger.SecondTradeInputBefore, ledger.SecondTradeOutputBefore, need, expected)
		if ambiguous {
			return ledger, fmt.Errorf("上次第二階交易中斷後狀態不明（%s）；已停止避免重複兌換", detail)
		}
		if committed {
			ledger.SecondInputConsumed += need
			ledger.SecondProduced += produced
			ledger.FinalItem = outItem
			ledger.Phase = "second_trade_recovered"
			logCollectDiagnostic(bot, "processing_second_trade_recovered_v420", detail)
		} else {
			ledger.Phase = "second_trade_not_committed"
			logCollectDiagnostic(bot, "processing_second_trade_not_committed_v420", detail)
		}
		processingClearTradePendingFieldsV420(&ledger, "second")
		changed = true
	}
	if changed {
		if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
			return ledger, fmt.Errorf("中斷交易對帳結果保存失敗: %w", err)
		}
	}
	return ledger, nil
}

func processingSetLotMachineReturnV418(bot *BotSession, target, returned int, done bool) error {
	if bot == nil {
		return errors.New("加工 BOT 不存在")
	}
	if target < 0 {
		target = 0
	}
	if returned < 0 {
		returned = 0
	}
	bot.mu.Lock()
	ledger := bot.ProcessLotLedger
	if ledger.Active {
		ledger.Version = 1
		if target > 0 {
			ledger.MachineReturnTarget = target
		}
		if returned > ledger.MachineReturned {
			ledger.MachineReturned = returned
		}
		if done {
			ledger.MachineReturnDone = true
			ledger.ReturnOwedUnits = 0
			ledger.Phase = "machine_return_confirmed"
		}
		ledger.UpdatedAt = time.Now()
		bot.ProcessLotLedger = ledger
	}
	bot.mu.Unlock()
	return saveHelperProcessingConfig(bot)
}

func processingPersistSecondCarryV419(bot *BotSession, item string, count int) error {
	if bot == nil {
		return errors.New("加工 BOT 不存在")
	}
	item = strings.TrimSpace(item)
	if count < 0 {
		count = 0
	}
	if count == 0 {
		item = ""
	}
	bot.mu.Lock()
	bot.ProcessSecondCarryItem = item
	bot.ProcessSecondCarryCount = count
	bot.mu.Unlock()
	return saveHelperProcessingConfig(bot)
}

func processingClearLotLedgerV412(bot *BotSession) error {
	if bot == nil {
		return nil
	}
	bot.mu.Lock()
	bot.ProcessLotLedger = processingLotLedgerV412{Version: 1, Active: false, Phase: "completed", UpdatedAt: time.Now()}
	bot.mu.Unlock()
	return saveHelperProcessingConfig(bot)
}

type savedHelperProcessingConfig struct {
	PurchaseOutputMode          string `json:"purchase_output_mode"`
	PurchaseOutputBox           Vec3i  `json:"purchase_output_box"`
	PurchaseOutputBoxConfigured bool   `json:"purchase_output_box_configured"`
	ProcessSourceBox            Vec3i  `json:"process_source_box"`
	ProcessSourceBoxConfigured  bool   `json:"process_source_box_configured"`
	ProcessFirstExchange        string `json:"process_first_exchange"`
	ProcessTradeDelayMS         int    `json:"process_trade_delay_ms"`
	ProcessSecondTradeDelayMS   int    `json:"process_second_trade_delay_ms"`
	ProcessReturnEnabled        bool   `json:"process_return_enabled"`
	ProcessMachinePos           Vec3i  `json:"process_machine_box"`
	ProcessMachinePosConfigured bool   `json:"process_machine_box_configured"`
	ProcessReturnCount          int    `json:"process_return_count"`
	// ProcessReturnOwedUnits stores hundredths of one item still owed to the
	// machine allocation. It intentionally may exceed 99 when the machine box is
	// temporarily full, so no integer item is ever lost from the configured ratio.
	ProcessReturnOwedUnits       int    `json:"process_return_owed_units"`
	ProcessReturnOwedItem        string `json:"process_return_owed_item"`
	ProcessReturnCheckpointPhase string `json:"process_return_checkpoint_phase"`
	ProcessSecondExchange        string `json:"process_second_exchange"`
	ProcessSecondCarryItem       string `json:"process_second_carry_item"`
	ProcessSecondCarryCount      int    `json:"process_second_carry_count"`
	ProcessOutputBox             Vec3i  `json:"process_output_box"`
	ProcessOutputBoxConfigured   bool   `json:"process_output_box_configured"`
	// V424: completion belongs to the physical 27-slot output box, not a 1728-source lot.
	// Keep this fence across App restarts so a full box is announced exactly once
	// while the machine is still pushing/replacing it. It is cleared as soon as
	// the verified output position shows space again.
	ProcessOutputBoxFullNotified bool                    `json:"process_output_box_full_notified"`
	ProcessLotLedger             processingLotLedgerV412 `json:"process_lot_ledger,omitempty"`
}

func helperProcessingConfigPath() string {
	return filepath.Join(botDataDir, "helper-processing.json")
}

func loadHelperProcessingConfig(id int) (savedHelperProcessingConfig, bool) {
	if db, err := suiteOpenStateDB(); err == nil && db != nil {
		var raw string
		if err := db.QueryRow(`SELECT state_json FROM processing_state WHERE bot_id=?`, id).Scan(&raw); err == nil {
			var cfg savedHelperProcessingConfig
			if json.Unmarshal([]byte(raw), &cfg) == nil {
				return cfg, true
			}
		}
	}
	// Legacy helper-processing.json is migration input only.
	helperProcessingConfigFileMu.Lock()
	data, err := os.ReadFile(helperProcessingConfigPath())
	helperProcessingConfigFileMu.Unlock()
	if err != nil {
		return savedHelperProcessingConfig{}, false
	}
	all := map[string]savedHelperProcessingConfig{}
	if json.Unmarshal(data, &all) != nil {
		return savedHelperProcessingConfig{}, false
	}
	cfg, ok := all[strconv.Itoa(id)]
	if ok {
		if raw, e := json.Marshal(cfg); e == nil {
			if db, e := suiteOpenStateDB(); e == nil {
				_, _ = db.Exec(`INSERT INTO processing_state(bot_id,state_json,updated_at_ns) VALUES(?,?,?) ON CONFLICT(bot_id) DO UPDATE SET state_json=excluded.state_json,updated_at_ns=excluded.updated_at_ns`, id, string(raw), time.Now().UnixNano())
			}
		}
	}
	return cfg, ok
}

func applyHelperProcessingConfig(bot *BotSession, cfg savedHelperProcessingConfig) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	bot.PurchaseOutputMode = normalisePurchaseOutputModeV159(cfg.PurchaseOutputMode)
	bot.PurchaseOutputBox = cfg.PurchaseOutputBox
	bot.PurchaseOutputBoxConfigured = cfg.PurchaseOutputBoxConfigured
	bot.ProcessSourceBox = cfg.ProcessSourceBox
	bot.ProcessSourceBoxConfigured = cfg.ProcessSourceBoxConfigured
	bot.ProcessFirstExchange = strings.TrimSpace(cfg.ProcessFirstExchange)
	// V409: 2500/2500 was the historical untouched default. Migrate only that
	// exact pair so explicitly tuned first/second delays are never rewritten.
	firstDelayMS, secondDelayMS := cfg.ProcessTradeDelayMS, cfg.ProcessSecondTradeDelayMS
	if firstDelayMS == 2500 && secondDelayMS == 2500 {
		firstDelayMS = processingTradeDelayDefaultV372
		secondDelayMS = processingTradeDelayDefaultV372
	}
	bot.ProcessTradeDelayMS = normaliseProcessingTradeDelayMSV372(firstDelayMS)
	bot.ProcessSecondTradeDelayMS = normaliseProcessingTradeDelayMSV372(secondDelayMS)
	bot.ProcessReturnEnabled = cfg.ProcessReturnEnabled
	bot.ProcessMachinePos = cfg.ProcessMachinePos
	bot.ProcessMachinePosConfigured = cfg.ProcessMachinePosConfigured
	// V418: 回機器固定以「本盒 1728 原料」計算，50% 永遠是 864。
	// 舊版曾用第一階實際產出 × 50% 累計 debt；載入時依本盒已確認回料量
	// 把舊 debt 夾到固定 864 的剩餘額，避免升級後又多補一倍。
	bot.ProcessReturnCount = processingFixedMachineReturnPercentV393
	owed := cfg.ProcessReturnOwedUnits
	maxRemainingReturn := processingFixedMachineReturnItemsV418 - cfg.ProcessLotLedger.MachineReturned
	if maxRemainingReturn < 0 {
		maxRemainingReturn = 0
	}
	if owed > maxRemainingReturn*100 {
		owed = maxRemainingReturn * 100
	}
	if owed < 100 {
		owed = 0
	}
	bot.ProcessReturnOwedUnits = owed
	bot.ProcessReturnOwedItem = strings.TrimSpace(cfg.ProcessReturnOwedItem)
	bot.ProcessReturnCheckpointPhase = strings.TrimSpace(cfg.ProcessReturnCheckpointPhase)
	if owed == 0 {
		bot.ProcessReturnOwedItem = ""
		bot.ProcessReturnCheckpointPhase = ""
	} else if bot.ProcessReturnCheckpointPhase == "" {
		bot.ProcessReturnCheckpointPhase = "accruing"
	}
	bot.ProcessSecondExchange = strings.TrimSpace(cfg.ProcessSecondExchange)
	bot.ProcessSecondCarryItem = strings.TrimSpace(cfg.ProcessSecondCarryItem)
	bot.ProcessSecondCarryCount = cfg.ProcessSecondCarryCount
	if bot.ProcessSecondCarryCount < 0 {
		bot.ProcessSecondCarryCount = 0
	}
	if bot.ProcessSecondCarryCount == 0 {
		bot.ProcessSecondCarryItem = ""
	}
	bot.ProcessOutputBox = cfg.ProcessOutputBox
	bot.ProcessOutputBoxConfigured = cfg.ProcessOutputBoxConfigured
	bot.ProcessOutputBoxFullNotified = cfg.ProcessOutputBoxFullNotified
	bot.ProcessLotLedger = cfg.ProcessLotLedger
	if bot.ProcessLotLedger.Version == 0 {
		bot.ProcessLotLedger.Version = 1
	}
	bot.ProcessAutomationRunning = false
	bot.ProcessAutomationCancel = nil
	bot.ProcessStage = "等待設定"
	bot.ProcessStatus = "未啟動"
	if bot.ProcessLotLedger.Active && bot.ProcessLotLedger.SourceRemaining > 0 {
		bot.ProcessStage = "待續接加工批次"
		bot.ProcessStatus = fmt.Sprintf("偵測到中斷批次 %s｜剩餘原料 %d｜第一產物 %d｜按開始會先對帳再續接", bot.ProcessLotLedger.LotID, bot.ProcessLotLedger.SourceRemaining, bot.ProcessLotLedger.FirstProduced)
	}
	if bot.ProcessLotLedger.Active && (bot.ProcessLotLedger.FirstTradePending || bot.ProcessLotLedger.SecondTradePending) {
		bot.ProcessStage = "待對帳中斷交易"
		which := "第一階"
		if bot.ProcessLotLedger.SecondTradePending {
			which = "第二階"
		}
		bot.ProcessStatus = fmt.Sprintf("偵測到 %s 交易在 App 中斷前已送出但尚未完成落帳｜按開始會先比對伺服器背包，再決定補記或重試", which)
	}
	if bot.ProcessReturnOwedUnits >= 100 {
		bot.ProcessStage = "待續接回料"
		item := strings.TrimSpace(bot.ProcessReturnOwedItem)
		if item == "" {
			item = "中間產物"
		}
		bot.ProcessStatus = fmt.Sprintf("偵測到中斷前尚有 %d 個 %s 應回機器｜按開始會先補回再繼續", bot.ProcessReturnOwedUnits/100, item)
	} else if !bot.ProcessLotLedger.Active && bot.ProcessSecondCarryCount > 0 {
		item := strings.TrimSpace(bot.ProcessSecondCarryItem)
		if item == "" {
			item = "第二階材料"
		}
		bot.ProcessStage = "待合併第二階尾數"
		bot.ProcessStatus = fmt.Sprintf("上一盒保留 %d 個 %s｜下一盒第二階會自動合併", bot.ProcessSecondCarryCount, item)
	}
	bot.ProcessLastError = ""
	bot.ProcessLastActionAt = time.Time{}
	bot.applyPurchaseOutputModeLockedV159()
	switch bot.purchaseOutputModeLocked() {
	case purchaseOutputModeBoxV159:
		bot.PurchaseOutputStatus = "已還原：兌換成功後存入指定箱子"
	case purchaseOutputModeDropV159:
		bot.PurchaseOutputStatus = "已還原：兌換成功後直接丟棄"
	default:
		bot.PurchaseOutputStatus = "已還原：兌換成功後保留在背包"
	}
	bot.mu.Unlock()
}

func saveHelperProcessingConfig(bot *BotSession) error {
	if bot == nil {
		return errors.New("BOT 不存在")
	}
	bot.mu.Lock()
	cfg := savedHelperProcessingConfig{
		PurchaseOutputMode:           bot.purchaseOutputModeLocked(),
		PurchaseOutputBox:            bot.PurchaseOutputBox,
		PurchaseOutputBoxConfigured:  bot.PurchaseOutputBoxConfigured,
		ProcessSourceBox:             bot.ProcessSourceBox,
		ProcessSourceBoxConfigured:   bot.ProcessSourceBoxConfigured,
		ProcessFirstExchange:         strings.TrimSpace(bot.ProcessFirstExchange),
		ProcessTradeDelayMS:          normaliseProcessingTradeDelayMSV372(bot.ProcessTradeDelayMS),
		ProcessSecondTradeDelayMS:    normaliseProcessingTradeDelayMSV372(bot.ProcessSecondTradeDelayMS),
		ProcessReturnEnabled:         bot.ProcessReturnEnabled,
		ProcessMachinePos:            bot.ProcessMachinePos,
		ProcessMachinePosConfigured:  bot.ProcessMachinePosConfigured,
		ProcessReturnCount:           bot.ProcessReturnCount,
		ProcessReturnOwedUnits:       bot.ProcessReturnOwedUnits,
		ProcessReturnOwedItem:        strings.TrimSpace(bot.ProcessReturnOwedItem),
		ProcessReturnCheckpointPhase: strings.TrimSpace(bot.ProcessReturnCheckpointPhase),
		ProcessSecondExchange:        strings.TrimSpace(bot.ProcessSecondExchange),
		ProcessSecondCarryItem:       strings.TrimSpace(bot.ProcessSecondCarryItem),
		ProcessSecondCarryCount:      bot.ProcessSecondCarryCount,
		ProcessOutputBox:             bot.ProcessOutputBox,
		ProcessOutputBoxConfigured:   bot.ProcessOutputBoxConfigured,
		ProcessOutputBoxFullNotified: bot.ProcessOutputBoxFullNotified,
		ProcessLotLedger:             bot.ProcessLotLedger,
	}
	bot.mu.Unlock()

	raw, err := json.Marshal(cfg)
	if err != nil {
		return err
	}
	db, err := suiteOpenStateDB()
	if err != nil {
		return err
	}
	if _, err = db.Exec(`INSERT INTO processing_state(bot_id,state_json,updated_at_ns) VALUES(?,?,?) ON CONFLICT(bot_id) DO UPDATE SET state_json=excluded.state_json,updated_at_ns=excluded.updated_at_ns`, bot.ID, string(raw), time.Now().UnixNano()); err != nil {
		return err
	}
	// Keep the legacy JSON as an atomic compatibility mirror only; SQLite is authoritative.
	helperProcessingConfigFileMu.Lock()
	defer helperProcessingConfigFileMu.Unlock()
	all := map[string]savedHelperProcessingConfig{}
	path := helperProcessingConfigPath()
	if data, e := os.ReadFile(path); e == nil {
		_ = json.Unmarshal(data, &all)
	}
	all[strconv.Itoa(bot.ID)] = cfg
	data, err := json.MarshalIndent(all, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0644); err != nil {
		return err
	}
	_ = os.Remove(path)
	return os.Rename(tmp, path)
}

func botDialTarget(address string) string {
	// V25: the known-good reference dials the hostname exactly as configured.
	// Do not pin Bedrock hosts to an old IP: DNS/edge routing may change, and
	// the hard-coded address was one of the remaining differences from the working login.
	return strings.TrimSpace(address)
}

