func defaultSuiteAutomationSettings() suiteAutomationSettings {
	return suiteAutomationSettings{
		EatHungerThreshold: 14,
		CombatRange:        4.25,
		CombatHostilesOnly: true,
		IdleCraftCount:     1,
	}
}

func suiteAutomationSettingsPath(botID int) string {
	return filepath.Join(botDataDir, fmt.Sprintf("bot-%d-survival.json", botID))
}

func loadSuiteAutomationSettings(botID int) suiteAutomationSettings {
	settings := defaultSuiteAutomationSettings()
	data, err := os.ReadFile(suiteAutomationSettingsPath(botID))
	if err != nil {
		return settings
	}
	var saved suiteAutomationSettings
	if json.Unmarshal(data, &saved) != nil {
		return settings
	}
	if saved.EatHungerThreshold > 0 {
		settings.EatHungerThreshold = saved.EatHungerThreshold
	}
	if saved.CombatRange > 0 {
		settings.CombatRange = saved.CombatRange
	}
	if saved.IdleCraftCount > 0 {
		settings.IdleCraftCount = saved.IdleCraftCount
	}
	settings.AutoEatEnabled = saved.AutoEatEnabled
	settings.AutoCombatEnabled = saved.AutoCombatEnabled
	settings.CombatHostilesOnly = saved.CombatHostilesOnly
	settings.IdleAutomationEnabled = saved.IdleAutomationEnabled
	settings.IdleCraftItem = saved.IdleCraftItem
	return settings
}

func saveSuiteAutomationSettings(botID int, settings suiteAutomationSettings) error {
	if err := os.MkdirAll(botDataDir, 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return err
	}
	path := suiteAutomationSettingsPath(botID)
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

