func suiteCloneStorageProfileV111(profile *suiteStorageProfile) *suiteStorageProfile {
	if profile == nil {
		return nil
	}
	cp := *profile
	cp.Commands = append([]string(nil), profile.Commands...)
	cp.Offsets = append([]Vec3i(nil), profile.Offsets...)
	if profile.DropPosition != nil {
		v := *profile.DropPosition
		cp.DropPosition = &v
	}
	cp.Boxes = make([]suiteStorageBox, len(profile.Boxes))
	for i, box := range profile.Boxes {
		cp.Boxes[i] = box
		cp.Boxes[i].Materials = cloneCountMap(box.Materials)
	}
	return &cp
}

func suiteAttachStorageSnapshotToPayloadV117(botID int, payload map[string]interface{}) {
	if payload == nil {
		return
	}
	storageID := strings.TrimSpace(suitePayloadString(payload, "storage_id", ""))
	if storageID == "" {
		return
	}
	if _, exists := payload["storage_snapshot"]; exists {
		return
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	var snapshot *suiteStorageProfile
	for i := range suitePortState.data.StorageProfiles[botID] {
		if suitePortState.data.StorageProfiles[botID][i].ID == storageID {
			snapshot = suiteCloneStorageProfileV111(&suitePortState.data.StorageProfiles[botID][i])
			break
		}
	}
	suitePortState.Unlock()
	if snapshot == nil {
		return
	}
	payload["storage_revision"] = snapshot.Revision
	payload["storage_snapshot"] = snapshot
}

func suiteStorageSnapshotFromPayloadV117(payload map[string]interface{}) *suiteStorageProfile {
	if payload == nil {
		return nil
	}
	raw, ok := payload["storage_snapshot"]
	if !ok || raw == nil {
		return nil
	}
	data, err := json.Marshal(raw)
	if err != nil {
		return nil
	}
	var profile suiteStorageProfile
	if json.Unmarshal(data, &profile) != nil || strings.TrimSpace(profile.ID) == "" {
		return nil
	}
	return suiteCloneStorageProfileV111(&profile)
}

func suiteTaskStorageProfileV117(bot *BotSession, t *suiteTask, materials map[string]int, preferredPos *Vec3i) *suiteStorageProfile {
	if t != nil {
		if snapshot := suiteStorageSnapshotFromPayloadV117(t.Payload); snapshot != nil {
			return snapshot
		}
	}
	requestedID := ""
	if t != nil {
		requestedID = strings.TrimSpace(suitePayloadString(t.Payload, "storage_id", ""))
	}
	return suiteSelectBuildStorageProfileV111(bot, requestedID, materials, preferredPos)
}

func suiteStorageProfileMaterialCountV111(bot *BotSession, profile suiteStorageProfile, block string) int {
	if bot == nil {
		return 0
	}
	bot.mu.Lock()
	defer bot.mu.Unlock()
	total := 0
	for _, box := range profile.Boxes {
		if !box.Enabled {
			continue
		}
		for material, count := range box.Materials {
			if count > 0 && suiteBuildMaterialNameMatchesLockedV111(bot, block, material) {
				total += count
			}
		}
	}
	return total
}

// suiteSelectBuildStorageProfileV111 connects the existing material-box scanner
// to every construction mode. An explicitly requested profile wins. Otherwise a
// profile at the manually selected storage coordinate wins, then the scanned
// profile covering the most near-term plan materials is chosen automatically.
func suiteSelectBuildStorageProfileV111(bot *BotSession, requestedID string, materials map[string]int, preferredPos *Vec3i) *suiteStorageProfile {
	if bot == nil {
		return nil
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	list := append([]suiteStorageProfile(nil), suitePortState.data.StorageProfiles[bot.ID]...)
	suitePortState.Unlock()
	if len(list) == 0 {
		return nil
	}
	requestedID = strings.TrimSpace(requestedID)
	if requestedID != "" {
		for i := range list {
			if list[i].ID == requestedID {
				return suiteCloneStorageProfileV111(&list[i])
			}
		}
	}
	if preferredPos != nil {
		for i := range list {
			if list[i].Position == *preferredPos {
				return suiteCloneStorageProfileV111(&list[i])
			}
		}
	}

	best := -1
	bestKinds := -1
	bestCovered := -1
	bestScanned := false
	for i := range list {
		kinds := 0
		covered := 0
		for block, need := range materials {
			if need <= 0 {
				continue
			}
			stock := suiteStorageProfileMaterialCountV111(bot, list[i], block)
			if stock <= 0 {
				continue
			}
			kinds++
			covered += minInt(stock, need)
		}
		scanned := !list[i].ScannedAt.IsZero() && len(list[i].Boxes) > 0
		if best < 0 || kinds > bestKinds ||
			(kinds == bestKinds && covered > bestCovered) ||
			(kinds == bestKinds && covered == bestCovered && scanned && !bestScanned) {
			best = i
			bestKinds = kinds
			bestCovered = covered
			bestScanned = scanned
		}
	}
	// Automatic selection is driven by the scanner, not by profile list order.
	// If no scanned box covers any material in this plan, leave the existing/manual
	// storage context untouched instead of teleporting to an unrelated warehouse.
	if best < 0 || bestKinds <= 0 {
		return nil
	}
	return suiteCloneStorageProfileV111(&list[best])
}

func suiteApplyStorageProfileLockedV111(bot *BotSession, profile *suiteStorageProfile) {
	if bot == nil {
		return
	}
	bot.SuiteStorageProfile = suiteCloneStorageProfileV111(profile)
	bot.SuiteStorageBoxes = nil
	if profile == nil {
		return
	}
	bot.MapArtStoragePos = profile.Position
	bot.MapArtStorageConfigured = true
	bot.SuiteStorageBoxes = make([]suiteStorageBox, len(profile.Boxes))
	for i, box := range profile.Boxes {
		bot.SuiteStorageBoxes[i] = box
		bot.SuiteStorageBoxes[i].Materials = cloneCountMap(box.Materials)
	}
}

func suiteInstallBuildItemMappingsV116(bot *BotSession, mappings map[string]string) func() {
	if bot == nil {
		return func() {}
	}
	bot.mu.Lock()
	old := suiteCloneStringMap(bot.SuiteItemMappings)
	bot.SuiteItemMappings = suiteCloneStringMap(mappings)
	bot.mu.Unlock()
	return func() {
		bot.mu.Lock()
		bot.SuiteItemMappings = old
		bot.mu.Unlock()
	}
}

func suiteInstallBuildStorageContextV111(bot *BotSession, profile *suiteStorageProfile, manualPos *Vec3i) func() {
	if bot == nil {
		return func() {}
	}
	bot.mu.Lock()
	oldPos := bot.MapArtStoragePos
	oldConfigured := bot.MapArtStorageConfigured
	oldBoxes := make([]suiteStorageBox, len(bot.SuiteStorageBoxes))
	for i, box := range bot.SuiteStorageBoxes {
		oldBoxes[i] = box
		oldBoxes[i].Materials = cloneCountMap(box.Materials)
	}
	oldProfile := suiteCloneStorageProfileV111(bot.SuiteStorageProfile)
	if profile != nil {
		suiteApplyStorageProfileLockedV111(bot, profile)
	}
	if manualPos != nil {
		bot.MapArtStoragePos = *manualPos
		bot.MapArtStorageConfigured = true
	}
	bot.mu.Unlock()

	return func() {
		bot.mu.Lock()
		bot.MapArtStoragePos = oldPos
		bot.MapArtStorageConfigured = oldConfigured
		bot.SuiteStorageBoxes = oldBoxes
		bot.SuiteStorageProfile = oldProfile
		bot.mu.Unlock()
	}
}

