func suiteReadDeviceSetting(key string) ([]byte, bool, error) {
	db, err := suiteOpenStateDB()
	if err != nil {
		return nil, false, err
	}
	var value string
	err = db.QueryRow(`SELECT value_json FROM device_settings WHERE key=?`, key).Scan(&value)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	return []byte(value), true, nil
}

func suiteWriteDeviceSetting(key string, value []byte) error {
	db, err := suiteOpenStateDB()
	if err != nil {
		return err
	}
	_, err = db.Exec(`INSERT INTO device_settings(key,value_json,updated_at_ns) VALUES(?,?,?)
		ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json,updated_at_ns=excluded.updated_at_ns`,
		key, string(value), time.Now().UnixNano())
	return err
}

