var suiteMapShadeMultiplierV412 = [3]int{180, 220, 255}

func suiteMapColorRGBV412(code int) (uint8, uint8, uint8, bool) {
	id, shade := code/4, code%4
	if id < 1 || shade < 0 || shade > 2 {
		return 0, 0, 0, false
	}
	for _, row := range suiteMapColorBasesV412 {
		if row.ID == id {
			m := suiteMapShadeMultiplierV412[shade]
			return uint8(int((row.RGB>>16)&255) * m / 255), uint8(int((row.RGB>>8)&255) * m / 255), uint8(int(row.RGB&255) * m / 255), true
		}
	}
	return 0, 0, 0, false
}

func suiteMapColorBaseForBlockV412(block string) (int, bool) {
	b := suiteNormaliseMaterialID(block)
	if b == "" {
		return 0, false
	}
	for _, row := range suiteMapColorBasesV412 {
		for _, c := range row.Candidates {
			if suiteNormaliseMaterialID(c) == b {
				return row.ID, true
			}
		}
		if suiteNormaliseMaterialID(row.Default) == b {
			return row.ID, true
		}
	}
	return 0, false
}

