func suiteCreatorPalette(botID int, mode string) ([]suiteCreatorPaletteEntry, error) {
	mode = strings.ToLower(strings.TrimSpace(mode))
	if mode == "" {
		mode = "mixed"
	}
	if mode == "mapcolor" {
		mode = "mixed"
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	policy := append([]string(nil), suitePortState.data.MapPolicy[botID]...)
	suitePortState.Unlock()
	allowed := map[string]bool{}
	for _, raw := range policy {
		if id := suiteNormaliseMaterialID(raw); id != "" {
			allowed[id] = true
		}
	}
	pick := func(row suiteMapColorBaseV412) string {
		if len(allowed) > 0 {
			for _, c := range row.Candidates {
				c = suiteNormaliseMaterialID(c)
				if allowed[c] {
					return c
				}
			}
			d := suiteNormaliseMaterialID(row.Default)
			if allowed[d] {
				return d
			}
			return ""
		}
		if !row.Safe {
			return ""
		}
		candidates := append([]string(nil), row.Candidates...)
		candidates = append(candidates, row.Default)
		for _, c := range candidates {
			lc := strings.ToLower(c)
			switch mode {
			case "concrete":
				if strings.Contains(lc, "concrete") {
					return suiteNormaliseMaterialID(c)
				}
			case "wool":
				if strings.Contains(lc, "wool") {
					return suiteNormaliseMaterialID(c)
				}
			case "terracotta":
				if strings.Contains(lc, "terracotta") {
					return suiteNormaliseMaterialID(c)
				}
			case "mixed":
				if c != "" {
					return suiteNormaliseMaterialID(c)
				}
			}
		}
		return ""
	}
	out := make([]suiteCreatorPaletteEntry, 0, 183)
	for _, row := range suiteMapColorBasesV412 {
		block := pick(row)
		if block == "" {
			continue
		}
		for shade := 0; shade < 3; shade++ {
			code := row.ID*4 + shade
			r, g, b, ok := suiteMapColorRGBV412(code)
			if ok {
				out = append(out, suiteCreatorPaletteEntry{Block: block, R: r, G: g, B: b, MapColor: code, Shade: shade})
			}
		}
	}
	if len(out) == 0 {
		return nil, errors.New("目前地圖材料政策沒有可用的 Minecraft MapColor 材料")
	}
	return out, nil
}

func suiteCreatorDecodeImage(raw []byte) (image.Image, string, error) {
	if len(raw) == 0 {
		return nil, "", errors.New("圖片是空的")
	}
	cfg, format, err := image.DecodeConfig(bytes.NewReader(raw))
	if err != nil {
		return nil, "", errors.New("圖片格式無法解析；請使用 PNG/JPG/GIF")
	}
	if cfg.Width < 1 || cfg.Height < 1 || cfg.Width > 10000 || cfg.Height > 10000 || int64(cfg.Width)*int64(cfg.Height) > 40000000 {
		return nil, "", fmt.Errorf("圖片尺寸過大：%dx%d（最多約 4000 萬像素）", cfg.Width, cfg.Height)
	}
	img, decodedFormat, err := image.Decode(bytes.NewReader(raw))
	if err != nil {
		return nil, "", errors.New("圖片解碼失敗")
	}
	if decodedFormat != "" {
		format = decodedFormat
	}
	return img, format, nil
}

func suiteCreatorSample(img image.Image, outX, outY, outW, outH int, fit string) color.NRGBA {
	b := img.Bounds()
	sw, sh := b.Dx(), b.Dy()
	if sw <= 0 || sh <= 0 || outW <= 0 || outH <= 0 {
		return color.NRGBA{A: 0}
	}
	fit = strings.ToLower(strings.TrimSpace(fit))
	var sx, sy float64
	switch fit {
	case "stretch":
		sx = (float64(outX)+0.5)*float64(sw)/float64(outW) - 0.5
		sy = (float64(outY)+0.5)*float64(sh)/float64(outH) - 0.5
	case "contain":
		scale := math.Min(float64(outW)/float64(sw), float64(outH)/float64(sh))
		rw, rh := float64(sw)*scale, float64(sh)*scale
		ox, oy := (float64(outW)-rw)/2, (float64(outH)-rh)/2
		px, py := float64(outX)+0.5, float64(outY)+0.5
		if px < ox || py < oy || px >= ox+rw || py >= oy+rh {
			return color.NRGBA{A: 0}
		}
		sx = (px-ox)/scale - 0.5
		sy = (py-oy)/scale - 0.5
	default: // crop
		scale := math.Max(float64(outW)/float64(sw), float64(outH)/float64(sh))
		rw, rh := float64(sw)*scale, float64(sh)*scale
		ox, oy := (rw-float64(outW))/2, (rh-float64(outH))/2
		sx = (float64(outX)+0.5+ox)/scale - 0.5
		sy = (float64(outY)+0.5+oy)/scale - 0.5
	}
	x := int(math.Round(sx))
	y := int(math.Round(sy))
	if x < 0 {
		x = 0
	}
	if y < 0 {
		y = 0
	}
	if x >= sw {
		x = sw - 1
	}
	if y >= sh {
		y = sh - 1
	}
	return color.NRGBAModel.Convert(img.At(b.Min.X+x, b.Min.Y+y)).(color.NRGBA)
}

func suiteCreatorNearest(palette []suiteCreatorPaletteEntry, r, g, b float64) suiteCreatorPaletteEntry {
	best := palette[0]
	bestDist := math.MaxFloat64
	for _, entry := range palette {
		dr := r - float64(entry.R)
		dg := g - float64(entry.G)
		db := b - float64(entry.B)
		// Slightly weight green, which better follows perceived map-art contrast.
		d := dr*dr*0.30 + dg*dg*0.59 + db*db*0.11
		if d < bestDist {
			bestDist = d
			best = entry
		}
	}
	return best
}

func suiteCreatorRender(img image.Image, outW, outH int, palette []suiteCreatorPaletteEntry, dither bool, fit, background string) ([]suiteCreatorPaletteEntry, *image.NRGBA, map[string]int, error) {
	if outW < 1 || outH < 1 || outW > 768 || outH > 768 {
		return nil, nil, nil, errors.New("地圖尺寸必須在 1x1～6x6（每張 128x128）")
	}
	if len(palette) == 0 {
		return nil, nil, nil, errors.New("色盤是空的")
	}
	background = strings.ToLower(strings.TrimSpace(background))
	if background == "" {
		background = "white"
	}
	pixels := make([]suiteCreatorPaletteEntry, outW*outH)
	preview := image.NewNRGBA(image.Rect(0, 0, outW, outH))
	usage := map[string]int{}
	type errRGB struct{ r, g, b float64 }
	curErr := make([]errRGB, outW+2)
	nextErr := make([]errRGB, outW+2)
	clamp := func(v float64) float64 {
		if v < 0 {
			return 0
		}
		if v > 255 {
			return 255
		}
		return v
	}
	for y := 0; y < outH; y++ {
		for x := range nextErr {
			nextErr[x] = errRGB{}
		}
		for x := 0; x < outW; x++ {
			c := suiteCreatorSample(img, x, y, outW, outH, fit)
			if c.A < 32 {
				switch background {
				case "transparent", "air":
					pixels[y*outW+x] = suiteCreatorPaletteEntry{}
					preview.SetNRGBA(x, y, color.NRGBA{A: 0})
					continue
				case "black":
					c = color.NRGBA{R: 0, G: 0, B: 0, A: 255}
				default:
					c = color.NRGBA{R: 255, G: 255, B: 255, A: 255}
				}
			}
			er := curErr[x+1]
			r := clamp(float64(c.R) + er.r)
			g := clamp(float64(c.G) + er.g)
			b := clamp(float64(c.B) + er.b)
			entry := suiteCreatorNearest(palette, r, g, b)
			pixels[y*outW+x] = entry
			usage[entry.Block]++
			preview.SetNRGBA(x, y, color.NRGBA{R: entry.R, G: entry.G, B: entry.B, A: 255})
			if dither {
				dr, dg, db := r-float64(entry.R), g-float64(entry.G), b-float64(entry.B)
				curErr[x+2].r += dr * 7 / 16
				curErr[x+2].g += dg * 7 / 16
				curErr[x+2].b += db * 7 / 16
				nextErr[x].r += dr * 3 / 16
				nextErr[x].g += dg * 3 / 16
				nextErr[x].b += db * 3 / 16
				nextErr[x+1].r += dr * 5 / 16
				nextErr[x+1].g += dg * 5 / 16
				nextErr[x+1].b += db * 5 / 16
				nextErr[x+2].r += dr * 1 / 16
				nextErr[x+2].g += dg * 1 / 16
				nextErr[x+2].b += db * 1 / 16
			}
		}
		curErr, nextErr = nextErr, curErr
	}
	return pixels, preview, usage, nil
}

func suiteCreatorPreviewDataURL(img image.Image) (string, error) {
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		return "", err
	}
	return "data:image/png;base64," + base64.StdEncoding.EncodeToString(buf.Bytes()), nil
}

func suiteLibrarySetTileMetaV194(botID int, itemID string, tileX, tileZ int, isMapTile bool) suiteLibraryItem {
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	list := suitePortState.data.Library[botID]
	for i := range list {
		if list[i].ID != itemID {
			continue
		}
		list[i].IsMapTile = isMapTile
		list[i].TileX = tileX
		list[i].TileZ = tileZ
		list[i].UpdatedAt = time.Now()
		suitePortState.data.Library[botID] = list
		_ = suiteSavePortStateLocked()
		return list[i]
	}
	return suiteLibraryItem{}
}

var suiteTileCoordPatternsV194 = []*regexp.Regexp{
	regexp.MustCompile(`(?i)\[\s*(\d+)\s*[,x_]\s*(\d+)\s*\]`),
	regexp.MustCompile(`(?i)(?:^|[_ .-])x(\d+)[_ .-]+z(\d+)(?:[_ .-]|$)`),
	regexp.MustCompile(`(?i)(?:^|[_ .-])(\d+)[_x-]+(\d+)(?:\.[^.]+)?$`),
}

func suiteInferTileCoordsV194(name string) (int, int, bool) {
	name = strings.TrimSpace(name)
	for _, re := range suiteTileCoordPatternsV194 {
		m := re.FindStringSubmatch(name)
		if len(m) != 3 {
			continue
		}
		x, xErr := strconv.Atoi(m[1])
		z, zErr := strconv.Atoi(m[2])
		if xErr != nil || zErr != nil {
			continue
		}
		// Reference UI presents tile positions as zero-based data internally, while
		// human-generated names commonly use 1-based coordinates. Bracket names are
		// generated by this app as [1,1], so normalise positive values to zero-based.
		if x > 0 {
			x--
		}
		if z > 0 {
			z--
		}
		return x, z, true
	}
	return 0, 0, false
}

func suiteCreatorGenerateGroup(botID int, name, sourceName string, mapsX, mapsZ int, pixels []suiteCreatorPaletteEntry) (suiteImportGroup, []suiteLibraryItem, error) {
	if mapsX < 1 || mapsX > 6 || mapsZ < 1 || mapsZ > 6 {
		return suiteImportGroup{}, nil, errors.New("地圖張數只能是 1～6 x 1～6")
	}
	outW := mapsX * 128
	outH := mapsZ * 128
	if len(pixels) != outW*outH {
		return suiteImportGroup{}, nil, errors.New("Creator 像素資料尺寸不一致")
	}
	name = strings.TrimSpace(name)
	if name == "" {
		name = strings.TrimSuffix(filepath.Base(sourceName), filepath.Ext(sourceName))
	}
	if name == "" {
		name = "地圖畫"
	}
	groupID := uuid.NewString()
	items := make([]suiteLibraryItem, 0, mapsX*mapsZ)
	itemIDs := make([]string, 0, mapsX*mapsZ)
	for tz := 0; tz < mapsZ; tz++ {
		for tx := 0; tx < mapsX; tx++ {
			cells := make([]BlueprintCell, 0, 128*129)
			for x := 0; x < 128; x++ {
				heights := [128]int{}
				h, minH := 0, 0
				any := false
				for z := 0; z < 128; z++ {
					px := pixels[(tz*128+z)*outW+(tx*128+x)]
					if px.Block == "" || px.Block == "minecraft:air" {
						heights[z] = h
						continue
					}
					any = true
					shade := px.Shade
					if px.MapColor > 0 {
						shade = px.MapColor % 4
					}
					if shade == 0 {
						h--
					} else if shade == 2 {
						h++
					}
					heights[z] = h
					if h < minH {
						minH = h
					}
				}
				if !any {
					continue
				}
				shift := -minH
				cells = append(cells, BlueprintCell{X: x, Y: shift, Z: 0, Block: "minecraft:stone"})
				for z := 0; z < 128; z++ {
					px := pixels[(tz*128+z)*outW+(tx*128+x)]
					if px.Block == "" || px.Block == "minecraft:air" {
						continue
					}
					cells = append(cells, BlueprintCell{X: x, Y: heights[z] + shift, Z: z + 1, Block: px.Block, MapColor: px.MapColor})
				}
			}
			if len(cells) == 0 {
				continue
			}
			bp, err := suiteBlueprintFromCells(fmt.Sprintf("%s [%d,%d]", name, tx+1, tz+1), cells)
			if err != nil {
				return suiteImportGroup{}, items, err
			}
			bp.Format = MapArtFormat
			// Java map-art uses a 128x129 construction footprint: 128 visible rows plus
			// one shading/baseline row. Reserve the full depth so claim-pool tiles never overlap.
			if bp.Depth < 129 {
				bp.Depth = 129
			}
			item, err := suiteSaveBlueprintArtifact(botID, groupID, sourceName, bp)
			if err != nil {
				return suiteImportGroup{}, items, err
			}
			item = suiteLibrarySetTileMetaV194(botID, item.ID, tx, tz, true)
			items = append(items, item)
			itemIDs = append(itemIDs, item.ID)
		}
	}
	if len(items) == 0 {
		return suiteImportGroup{}, nil, errors.New("圖片沒有產生任何可施工像素")
	}
	now := time.Now()
	group := suiteImportGroup{ID: groupID, BotID: botID, Name: name, Source: "creator:" + sourceName, ItemIDs: itemIDs, CreatedAt: now, UpdatedAt: now}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	suitePortState.data.ImportGroups[botID] = append(suitePortState.data.ImportGroups[botID], group)
	err := suiteSavePortStateLocked()
	suitePortState.Unlock()
	if err != nil {
		return suiteImportGroup{}, items, err
	}
	return group, items, nil
}

func suiteCreatorRequestSettings(r *http.Request) (mapsX, mapsZ int, paletteName string, dither bool, fit, background, name string, err error) {
	mapsX = suiteQueryInt(r, "maps_x", 1)
	mapsZ = suiteQueryInt(r, "maps_z", 1)
	if mapsX < 1 || mapsX > 6 || mapsZ < 1 || mapsZ > 6 {
		err = errors.New("地圖張數只能是 1～6 x 1～6")
		return
	}
	paletteName = strings.ToLower(strings.TrimSpace(r.URL.Query().Get("palette")))
	if paletteName == "" {
		paletteName = "mixed"
	}
	ditherRaw := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("dither")))
	dither = ditherRaw == "1" || ditherRaw == "true" || ditherRaw == "on" || ditherRaw == "yes"
	fit = strings.ToLower(strings.TrimSpace(r.URL.Query().Get("fit")))
	if fit == "" {
		fit = "crop"
	}
	if fit != "crop" && fit != "contain" && fit != "stretch" {
		err = errors.New("縮放方式只能是 crop/contain/stretch")
		return
	}
	background = strings.ToLower(strings.TrimSpace(r.URL.Query().Get("background")))
	if background == "" {
		background = "white"
	}
	if background != "white" && background != "black" && background != "transparent" && background != "air" {
		err = errors.New("背景只能是 white/black/transparent")
		return
	}
	name = strings.TrimSpace(r.URL.Query().Get("name"))
	return
}

func suiteImportGroupSnapshotV194(botID int, groupID string) (suiteImportGroup, []suiteLibraryItem, error) {
	groupID = strings.TrimSpace(groupID)
	if groupID == "" {
		return suiteImportGroup{}, nil, errors.New("group id is empty")
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	var found *suiteImportGroup
	for i := range suitePortState.data.ImportGroups[botID] {
		if suitePortState.data.ImportGroups[botID][i].ID == groupID {
			cp := suitePortState.data.ImportGroups[botID][i]
			found = &cp
			break
		}
	}
	library := append([]suiteLibraryItem(nil), suitePortState.data.Library[botID]...)
	suitePortState.Unlock()
	if found == nil {
		return suiteImportGroup{}, nil, errors.New("找不到匯入群組")
	}
	wanted := make(map[string]int, len(found.ItemIDs))
	for i, id := range found.ItemIDs {
		wanted[id] = i
	}
	items := make([]suiteLibraryItem, 0, len(found.ItemIDs))
	for _, item := range library {
		if _, ok := wanted[item.ID]; ok {
			items = append(items, item)
		}
	}
	sort.SliceStable(items, func(i, j int) bool { return wanted[items[i].ID] < wanted[items[j].ID] })
	return *found, items, nil
}

func suiteMosaicPlanV194(mapsX, mapsZ int, origin Vec3i, correction bool) map[string]interface{} {
	if mapsX < 1 {
		mapsX = 1
	}
	if mapsZ < 1 {
		mapsZ = 1
	}
	if correction {
		origin.X, origin.Z = suiteMapArtCorrectOriginV193(origin.X, origin.Z)
	}
	// Java map-art tiles use a 128x128 visible map plus one Z-row used by the
	// height/shading construction. Keeping a 129-block Z pitch prevents adjacent
	// tiles from sharing that construction row and matches the reference claim math.
	const tileW, tileD = 128, 129
	tiles := make([]map[string]interface{}, 0, mapsX*mapsZ)
	for z := 0; z < mapsZ; z++ {
		for x := 0; x < mapsX; x++ {
			start := Vec3i{X: origin.X + x*tileW, Y: origin.Y, Z: origin.Z + z*tileD}
			end := Vec3i{X: start.X + tileW - 1, Y: start.Y, Z: start.Z + tileD - 1}
			tiles = append(tiles, map[string]interface{}{
				"index":                z*mapsX + x + 1,
				"map_x":                x + 1,
				"map_z":                z + 1,
				"start":                start,
				"end":                  end,
				"outside_world_border": suiteMapArtOutsideWorldBorderV194(start),
			})
		}
	}
	bounds := Area{From: origin, To: Vec3i{X: origin.X + mapsX*tileW - 1, Y: origin.Y, Z: origin.Z + mapsZ*tileD - 1}}
	return map[string]interface{}{
		"origin":     origin,
		"maps_x":     mapsX,
		"maps_z":     mapsZ,
		"total":      mapsX * mapsZ,
		"tile_width": tileW,
		"tile_depth": tileD,
		"bounds":     bounds,
		"tiles":      tiles,
	}
}

func suitePlanImportGroupV194(botID int, groupID string, originX, originZ int, correction bool, buildServer, obstructionStrategy, endCityStrategy string) (map[string]interface{}, error) {
	group, items, err := suiteImportGroupSnapshotV194(botID, groupID)
	if err != nil {
		return nil, err
	}
	if correction {
		originX, originZ = suiteMapArtCorrectOriginV193(originX, originZ)
	}
	if obstructionStrategy == "" {
		obstructionStrategy = "shift_x"
	}
	if endCityStrategy == "" {
		endCityStrategy = "skip_nearby"
	}
	type positioned struct {
		item suiteLibraryItem
		x, z int
	}
	rows := make([]positioned, 0, len(items))
	fallbackX := 0
	for _, item := range items {
		x, z, ok := item.TileX, item.TileZ, item.IsMapTile
		if !ok {
			if ix, iz, parsed := suiteInferTileCoordsV194(item.Name); parsed {
				x, z, ok = ix, iz, true
			}
		}
		if !ok {
			x, z = fallbackX, 0
			fallbackX++
		}
		rows = append(rows, positioned{item: item, x: x, z: z})
	}
	if len(rows) == 0 {
		return nil, errors.New("匯入群組沒有可規劃項目")
	}
	minX, maxX, minZ, maxZ := rows[0].x, rows[0].x, rows[0].z, rows[0].z
	out := make([]map[string]interface{}, 0, len(rows))
	for _, row := range rows {
		if row.x < minX {
			minX = row.x
		}
		if row.x > maxX {
			maxX = row.x
		}
		if row.z < minZ {
			minZ = row.z
		}
		if row.z > maxZ {
			maxZ = row.z
		}
		startX := originX + row.x*128
		startZ := originZ + row.z*129
		out = append(out, map[string]interface{}{
			"tile": row.item, "startX": startX, "startZ": startZ,
			"obstructionStrategy": obstructionStrategy, "endCityStrategy": endCityStrategy, "buildServer": buildServer,
			"outsideWorldBorder": suiteMapArtOutsideWorldBorderV194(Vec3i{X: startX, Y: 64, Z: startZ}),
		})
	}
	bounds := map[string]int{
		"minX": originX + minX*128,
		"maxX": originX + maxX*128 + 127,
		"minZ": originZ + minZ*129,
		"maxZ": originZ + maxZ*129 + 128,
	}
	return map[string]interface{}{"ok": true, "group": group, "tiles": out, "bounds": bounds, "totalTiles": len(out)}, nil
}

func suiteWriteNBTStringV200(buf *bytes.Buffer, value string) error {
	if len(value) > 65535 {
		return errors.New("NBT 字串過長")
	}
	if err := binary.Write(buf, binary.BigEndian, uint16(len(value))); err != nil {
		return err
	}
	_, err := buf.WriteString(value)
	return err
}

func suiteWriteNBTNamedHeaderV200(buf *bytes.Buffer, tag byte, name string) error {
	if err := buf.WriteByte(tag); err != nil {
		return err
	}
	return suiteWriteNBTStringV200(buf, name)
}

// suiteEncodeVanillaStructureNBT writes a standard gzip-compressed Java Structure
// NBT file. The local Blueprint model intentionally contains block identifiers
// only, so the exporter preserves those identifiers and normalises coordinates
// into the structure's local origin.
func suiteEncodeVanillaStructureNBT(bp Blueprint) ([]byte, error) {
	if len(bp.Cells) == 0 {
		return nil, errors.New("藍圖沒有任何可輸出的方塊")
	}
	bounds := boundsForCells(bp.Cells)
	width := bp.Width
	if width <= 0 {
		width = bounds.MaxX - bounds.MinX + 1
	}
	depth := bp.Depth
	if depth <= 0 {
		depth = bounds.MaxZ - bounds.MinZ + 1
	}
	height := bounds.MaxY - bounds.MinY + 1
	if width <= 0 || depth <= 0 || height <= 0 {
		return nil, errors.New("藍圖尺寸無效")
	}
	if int64(width)*int64(depth)*int64(height) > 128_000_000 {
		return nil, errors.New("藍圖尺寸過大，無法安全輸出 Structure NBT")
	}

	paletteSet := make(map[string]struct{})
	for _, cell := range bp.Cells {
		block, err := NormaliseBlockName(cell.Block)
		if err != nil {
			return nil, err
		}
		if block == "minecraft:air" || block == "minecraft:cave_air" || block == "minecraft:void_air" {
			continue
		}
		paletteSet[block] = struct{}{}
	}
	if len(paletteSet) == 0 {
		return nil, errors.New("藍圖只有空氣，沒有可輸出方塊")
	}
	palette := make([]string, 0, len(paletteSet))
	for block := range paletteSet {
		palette = append(palette, block)
	}
	sort.Strings(palette)
	paletteIndex := make(map[string]int32, len(palette))
	for i, block := range palette {
		paletteIndex[block] = int32(i)
	}

	var raw bytes.Buffer
	if err := raw.WriteByte(10); err != nil { // root TAG_Compound
		return nil, err
	}
	if err := suiteWriteNBTStringV200(&raw, ""); err != nil {
		return nil, err
	}
	if err := suiteWriteNBTNamedHeaderV200(&raw, 3, "DataVersion"); err != nil {
		return nil, err
	}
	// 1.21-era Java data version. Structure loading is tolerant of older/newer
	// values; this is metadata and does not alter the palette/block payload.
	if err := binary.Write(&raw, binary.BigEndian, int32(3955)); err != nil {
		return nil, err
	}

	if err := suiteWriteNBTNamedHeaderV200(&raw, 9, "size"); err != nil {
		return nil, err
	}
	_ = raw.WriteByte(3) // list element TAG_Int
	_ = binary.Write(&raw, binary.BigEndian, int32(3))
	_ = binary.Write(&raw, binary.BigEndian, int32(width))
	_ = binary.Write(&raw, binary.BigEndian, int32(height))
	_ = binary.Write(&raw, binary.BigEndian, int32(depth))

	if err := suiteWriteNBTNamedHeaderV200(&raw, 9, "palette"); err != nil {
		return nil, err
	}
	_ = raw.WriteByte(10) // list element TAG_Compound
	_ = binary.Write(&raw, binary.BigEndian, int32(len(palette)))
	for _, block := range palette {
		if err := suiteWriteNBTNamedHeaderV200(&raw, 8, "Name"); err != nil {
			return nil, err
		}
		if err := suiteWriteNBTStringV200(&raw, block); err != nil {
			return nil, err
		}
		_ = raw.WriteByte(0) // end palette compound
	}

	validCells := make([]BlueprintCell, 0, len(bp.Cells))
	for _, cell := range bp.Cells {
		block, err := NormaliseBlockName(cell.Block)
		if err != nil {
			return nil, err
		}
		if _, ok := paletteIndex[block]; ok {
			cell.Block = block
			validCells = append(validCells, cell)
		}
	}
	if err := suiteWriteNBTNamedHeaderV200(&raw, 9, "blocks"); err != nil {
		return nil, err
	}
	_ = raw.WriteByte(10)
	_ = binary.Write(&raw, binary.BigEndian, int32(len(validCells)))
	for _, cell := range validCells {
		if err := suiteWriteNBTNamedHeaderV200(&raw, 9, "pos"); err != nil {
			return nil, err
		}
		_ = raw.WriteByte(3)
		_ = binary.Write(&raw, binary.BigEndian, int32(3))
		_ = binary.Write(&raw, binary.BigEndian, int32(cell.X-bounds.MinX))
		_ = binary.Write(&raw, binary.BigEndian, int32(cell.Y-bounds.MinY))
		_ = binary.Write(&raw, binary.BigEndian, int32(cell.Z-bounds.MinZ))
		if err := suiteWriteNBTNamedHeaderV200(&raw, 3, "state"); err != nil {
			return nil, err
		}
		_ = binary.Write(&raw, binary.BigEndian, paletteIndex[cell.Block])
		_ = raw.WriteByte(0)
	}

	if err := suiteWriteNBTNamedHeaderV200(&raw, 9, "entities"); err != nil {
		return nil, err
	}
	_ = raw.WriteByte(10)
	_ = binary.Write(&raw, binary.BigEndian, int32(0))
	_ = raw.WriteByte(0) // root compound end

	var out bytes.Buffer
	zw := gzip.NewWriter(&out)
	if _, err := zw.Write(raw.Bytes()); err != nil {
		_ = zw.Close()
		return nil, err
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

func suiteBlueprintPreviewPNGV200(bp Blueprint) ([]byte, error) {
	w, h := bp.Width, bp.Depth
	if w <= 0 || h <= 0 || w > 4096 || h > 4096 {
		return nil, errors.New("預覽尺寸無效或過大")
	}
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	colors := make(map[string]color.NRGBA)
	for _, row := range append(append(append([]suiteCreatorPaletteEntry{}, suiteCreatorConcretePalette...), suiteCreatorWoolPalette...), suiteCreatorTerracottaPalette...) {
		colors[strings.ToLower(row.Block)] = color.NRGBA{R: row.R, G: row.G, B: row.B, A: 255}
	}
	fallback := color.NRGBA{R: 125, G: 125, B: 125, A: 255}
	for _, cell := range bp.Cells {
		x, z := cell.X, cell.Z
		if x < 0 || z < 0 || x >= w || z >= h {
			continue
		}
		c, ok := colors[strings.ToLower(strings.TrimSpace(cell.Block))]
		if !ok {
			c = fallback
		}
		img.SetNRGBA(x, z, c)
	}
	var out bytes.Buffer
	if err := png.Encode(&out, img); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

func suiteSafeExportNameV200(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "mapart"
	}
	name = regexp.MustCompile(`[^0-9A-Za-z._\-\p{L}]+`).ReplaceAllString(name, "_")
	name = strings.Trim(name, "._-")
	if name == "" {
		name = "mapart"
	}
	if len([]rune(name)) > 80 {
		name = string([]rune(name)[:80])
	}
	return name
}

func suiteBlueprintTileV200(bp Blueprint, tileX, tileZ int) (Blueprint, bool) {
	x0, z0 := tileX*128, tileZ*128
	w := minInt(128, maxInt(0, bp.Width-x0))
	d := minInt(128, maxInt(0, bp.Depth-z0))
	if w <= 0 || d <= 0 {
		return Blueprint{}, false
	}
	cells := make([]BlueprintCell, 0, w*d)
	for _, c := range bp.Cells {
		if c.X < x0 || c.X >= x0+w || c.Z < z0 || c.Z >= z0+d {
			continue
		}
		c.X -= x0
		c.Z -= z0
		cells = append(cells, c)
	}
	if len(cells) == 0 {
		return Blueprint{}, false
	}
	out := Blueprint{Name: fmt.Sprintf("%s X%d Y%d", bp.Name, tileX+1, tileZ+1), Format: MapArtFormat, Width: w, Depth: d, Cells: cells}
	out.Bounds = boundsForCells(cells)
	out.Materials = MaterialTotalsCells(cells)
	return out, true
}

func suiteWriteMapArtArchiveV200(bp Blueprint) ([]byte, error) {
	if len(bp.Cells) == 0 {
		return nil, errors.New("請先產生有效藍圖")
	}
	base := suiteSafeExportNameV200(bp.Name)
	var out bytes.Buffer
	zw := zip.NewWriter(&out)
	write := func(name string, data []byte) error {
		f, err := zw.Create(name)
		if err != nil {
			return err
		}
		_, err = f.Write(data)
		return err
	}
	jsonData, err := json.MarshalIndent(bp, "", "  ")
	if err != nil {
		_ = zw.Close()
		return nil, err
	}
	if err := write(base+"-blueprint.json", jsonData); err != nil {
		_ = zw.Close()
		return nil, err
	}
	if pngData, pngErr := suiteBlueprintPreviewPNGV200(bp); pngErr == nil {
		if err := write(base+"-preview.png", pngData); err != nil {
			_ = zw.Close()
			return nil, err
		}
	}
	cols := maxInt(1, (bp.Width+127)/128)
	rows := maxInt(1, (bp.Depth+127)/128)
	written := 0
	for tz := 0; tz < rows; tz++ {
		for tx := 0; tx < cols; tx++ {
			tile, ok := suiteBlueprintTileV200(bp, tx, tz)
			if !ok {
				continue
			}
			nbt, err := suiteEncodeVanillaStructureNBT(tile)
			if err != nil {
				_ = zw.Close()
				return nil, fmt.Errorf("輸出 Tile X%d Y%d 失敗: %w", tx+1, tz+1, err)
			}
			name := fmt.Sprintf("structures/%s-X%02d-Y%02d.nbt", base, tx+1, tz+1)
			if err := write(name, nbt); err != nil {
				_ = zw.Close()
				return nil, err
			}
			written++
		}
	}
	if written == 0 {
		_ = zw.Close()
		return nil, errors.New("沒有可輸出的地圖 Tile")
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

func registerSuiteBlueprintExportV200() {
	http.HandleFunc("/api/suite/blueprint-export", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		if r.Method != http.MethodPost {
			mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "POST only"})
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 192<<20)
		var bp Blueprint
		if err := json.NewDecoder(r.Body).Decode(&bp); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "藍圖格式錯誤：" + err.Error()})
			return
		}
		if len(bp.Cells) == 0 {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "藍圖沒有方塊"})
			return
		}
		formatName := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("format")))
		base := suiteSafeExportNameV200(bp.Name)
		if formatName == "nbt" {
			data, err := suiteEncodeVanillaStructureNBT(bp)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			w.Header().Set("Content-Type", "application/octet-stream")
			w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s.nbt"`, strings.ReplaceAll(base, `"`, "")))
			_, _ = w.Write(data)
			return
		}
		data, err := suiteWriteMapArtArchiveV200(bp)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		w.Header().Set("Content-Type", "application/zip")
		w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s-mapart.zip"`, strings.ReplaceAll(base, `"`, "")))
		_, _ = w.Write(data)
	})
}

func registerSuiteCreatorRoute() {
	registerSuiteBlueprintExportV200()
	http.HandleFunc("/api/suite/creator", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			policy := append([]string(nil), suitePortState.data.MapPolicy[id]...)
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{
				"ok": true, "maps_min": 1, "maps_max": 6,
				"palettes": []string{"mapcolor", "mixed", "concrete", "wool", "terracotta"},
				"policy":   policy,
			})
			return
		}
		if r.Method != http.MethodPost {
			mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "Creator 預覽/產生需要 POST"})
			return
		}
		mapsX, mapsZ, paletteName, dither, fit, background, name, err := suiteCreatorRequestSettings(r)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		raw, sourceName, err := mapArtReadUpload(r, 24<<20)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		img, imageFormat, err := suiteCreatorDecodeImage(raw)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		palette, err := suiteCreatorPalette(id, paletteName)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		pixels, preview, usage, err := suiteCreatorRender(img, mapsX*128, mapsZ*128, palette, dither, fit, background)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		previewURL, err := suiteCreatorPreviewDataURL(preview)
		if err != nil {
			mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		base := map[string]interface{}{
			"ok": true, "source": sourceName, "image_format": imageFormat,
			"maps_x": mapsX, "maps_z": mapsZ, "width": mapsX * 128, "depth": mapsZ * 128,
			"palette": paletteName, "dither": dither, "fit": fit, "background": background,
			"materials": usage, "preview": previewURL,
		}
		switch action {
		case "preview":
			mapArtWriteJSON(w, http.StatusOK, base)
			return
		case "plan_mosaic":
			origin := Vec3i{X: suiteQueryInt(r, "x", 0), Y: suiteQueryInt(r, "y", 64), Z: suiteQueryInt(r, "z", 0)}
			base["plan"] = suiteMosaicPlanV194(mapsX, mapsZ, origin, suiteQueryCorrectionEnabledV193(r))
			mapArtWriteJSON(w, http.StatusOK, base)
			return
		case "generate":
			group, items, err := suiteCreatorGenerateGroup(id, name, sourceName, mapsX, mapsZ, pixels)
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error(), "partial_items": items})
				return
			}
			base["group"] = group
			base["items"] = items
			mapArtWriteJSON(w, http.StatusOK, base)
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知 Creator 操作"})
			return
		}
	})
}

func suiteDebugSnapshot(id int) map[string]interface{} {
	bot, _ := suiteLookupBot(id)
	if bot == nil {
		return map[string]interface{}{"ok": false, "error": "找不到 BOT"}
	}
	bot.mu.Lock()
	systemLogs := append([]string(nil), bot.SystemLogs...)
	gameLogs := append([]string(nil), bot.GameLogs...)
	logs := append([]string(nil), bot.Logs...)
	debugPosition := bot.LastPlayerPos
	debugSource := "reconciled_local"
	if bot.HasServerPlayerPos && bot.LastServerPlayerPos != ([3]float32{}) {
		debugPosition = bot.LastServerPlayerPos
		debugSource = "server"
	}
	successLogs := debugSuccessHistorySnapshotV371()
	row := map[string]interface{}{
		"ok": true, "bot_id": id, "bot_name": bot.Name, "connected": bot.Connected, "player_ready": bot.PlayerReady, "latency": bot.LatencyMS,
		"position": debugPosition, "position_source": debugSource, "local_position": bot.LastPlayerPos, "server_position": bot.LastServerPlayerPos,
		"last_packet": bot.SuiteLastPacketIn, "packet_in": bot.SuitePacketInCount, "packet_out": bot.SuitePacketOutCount,
		"entities": len(bot.SuiteEntities), "system_logs": systemLogs, "success_logs": successLogs, "problem_logs": debugProblemHistorySnapshotV369(), "game_logs": gameLogs, "logs": logs,
	}
	bot.mu.Unlock()
	taskSnapshot := bedrockSuiteTasks.snapshot(id)
	row["events"] = taskSnapshot
	return row
}

func suiteQueueHistoryDrawMaps(executorBotID int, taskIDs []string, claimOwnerBotID int, claimIDs []string, separateGroups bool) error {
	if _, err := suiteLookupBot(executorBotID); err != nil {
		return err
	}
	taskSet := map[string]bool{}
	for _, value := range taskIDs {
		if value = strings.TrimSpace(value); value != "" {
			taskSet[value] = true
		}
	}
	claimSet := map[string]bool{}
	for _, value := range claimIDs {
		if value = strings.TrimSpace(value); value != "" {
			claimSet[value] = true
		}
	}
	if len(taskSet) == 0 && len(claimSet) == 0 {
		return errors.New("沒有選取可重新繪製的歷史任務或領地")
	}
	if len(claimSet) > 0 && claimOwnerBotID <= 0 {
		return errors.New("選取領地時必須指定領地所屬 BOT")
	}

	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	if len(claimSet) > 0 {
		knownClaims := map[string]bool{}
		for _, claim := range suitePortState.data.BuildClaims[claimOwnerBotID] {
			knownClaims[claim.ID] = true
		}
		for claimID := range claimSet {
			if !knownClaims[claimID] {
				suitePortState.Unlock()
				return fmt.Errorf("找不到領地：%s", claimID)
			}
		}
	}
	selected := make([]suitePersistentHistory, 0, len(taskSet)+len(claimSet))
	foundTasks := map[string]bool{}
	seenHistory := map[string]bool{}
	for botID, entries := range suitePortState.data.History {
		for _, entry := range entries {
			if entry.Deleted {
				continue
			}
			selectedByTask := taskSet[entry.ID] || taskSet[entry.TaskID]
			selectedByClaim := botID == claimOwnerBotID && claimSet[strings.TrimSpace(suitePayloadString(entry.Payload, "claim_id", ""))]
			if !selectedByTask && !selectedByClaim {
				continue
			}
			key := entry.TaskID
			if key == "" {
				key = entry.ID
			}
			if seenHistory[key] {
				continue
			}
			seenHistory[key] = true
			if selectedByTask {
				foundTasks[entry.ID] = true
				foundTasks[entry.TaskID] = true
			}
			selected = append(selected, entry)
		}
	}
	suitePortState.Unlock()
	for taskID := range taskSet {
		if !foundTasks[taskID] {
			return fmt.Errorf("找不到歷史任務：%s", taskID)
		}
	}
	if len(selected) == 0 {
		return errors.New("所選項目沒有可重新繪製的歷史")
	}
	sort.SliceStable(selected, func(i, j int) bool {
		return selected[i].CompletedAt.Before(selected[j].CompletedAt)
	})

	batchID := uuid.NewString()
	queued := 0
	for _, entry := range selected {
		payload := suiteClonePayloadMap(entry.Payload)
		if payload == nil {
			payload = map[string]interface{}{}
		}
		libraryID := strings.TrimSpace(suitePayloadString(payload, "library_id", ""))
		if libraryID == "" {
			return fmt.Errorf("歷史任務 %s 沒有可重新繪製的地圖資料", entry.TaskID)
		}
		clonedItem, err := suiteCloneLibraryItemToBot(entry.BotID, executorBotID, libraryID)
		if err != nil {
			return fmt.Errorf("複製歷史地圖 %s 到執行 BOT 失敗：%w", libraryID, err)
		}
		payload["artifact_sha256"] = clonedItem.SHA256
		payload["materials"] = clonedItem.Materials
		payload["history_task_id"] = entry.TaskID
		payload["history_source_bot_id"] = entry.BotID
		if separateGroups {
			groupID := strings.TrimSpace(suitePayloadString(payload, "claim_id", ""))
			if groupID == "" {
				groupID = entry.ParentID
			}
			if groupID == "" {
				groupID = entry.TaskID
			}
			payload["history_group"] = groupID
		} else {
			payload["history_group"] = batchID
		}
		bedrockSuiteTasks.enqueue(executorBotID, "draw_map", "歷史重新繪製："+entry.Name, 70, payload)
		queued++
	}
	suiteRecordEvent(executorBotID, "TaskQueued", "info", fmt.Sprintf("已加入 %d 個歷史重新繪圖任務", queued), "", map[string]interface{}{"kind": "draw_map", "count": queued, "batch_id": batchID, "separate_groups": separateGroups})
	return nil
}

type suiteLocalMaterialUsage struct {
	Material string `json:"material"`
	Count    int    `json:"count"`
	Allowed  bool   `json:"allowed"`
}

func suiteLocalMaterialUsageForBot(botID int) []suiteLocalMaterialUsage {
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	items := append([]suiteLibraryItem(nil), suitePortState.data.Library[botID]...)
	policy := append([]string(nil), suitePortState.data.MapPolicy[botID]...)
	suitePortState.Unlock()

	counts := map[string]int{}
	for _, item := range items {
		for material, count := range item.Materials {
			material = suiteNormaliseMaterialID(material)
			if material != "" && count > 0 {
				counts[material] += count
			}
		}
	}
	allowed := map[string]bool{}
	for _, material := range policy {
		if material = suiteNormaliseMaterialID(material); material != "" {
			allowed[material] = true
		}
	}
	rows := make([]suiteLocalMaterialUsage, 0, len(counts))
	for material, count := range counts {
		rows = append(rows, suiteLocalMaterialUsage{Material: material, Count: count, Allowed: len(allowed) == 0 || allowed[material]})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].Count != rows[j].Count {
			return rows[i].Count > rows[j].Count
		}
		return rows[i].Material < rows[j].Material
	})
	return rows
}

func suiteLocalClaimPreview(botID int, claimID string) (map[string]interface{}, error) {
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	var found *suiteBuildClaim
	for i := range suitePortState.data.BuildClaims[botID] {
		if suitePortState.data.BuildClaims[botID][i].ID == claimID {
			claim := suitePortState.data.BuildClaims[botID][i]
			found = &claim
			break
		}
	}
	suitePortState.Unlock()
	if found == nil {
		return nil, errors.New("找不到領地")
	}
	area := NormaliseArea(Area{From: found.From, To: found.To})
	width := area.To.X - area.From.X + 1
	depth := area.To.Z - area.From.Z + 1
	columns := maxInt(1, (width+127)/128)
	rows := maxInt(1, (depth+127)/128)
	cells := make([]map[string]interface{}, 0, columns*rows)
	for row := 0; row < rows; row++ {
		for column := 0; column < columns; column++ {
			cells = append(cells, map[string]interface{}{
				"slot":  row*columns + column,
				"start": Vec3i{X: area.From.X + column*128, Y: area.From.Y, Z: area.From.Z + row*128},
			})
		}
	}
	return map[string]interface{}{"ok": true, "claim": found, "width": width, "depth": depth, "columns": columns, "rows": rows, "cells": cells}, nil
}

func suiteQueueImportGroupLocal(botID int, groupID, mode, claimID, storageID string) ([]suiteTask, error) {
	mode = strings.ToLower(strings.TrimSpace(mode))
	if mode == "" {
		mode = "draw_map"
	}
	if mode != "draw_map" && mode != "build" {
		return nil, errors.New("mode 只接受 draw_map/build")
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	var group *suiteImportGroup
	for i := range suitePortState.data.ImportGroups[botID] {
		if suitePortState.data.ImportGroups[botID][i].ID == groupID {
			copyGroup := suitePortState.data.ImportGroups[botID][i]
			group = &copyGroup
			break
		}
	}
	suitePortState.Unlock()
	if group == nil {
		return nil, errors.New("找不到匯入群組")
	}
	bot, err := suiteLookupBot(botID)
	if err != nil {
		return nil, err
	}
	base := Vec3i{}
	if claimID == "" {
		base, _, err = suiteCurrentPosition(bot)
		if err != nil {
			return nil, fmt.Errorf("整組排入需要已連線 BOT 的目前位置或領地池：%w", err)
		}
	}

	tasks := make([]suiteTask, 0, len(group.ItemIDs))
	xOffset := 0
	for _, itemID := range group.ItemIDs {
		_, item, loadErr := suiteLoadBlueprintArtifact(botID, itemID)
		if loadErr != nil {
			return tasks, fmt.Errorf("讀取群組項目 %s 失敗：%w", itemID, loadErr)
		}
		position := Vec3i{X: base.X + xOffset, Y: base.Y, Z: base.Z}
		claimSlot := -1
		if claimID != "" {
			position, claimSlot, loadErr = suiteReserveClaimSlot(botID, claimID, "", item.Name, item.Width, item.Depth)
			if loadErr != nil {
				return tasks, loadErr
			}
		} else {
			xOffset += maxInt(1, item.Width) + 1
		}
		kind := "draw_map"
		name := "地圖畫：" + item.Name
		if mode == "build" {
			kind = "build_library"
			name = "建築：" + item.Name
		}
		payload := map[string]interface{}{
			"library_id": itemID, "artifact_sha256": item.SHA256, "materials": item.Materials,
			"x": position.X, "y": position.Y, "z": position.Z, "rotation": "north",
			"storage_id": storageID, "claim_id": claimID, "claim_slot": claimSlot,
			"delay_ms": 300, "max_walk": 96, "skip_existing": true,
		}
		task := bedrockSuiteTasks.enqueue(botID, kind, name, 70, payload)
		if claimID != "" && claimSlot >= 0 {
			suiteAttachClaimTask(botID, claimID, claimSlot, task.ID)
		}
		tasks = append(tasks, task)
	}
	return tasks, nil
}

func registerSuiteLocalRoute() {
	http.HandleFunc("/api/suite/local", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		botID, _ := strconv.Atoi(r.URL.Query().Get("id"))
		bot, err := suiteLookupBot(botID)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		switch action {
		case "debug_logs":
			mapArtWriteJSON(w, http.StatusOK, suiteDebugSnapshot(botID))
		case "material_usage":
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "materials": suiteLocalMaterialUsageForBot(botID)})
		case "preview_claim":
			out, previewErr := suiteLocalClaimPreview(botID, strings.TrimSpace(r.URL.Query().Get("claim_id")))
			if previewErr != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": previewErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, out)
		case "discover_claims":
			owner := strings.TrimSpace(r.URL.Query().Get("owner"))
			if owner != "" {
				ctx, cancel := context.WithTimeout(r.Context(), 45*time.Second)
				defer cancel()
				candidates, discoverErr := suiteDiscoverPlayerClaimsV121(ctx, bot, owner)
				if discoverErr != nil {
					mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": discoverErr.Error()})
					return
				}
				mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "live": true, "candidates": candidates})
				return
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			claims := append([]suiteBuildClaim(nil), suitePortState.data.BuildClaims[botID]...)
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "live": false, "claims": claims})
		case "add_player_claim":
			playerID := strings.TrimSpace(r.URL.Query().Get("player_id"))
			owner := strings.TrimSpace(r.URL.Query().Get("owner"))
			if owner == "" {
				owner = playerID
			}
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				name = "玩家領地"
			}
			server := strings.TrimSpace(r.URL.Query().Get("server"))
			var from, to Vec3i
			hasBounds := false
			if x1, e1 := strconv.Atoi(r.URL.Query().Get("x1")); e1 == nil {
				if z1, e2 := strconv.Atoi(r.URL.Query().Get("z1")); e2 == nil {
					if x2, e3 := strconv.Atoi(r.URL.Query().Get("x2")); e3 == nil {
						if z2, e4 := strconv.Atoi(r.URL.Query().Get("z2")); e4 == nil {
							y := suiteQueryInt(r, "y", 64)
							from = Vec3i{X: x1, Y: y, Z: z1}
							to = Vec3i{X: x2, Y: y, Z: z2}
							hasBounds = true
						}
					}
				}
			}
			if !hasBounds {
				position, currentServer, positionErr := suiteCurrentPosition(bot)
				if positionErr != nil {
					mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": positionErr.Error()})
					return
				}
				width, depth := suiteQueryInt(r, "width", 128), suiteQueryInt(r, "depth", 129)
				if width < 1 || depth < 1 {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "領地寬度與深度必須大於 0"})
					return
				}
				from = position
				to = Vec3i{X: position.X + width - 1, Y: position.Y, Z: position.Z + depth - 1}
				if server == "" {
					server = currentServer
				}
			}
			area := NormaliseArea(Area{From: from, To: to})
			from, to = area.From, area.To
			claim := suiteBuildClaim{ID: uuid.NewString(), BotID: botID, Name: name, Owner: owner, Server: server, From: from, To: to, SourceMode: "player_claim", PlayerID: playerID, ClaimName: name, UpdatedAt: time.Now()}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			if validateErr := suiteValidateClaimV194(botID, claim, ""); validateErr != nil {
				suitePortState.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": validateErr.Error()})
				return
			}
			suitePortState.data.BuildClaims[botID] = append(suitePortState.data.BuildClaims[botID], claim)
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claim": claim})
		case "queue_import_group", "queue_import_claim_pool":
			claimID := ""
			if action == "queue_import_claim_pool" {
				claimID = strings.TrimSpace(r.URL.Query().Get("claim_id"))
				if claimID == "" {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先選擇領地池"})
					return
				}
			}
			tasks, queueErr := suiteQueueImportGroupLocal(botID, strings.TrimSpace(r.URL.Query().Get("group_id")), r.URL.Query().Get("mode"), claimID, strings.TrimSpace(r.URL.Query().Get("storage_id")))
			if queueErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": queueErr.Error(), "tasks": tasks})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "tasks": tasks})
		case "queue_history_draw":
			historyIDs := make([]string, 0)
			rawHistory := strings.TrimSpace(r.URL.Query().Get("history_ids"))
			if rawHistory == "" {
				rawHistory = strings.TrimSpace(r.URL.Query().Get("history_id"))
			}
			for _, value := range strings.FieldsFunc(rawHistory, func(ch rune) bool { return ch == ',' || ch == ';' || ch == '\n' || ch == '\r' }) {
				if value = strings.TrimSpace(value); value != "" {
					historyIDs = append(historyIDs, value)
				}
			}
			claimIDs := make([]string, 0)
			for _, value := range strings.FieldsFunc(strings.TrimSpace(r.URL.Query().Get("claim_ids")), func(ch rune) bool { return ch == ',' || ch == ';' || ch == '\n' || ch == '\r' }) {
				if value = strings.TrimSpace(value); value != "" {
					claimIDs = append(claimIDs, value)
				}
			}
			claimOwnerBotID, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("claim_owner_bot")))
			if len(claimIDs) > 0 && claimOwnerBotID <= 0 {
				claimOwnerBotID = botID
			}
			separateGroups := strings.EqualFold(strings.TrimSpace(r.URL.Query().Get("separate_groups")), "true") || strings.TrimSpace(r.URL.Query().Get("separate_groups")) == "1"
			if err := suiteQueueHistoryDrawMaps(botID, historyIDs, claimOwnerBotID, claimIDs, separateGroups); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "history_count": len(historyIDs), "claim_count": len(claimIDs), "separate_groups": separateGroups})
		case "events":
			snapshot := bedrockSuiteTasks.snapshot(botID)
			events := make([]suiteTask, 0)
			if queue, ok := snapshot["queue"].([]suiteTask); ok {
				events = append(events, queue...)
			}
			if history, ok := snapshot["history"].([]suiteTask); ok {
				events = append(events, history...)
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "events": events, "records": suiteStoredEvents(botID, 100)})
		case "issue_submit", "issue_list":
			mapArtWriteJSON(w, http.StatusGone, map[string]interface{}{"ok": false, "disabled": true, "error": "此版本不提供問題回報功能"})
			return
		case "issue_submit_legacy_disabled":
			if r.Method != http.MethodPost {
				mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "POST only"})
				return
			}
			r.Body = http.MaxBytesReader(w, r.Body, 64<<10)
			var request struct {
				Message string `json:"message"`
			}
			if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "問題描述格式錯誤"})
				return
			}
			report, submitErr := suiteSubmitLocalIssue(botID, request.Message)
			if submitErr != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": submitErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "report": report})
		case "issue_list_legacy_disabled":
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			reports := append([]suiteIssueReport(nil), suitePortState.data.IssueReports[botID]...)
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "reports": reports})
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知本機工具操作"})
		}
	})
}

func suiteSubmitLocalIssue(id int, message string) (suiteIssueReport, error) {
	message = strings.TrimSpace(message)
	if message == "" {
		return suiteIssueReport{}, errors.New("請填寫問題描述")
	}
	if len([]rune(message)) > 4000 {
		message = string([]rune(message)[:4000])
	}
	snap := suiteDebugSnapshot(id)
	// Avoid placing chat/game text or credentials into local issue snapshot.
	delete(snap, "game_logs")
	delete(snap, "logs")
	report := suiteIssueReport{ID: uuid.NewString(), BotID: id, Message: message, Status: "local", Snapshot: snap, CreatedAt: time.Now()}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	suitePortState.data.IssueReports[id] = append(suitePortState.data.IssueReports[id], report)
	err := suiteSavePortStateLocked()
	suitePortState.Unlock()
	return report, err
}

func registerSuiteRoutes() {
	registerSuiteCreatorRoute()
	registerSuiteLocalRoute()
	suiteLoadTaskStore()

	http.HandleFunc("/api/suite/dashboard", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			mapArtWriteJSON(w, http.StatusOK, suiteDashboardSnapshotAll())
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if id <= 0 {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "BOT ID 不正確"})
			return
		}
		switch action {
		case "start":
			if err := suiteSetBotActive(id, true); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
		case "stop":
			if err := suiteSetBotActive(id, false); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
		case "pause":
			bedrockSuiteTasks.setPaused(id, true)
		case "resume":
			bedrockSuiteTasks.setPaused(id, false)
		case "retry":
			taskID := strings.TrimSpace(r.URL.Query().Get("task_id"))
			if taskID == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "缺少 task_id"})
				return
			}
			if _, ok := bedrockSuiteTasks.retryTask(id, taskID); !ok {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到可重試任務"})
				return
			}
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知儀表板操作"})
			return
		}
		mapArtWriteJSON(w, http.StatusOK, suiteDashboardSnapshotAll())
	})

	http.HandleFunc("/api/suite/tasks", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			mapArtWriteJSON(w, http.StatusOK, bedrockSuiteTasks.snapshot(id))
			return
		}
		switch action {
		case "pause":
			bedrockSuiteTasks.setPaused(id, true)
		case "resume":
			bedrockSuiteTasks.setPaused(id, false)
		case "cancel":
			bedrockSuiteTasks.cancelTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
		case "remove":
			bedrockSuiteTasks.removeTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
		case "clear_finished":
			bedrockSuiteTasks.clearFinished(id)
		case "clear_queue":
			removed := bedrockSuiteTasks.clearQueue(id)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "removed": removed, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "retry":
			t, ok := bedrockSuiteTasks.retryTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
			if !ok {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到可重試的任務"})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "retry_failed":
			count := bedrockSuiteTasks.retryFailed(id)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "count": count})
			return
		case "resolve":
			resolution := map[string]interface{}{}
			if r.Method == http.MethodPost && r.Body != nil {
				_ = json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&resolution)
			}
			ok := bedrockSuiteTasks.resolveTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")), resolution)
			status := http.StatusOK
			if !ok {
				status = http.StatusConflict
			}
			mapArtWriteJSON(w, status, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "release":
			ok := bedrockSuiteTasks.releaseTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
			status := http.StatusOK
			if !ok {
				status = http.StatusConflict
			}
			mapArtWriteJSON(w, status, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "move_up":
			ok := bedrockSuiteTasks.reorderTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")), -1)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "move_down":
			ok := bedrockSuiteTasks.reorderTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")), 1)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "reassign":
			targetID, _ := strconv.Atoi(r.URL.Query().Get("target_bot"))
			t, ok := bedrockSuiteTasks.reassignTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")), targetID)
			if !ok {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "任務無法重新指派"})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "update":
			if r.Method != http.MethodPost {
				mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "更新任務需要 POST"})
				return
			}
			var req struct {
				TaskID   string                 `json:"task_id"`
				Name     string                 `json:"name"`
				Priority *int                   `json:"priority"`
				Payload  map[string]interface{} `json:"payload"`
			}
			if err := json.NewDecoder(io.LimitReader(r.Body, 2<<20)).Decode(&req); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "任務設定 JSON 無效：" + err.Error()})
				return
			}
			t, found, err := bedrockSuiteTasks.updateQueuedTask(id, strings.TrimSpace(req.TaskID), req.Name, req.Priority, req.Payload)
			if !found {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到任務"})
				return
			}
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "reconnect":
			ok := bedrockSuiteTasks.reconnectTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
			status := http.StatusOK
			if !ok {
				status = http.StatusConflict
			}
			mapArtWriteJSON(w, status, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "authenticated_resume":
			ok := bedrockSuiteTasks.resumeAuthenticatedTask(id, strings.TrimSpace(r.URL.Query().Get("task_id")))
			status := http.StatusOK
			if !ok {
				status = http.StatusConflict
			}
			mapArtWriteJSON(w, status, map[string]interface{}{"ok": ok, "snapshot": bedrockSuiteTasks.snapshot(id)})
			return
		case "enqueue_command":
			cmd := strings.TrimSpace(r.URL.Query().Get("command"))
			if cmd == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "指令不可空白"})
				return
			}
			t := bedrockSuiteTasks.enqueue(id, "command", "指令："+cmd, 40, map[string]interface{}{"command": cmd})
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "enqueue_eat":
			t := bedrockSuiteTasks.enqueue(id, "eat", "進食", 90, nil)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "enqueue_combat":
			t := bedrockSuiteTasks.enqueue(id, "combat", "攻擊附近敵對生物", 100, nil)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知任務操作"})
			return
		}
		mapArtWriteJSON(w, http.StatusOK, bedrockSuiteTasks.snapshot(id))
	})

	http.HandleFunc("/api/suite/build", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		bot, err := suiteLookupBot(id)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			mapArtWriteJSON(w, http.StatusOK, suiteBuildStatus(id, bot))
			return
		}
		ws := getSuiteBuildWorkspace(id)
		switch action {
		case "upload":
			data, name, err := mapArtReadUpload(r, 32<<20)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bp, err := ParseBuildBlueprint(data, name)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			ws.mu.Lock()
			ws.Blueprint = &bp
			ws.FileName = name
			ws.Plan = nil
			ws.Engine = NewMapArtEngine()
			ws.LastError = ""
			ws.mu.Unlock()
		case "plan":
			origin, coordErr := suiteRequiredQueryVec3(r, [3]string{"x", "y", "z"}, [3]string{"施工 X", "施工 Y", "施工 Z"})
			if coordErr != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": coordErr.Error()})
				return
			}
			rotation := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("rotation")))
			if rotation == "" {
				rotation = RotationNorth
			}
			ws.mu.Lock()
			if ws.Blueprint == nil {
				ws.mu.Unlock()
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先載入藍圖"})
				return
			}
			bp := suiteApplyBlockReplacements(*ws.Blueprint, ws.BlockReplacements)
			buildOrder := ws.BuildOrder
			ws.mu.Unlock()
			area, err := suiteBuildAreaForOrigin(bp, origin, rotation)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			plan, err := MakeBuildPlan(bp, origin, area, rotation, false)
			if err == nil {
				suiteApplyBuildOrder(&plan, buildOrder)
			}
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			ws.mu.Lock()
			ws.Plan = &plan
			ws.LastError = ""
			ws.mu.Unlock()
		case "settings":
			type buildSettingsPayload struct {
				PlacementMS       int               `json:"placement_ms"`
				MaxWalk           float64           `json:"max_walk"`
				SkipExisting      *bool             `json:"skip_existing"`
				StorageX          *int              `json:"storage_x"`
				StorageY          *int              `json:"storage_y"`
				StorageZ          *int              `json:"storage_z"`
				BlockReplacements map[string]string `json:"block_replacements"`
				ItemMappings      map[string]string `json:"item_mappings"`
				ReplacementsText  string            `json:"replacements_text"`
				ItemMappingsText  string            `json:"item_mappings_text"`
				BuildOrder        string            `json:"build_order"`
			}
			cfg := buildSettingsPayload{}
			if r.Method == http.MethodPost && r.Body != nil {
				_ = json.NewDecoder(io.LimitReader(r.Body, 2<<20)).Decode(&cfg)
			} else {
				cfg.PlacementMS, _ = strconv.Atoi(r.URL.Query().Get("placement_ms"))
				cfg.MaxWalk, _ = strconv.ParseFloat(r.URL.Query().Get("max_walk"), 64)
				skip := r.URL.Query().Get("skip_existing") != "0"
				cfg.SkipExisting = &skip
				if v, err := strconv.Atoi(r.URL.Query().Get("storage_x")); err == nil {
					cfg.StorageX = &v
				}
				if v, err := strconv.Atoi(r.URL.Query().Get("storage_y")); err == nil {
					cfg.StorageY = &v
				}
				if v, err := strconv.Atoi(r.URL.Query().Get("storage_z")); err == nil {
					cfg.StorageZ = &v
				}
				cfg.ReplacementsText = r.URL.Query().Get("replacements")
				cfg.ItemMappingsText = r.URL.Query().Get("item_mappings")
				cfg.BuildOrder = r.URL.Query().Get("build_order")
			}
			if cfg.BlockReplacements == nil && strings.TrimSpace(cfg.ReplacementsText) != "" {
				cfg.BlockReplacements = suiteParseMappingText(cfg.ReplacementsText)
			}
			if cfg.ItemMappings == nil && strings.TrimSpace(cfg.ItemMappingsText) != "" {
				cfg.ItemMappings = suiteParseMappingText(cfg.ItemMappingsText)
			}
			order := strings.TrimSpace(cfg.BuildOrder)
			upperOrder := strings.ToUpper(order)
			switch upperOrder {
			case "XYZ", "XZY", "YXZ", "YZX", "ZXY", "ZYX":
				order = upperOrder
			default:
				legacyOrder := strings.ToLower(order)
				switch legacyOrder {
				case "", "layer_snake", "top_down", "material", "nearest":
					order = legacyOrder
				default:
					order = "YZX"
				}
			}
			ws.mu.Lock()
			if cfg.PlacementMS >= 0 {
				ws.PlacementMS = cfg.PlacementMS
			}
			if cfg.MaxWalk > 0 {
				ws.MaxWalk = cfg.MaxWalk
			}
			if cfg.SkipExisting != nil {
				ws.SkipExisting = *cfg.SkipExisting
			}
			if cfg.StorageX != nil && cfg.StorageY != nil && cfg.StorageZ != nil {
				ws.Storage = Vec3i{X: *cfg.StorageX, Y: *cfg.StorageY, Z: *cfg.StorageZ}
				ws.StorageSet = true
			}
			if cfg.BlockReplacements != nil {
				ws.BlockReplacements = suiteCloneStringMap(cfg.BlockReplacements)
			}
			if cfg.ItemMappings != nil {
				ws.ItemMappings = suiteCloneStringMap(cfg.ItemMappings)
			}
			if order != "" {
				ws.BuildOrder = order
			}
			// 若已建過施工計畫，套用替換/順序後立即重新建立，避免畫面設定和實際任務不同步。
			if ws.Plan != nil && ws.Blueprint != nil {
				origin, area, rotation := ws.Plan.Origin, ws.Plan.Area, ws.Plan.Rotation
				bp := suiteApplyBlockReplacements(*ws.Blueprint, ws.BlockReplacements)
				if plan, planErr := MakeBuildPlan(bp, origin, area, rotation, false); planErr == nil {
					suiteApplyBuildOrder(&plan, ws.BuildOrder)
					ws.Plan = &plan
					ws.LastError = ""
				} else {
					ws.LastError = planErr.Error()
				}
			}
			ws.mu.Unlock()
		case "export_replaced":
			ws.mu.Lock()
			if ws.Blueprint == nil {
				ws.mu.Unlock()
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先載入藍圖"})
				return
			}
			bp := suiteApplyBlockReplacements(*ws.Blueprint, ws.BlockReplacements)
			base := strings.TrimSuffix(filepath.Base(ws.FileName), filepath.Ext(ws.FileName))
			ws.mu.Unlock()
			if base == "" {
				base = "blueprint"
			}
			data, exportErr := suiteEncodeVanillaStructureNBT(bp)
			if exportErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "輸出替換後藍圖失敗：" + exportErr.Error()})
				return
			}
			w.Header().Set("Content-Type", "application/octet-stream")
			w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s-replaced.nbt"`, strings.ReplaceAll(base, `"`, "")))
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write(data)
			return
		case "enqueue":
			ws.mu.Lock()
			if ws.Blueprint == nil || ws.Plan == nil {
				ws.mu.Unlock()
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先載入藍圖並建立施工計畫"})
				return
			}
			bpSnapshot := suiteApplyBlockReplacements(*ws.Blueprint, ws.BlockReplacements)
			planSnapshot := *ws.Plan
			delayMS := ws.PlacementMS
			maxWalk := ws.MaxWalk
			skipExisting := ws.SkipExisting
			storage := ws.Storage
			storageSet := ws.StorageSet
			itemMappings := suiteCloneStringMap(ws.ItemMappings)
			coordinateOrder := strings.TrimSpace(ws.BuildOrder)
			fileName := strings.TrimSpace(ws.FileName)
			ws.mu.Unlock()
			if requested := strings.TrimSpace(r.URL.Query().Get("coordinate_order")); requested != "" {
				coordinateOrder = requested
			}
			if coordinateOrder == "" {
				coordinateOrder = "YZX"
			}
			relPath, artifactHash, snapErr := suiteWriteBuildTaskSnapshotV191(bpSnapshot)
			if snapErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "建立建築任務快照失敗：" + snapErr.Error()})
				return
			}
			payload := map[string]interface{}{
				"blueprint_snapshot_path": relPath,
				"artifact_sha256":         artifactHash,
				"source_name":             fileName,
				"materials":               bpSnapshot.Materials,
				"x":                       planSnapshot.Origin.X,
				"y":                       planSnapshot.Origin.Y,
				"z":                       planSnapshot.Origin.Z,
				"rotation":                planSnapshot.Rotation,
				"delay_ms":                delayMS,
				"max_walk":                maxWalk,
				"skip_existing":           skipExisting,
				"coordinate_order":        coordinateOrder,
				"build_server":            strings.TrimSpace(r.URL.Query().Get("build_server")),
				"storage_id":              strings.TrimSpace(r.URL.Query().Get("storage_id")),
				"storage_set":             storageSet,
				"storage_x":               storage.X,
				"storage_y":               storage.Y,
				"storage_z":               storage.Z,
				"item_mappings":           itemMappings,
			}
			t := bedrockSuiteTasks.enqueue(id, "build", "藍圖建築", 60, payload)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t, "status": suiteBuildStatus(id, bot)})
			return
		case "pause":
			ws.mu.Lock()
			if ws.Engine != nil {
				ws.Engine.Pause()
			}
			ws.mu.Unlock()
		case "resume":
			ws.mu.Lock()
			if ws.Engine != nil {
				ws.Engine.Resume()
			}
			ws.mu.Unlock()
		case "stop":
			ws.mu.Lock()
			if ws.Engine != nil {
				ws.Engine.Stop()
			}
			ws.mu.Unlock()
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知建築操作"})
			return
		}
		mapArtWriteJSON(w, http.StatusOK, suiteBuildStatus(id, bot))
	})

	http.HandleFunc("/api/suite/explosion", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		ws := getSuiteExplosionWorkspace(id)
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			ws.mu.Lock()
			out := map[string]interface{}{
				"ok": true, "from": ws.From, "to": ws.To, "spacing": ws.Spacing, "mode": ws.Mode,
				"target_server": ws.TargetServer, "collect_item": ws.CollectItem, "collect_count": ws.CollectCount,
				"auto_pack": ws.AutoPack, "packing_home": ws.PackingHome, "use_back": ws.UseBack,
				"plane_block": ws.PlaneBlock, "handle_obsidian": ws.HandleObsidian,
				"collect_during": ws.CollectDuringExplosion, "last_error": ws.LastError,
			}
			ws.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, out)
			return
		}
		switch action {
		case "settings":
			from, fromErr := suiteRequiredQueryBlockVec3V99(r, [3]string{"x1", "y1", "z1"}, [3]string{"點 1 X", "點 1 Y", "點 1 Z"})
			if fromErr != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": fromErr.Error()})
				return
			}
			to, toErr := suiteRequiredQueryBlockVec3V99(r, [3]string{"x2", "y2", "z2"}, [3]string{"點 2 X", "點 2 Y", "點 2 Z"})
			if toErr != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": toErr.Error()})
				return
			}
			spacing, _ := strconv.Atoi(r.URL.Query().Get("spacing"))
			if spacing < 1 {
				spacing = 7
			}
			mode := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("mode")))
			switch mode {
			case "blast":
				mode = "explode"
			case "explode", "collect", "clear_bedrock", "place_plane", "clear_obsidian":
			default:
				mode = "explode"
			}
			targetServer, _ := strconv.Atoi(r.URL.Query().Get("target_server"))
			collectCount, _ := strconv.Atoi(r.URL.Query().Get("collect_count"))
			if collectCount <= 0 {
				collectCount = 64
			}
			collectItem := strings.TrimSpace(r.URL.Query().Get("collect_item"))
			if collectItem == "" {
				collectItem = "minecraft:netherrack"
			}
			planeBlock := strings.TrimSpace(r.URL.Query().Get("plane_block"))
			if planeBlock == "" {
				planeBlock = "minecraft:white_stained_glass"
			}
			ws.mu.Lock()
			ws.From = from
			ws.To = to
			ws.Spacing = spacing
			ws.Mode = mode
			ws.TargetServer = targetServer
			ws.CollectItem = collectItem
			ws.CollectCount = collectCount
			ws.AutoPack = r.URL.Query().Get("auto_pack") == "1" || strings.EqualFold(r.URL.Query().Get("auto_pack"), "true")
			ws.PackingHome = strings.TrimSpace(r.URL.Query().Get("packing_home"))
			ws.UseBack = r.URL.Query().Get("use_back") == "1" || strings.EqualFold(r.URL.Query().Get("use_back"), "true")
			ws.PlaneBlock = planeBlock
			ws.HandleObsidian = r.URL.Query().Get("handle_obsidian") == "1" || strings.EqualFold(r.URL.Query().Get("handle_obsidian"), "true")
			ws.CollectDuringExplosion = r.URL.Query().Get("collect_during") == "1" || strings.EqualFold(r.URL.Query().Get("collect_during"), "true")
			ws.LastError = ""
			ws.mu.Unlock()
			if err := saveSuiteExplosionSettings(id, ws); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "儲存爆破設定失敗：" + err.Error()})
				return
			}
			ws.mu.Lock()
			out := map[string]interface{}{
				"ok": true, "from": ws.From, "to": ws.To, "spacing": ws.Spacing, "mode": ws.Mode,
				"target_server": ws.TargetServer, "collect_item": ws.CollectItem, "collect_count": ws.CollectCount,
				"auto_pack": ws.AutoPack, "packing_home": ws.PackingHome, "use_back": ws.UseBack,
				"plane_block": ws.PlaneBlock, "handle_obsidian": ws.HandleObsidian,
				"collect_during": ws.CollectDuringExplosion, "last_error": ws.LastError,
			}
			ws.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, out)
			return
		case "enqueue":
			ws.mu.Lock()
			payload := map[string]interface{}{
				"mode": ws.Mode,
				"x1":   ws.From.X, "y1": ws.From.Y, "z1": ws.From.Z,
				"x2": ws.To.X, "y2": ws.To.Y, "z2": ws.To.Z,
				"spacing": ws.Spacing, "target_server": ws.TargetServer,
				"collect_item": ws.CollectItem, "collect_count": ws.CollectCount,
				"auto_pack": ws.AutoPack, "packing_home": ws.PackingHome, "use_back": ws.UseBack,
				"plane_block": ws.PlaneBlock, "handle_obsidian": ws.HandleObsidian,
				"collect_during": ws.CollectDuringExplosion,
			}
			mode := ws.Mode
			ws.mu.Unlock()
			t := bedrockSuiteTasks.enqueue(id, "explosion", suiteExplosionModeName(mode), 70, payload)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知爆破操作"})
			return
		}
	})

	http.HandleFunc("/api/suite/automation", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		bot, err := suiteLookupBot(id)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "save" {
			bot.mu.Lock()
			bot.SuiteAutomation.AutoEatEnabled = r.URL.Query().Get("auto_eat") == "1" || strings.EqualFold(r.URL.Query().Get("auto_eat"), "true")
			if v, err := strconv.ParseFloat(r.URL.Query().Get("eat_threshold"), 32); err == nil && v > 0 {
				bot.SuiteAutomation.EatHungerThreshold = float32(v)
			}
			bot.SuiteAutomation.AutoCombatEnabled = r.URL.Query().Get("auto_combat") == "1" || strings.EqualFold(r.URL.Query().Get("auto_combat"), "true")
			if v, err := strconv.ParseFloat(r.URL.Query().Get("combat_range"), 64); err == nil && v > 0 {
				bot.SuiteAutomation.CombatRange = v
			}
			bot.SuiteAutomation.CombatHostilesOnly = r.URL.Query().Get("hostiles_only") != "0"
			settings := bot.SuiteAutomation
			bot.mu.Unlock()
			if err := saveSuiteAutomationSettings(id, settings); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "儲存生存設定失敗：" + err.Error()})
				return
			}
			bot.suiteMaybeScheduleAutomations()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "settings": settings})
			return
		}
		bot.mu.Lock()
		settings := bot.SuiteAutomation
		vitals := map[string]interface{}{"health": bot.SuiteHealth, "max_health": bot.SuiteMaxHealth, "hunger": bot.SuiteHunger, "max_hunger": bot.SuiteMaxHunger, "saturation": bot.SuiteSaturation, "known": bot.SuiteVitalsKnown}
		entities := len(bot.SuiteEntities)
		bot.mu.Unlock()
		mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "settings": settings, "vitals": vitals, "entities": entities})
	})

	http.HandleFunc("/api/suite/storage", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		bot, err := suiteLookupBot(id)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			snap := suiteToolboxSnapshot(id)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "storage": snap["storage"]})
			return
		}
		switch action {
		case "current_position":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, server, posErr := suiteCurrentPosition(bot)
			if posErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": posErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "position": pos, "server": server})
			return
		case "scan":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "containers": suiteScanNearbyContainers(bot, rng)})
			return
		case "scan_facing":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			if rng <= 0 {
				rng = 8
			}
			row, ok := suiteScanFacingContainer(bot, rng)
			if !ok {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "面前沒有找到箱子/木桶/界伏盒；請看著箱子並保持在 8 格內"})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "container": row})
			return
		case "add_box":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			x, ex := strconv.Atoi(r.URL.Query().Get("x"))
			y, ey := strconv.Atoi(r.URL.Query().Get("y"))
			z, ez := strconv.Atoi(r.URL.Query().Get("z"))
			if profileID == "" || ex != nil || ey != nil || ez != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "加入箱子需要有效的倉庫設定檔與 X/Y/Z"})
				return
			}
			pos := Vec3i{X: x, Y: y, Z: z}
			if _, ok := suiteContainerBlockAt(bot, pos); !ok {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "這個座標目前不是已載入的箱子/木桶/界伏盒；請靠近後重新掃描"})
				return
			}

			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.StorageProfiles[id]
			idx := -1
			var profile suiteStorageProfile
			for i := range list {
				if list[i].ID == profileID {
					idx = i
					profile = list[i]
					break
				}
			}
			suitePortState.Unlock()
			if idx < 0 {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到倉庫設定"})
				return
			}

			release, actionErr := beginBedrockAction(r.Context(), bot, "加入材料箱")
			if actionErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": actionErr.Error()})
				return
			}
			box, scanErr := suiteScanStorageBoxAtControlled(r.Context(), bot, pos)
			release()
			box.Pinned = true
			if scanErr == nil {
				box.VerifiedAt = time.Now()
			}
			if scanErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "加入箱子失敗：" + scanErr.Error(), "box": box})
				return
			}

			replaced := false
			for i := range profile.Boxes {
				if profile.Boxes[i].Position == pos {
					profile.Boxes[i] = box
					replaced = true
					break
				}
			}
			if !replaced {
				profile.Boxes = append(profile.Boxes, box)
			}
			profile.ScannedAt = time.Now()
			profile.LastScanFound = len(profile.Boxes)
			profile.LastScanOpened = len(profile.Boxes)
			profile.LastScanFailed = 0
			profile.UpdatedAt = time.Now()
			profile.Revision++

			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list = suitePortState.data.StorageProfiles[id]
			updated := false
			for i := range list {
				if list[i].ID == profileID {
					list[i] = profile
					updated = true
					break
				}
			}
			if updated {
				suitePortState.data.StorageProfiles[id] = list
			}
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			bot.mu.Lock()
			if bot.SuiteStorageProfile != nil && bot.SuiteStorageProfile.ID == profile.ID {
				suiteApplyStorageProfileLockedV111(bot, &profile)
			}
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile, "box": box, "replaced": replaced})
			return
		case "remove_box":
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			x, ex := strconv.Atoi(r.URL.Query().Get("x"))
			y, ey := strconv.Atoi(r.URL.Query().Get("y"))
			z, ez := strconv.Atoi(r.URL.Query().Get("z"))
			if profileID == "" || ex != nil || ey != nil || ez != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "移除箱子需要有效的倉庫設定檔與 X/Y/Z"})
				return
			}
			pos := Vec3i{X: x, Y: y, Z: z}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.StorageProfiles[id]
			found := -1
			var profile suiteStorageProfile
			for i := range list {
				if list[i].ID == profileID {
					found = i
					profile = list[i]
					break
				}
			}
			if found < 0 {
				suitePortState.Unlock()
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到倉庫設定"})
				return
			}
			nextBoxes := profile.Boxes[:0]
			removed := false
			for _, box := range profile.Boxes {
				if box.Position == pos {
					removed = true
					continue
				}
				nextBoxes = append(nextBoxes, box)
			}
			profile.Boxes = nextBoxes
			profile.LastScanFound = len(profile.Boxes)
			profile.LastScanOpened = len(profile.Boxes)
			profile.LastScanFailed = 0
			profile.UpdatedAt = time.Now()
			profile.Revision++
			list[found] = profile
			suitePortState.data.StorageProfiles[id] = list
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			bot.mu.Lock()
			if bot.SuiteStorageProfile != nil && bot.SuiteStorageProfile.ID == profile.ID {
				suiteApplyStorageProfileLockedV111(bot, &profile)
			}
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile, "removed": removed})
			return
		case "scan_status":
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			state := suiteStorageScanGet(id)
			var profile *suiteStorageProfile
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			for i := range suitePortState.data.StorageProfiles[id] {
				if profileID == "" || suitePortState.data.StorageProfiles[id][i].ID == profileID {
					cp := suitePortState.data.StorageProfiles[id][i]
					profile = &cp
					if profileID != "" {
						break
					}
				}
			}
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "scan": state, "profile": profile})
			return
		case "scan_profile":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.StorageProfiles[id]
			idx := -1
			var profile suiteStorageProfile
			for i := range list {
				if list[i].ID == profileID {
					idx = i
					profile = list[i]
					break
				}
			}
			suitePortState.Unlock()
			if idx < 0 {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到倉庫設定"})
				return
			}
			currentScan := suiteStorageScanGet(id)
			if currentScan.Running {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "材料箱正在掃描中", "scan": currentScan})
				return
			}
			discover := r.URL.Query().Get("discover") == "1" || strings.EqualFold(r.URL.Query().Get("discover"), "true")
			previousBoxes := append([]suiteStorageBox(nil), profile.Boxes...)
			previousPosition := profile.Position
			if discover {
				// User-triggered discovery defines the warehouse floor from the Bot's
				// current position. This repairs old profiles whose anchor was previously
				// overwritten by a chest on the wrong level. The previous useful profile
				// is restored if this pass cannot open any container.
				if currentPos, _, currentErr := suiteCurrentPosition(bot); currentErr == nil {
					profile.Position = currentPos
				}
				profile.Boxes = nil
			}
			started := suiteStorageScanSet(id, func(state *suiteStorageScanState) {
				*state = suiteStorageScanState{
					Running:     true,
					ProfileID:   profile.ID,
					ProfileName: profile.Name,
					Message:     "正在搜尋 BOT 附近的材料箱…",
					StartedAt:   time.Now(),
				}
			})
			go func(botID int, scanProfile suiteStorageProfile, oldBoxes []suiteStorageBox, oldPosition Vec3i, discover bool) {
				scanCtx, cancel := context.WithTimeout(context.Background(), 155*time.Second)
				defer cancel()
				result, scanErr := suiteScanStorageProfile(scanCtx, bot, scanProfile, oldBoxes...)
				if scanErr == nil && discover && result.LastScanOpened == 0 && len(oldBoxes) > 0 {
					// A discovery pass that cannot successfully open any candidate must
					// not wipe a previously useful warehouse. Restore both the old material
					// index and its anchor so a failed scan cannot shift the station floor.
					result.Boxes = oldBoxes
					result.Position = oldPosition
				}
				saveErr := error(nil)
				if scanErr == nil {
					suitePortState.Lock()
					suiteEnsurePortStateLocked()
					list := suitePortState.data.StorageProfiles[botID]
					found := false
					for i := range list {
						if list[i].ID == result.ID {
							list[i] = result
							found = true
							break
						}
					}
					if found {
						suitePortState.data.StorageProfiles[botID] = list
						saveErr = suiteSavePortStateLocked()
					}
					suitePortState.Unlock()
					if saveErr == nil {
						ws := getSuiteBuildWorkspace(botID)
						ws.mu.Lock()
						ws.Storage = result.Position
						ws.StorageSet = true
						ws.mu.Unlock()
						bot.mu.Lock()
						suiteApplyStorageProfileLockedV111(bot, &result)
						bot.mu.Unlock()
					}
				}
				finalErr := ""
				if scanErr != nil {
					finalErr = scanErr.Error()
				} else if saveErr != nil {
					finalErr = saveErr.Error()
				}
				suiteStorageScanSet(botID, func(state *suiteStorageScanState) {
					state.Running = false
					state.CurrentPos = nil
					state.Error = finalErr
					if finalErr != "" {
						state.Message = "掃描失敗：" + finalErr
					} else {
						state.Found = minInt(result.LastScanFound, 48)
						state.Opened = result.LastScanOpened
						state.Failed = result.LastScanFailed
						state.Current = minInt(state.Found, state.Opened+state.Failed)
						state.Message = fmt.Sprintf("掃描完成：成功 %d / %d，失敗 %d；已套用補料", state.Opened, state.Found, state.Failed)
					}
				})
			}(id, profile, previousBoxes, previousPosition, discover)
			mapArtWriteJSON(w, http.StatusAccepted, map[string]interface{}{"ok": true, "started": true, "scan": started})
			return
		case "add_current":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, server, err := suiteCurrentPosition(bot)
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				name = "倉庫 " + time.Now().Format("15:04")
			}
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			if rng <= 0 {
				rng = 24
			}
			profile := suiteStorageProfile{ID: uuid.NewString(), BotID: id, Name: name, Revision: 1, Server: server, StorageMode: strings.TrimSpace(r.URL.Query().Get("storage_mode")), WarpCommand: strings.TrimSpace(r.URL.Query().Get("warp")), ReturnMode: strings.TrimSpace(r.URL.Query().Get("return_mode")), Commands: strings.FieldsFunc(strings.ReplaceAll(r.URL.Query().Get("commands"), "\r", ""), func(r rune) bool { return r == '\n' || r == ';' }), Position: pos, ScanMode: strings.TrimSpace(r.URL.Query().Get("scan_mode")), ScanRange: rng, Offsets: suiteParseVec3Lines(r.URL.Query().Get("offsets")), UpdatedAt: time.Now()}
			if profile.StorageMode == "" {
				profile.StorageMode = "position"
			}
			if profile.ReturnMode == "" {
				if profile.StorageMode == "warp" || profile.StorageMode == "server" || strings.TrimSpace(profile.WarpCommand) != "" {
					profile.ReturnMode = "back"
				} else {
					profile.ReturnMode = "walk"
				}
			}
			if profile.ScanMode == "" {
				profile.ScanMode = "nearby_containers"
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			suitePortState.data.StorageProfiles[id] = append(suitePortState.data.StorageProfiles[id], profile)
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			ws := getSuiteBuildWorkspace(id)
			ws.mu.Lock()
			ws.Storage = profile.Position
			ws.StorageSet = true
			ws.mu.Unlock()
			bot.mu.Lock()
			suiteApplyStorageProfileLockedV111(bot, &profile)
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile})
			return
		case "save":
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			x, ex := strconv.Atoi(r.URL.Query().Get("x"))
			y, ey := strconv.Atoi(r.URL.Query().Get("y"))
			z, ez := strconv.Atoi(r.URL.Query().Get("z"))
			if ex != nil || ey != nil || ez != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "倉庫 X/Y/Z 必須是整數"})
				return
			}
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				name = "倉庫"
			}
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			if rng <= 0 {
				rng = 24
			}
			bot.mu.Lock()
			server := bot.ServerAddr
			bot.mu.Unlock()
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.StorageProfiles[id]
			found := -1
			for i := range list {
				if list[i].ID == profileID && profileID != "" {
					found = i
					break
				}
			}
			profile := suiteStorageProfile{ID: profileID, BotID: id, Name: name, Revision: 1, Server: server, StorageMode: strings.TrimSpace(r.URL.Query().Get("storage_mode")), WarpCommand: strings.TrimSpace(r.URL.Query().Get("warp")), ReturnMode: strings.TrimSpace(r.URL.Query().Get("return_mode")), Commands: strings.FieldsFunc(strings.ReplaceAll(r.URL.Query().Get("commands"), "\r", ""), func(r rune) bool { return r == '\n' || r == ';' }), Position: Vec3i{X: x, Y: y, Z: z}, ScanMode: strings.TrimSpace(r.URL.Query().Get("scan_mode")), ScanRange: rng, Offsets: suiteParseVec3Lines(r.URL.Query().Get("offsets")), UpdatedAt: time.Now()}
			if requestedServer := strings.TrimSpace(r.URL.Query().Get("server")); requestedServer != "" {
				profile.Server = requestedServer
			}
			if dx, e1 := strconv.Atoi(r.URL.Query().Get("drop_x")); e1 == nil {
				if dy, e2 := strconv.Atoi(r.URL.Query().Get("drop_y")); e2 == nil {
					if dz, e3 := strconv.Atoi(r.URL.Query().Get("drop_z")); e3 == nil {
						v := Vec3i{X: dx, Y: dy, Z: dz}
						profile.DropPosition = &v
					}
				}
			}
			if found >= 0 {
				old := list[found]
				profile.Revision = old.Revision + 1
				profile.Boxes = old.Boxes
				if len(profile.Offsets) == 0 {
					profile.Offsets = append([]Vec3i(nil), old.Offsets...)
				}
				if profile.DropPosition == nil {
					profile.DropPosition = old.DropPosition
				}
				profile.ScannedAt = old.ScannedAt
				profile.LastScanFound = old.LastScanFound
				profile.LastScanOpened = old.LastScanOpened
				profile.LastScanFailed = old.LastScanFailed
			}
			if profile.StorageMode == "" {
				if profile.WarpCommand != "" {
					profile.StorageMode = "warp"
				} else {
					profile.StorageMode = "position"
				}
			}
			if profile.ReturnMode == "" {
				if profile.StorageMode == "warp" || profile.StorageMode == "server" || strings.TrimSpace(profile.WarpCommand) != "" {
					profile.ReturnMode = "back"
				} else {
					profile.ReturnMode = "walk"
				}
			}
			if profile.ScanMode == "" {
				profile.ScanMode = "nearby_containers"
			}
			if profile.ID == "" {
				profile.ID = uuid.NewString()
			}
			if found >= 0 {
				list[found] = profile
			} else {
				list = append(list, profile)
			}
			suitePortState.data.StorageProfiles[id] = list
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			// Saving (including the UI autosave path) immediately becomes the shared
			// refill source for plane placement, TNT and map-art builds.
			ws := getSuiteBuildWorkspace(id)
			ws.mu.Lock()
			ws.Storage = profile.Position
			ws.StorageSet = true
			ws.mu.Unlock()
			bot.mu.Lock()
			suiteApplyStorageProfileLockedV111(bot, &profile)
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile})
			return
		case "remove":
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.StorageProfiles[id]
			next := list[:0]
			for _, p := range list {
				if p.ID != profileID {
					next = append(next, p)
				}
			}
			suitePortState.data.StorageProfiles[id] = next
			_ = suiteSavePortStateLocked()
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
			return
		case "apply", "go", "open":
			profileID := strings.TrimSpace(r.URL.Query().Get("profile_id"))
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			var profile *suiteStorageProfile
			for i := range suitePortState.data.StorageProfiles[id] {
				if suitePortState.data.StorageProfiles[id][i].ID == profileID {
					cp := suitePortState.data.StorageProfiles[id][i]
					profile = &cp
					break
				}
			}
			suitePortState.Unlock()
			if profile == nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到倉庫設定"})
				return
			}
			ws := getSuiteBuildWorkspace(id)
			ws.mu.Lock()
			ws.Storage = profile.Position
			ws.StorageSet = true
			ws.mu.Unlock()
			bot.mu.Lock()
			suiteApplyStorageProfileLockedV111(bot, profile)
			bot.mu.Unlock()
			if action == "go" {
				bot.mu.Lock()
				scanBusy := bot.BedrockActionRunning && strings.TrimSpace(bot.BedrockActionKind) == "掃描材料箱"
				bot.mu.Unlock()
				if scanBusy {
					mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "材料箱正在掃描中；掃描完成後再前往倉庫，避免產生卡在等待資源的任務"})
					return
				}
				if strings.TrimSpace(profile.WarpCommand) != "" {
					t := bedrockSuiteTasks.enqueue(id, "command", "前往倉庫："+profile.Name, 70, map[string]interface{}{"command": profile.WarpCommand})
					mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile, "task": t})
					return
				}
				t := bedrockSuiteTasks.enqueue(id, "walk", "前往倉庫："+profile.Name, 70, map[string]interface{}{"x": profile.Position.X, "y": profile.Position.Y, "z": profile.Position.Z, "max_distance": 512})
				mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile, "task": t})
				return
			}
			if action == "open" {
				bot.mu.Lock()
				scanBusy := bot.BedrockActionRunning && strings.TrimSpace(bot.BedrockActionKind) == "掃描材料箱"
				bot.mu.Unlock()
				if scanBusy {
					mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "材料箱正在掃描中；掃描完成後再開啟倉庫"})
					return
				}
				t := bedrockSuiteTasks.enqueue(id, "container", "開啟倉庫："+profile.Name, 75, map[string]interface{}{"x": profile.Position.X, "y": profile.Position.Y, "z": profile.Position.Z})
				mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile, "task": t})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "profile": profile})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知倉庫操作"})
			return
		}
	})

	http.HandleFunc("/api/suite/claims", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		bot, err := suiteLookupBot(id)
		if err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			snap := suiteToolboxSnapshot(id)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claims": snap["claims"]})
			return
		}
		switch action {
		case "preview_current":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, server, posErr := suiteCurrentPosition(bot)
			if posErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": posErr.Error()})
				return
			}
			width := suiteQueryInt(r, "width", 128)
			depth := suiteQueryInt(r, "depth", 129)
			if width < 1 || depth < 1 {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "領地寬度與深度必須大於 0"})
				return
			}
			claim := suiteBuildClaim{BotID: id, Name: strings.TrimSpace(r.URL.Query().Get("name")), Owner: strings.TrimSpace(r.URL.Query().Get("owner")), Server: server, From: pos, To: Vec3i{X: pos.X + width - 1, Y: pos.Y, Z: pos.Z + depth - 1}, SourceMode: "current_position", UpdatedAt: time.Now()}
			area := NormaliseArea(Area{From: claim.From, To: claim.To})
			columns := maxInt(1, area.Width()/128)
			rows := maxInt(1, area.Depth()/129)
			claim.Slots = columns * rows
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claim": claim, "columns": columns, "rows": rows, "slots": claim.Slots, "saved": false})
			return
		case "add_current":
			if _, err := suiteGetBot(id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, server, err := suiteCurrentPosition(bot)
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			width, _ := strconv.Atoi(r.URL.Query().Get("width"))
			depth, _ := strconv.Atoi(r.URL.Query().Get("depth"))
			if width <= 0 {
				width = 128
			}
			if depth <= 0 {
				depth = 128
			}
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				name = "領地 " + time.Now().Format("15:04")
			}
			slots, _ := strconv.Atoi(r.URL.Query().Get("slots"))
			claim := suiteBuildClaim{ID: uuid.NewString(), BotID: id, Name: name, Owner: strings.TrimSpace(r.URL.Query().Get("owner")), Server: server, From: pos, To: Vec3i{X: pos.X + width - 1, Y: pos.Y, Z: pos.Z + depth - 1}, Slots: slots, SourceMode: "current_position", PlayerID: strings.TrimSpace(r.URL.Query().Get("player_id")), ClaimName: strings.TrimSpace(r.URL.Query().Get("claim_name")), UpdatedAt: time.Now()}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			if validateErr := suiteValidateClaimV194(id, claim, ""); validateErr != nil {
				suitePortState.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": validateErr.Error()})
				return
			}
			suitePortState.data.BuildClaims[id] = append(suitePortState.data.BuildClaims[id], claim)
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claim": claim})
			return
		case "save":
			claimID := strings.TrimSpace(r.URL.Query().Get("claim_id"))
			vals := make([]int, 6)
			keys := []string{"x1", "y1", "z1", "x2", "y2", "z2"}
			for i, key := range keys {
				v, err := strconv.Atoi(r.URL.Query().Get(key))
				if err != nil {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": key + " 必須是整數"})
					return
				}
				vals[i] = v
			}
			bot.mu.Lock()
			server := bot.ServerAddr
			bot.mu.Unlock()
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				name = "領地"
			}
			slots, _ := strconv.Atoi(r.URL.Query().Get("slots"))
			sourceMode := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("source_mode")))
			if sourceMode != "player_claim" {
				sourceMode = "current_position"
			}
			claim := suiteBuildClaim{ID: claimID, BotID: id, Name: name, Owner: strings.TrimSpace(r.URL.Query().Get("owner")), Server: server, From: Vec3i{X: vals[0], Y: vals[1], Z: vals[2]}, To: Vec3i{X: vals[3], Y: vals[4], Z: vals[5]}, Slots: slots, SourceMode: sourceMode, PlayerID: strings.TrimSpace(r.URL.Query().Get("player_id")), ClaimName: strings.TrimSpace(r.URL.Query().Get("claim_name")), UpdatedAt: time.Now()}
			if requestedServer := strings.TrimSpace(r.URL.Query().Get("server")); requestedServer != "" {
				claim.Server = requestedServer
			}
			if claim.ID == "" {
				claim.ID = uuid.NewString()
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.BuildClaims[id]
			if validateErr := suiteValidateClaimV194(id, claim, claimID); validateErr != nil {
				suitePortState.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": validateErr.Error()})
				return
			}
			found := -1
			for i := range list {
				if list[i].ID == claimID && claimID != "" {
					found = i
					break
				}
			}
			if found >= 0 {
				old := list[found]
				claim.Uses = append([]suiteClaimUse(nil), old.Uses...)
				if claim.Slots <= 0 {
					claim.Slots = old.Slots
				}
				if claim.PlayerID == "" {
					claim.PlayerID = old.PlayerID
				}
				if claim.ClaimName == "" {
					claim.ClaimName = old.ClaimName
				}
				list[found] = claim
			} else {
				list = append(list, claim)
			}
			suitePortState.data.BuildClaims[id] = list
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claim": claim})
			return
		case "remove":
			claimID := strings.TrimSpace(r.URL.Query().Get("claim_id"))
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.BuildClaims[id]
			next := list[:0]
			blocked := false
			found := false
			for _, c := range list {
				if c.ID == claimID {
					found = true
					for _, use := range c.Uses {
						if use.Status != "completed" && use.Status != "error" && use.Status != "cancelled" {
							blocked = true
							break
						}
					}
					if !blocked {
						continue
					}
				}
				next = append(next, c)
			}
			if !blocked {
				suitePortState.data.BuildClaims[id] = next
				_ = suiteSavePortStateLocked()
			}
			suitePortState.Unlock()
			if blocked {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "領地仍有等待/執行中的任務，不能移除"})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": found})
			return
		case "move_up", "move_down":
			claimID := strings.TrimSpace(r.URL.Query().Get("claim_id"))
			direction := -1
			if action == "move_down" {
				direction = 1
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.BuildClaims[id]
			idx := -1
			for i := range list {
				if list[i].ID == claimID {
					idx = i
					break
				}
			}
			target := idx + direction
			ok := idx >= 0 && target >= 0 && target < len(list)
			if ok {
				list[idx], list[target] = list[target], list[idx]
				suitePortState.data.BuildClaims[id] = list
				_ = suiteSavePortStateLocked()
			}
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": ok})
			return
		case "get":
			claimID := strings.TrimSpace(r.URL.Query().Get("claim_id"))
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			var claim *suiteBuildClaim
			for i := range suitePortState.data.BuildClaims[id] {
				if suitePortState.data.BuildClaims[id][i].ID == claimID {
					cp := suitePortState.data.BuildClaims[id][i]
					claim = &cp
					break
				}
			}
			suitePortState.Unlock()
			if claim == nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到領地"})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "claim": claim})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知領地操作"})
			return
		}
	})

	http.HandleFunc("/api/suite/toolbox", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "status" {
			mapArtWriteJSON(w, http.StatusOK, suiteToolboxSnapshot(id))
			return
		}
		switch action {

		case "save_map_tools":
			delay, _ := strconv.Atoi(r.URL.Query().Get("delay_ms"))
			if delay < 80 {
				delay = 350
			}
			if delay > 10000 {
				delay = 10000
			}
			qInt := func(key string, fallback int) int {
				v, err := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get(key)))
				if err != nil {
					return fallback
				}
				return v
			}
			qBool := func(key string) bool {
				v := strings.TrimSpace(r.URL.Query().Get(key))
				return v == "1" || strings.EqualFold(v, "true") || strings.EqualFold(v, "on") || strings.EqualFold(v, "yes")
			}
			settings := suiteMapToolSettings{
				StartCommands:            suiteSplitCommandLines(r.URL.Query().Get("start_commands")),
				BoxCommands:              suiteSplitCommandLines(r.URL.Query().Get("box_commands")),
				Owners:                   suiteSplitCommandLines(r.URL.Query().Get("owners")),
				AutoBuild:                qBool("auto_build"),
				BuildServer:              strings.TrimSpace(r.URL.Query().Get("build_server")),
				BuildHome:                strings.TrimSpace(r.URL.Query().Get("build_home")),
				DrawMapHome:              strings.TrimSpace(r.URL.Query().Get("draw_map_home")),
				DrawMapStart:             Vec3i{X: qInt("draw_map_x", 0), Y: qInt("draw_map_y", 64), Z: qInt("draw_map_z", 0)},
				BlankMapMarker:           strings.TrimSpace(r.URL.Query().Get("blank_map_marker")),
				RenameExperienceStrategy: strings.TrimSpace(r.URL.Query().Get("rename_exp_strategy")),
				RenameExperienceWarp:     strings.TrimSpace(r.URL.Query().Get("rename_exp_warp")),
				RenameServer:             strings.TrimSpace(r.URL.Query().Get("rename_server")),
				RenameWarp:               strings.TrimSpace(r.URL.Query().Get("rename_warp")),
				RenameInput:              Vec3i{X: qInt("rename_in_x", 0), Y: qInt("rename_in_y", 0), Z: qInt("rename_in_z", 0)},
				RenameOutput:             Vec3i{X: qInt("rename_out_x", 0), Y: qInt("rename_out_y", 0), Z: qInt("rename_out_z", 0)},
				RenameAnvil:              Vec3i{X: qInt("rename_anvil_x", 0), Y: qInt("rename_anvil_y", 0), Z: qInt("rename_anvil_z", 0)},
				StorageServer:            strings.TrimSpace(r.URL.Query().Get("storage_server")),
				StorageMode:              strings.TrimSpace(r.URL.Query().Get("storage_mode")),
				StorageWarpCommand:       strings.TrimSpace(r.URL.Query().Get("storage_warp")),
				StorageReturnMode:        strings.TrimSpace(r.URL.Query().Get("storage_return")),
				MaterialDropEnabled:      qBool("material_drop_enabled"),
				MaterialDrop:             Vec3i{X: qInt("material_drop_x", 0), Y: qInt("material_drop_y", 0), Z: qInt("material_drop_z", 0)},
				CopyCommand:              strings.TrimSpace(r.URL.Query().Get("copy_command")),
				RenameCommand:            strings.TrimSpace(r.URL.Query().Get("rename_command")),
				CommandDelay:             delay,
				FlexibleMatching:         qBool("flexible_matching"),
			}
			settings = suiteDefaultMapToolSettings(settings)
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			suitePortState.data.MapTools[id] = settings
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "settings": settings})
			return
		case "queue_box_commands":
			task, err := suiteQueueConfiguredBoxCommands(id)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": task})
			return
		case "run_start_commands":
			settings := suiteConfiguredMapTools(id)
			if len(settings.StartCommands) == 0 {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "尚未設定登入後啟動指令"})
				return
			}
			t := bedrockSuiteTasks.enqueue(id, "command_sequence", "登入後啟動指令", 60, map[string]interface{}{"commands": settings.StartCommands, "delay_ms": settings.CommandDelay})
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "save_map_policy":
			raw := strings.TrimSpace(r.URL.Query().Get("materials"))
			materials := make([]string, 0)
			seen := map[string]bool{}
			for _, part := range strings.FieldsFunc(raw, func(r rune) bool { return r == ',' || r == '\n' || r == '\r' || r == ';' }) {
				part = strings.ToLower(strings.TrimSpace(part))
				if part == "" {
					continue
				}
				if !strings.Contains(part, ":") {
					part = "minecraft:" + part
				}
				if !seen[part] {
					seen[part] = true
					materials = append(materials, part)
				}
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			suitePortState.data.MapPolicy[id] = materials
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "materials": materials})
			return
		case "queue_copy":
			count, _ := strconv.Atoi(r.URL.Query().Get("count"))
			if count < 1 {
				count = 1
			}
			if count > 1728 {
				count = 1728
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			settings := suitePortState.data.MapTools[id]
			suitePortState.Unlock()
			tpl := strings.TrimSpace(r.URL.Query().Get("command"))
			if tpl == "" {
				tpl = strings.TrimSpace(settings.CopyCommand)
			}
			cmds := make([]string, 0, count)
			if tpl != "" {
				for i := 1; i <= count; i++ {
					cmd := strings.ReplaceAll(tpl, "{n}", strconv.Itoa(i))
					cmds = append(cmds, cmd)
				}
			}
			flexibleMatching := settings.FlexibleMatching
			if raw := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("flexible_matching"))); raw != "" {
				flexibleMatching = raw == "1" || raw == "true" || raw == "on" || raw == "yes"
			}
			t := bedrockSuiteTasks.enqueue(id, "copy_map", fmt.Sprintf("複印地圖 × %d", count), 45, map[string]interface{}{"count": count, "commands": cmds, "delay_ms": settings.CommandDelay, "flexible_matching": flexibleMatching})
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "queue_rename":
			name := strings.TrimSpace(r.URL.Query().Get("name"))
			if name == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "新名稱不可空白"})
				return
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			settings := suitePortState.data.MapTools[id]
			suitePortState.Unlock()
			template := strings.TrimSpace(r.URL.Query().Get("template"))
			if template == "" {
				template = name
			}
			startX, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("start_x")))
			startY, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("start_y")))
			if startX < 0 {
				startX = 0
			}
			if startY < 0 {
				startY = 0
			}
			renderedName := suiteRenderRenameTemplateV191(template, startX, startY, 1, 1)
			if renderedName == "" {
				renderedName = name
			}
			tpl := strings.TrimSpace(r.URL.Query().Get("command"))
			if tpl == "" {
				tpl = strings.TrimSpace(settings.RenameCommand)
			}
			cmds := []string{}
			if tpl != "" {
				cmds = append(cmds, strings.ReplaceAll(tpl, "{name}", renderedName))
			}
			flexibleMatching := settings.FlexibleMatching
			if raw := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("flexible_matching"))); raw != "" {
				flexibleMatching = raw == "1" || raw == "true" || raw == "on" || raw == "yes"
			}
			t := bedrockSuiteTasks.enqueue(id, "rename_map", "命名地圖："+renderedName, 45, map[string]interface{}{"name": renderedName, "template": template, "start_x": startX, "start_y": startY, "map_index": 1, "map_total": 1, "commands": cmds, "delay_ms": settings.CommandDelay, "flexible_matching": flexibleMatching})
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "queue_command":
			cmd := strings.TrimSpace(r.URL.Query().Get("command"))
			if cmd == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "指令不可空白"})
				return
			}
			t := bedrockSuiteTasks.enqueue(id, "command", "能力任務："+cmd, 40, map[string]interface{}{"command": cmd})
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		case "cleanup_storage":
			result := suiteCleanupUnusedStorageV117(id)
			out := map[string]interface{}{"ok": true}
			for k, v := range result {
				out[k] = v
			}
			mapArtWriteJSON(w, http.StatusOK, out)
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知工具箱操作"})
			return
		}

	})

	http.HandleFunc("/api/suite/library", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "list" || action == "status" {
			mapArtWriteJSON(w, http.StatusOK, suiteLibrarySnapshot(id))
			return
		}
		switch action {
		case "save_blueprint":
			if r.Method != http.MethodPost {
				mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "POST only"})
				return
			}
			r.Body = http.MaxBytesReader(w, r.Body, 96<<20)
			var bp Blueprint
			if err := json.NewDecoder(r.Body).Decode(&bp); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "藍圖 JSON 讀取失敗：" + err.Error()})
				return
			}
			groupID := strings.TrimSpace(r.URL.Query().Get("group_id"))
			item, err := suiteSaveBlueprintArtifact(id, groupID, strings.TrimSpace(r.URL.Query().Get("source")), bp)
			if err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "item": item})
			return
		case "load":
			bp, item, err := suiteLoadBlueprintArtifact(id, strings.TrimSpace(r.URL.Query().Get("item_id")))
			if err != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "item": item, "blueprint": bp})
			return
		case "delete":
			ok := suiteDeleteLibraryItem(id, strings.TrimSpace(r.URL.Query().Get("item_id")))
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": ok})
			return
		case "use_build":
			bp, item, err := suiteLoadBlueprintArtifact(id, strings.TrimSpace(r.URL.Query().Get("item_id")))
			if err != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			ws := getSuiteBuildWorkspace(id)
			ws.mu.Lock()
			if ws.Engine != nil {
				ws.Engine.Stop()
			}
			ws.Blueprint = &bp
			ws.FileName = item.SourceName
			if ws.FileName == "" {
				ws.FileName = item.Name + ".json"
			}
			ws.Plan = nil
			ws.Engine = NewMapArtEngine()
			ws.LastError = ""
			ws.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "item": item})
			return
		case "use_mapart":
			bp, item, err := suiteLoadBlueprintArtifact(id, strings.TrimSpace(r.URL.Query().Get("item_id")))
			if err != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			ws := getMapArtWorkspace(id)
			ws.mu.Lock()
			if ws.Cancel != nil {
				ws.Cancel()
				ws.Cancel = nil
			}
			if ws.Engine != nil {
				ws.Engine.Stop()
			}
			ws.Blueprint = &bp
			ws.BlueprintFileName = item.SourceName
			if ws.BlueprintFileName == "" {
				ws.BlueprintFileName = item.Name + ".json"
			}
			ws.Plan = nil
			ws.Engine = NewMapArtEngine()
			ws.LastError = ""
			ws.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "item": item})
			return
		case "queue":
			itemID := strings.TrimSpace(r.URL.Query().Get("item_id"))
			_, item, err := suiteLoadBlueprintArtifact(id, itemID)
			if err != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mode := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("mode")))
			if mode == "" {
				mode = "draw_map"
			}
			kind := "draw_map"
			name := "地圖畫：" + item.Name
			if mode == "build" {
				kind = "build_library"
				name = "建築：" + item.Name
			}
			if mode != "draw_map" && mode != "build" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "mode 只接受 draw_map/build"})
				return
			}
			claimID := strings.TrimSpace(r.URL.Query().Get("claim_id"))
			position := Vec3i{}
			if claimID == "" {
				var positionErr error
				position, positionErr = suiteRequiredQueryVec3(r, [3]string{"x", "y", "z"}, [3]string{"任務 X", "任務 Y", "任務 Z"})
				if positionErr != nil {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": positionErr.Error()})
					return
				}
			}
			px, py, pz := position.X, position.Y, position.Z
			correctionEnabled := suiteQueryCorrectionEnabledV193(r)
			obstructionStrategy := suiteNormaliseObstructionStrategyV193(r.URL.Query().Get("obstruction_strategy"))
			endCityStrategy := suiteNormaliseEndCityStrategyV193(r.URL.Query().Get("end_city_strategy"))
			claimSlot := -1
			if claimID == "" && correctionEnabled {
				px, pz = suiteMapArtCorrectOriginV193(px, pz)
			}
			if claimID != "" {
				start, slot, reserveErr := suiteReserveClaimSlot(id, claimID, "", item.Name, item.Width, item.Depth)
				if reserveErr != nil {
					mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": reserveErr.Error()})
					return
				}
				px, py, pz = start.X, start.Y, start.Z
				claimSlot = slot
			}
			payload := map[string]interface{}{
				"library_id":            itemID,
				"artifact_sha256":       item.SHA256,
				"materials":             item.Materials,
				"x":                     px,
				"y":                     py,
				"z":                     pz,
				"rotation":              strings.TrimSpace(r.URL.Query().Get("rotation")),
				"storage_id":            strings.TrimSpace(r.URL.Query().Get("storage_id")),
				"claim_id":              claimID,
				"claim_slot":            claimSlot,
				"delay_ms":              suiteQueryInt(r, "delay_ms", 300),
				"max_walk":              suiteQueryFloat(r, "max_walk", 96),
				"skip_existing":         r.URL.Query().Get("skip_existing") != "0",
				"build_server":          strings.TrimSpace(r.URL.Query().Get("build_server")),
				"coordinate_order":      strings.TrimSpace(r.URL.Query().Get("coordinate_order")),
				"coordinate_correction": correctionEnabled,
				"obstruction_strategy":  obstructionStrategy,
				"end_city_strategy":     endCityStrategy,
				"allow_world_border":    r.URL.Query().Get("allow_world_border") == "1" || strings.EqualFold(r.URL.Query().Get("allow_world_border"), "true"),
			}
			t := bedrockSuiteTasks.enqueue(id, kind, name, 70, payload)
			if claimID != "" && claimSlot >= 0 {
				suiteAttachClaimTask(id, claimID, claimSlot, t.ID)
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t, "item": item})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知圖庫操作"})
			return
		}
	})

	http.HandleFunc("/api/suite/imports", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "list" {
			mapArtWriteJSON(w, http.StatusOK, suiteLibrarySnapshot(id))
			return
		}
		switch action {
		case "plan_mosaic":
			plan, planErr := suitePlanImportGroupV194(id, r.URL.Query().Get("group_id"), suiteQueryInt(r, "x", 0), suiteQueryInt(r, "z", 0), suiteQueryCorrectionEnabledV193(r), strings.TrimSpace(r.URL.Query().Get("build_server")), strings.TrimSpace(r.URL.Query().Get("obstruction_strategy")), strings.TrimSpace(r.URL.Query().Get("end_city_strategy")))
			if planErr != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": planErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, plan)
			return
		case "get_group", "group":
			group, items, groupErr := suiteImportGroupSnapshotV194(id, r.URL.Query().Get("group_id"))
			if groupErr != nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": groupErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "group": group, "items": items})
			return
		case "upload":
			if r.Method != http.MethodPost {
				mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "POST only"})
				return
			}
			data, name, err := mapArtReadUpload(r, 128<<20)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			groupID := uuid.NewString()
			groupName := strings.TrimSpace(r.URL.Query().Get("name"))
			if groupName == "" {
				groupName = strings.TrimSuffix(filepath.Base(name), filepath.Ext(name))
			}
			itemIDs := make([]string, 0)
			items := make([]suiteLibraryItem, 0)
			parseOne := func(fileName string, fileData []byte) error {
				bp, parseErr := ParseBuildBlueprint(fileData, fileName)
				if parseErr != nil {
					return parseErr
				}
				item, saveErr := suiteSaveBlueprintArtifact(id, groupID, fileName, bp)
				if saveErr != nil {
					return saveErr
				}
				if tx, tz, ok := suiteInferTileCoordsV194(fileName); ok {
					item = suiteLibrarySetTileMetaV194(id, item.ID, tx, tz, bp.Format == MapArtFormat)
				}
				itemIDs = append(itemIDs, item.ID)
				items = append(items, item)
				return nil
			}
			ext := strings.ToLower(filepath.Ext(name))
			if ext == ".zip" {
				zr, zipErr := zip.NewReader(bytes.NewReader(data), int64(len(data)))
				if zipErr != nil {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "ZIP 讀取失敗：" + zipErr.Error()})
					return
				}
				failures := make([]string, 0)
				for _, entry := range zr.File {
					if len(items) >= 128 || entry.FileInfo().IsDir() {
						continue
					}
					ext := strings.ToLower(filepath.Ext(entry.Name))
					if ext != ".json" && ext != ".litematic" && ext != ".nbt" && ext != ".schem" {
						continue
					}
					if entry.UncompressedSize64 > 96<<20 {
						failures = append(failures, filepath.Base(entry.Name)+"：檔案過大")
						continue
					}
					rc, openErr := entry.Open()
					if openErr != nil {
						failures = append(failures, filepath.Base(entry.Name)+"："+openErr.Error())
						continue
					}
					entryData, readErr := io.ReadAll(io.LimitReader(rc, 96<<20))
					_ = rc.Close()
					if readErr != nil {
						failures = append(failures, filepath.Base(entry.Name)+"："+readErr.Error())
						continue
					}
					if err := parseOne(filepath.Base(entry.Name), entryData); err != nil {
						failures = append(failures, filepath.Base(entry.Name)+"："+err.Error())
					}
				}
				if len(items) == 0 {
					msg := "ZIP 裡找不到可用的 JSON/Litematic/NBT/Schem 藍圖"
					if len(failures) > 0 {
						msg += "；" + strings.Join(failures[:minInt(len(failures), 5)], "；")
					}
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": msg})
					return
				}
			} else {
				if err := parseOne(name, data); err != nil {
					mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
					return
				}
			}
			now := time.Now()
			group := suiteImportGroup{ID: groupID, BotID: id, Name: groupName, Source: name, ItemIDs: itemIDs, CreatedAt: now, UpdatedAt: now}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			suitePortState.data.ImportGroups[id] = append(suitePortState.data.ImportGroups[id], group)
			saveErr := suiteSavePortStateLocked()
			suitePortState.Unlock()
			if saveErr != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": saveErr.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "group": group, "items": items})
			return
		case "delete_group":
			groupID := strings.TrimSpace(r.URL.Query().Get("group_id"))
			deleteItems := r.URL.Query().Get("keep_items") != "1"
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			groups := suitePortState.data.ImportGroups[id]
			next := groups[:0]
			itemIDs := make([]string, 0)
			for _, g := range groups {
				if g.ID == groupID {
					itemIDs = append(itemIDs, g.ItemIDs...)
					continue
				}
				next = append(next, g)
			}
			suitePortState.data.ImportGroups[id] = next
			_ = suiteSavePortStateLocked()
			suitePortState.Unlock()
			if deleteItems {
				for _, itemID := range itemIDs {
					suiteDeleteLibraryItem(id, itemID)
				}
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知匯入操作"})
			return
		}
	})

	http.HandleFunc("/api/suite/history", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		if _, err := suiteLookupBot(id); err != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "" || action == "list" {
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			history := append([]suitePersistentHistory(nil), suitePortState.data.History[id]...)
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "entries": history})
			return
		}
		entryID := strings.TrimSpace(r.URL.Query().Get("history_id"))
		switch action {
		case "delete_group":
			groupID := strings.TrimSpace(r.URL.Query().Get("group_id"))
			if groupID == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請指定歷史群組"})
				return
			}
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			itemGroups := map[string]string{}
			for _, item := range suitePortState.data.Library[id] {
				itemGroups[item.ID] = item.GroupID
			}
			changed := 0
			for i := range suitePortState.data.History[id] {
				h := &suitePortState.data.History[id][i]
				payloadGroup := strings.TrimSpace(suitePayloadString(h.Payload, "group_id", suitePayloadString(h.Payload, "group", "")))
				libraryID := strings.TrimSpace(suitePayloadString(h.Payload, "library_id", ""))
				if payloadGroup == groupID || itemGroups[libraryID] == groupID {
					if !h.Deleted {
						h.Deleted = true
						changed++
					}
				}
			}
			_ = suiteSavePortStateLocked()
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "deleted": changed})
			return
		case "delete":
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			for i := range suitePortState.data.History[id] {
				if suitePortState.data.History[id][i].ID == entryID || suitePortState.data.History[id][i].TaskID == entryID {
					suitePortState.data.History[id][i].Deleted = true
				}
			}
			_ = suiteSavePortStateLocked()
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
			return
		case "purge_deleted":
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			list := suitePortState.data.History[id]
			next := list[:0]
			for _, entry := range list {
				if !entry.Deleted {
					next = append(next, entry)
				}
			}
			suitePortState.data.History[id] = next
			_ = suiteSavePortStateLocked()
			suitePortState.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "count": len(next)})
			return
		case "restore", "retry":
			suitePortState.Lock()
			suiteEnsurePortStateLocked()
			var found *suitePersistentHistory
			for i := range suitePortState.data.History[id] {
				if suitePortState.data.History[id][i].ID == entryID || suitePortState.data.History[id][i].TaskID == entryID {
					cp := suitePortState.data.History[id][i]
					found = &cp
					break
				}
			}
			suitePortState.Unlock()
			if found == nil {
				mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到歷史任務"})
				return
			}
			payload := suiteClonePayloadMap(found.Payload)
			name := found.Name
			if action == "restore" {
				name = "恢復：" + name
			} else {
				name = "重試：" + name
			}
			t := bedrockSuiteTasks.enqueue(id, found.Kind, name, 70, payload)
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "task": t})
			return
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知歷史操作"})
			return
		}
	})
}

