// processingWaitForBoxSpaceV182 keeps a full output container open and waits for
// the server's own InventorySlot/InventoryContent update. A 20-second watchdog
// closes/reopens the viewer once so a lost notification cannot leave the BOT
// staring at an already-drained box forever.
func processingWaitForBoxSpaceV182(ctx context.Context, bot *BotSession, boxPos Vec3i, target, label string) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	resolved := bot.resolveDropItemTarget(target)
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		release, err := beginInternalBotActionWaitV186(ctx, bot, "加工循環｜等待箱子空位", true, false)
		if err != nil {
			if processingInventoryTransientV176(err) {
				if waitErr := processingWaitRetryV176(ctx, 4*time.Second); waitErr != nil {
					return waitErr
				}
				continue
			}
			return err
		}

		processingSetStageV159(bot, label, fmt.Sprintf(
			"使用搬運同款飛行路徑重新前往並監看 %s", boxPos,
		))
		err = processingOpenBoundContainerV392(ctx, bot, boxPos, label)
		if err != nil {
			release()
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				if ctx.Err() != nil {
					return ctx.Err()
				}
			}
			processingSetStageV159(bot, label, fmt.Sprintf("箱子暫時無法開啟｜%s 後自動重試", (1200*time.Millisecond).Round(100*time.Millisecond)))
			if waitErr := processingWaitRetryV176(ctx, 1200*time.Millisecond); waitErr != nil {
				return waitErr
			}
			continue
		}

		watchStarted := time.Now()
		for {
			if err := ctx.Err(); err != nil {
				_ = bedrockCloseContainerControlled(bot)
				release()
				return err
			}
			bot.mu.Lock()
			opened := bot.MapArtContainerOpen && bot.MapArtContainerPos == boxPos && bot.MapArtContainerItemsReady && bot.conn != nil
			space := false
			if opened {
				for _, item := range bot.MapArtContainerItems {
					if item.Stack.Count == 0 {
						space = true
						break
					}
					if item.Stack.Count >= 64 {
						continue
					}
					id := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
					if suiteBuildInventoryItemMatchesLocked(bot, resolved, item) ||
						suiteBuildInventoryItemMatchesLocked(bot, target, item) ||
						collectDropItemMatches(resolved, id) {
						space = true
						break
					}
				}
			}
			notify := bot.MapArtNotify
			bot.mu.Unlock()

			if space {
				// V424: seeing space at the verified output position proves the machine
				// has replaced/pushed the previously full box. Re-arm completion before
				// closing this viewer so the new box can produce exactly one notice.
				processingSyncOutputBoxCompletionV424(bot, boxPos, target)
				_ = bedrockCloseContainerControlled(bot)
				release()
				logCollectDiagnostic(bot, "processing_box_space_resume_v182", fmt.Sprintf("label=%s target=%s box=%s waited=%s", label, target, boxPos, time.Since(watchStarted).Round(10*time.Millisecond)))
				return nil
			}
			if !opened {
				_ = bedrockCloseContainerControlled(bot)
				release()
				processingSetStageV159(bot, label, "箱子狀態被中斷｜正在重新同步")
				if waitErr := processingWaitRetryV176(ctx, 800*time.Millisecond); waitErr != nil {
					return waitErr
				}
				break
			}

			elapsed := time.Since(watchStarted).Round(time.Second)
			processingSetStageV159(bot, label, fmt.Sprintf("箱子已滿｜保持監看 %s｜有空位立即恢復", elapsed))
			timer := time.NewTimer(20 * time.Second)
			select {
			case <-ctx.Done():
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				_ = bedrockCloseContainerControlled(bot)
				release()
				return ctx.Err()
			case <-notify:
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				continue
			case <-timer.C:
				// Watchdog refresh: a missed container update must never become a
				// permanent idle state. Re-open at a very low cadence instead of
				// repeatedly clicking the same box.
				_ = bedrockCloseContainerControlled(bot)
				release()
				processingSetStageV159(bot, label, "箱子仍滿｜重新同步一次後繼續等待")
				if waitErr := processingWaitRetryV176(ctx, 700*time.Millisecond); waitErr != nil {
					return waitErr
				}
				break
			}
		}
	}
}

// processingMoveCountViaCursorV167 mirrors a real Bedrock chest click for an
// exact amount: take the requested count onto the cursor, wait for the server's
// authoritative cursor StackNetworkID, then place that cursor stack into the
// open container. Some strict Bedrock/Geyser servers reject a direct
// inventory->container Place request (status=1) even though the same move is
// accepted when performed as native cursor clicks.
func processingMoveCountViaCursorV167(ctx context.Context, bot *BotSession, fromRef, toRef string, count int) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if count <= 0 || count > 255 {
		return errors.New("移動數量必須介於 1~255")
	}
	if strings.EqualFold(strings.TrimSpace(fromRef), strings.TrimSpace(toRef)) {
		return nil
	}
	ctx = suiteInternalInventoryContextV117(ctx)
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	bot.mu.Lock()
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return errors.New("BOT 尚未完成登入/出生")
	}
	if bot.MapArtCursor.Stack.Count != 0 {
		bot.mu.Unlock()
		return errors.New("游標目前有物品，無法執行存箱")
	}
	conn := bot.conn
	source, sourceContainer, sourceSlot, err := appInventoryRefLocked(bot, fromRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	destination, destinationContainer, destinationSlot, err := appInventoryRefLocked(bot, toRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	if source.Stack.Count < uint16(count) {
		bot.mu.Unlock()
		return fmt.Errorf("來源 %s 只有 %d 個，無法移動 %d 個", fromRef, source.Stack.Count, count)
	}
	if destination.Stack.Count > 0 {
		sourceID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, source)))
		destinationID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, destination)))
		if sourceID == "" || sourceID != destinationID || source.Stack.MetadataValue != destination.Stack.MetadataValue {
			bot.mu.Unlock()
			return errors.New("目的格不是空格或相同物品")
		}
		if int(destination.Stack.Count)+count > 64 {
			bot.mu.Unlock()
			return fmt.Errorf("目的格容量不足：目前 %d，要再放 %d", destination.Stack.Count, count)
		}
	}
	bot.mu.Unlock()

	cursorContainer := protocol.FullContainerName{ContainerID: byte(protocol.ContainerCursor)}
	takeRequestID := bot.nextMapArtStackRequestID()
	takeReq := protocol.ItemStackRequest{
		RequestID: takeRequestID,
		Actions: []protocol.StackRequestAction{collectNewTakeStackRequestAction(
			byte(count),
			protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: source.StackNetworkID},
			protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: 0},
		)},
		FilterCause: -1,
	}
	takePending := bedrockPendingStackRequest{RequestID: takeRequestID, Kind: "process_store_take_cursor_v167", CreatedAt: time.Now(), SourceSlot: sourceSlot, Source: source, Requested: count, SourceContainer: sourceContainer}
	takeResponse, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, takeReq, takePending, 3500*time.Millisecond)
	if err != nil {
		_ = requestBedrockInventoryResync(bot)
		return fmt.Errorf("存箱拿起物品失敗: %w", err)
	}

	sourceFallback := source
	if int(sourceFallback.Stack.Count) <= count {
		sourceFallback = protocol.ItemInstance{}
	} else {
		sourceFallback.Stack.Count -= uint16(count)
	}
	cursorFallback := source
	cursorFallback.Stack.Count = uint16(count)
	sourceAfter, found := appInventoryResponseItem(takeResponse, sourceContainer, sourceSlot, sourceFallback)
	if !found {
		sourceAfter = sourceFallback
	}
	cursorAfterTake, found := appInventoryResponseItem(takeResponse, cursorContainer, 0, cursorFallback)
	if !found {
		cursorAfterTake = cursorFallback
	}
	if cursorAfterTake.Stack.Count == 0 || cursorAfterTake.StackNetworkID == 0 {
		_ = requestBedrockInventoryResync(bot)
		return errors.New("存箱拿起物品失敗：伺服器沒有回傳游標物品編號")
	}
	appInventorySetMoveState(bot, fromRef, sourceAfter, cursorAfterTake)

	placeCount := int(cursorAfterTake.Stack.Count)
	if placeCount > count {
		placeCount = count
	}
	placeRequestID := bot.nextMapArtStackRequestID()
	placeReq := protocol.ItemStackRequest{
		RequestID: placeRequestID,
		Actions: []protocol.StackRequestAction{collectNewPlaceStackRequestAction(
			byte(placeCount),
			protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: cursorAfterTake.StackNetworkID},
			protocol.StackRequestSlotInfo{Container: destinationContainer, Slot: byte(destinationSlot), StackNetworkID: destination.StackNetworkID},
		)},
		FilterCause: -1,
	}
	placePending := bedrockPendingStackRequest{RequestID: placeRequestID, Kind: "process_store_place_cursor_v167", CreatedAt: time.Now(), SourceSlot: 0, Source: cursorAfterTake, Requested: placeCount, SourceContainer: cursorContainer}
	placeResponse, placeErr := bot.bedrockSendStandaloneStackRequest(ctx, conn, placeReq, placePending, 3500*time.Millisecond)
	if placeErr != nil {
		// Put the partial cursor stack back into the original source slot. Unlike the
		// generic swap rollback, this source may still contain the rest of the stack,
		// so preserve its authoritative StackNetworkID for the merge destination.
		rollbackRequestID := bot.nextMapArtStackRequestID()
		rollbackReq := protocol.ItemStackRequest{
			RequestID: rollbackRequestID,
			Actions: []protocol.StackRequestAction{collectNewPlaceStackRequestAction(
				byte(cursorAfterTake.Stack.Count),
				protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: cursorAfterTake.StackNetworkID},
				protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: sourceAfter.StackNetworkID},
			)},
			FilterCause: -1,
		}
		rollbackPending := bedrockPendingStackRequest{RequestID: rollbackRequestID, Kind: "process_store_rollback_v167", CreatedAt: time.Now(), SourceSlot: 0, Source: cursorAfterTake, Requested: int(cursorAfterTake.Stack.Count), SourceContainer: cursorContainer}
		rollbackResponse, rollbackErr := bot.bedrockSendStandaloneStackRequest(ctx, conn, rollbackReq, rollbackPending, 2500*time.Millisecond)
		if rollbackErr == nil {
			sourceFinal, ok := appInventoryResponseItem(rollbackResponse, sourceContainer, sourceSlot, source)
			if !ok {
				sourceFinal = source
			}
			cursorFinal, ok := appInventoryResponseItem(rollbackResponse, cursorContainer, 0, protocol.ItemInstance{})
			if !ok {
				cursorFinal = protocol.ItemInstance{}
			}
			appInventorySetMoveState(bot, fromRef, sourceFinal, cursorFinal)
		} else {
			_ = requestBedrockInventoryResync(bot)
			return fmt.Errorf("存箱放置失敗: %v；游標回復也失敗: %v", placeErr, rollbackErr)
		}
		return fmt.Errorf("存箱放置失敗: %w", placeErr)
	}

	destinationFallback := destination
	if destinationFallback.Stack.Count == 0 {
		destinationFallback = cursorAfterTake
		destinationFallback.Stack.Count = uint16(placeCount)
	} else {
		destinationFallback.Stack.Count += uint16(placeCount)
	}
	destinationAfter, found := appInventoryResponseItem(placeResponse, destinationContainer, destinationSlot, destinationFallback)
	if !found {
		destinationAfter = destinationFallback
	}
	cursorAfterPlace, found := appInventoryResponseItem(placeResponse, cursorContainer, 0, protocol.ItemInstance{})
	if !found {
		cursorAfterPlace = protocol.ItemInstance{}
	}
	appInventorySetMoveState(bot, toRef, destinationAfter, cursorAfterPlace)
	if cursorAfterPlace.Stack.Count != 0 {
		_ = requestBedrockInventoryResync(bot)
		return errors.New("存箱完成後游標仍有物品")
	}
	return nil
}

type processingLiveMachineSinkContextKeyV386 struct{}

func processingWithLiveMachineSinkV386(ctx context.Context) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	return context.WithValue(ctx, processingLiveMachineSinkContextKeyV386{}, true)
}

func processingIsLiveMachineSinkV386(ctx context.Context) bool {
	if ctx == nil {
		return false
	}
	v, _ := ctx.Value(processingLiveMachineSinkContextKeyV386{}).(bool)
	return v
}

const processingChestTransferGapV328 = 100 * time.Millisecond

// processingMoveCountToOpenContainerV169 performs the storage direction with the
// action shape already used by the App's direct inventory mover. On this server a
// cursor->container Place is rejected with status=1; for an empty chest slot the
// native direct action is Take(source inventory -> empty destination). Keep the
// cursor implementation above only as legacy/reference and do not use it here.
func processingMoveCountToOpenContainerInternalV386(ctx context.Context, bot *BotSession, fromRef, toRef string, count int, resyncOnError bool) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if count <= 0 || count > 255 {
		return errors.New("移動數量必須介於 1~255")
	}
	ctx = suiteInternalInventoryContextV117(ctx)
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	// V332: do not sleep after the caller selected inventory:X. A previous ACK,
	// merge, or inventory refresh can empty that slot during the delay. Read the
	// live source/destination and send immediately; apply the 100ms pacing AFTER
	// the server confirms this move.
	bot.mu.Lock()
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return errors.New("BOT 尚未完成登入/出生")
	}
	if bot.MapArtCursor.Stack.Count != 0 {
		bot.mu.Unlock()
		return errors.New("游標目前有物品，無法執行存箱")
	}
	conn := bot.conn
	source, sourceContainer, sourceSlot, err := appInventoryRefLocked(bot, fromRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	destination, destinationContainer, destinationSlot, err := appInventoryRefLocked(bot, toRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	if source.Stack.Count < uint16(count) {
		bot.mu.Unlock()
		return fmt.Errorf("來源 %s 只有 %d 個，無法移動 %d 個", fromRef, source.Stack.Count, count)
	}
	if destination.Stack.Count > 0 {
		sourceID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, source)))
		destinationID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, destination)))
		if sourceID == "" || sourceID != destinationID || source.Stack.MetadataValue != destination.Stack.MetadataValue {
			bot.mu.Unlock()
			return errors.New("目的格不是空格或相同物品")
		}
		if int(destination.Stack.Count)+count > 64 {
			bot.mu.Unlock()
			return fmt.Errorf("目的格容量不足：目前 %d，要再放 %d", destination.Stack.Count, count)
		}
	}
	bot.mu.Unlock()

	sourceInfo := protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: source.StackNetworkID}
	destinationInfo := protocol.StackRequestSlotInfo{Container: destinationContainer, Slot: byte(destinationSlot), StackNetworkID: destination.StackNetworkID}
	var action protocol.StackRequestAction
	kind := "process_store_take_direct_v169"
	if destination.Stack.Count == 0 {
		// appInventoryDirectMoveAction uses Take when the destination is empty.
		action = collectNewTakeStackRequestAction(byte(count), sourceInfo, destinationInfo)
	} else {
		// Only reached when no empty chest slot remains and a same-item partial stack
		// was selected. Place is the merge action for an occupied destination.
		kind = "process_store_merge_direct_v169"
		action = collectNewPlaceStackRequestAction(byte(count), sourceInfo, destinationInfo)
	}
	requestID := bot.nextMapArtStackRequestID()
	req := protocol.ItemStackRequest{RequestID: requestID, Actions: []protocol.StackRequestAction{action}, FilterCause: -1}
	pending := bedrockPendingStackRequest{RequestID: requestID, Kind: kind, CreatedAt: time.Now(), SourceSlot: sourceSlot, Source: source, Requested: count, SourceContainer: sourceContainer}
	response, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, req, pending, 3500*time.Millisecond)
	if err != nil {
		if resyncOnError {
			_ = requestBedrockInventoryResync(bot)
		}
		return err
	}

	sourceAfter := source
	if int(sourceAfter.Stack.Count) <= count {
		sourceAfter = protocol.ItemInstance{}
	} else {
		sourceAfter.Stack.Count -= uint16(count)
	}
	destinationAfter := destination
	if destinationAfter.Stack.Count == 0 {
		destinationAfter = source
		destinationAfter.Stack.Count = uint16(count)
	} else {
		destinationAfter.Stack.Count += uint16(count)
	}
	if authoritative, ok := appInventoryResponseItem(response, sourceContainer, sourceSlot, sourceAfter); ok {
		sourceAfter = authoritative
	}
	if authoritative, ok := appInventoryResponseItem(response, destinationContainer, destinationSlot, destinationAfter); ok {
		destinationAfter = authoritative
	}
	appInventoryApplyDirectMove(bot, fromRef, toRef, sourceAfter, destinationAfter)

	// V332: preserve the requested slower put-away speed, but only after ACK so
	// the next stack selection is based on a fresh server-authoritative mirror.
	if err := processingWaitSafeCadenceV176(ctx, bot, processingChestTransferGapV328); err != nil {
		return err
	}
	return nil
}

func processingMoveCountToOpenContainerV169(ctx context.Context, bot *BotSession, fromRef, toRef string, count int) error {
	return processingMoveCountToOpenContainerInternalV386(ctx, bot, fromRef, toRef, count, true)
}

func processingMoveCountToOpenContainerLiveMachineV386(ctx context.Context, bot *BotSession, fromRef, toRef string, count int) error {
	return processingMoveCountToOpenContainerInternalV386(ctx, bot, fromRef, toRef, count, false)
}

// depositBedrockInventoryItemToBoxV159 moves at most requested matching items to
// one verified container.  The caller passes the actual positive transaction
// delta, so the backpack is never reduced below its pre-transaction total even
// when Bedrock merged the new items into an older same-item stack.
func depositBedrockInventoryItemToBoxV159(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, requested int, allowProcess bool) (int, error) {
	if bot == nil {
		return 0, errors.New("找不到 BOT")
	}
	if requested <= 0 {
		return 0, nil
	}
	release, err := beginInternalBotActionWaitV186(ctx, bot, "兌換後存箱", allowProcess, !allowProcess)
	if err != nil {
		return 0, err
	}
	defer release()

	// V377: settle the freshly traded PLAYER inventory before opening the chest.
	// V376 refreshed after ContainerOpen; on Geyser that can interleave player
	// InventoryContent/Slot with the live chest stream and leave the machine box
	// visually open while the deposit loop sees the wrong container state.
	processingRefreshInventoryAfterTradeV170(ctx, bot)

	liveMachineSink := processingIsLiveMachineSinkV386(ctx)
	moveLabel := "加工成品/存放箱"
	moveStage := "前往成品箱"
	if liveMachineSink {
		moveLabel = "加工機器投料箱"
		moveStage = "前往機器投料箱"
	}
	processingSetStageV159(bot, moveStage, fmt.Sprintf(
		"使用搬運同款飛行路徑前往並開啟 %s", boxPos,
	))
	if err = processingOpenBoundContainerV392(ctx, bot, boxPos, moveLabel); err != nil {
		return 0, fmt.Errorf("%s移動/開啟失敗: %w", moveLabel, err)
	}
	defer bedrockCloseContainerControlled(bot)
	if !liveMachineSink {
		processingSyncOutputBoxCompletionV424(bot, boxPos, target)
	}

	resolvedTarget := bot.resolveDropItemTarget(target)
	initialInventoryCount := helperOutputInventoryCountV159(bot, resolvedTarget)
	if initialInventoryCount < requested {
		return 0, fmt.Errorf("背包只有 %d 個 %s，無法存入 %d 個", initialInventoryCount, target, requested)
	}
	expectedRemaining := initialInventoryCount - requested
	movedTotal := 0
	consecutiveRetries := 0
	totalRetries := 0
	liveSinkRaces := 0

	// V377: the player inventory was settled BEFORE ContainerOpen. From this point
	// onward the chest stays a pure live session and every accepted ItemStackResponse
	// updates both sides authoritatively. Do not inject a mismatch/resync here.
	for movedTotal < requested {
		if err := ctx.Err(); err != nil {
			return movedTotal, err
		}
		// A response timeout is ambiguous: the server may have committed the move
		// even though the matching response arrived too late. After a resync, infer
		// that progress from the authoritative remaining item count so a retry can
		// never deposit the same logical output twice.
		if inferred := initialInventoryCount - helperOutputInventoryCountV159(bot, resolvedTarget); inferred > movedTotal {
			if inferred > requested {
				inferred = requested
			}
			movedTotal = inferred
			if movedTotal >= requested {
				break
			}
		}

		matches, found := bot.bedrockSearchInventory(resolvedTarget, requested-movedTotal)
		if found <= 0 || len(matches) == 0 {
			break
		}
		match := matches[0]

		// V379: never call the double-chest target matcher while bot.mu is held.
		// Snapshot the open scene, validate it outside the mutex, then re-lock and
		// fence against a container-generation change before using the slot arrays.
		bot.mu.Lock()
		openNow := bot.MapArtContainerOpen
		readyNow := bot.MapArtContainerItemsReady
		connNow := bot.conn
		openPosNow := bot.MapArtContainerPos
		openSeqNow := bot.MapArtContainerOpenSeq
		containerRevisionNow := bot.MapArtContainerRevision
		bot.mu.Unlock()
		if !openNow || !readyNow || connNow == nil || !bedrockContainerOpenMatchesTargetV204(bot, boxPos, openPosNow) {
			return movedTotal, errors.New("存放箱已關閉、座標不符或內容尚未就緒")
		}

		bot.mu.Lock()
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady || bot.conn == nil ||
			bot.MapArtContainerOpenSeq != openSeqNow || bot.MapArtContainerPos != openPosNow {
			bot.mu.Unlock()
			continue
		}
		if match.Slot < 0 || match.Slot >= len(bot.MapArtInventory) {
			bot.mu.Unlock()
			return movedTotal, errors.New("來源背包格已失效")
		}
		source := bot.MapArtInventory[match.Slot]
		if source.Stack.Count == 0 {
			bot.mu.Unlock()
			continue
		}

		// V386: output boxes keep the established first-empty rule. The machine-input
		// box is different: a hopper/machine may consume from it while this loop is
		// depositing. For that live sink, prefer the highest-index empty/merge slot so
		// we are less likely to race the low slots a hopper normally drains first.
		destSlot := -1
		room := 0
		if liveMachineSink {
			for i := len(bot.MapArtContainerItems) - 1; i >= 0; i-- {
				if bot.MapArtContainerItems[i].Stack.Count == 0 {
					destSlot = i
					room = 64
					break
				}
			}
		} else {
			for i, item := range bot.MapArtContainerItems {
				if item.Stack.Count == 0 {
					destSlot = i
					room = 64
					break
				}
			}
		}
		if destSlot < 0 {
			sourceID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, source)))
			if liveMachineSink {
				for i := len(bot.MapArtContainerItems) - 1; i >= 0; i-- {
					item := bot.MapArtContainerItems[i]
					if item.Stack.Count == 0 || item.Stack.Count >= 64 {
						continue
					}
					itemID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
					if sourceID != "" && itemID == sourceID && item.Stack.MetadataValue == source.Stack.MetadataValue {
						destSlot = i
						room = 64 - int(item.Stack.Count)
						break
					}
				}
			} else {
				for i, item := range bot.MapArtContainerItems {
					if item.Stack.Count == 0 || item.Stack.Count >= 64 {
						continue
					}
					itemID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
					if sourceID != "" && itemID == sourceID && item.Stack.MetadataValue == source.Stack.MetadataValue {
						destSlot = i
						room = 64 - int(item.Stack.Count)
						break
					}
				}
			}
		}
		bot.mu.Unlock()
		if destSlot < 0 || room <= 0 {
			if !liveMachineSink {
				processingSyncOutputBoxCompletionV424(bot, boxPos, target)
			}
			return movedTotal, errors.New("指定存放箱已滿")
		}

		moveCount := requested - movedTotal
		if moveCount > int(source.Stack.Count) {
			moveCount = int(source.Stack.Count)
		}
		if moveCount > room {
			moveCount = room
		}
		if moveCount > 255 {
			moveCount = 255
		}
		if moveCount <= 0 {
			break
		}

		// V176: this server accepts inventory->empty-container as Take and rejects the
		// old Place-first probe. Send the accepted shape first. A rejection is treated
		// as stale authoritative state: resync, wait with bounded backoff, reselect the
		// source/destination, and occasionally reopen the container scene.
		fromRef := fmt.Sprintf("inventory:%d", match.Slot)
		toRef := fmt.Sprintf("container:%d", destSlot)
		if allowProcess {
			processingSetStageV159(bot, "存箱中", fmt.Sprintf(
				"%s｜已放 %d/%d｜背包格 %d → 箱子格 %d｜本次 %d 個",
				target, movedTotal, requested, match.Slot, destSlot, moveCount,
			))
		}
		beforeMoveInventory := helperOutputInventoryCountV159(bot, resolvedTarget)
		var moveErr error
		if liveMachineSink {
			moveErr = processingMoveCountToOpenContainerLiveMachineV386(ctx, bot, fromRef, toRef, moveCount)
		} else {
			moveErr = processingMoveCountToOpenContainerV169(ctx, bot, fromRef, toRef, moveCount)
		}
		if moveErr != nil {
			if !processingInventoryTransientV176(moveErr) {
				return movedTotal, fmt.Errorf("存放 %s 失敗: %w", target, moveErr)
			}

			// V379: a strict proxy can commit the ItemStackRequest but let the matching
			// response arrive after our request timeout. The live InventorySlot/Content
			// mirror is authoritative enough to prove that exact backpack decrease.
			// When proven, continue in the SAME open-container session instead of doing
			// the old multi-second close -> resync -> reopen recovery.
			if waitErr := processingWaitRetryV176(ctx, 120*time.Millisecond); waitErr != nil {
				return movedTotal, waitErr
			}
			afterMoveInventory := helperOutputInventoryCountV159(bot, resolvedTarget)
			committed := beforeMoveInventory - afterMoveInventory
			if committed > 0 {
				if committed > moveCount {
					committed = moveCount
				}
				if committed > requested-movedTotal {
					committed = requested - movedTotal
				}
				movedTotal += committed
				consecutiveRetries = 0
				logCollectDiagnostic(bot, "processing_store_late_ack_v379", fmt.Sprintf(
					"target=%s committed=%d requested_move=%d moved_total=%d/%d error=%v",
					target, committed, moveCount, movedTotal, requested, moveErr,
				))
				if allowProcess {
					processingSetStageV159(bot, "存箱延遲確認", fmt.Sprintf(
						"%s｜伺服器已實際收貨 %d 個｜累計 %d/%d｜直接續存，不重開箱",
						target, committed, movedTotal, requested,
					))
				}
				if !liveMachineSink {
					processingSyncOutputBoxCompletionV424(bot, boxPos, target)
				}
				continue
			}

			if liveMachineSink {
				liveSinkRaces++
				if liveSinkRaces <= 8 {
					logCollectDiagnostic(bot, "processing_machine_live_reselect_v386", fmt.Sprintf(
						"target=%s from=%s to=%s requested=%d race=%d revision=%d error=%v",
						target, fromRef, toRef, moveCount, liveSinkRaces, containerRevisionNow, moveErr,
					))
					if waitErr := processingWaitSourceRevisionV385(ctx, bot, openSeqNow, containerRevisionNow); waitErr != nil {
						return movedTotal, waitErr
					}
					// The machine may have consumed the chosen destination slot. Re-run
					// the loop immediately against the newest live container mirror.
					continue
				}
			}

			consecutiveRetries++
			totalRetries++
			if consecutiveRetries > 6 || totalRetries > 10 {
				return movedTotal, fmt.Errorf("存放 %s 經安全退避重試仍失敗: %w", target, moveErr)
			}
			delay := processingRetryDelayV176(consecutiveRetries)
			retryReason := "伺服器暫時拒絕"
			if strings.Contains(strings.ToLower(moveErr.Error()), "來源 inventory:") {
				retryReason = "背包格已被伺服器更新，重新選格"
			}
			processingSetStageV159(bot, "存箱同步重試", fmt.Sprintf(
				"%s｜%s｜第 %d 次｜%s 後重試",
				target, retryReason, totalRetries, delay.Round(10*time.Millisecond),
			))
			logCollectDiagnostic(bot, "processing_store_retry_v176", fmt.Sprintf(
				"target=%s moved=%d requested=%d attempt=%d delay=%s from=%s to=%s error=%v",
				target, movedTotal, requested, totalRetries, delay, fromRef, toRef, moveErr,
			))
			// V377: close first, then resync player inventory, then reopen. This keeps
			// the live container subscription and player resync packet streams separate.
			_ = bedrockCloseContainerControlled(bot)
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			if err := processingWaitRetryV176(ctx, delay); err != nil {
				return movedTotal, err
			}
			reopenErr := processingOpenBoundContainerV392(ctx, bot, boxPos, moveLabel+"重開")
			if reopenErr != nil {
				return movedTotal, fmt.Errorf("重新移動/開啟存放箱 %s 失敗: %w", boxPos, reopenErr)
			}
			liveSinkRaces = 0
			continue
		}
		consecutiveRetries = 0
		liveSinkRaces = 0
		movedTotal += moveCount
		if !liveMachineSink {
			processingSyncOutputBoxCompletionV424(bot, boxPos, target)
		}
	}
	// One best-effort final resync keeps the general UI/backpack mirror fresh
	// without stalling every individual stack transfer.
	if movedTotal > 0 {
		_ = requestBedrockInventoryResync(bot)
	}
	if helperOutputInventoryCountV159(bot, resolvedTarget) <= expectedRemaining {
		movedTotal = requested
	}
	if movedTotal != requested {
		return movedTotal, fmt.Errorf("只存入 %d / %d 個 %s", movedTotal, requested, target)
	}
	logCollectDiagnostic(bot, "processing_store_batch_v176", fmt.Sprintf(
		"target=%s requested=%d moved=%d retries=%d box=%s", target, requested, movedTotal, totalRetries, boxPos,
	))
	return movedTotal, nil
}

// processingSyncOutputBoxCompletionV424 makes the physical output container the
// authoritative definition of "one completed box". A source lot may contribute
// 832, 896, or any other amount; none of those numbers completes a box by itself.
// Only when the verified output container actually contains 1728 items (27x64)
// is one completion emitted. The full-notified fence survives App restart and is
// cleared only after the machine has replaced/pushed the full box and the same
// output position visibly has space again.
func processingSyncOutputBoxCompletionV424(bot *BotSession, boxPos Vec3i, target string) {
	if bot == nil {
		return
	}
	target = strings.TrimSpace(target)
	bot.mu.Lock()
	// This observer is processing-output specific. Generic purchase/source/machine
	// containers also use the shared deposit/wait engine and must never affect the
	// physical output-box completion fence.
	if !bot.ProcessOutputBoxConfigured || boxPos != bot.ProcessOutputBox ||
		!bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady || bot.conn == nil ||
		bot.MapArtContainerPos != boxPos {
		bot.mu.Unlock()
		return
	}
	total := 0
	for _, item := range bot.MapArtContainerItems {
		if item.Stack.Count > 0 {
			total += int(item.Stack.Count)
		}
	}
	wasNotified := bot.ProcessOutputBoxFullNotified
	shouldNotify := false
	stateChanged := false
	if total >= processingAutomationBoxBatchV317 {
		if !wasNotified {
			bot.ProcessOutputBoxFullNotified = true
			shouldNotify = true
			stateChanged = true
		}
	} else if wasNotified {
		// The machine has pushed/replaced the full shulker and this verified output
		// position is now the next box. Re-arm completion for the new physical box.
		bot.ProcessOutputBoxFullNotified = false
		stateChanged = true
	}
	botID := bot.ID
	bot.mu.Unlock()

	if stateChanged {
		if err := saveHelperProcessingConfig(bot); err != nil {
			logCollectDiagnostic(bot, "processing_output_box_fence_save_v424", fmt.Sprintf("total=%d target=%s error=%v", total, target, err))
		}
	}
	if !shouldNotify {
		return
	}
	if target == "" {
		target = "成品"
	}
	notice := fmt.Sprintf(
		"成品箱實際存入：%d / %d\n成品：%s\n完成判定：成品箱已滿，等待機器推掉滿盒並補上新的空盒",
		processingAutomationBoxBatchV317, processingAutomationBoxBatchV317, target,
	)
	discordWebhookEnqueueV414(botID, "processing_complete", "加工完成一盒", notice)
	logCollectDiagnostic(bot, "processing_output_box_complete_v424", fmt.Sprintf("target=%s physical_total=%d", target, total))
}

func processingContainerFillV375(items []protocol.ItemInstance) float64 {
	if len(items) <= 0 {
		return 0
	}
	total := 0
	for _, item := range items {
		if item.Stack.Count > 0 {
			total += int(item.Stack.Count)
		}
	}
	capacityItems := len(items) * 64
	if capacityItems <= 0 {
		return 0
	}
	fill := float64(total) / float64(capacityItems)
	if fill < 0 {
		return 0
	}
	if fill > 1 {
		return 1
	}
	return fill
}

// processingTakeFromBoxV159 fills the backpack to the V177 safe target in one
// container session. V179 deliberately keeps an empty source container open:
// hoppers/machines update an open viewer through InventorySlot/Content, so the
// Bot can react immediately without repeatedly clicking the same box and being
// classified as spam by the server.
const processingAutomationBoxBatchV317 = 1728 // 27 stacks × 64 = one full shulker-box worth.
const processingFixedMachineReturnPercentV393 = 50
const processingFixedMachineReturnItemsV418 = processingAutomationBoxBatchV317 * processingFixedMachineReturnPercentV393 / 100 // 864，永遠以一盒 1728 原料為基準。

// processingOpenBoundContainerV392 intentionally delegates to the transport
// opener. Processing keeps its own inventory/trade state machine, but every runtime
// move to source/machine/output now uses the exact transfer movement contract:
// 30s outer budget -> shared flight-only container opener -> ContainerOpen confirm.
// No processing-specific walking/A* fallback is allowed here.
func processingOpenBoundContainerV392(ctx context.Context, bot *BotSession, boxPos Vec3i, label string) error {
	if bot == nil {
		return errors.New("找不到加工 BOT")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	return transportOpenBoundContainerV344(ctx, bot, boxPos, strings.TrimSpace(label))
}

func processingWaitSourceRevisionV385(ctx context.Context, bot *BotSession, openSeq, revision uint64) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if bot == nil {
		return errors.New("找不到 BOT")
	}

	timer := time.NewTimer(45 * time.Millisecond)
	defer timer.Stop()
	for {
		bot.mu.Lock()
		stillOpen := bot.MapArtContainerOpen && bot.MapArtContainerOpenSeq == openSeq
		currentRevision := bot.MapArtContainerRevision
		notify := bot.MapArtNotify
		bot.mu.Unlock()

		if !stillOpen || currentRevision != revision {
			return nil
		}

		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-notify:
			// Server already pushed a new InventorySlot/Content. Re-check now.
		case <-timer.C:
			return nil
		}
	}
}

func processingTakeFromBoxV159(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, minCount, targetCount int) (int, float64, error) {
	if minCount < 1 {
		minCount = 1
	}
	if targetCount < minCount {
		targetCount = minCount
	}
	release, err := beginInternalBotActionWaitV186(ctx, bot, "加工循環｜來源箱", true, false)
	if err != nil {
		return 0, 0, err
	}
	defer release()
	processingSetStageV159(bot, "前往來源箱", fmt.Sprintf(
		"使用搬運同款飛行路徑前往並開啟 %s", boxPos,
	))
	if err := processingOpenBoundContainerV392(ctx, bot, boxPos, "加工來源箱"); err != nil {
		return 0, 0, fmt.Errorf("來源箱移動/開啟失敗: %w", err)
	}
	defer bedrockCloseContainerControlled(bot)

	resolved := bot.resolveDropItemTarget(target)
	taken := 0
	fill := 0.0
	batchAvailabilityVerified := false
	liveSourceRaces := 0
	for {
		if err := ctx.Err(); err != nil {
			return taken, fill, err
		}
		// V379: same double-chest lock rule as storage: validate the opened
		// container outside bot.mu, then re-lock only for the authoritative arrays.
		bot.mu.Lock()
		openNow := bot.MapArtContainerOpen
		readyNow := bot.MapArtContainerItemsReady
		connNow := bot.conn
		openPosNow := bot.MapArtContainerPos
		openSeqNow := bot.MapArtContainerOpenSeq
		containerRevisionNow := bot.MapArtContainerRevision
		bot.mu.Unlock()
		if !openNow || !readyNow || connNow == nil || !bedrockContainerOpenMatchesTargetV204(bot, boxPos, openPosNow) {
			return taken, fill, errors.New("來源箱已關閉、座標不符或內容尚未就緒")
		}

		bot.mu.Lock()
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady || bot.conn == nil ||
			bot.MapArtContainerOpenSeq != openSeqNow || bot.MapArtContainerPos != openPosNow {
			bot.mu.Unlock()
			continue
		}
		nonEmpty := 0
		sourceSlot := -1
		sourceAvailable := 0
		bestSourceCount := -1
		var source protocol.ItemInstance
		for i, item := range bot.MapArtContainerItems {
			if item.Stack.Count == 0 {
				continue
			}
			nonEmpty++
			id := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
			if suiteBuildInventoryItemMatchesLocked(bot, resolved, item) || suiteBuildInventoryItemMatchesLocked(bot, target, item) || collectDropItemMatches(resolved, id) {
				count := int(item.Stack.Count)
				sourceAvailable += count
				// V385: prefer the fullest stack. A hopper/machine normally mutates
				// the partial stack it is actively filling; a full x64 stack is much
				// more stable between our snapshot and ItemStackRequest send.
				if count > bestSourceCount {
					bestSourceCount = count
					sourceSlot, source = i, item
				}
			}
		}
		capacity := len(bot.MapArtContainerItems)
		fill = processingContainerFillV375(bot.MapArtContainerItems)
		bot.ProcessSourceFill = fill
		usedInventory := 0
		emptyDestSlot := -1
		mergeDestSlot := -1
		mergeDestCount := -1
		backpackMatching := 0
		for i := 0; i < 36; i++ {
			if i >= len(bot.MapArtInventory) {
				if emptyDestSlot < 0 {
					emptyDestSlot = i
				}
				continue
			}
			item := bot.MapArtInventory[i]
			if item.Stack.Count > 0 {
				usedInventory++
				id := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
				matchesTarget := suiteBuildInventoryItemMatchesLocked(bot, resolved, item) ||
					suiteBuildInventoryItemMatchesLocked(bot, target, item) ||
					collectDropItemMatches(resolved, id)
				if matchesTarget {
					backpackMatching += int(item.Stack.Count)
					// V321: never open a new inventory slot while the same exact item
					// has a compatible partial stack. Fill the fullest partial first.
					if sourceSlot >= 0 && item.Stack.Count < 64 &&
						appInventoryStackMergeCompatible(source, item) &&
						int(item.Stack.Count) > mergeDestCount {
						mergeDestSlot = i
						mergeDestCount = int(item.Stack.Count)
					}
				}
			} else if emptyDestSlot < 0 {
				emptyDestSlot = i
			}
		}
		destSlot := mergeDestSlot
		if destSlot < 0 {
			destSlot = emptyDestSlot
		}
		notify := bot.MapArtNotify
		bot.mu.Unlock()

		_ = capacity // retained for source-container diagnostics/shape parity.
		// V375: ProcessSourceFill was already updated from the authoritative open
		// container snapshot above. It is item-count based, so partial stacks no
		// longer look like a completely full source box.
		// V321 one-box semantics:
		// targetCount is the remaining committed lot (1728 at the start of a box).
		// It only has to exist across backpack + the still-open source container.
		// minCount is the smallest amount that must fit in the backpack before we
		// return to trading. This prevents the impossible condition where all 1728
		// must physically fit in the player's backpack at the same instant.
		availableForBatch := backpackMatching + sourceAvailable
		if availableForBatch < targetCount {
			if sourceSlot < 0 && nonEmpty > 0 {
				return taken, fill, fmt.Errorf("來源箱有物品，但找不到可辨識的 %s（解析為 %s）", target, resolved)
			}
			processingSetStageV159(bot, "等待來源", fmt.Sprintf(
				"%s 本盒可用 %d / %d｜來源箱保持開啟並即時接收機器補料，不重複開關箱",
				target, availableForBatch, targetCount,
			))
			logCollectDiagnostic(bot, "processing_source_hold_open_v321", fmt.Sprintf(
				"target=%s available=%d lot_required=%d backpack_min=%d box=%s",
				target, availableForBatch, targetCount, minCount, boxPos,
			))
			timer := time.NewTimer(2 * time.Second)
			select {
			case <-ctx.Done():
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				return taken, fill, ctx.Err()
			case <-notify:
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
			case <-timer.C:
			}
			continue
		}
		batchAvailabilityVerified = true
		if backpackMatching >= targetCount {
			break
		}
		if sourceSlot < 0 {
			break
		}

		// V317: drain one exact processing lot while this one container session stays open.
		// V177/V179: fill to 34 occupied slots normally and 35 when the source is
		// busy. Re-evaluate after every authoritative response so partial stacks or
		// unrelated inventory never make the loop overrun the emergency headroom.
		targetUsedSlots := 34
		if fill >= 0.55 {
			targetUsedSlots = 35
		}
		freeInventory := 36 - usedInventory
		if freeInventory < 0 {
			freeInventory = 0
		}
		allowEmergencyBatch := usedInventory >= targetUsedSlots && freeInventory > 0 && backpackMatching < minCount
		if usedInventory >= targetUsedSlots && !allowEmergencyBatch {
			// V322: the source chest is open here, so do not open the player inventory
			// scene on top of it. Return a tradeable chunk, close the chest, compact,
			// then continue the same 1728-lot on the next refill pass.
			if batchAvailabilityVerified && backpackMatching >= minCount {
				break
			}
			if freeInventory == 0 {
				return taken, fill, fmt.Errorf("背包沒有空格且目前 %s 只有 %d 個；來源箱關閉後會先整理堆疊", target, backpackMatching)
			}
			break
		}
		if destSlot < 0 {
			if batchAvailabilityVerified && backpackMatching >= minCount {
				break
			}
			return taken, fill, fmt.Errorf("背包沒有可用空格，且 %s 目前只有 %d 個；來源箱關閉後會先整理堆疊", target, backpackMatching)
		}
		moveCount := int(source.Stack.Count)
		if moveCount > 255 {
			moveCount = 255
		}
		remainingTarget := targetCount - backpackMatching
		if remainingTarget <= 0 {
			break
		}
		if moveCount > remainingTarget {
			moveCount = remainingTarget
		}
		if mergeDestSlot >= 0 && mergeDestCount >= 0 {
			room := 64 - mergeDestCount
			if moveCount > room {
				moveCount = room
			}
		}
		if moveCount <= 0 {
			continue
		}
		// V165: do not build a second chest->inventory Take request here.
		// This server rejected that path with ItemStackResponse status=1 even though
		// the chest was open and the source StackNetworkID was valid. Reuse the
		// workflow inventory mover instead: it resolves the live container/player
		// slot descriptors itself, sends the already-used Place-style authoritative
		// request, applies the authoritative response, and requests a resync on reject.
		fromRef := fmt.Sprintf("container:%d", sourceSlot)
		toRef := fmt.Sprintf("inventory:%d", destSlot)

		// V330: do NOT sleep after selecting sourceSlot. The source container can
		// change underneath us (hopper/server updates), so a pre-send 100ms delay
		// turns a valid "8 items in slot 16" snapshot into "slot 16 = 0".
		//
		// Send immediately using the live slot, wait for the authoritative ACK,
		// then apply the requested 100ms pacing BEFORE planning the next slot.
		if moveErr := suiteInventoryMoveCountV117(ctx, bot, fromRef, toRef, moveCount); moveErr != nil {
			if processingInventoryTransientV176(moveErr) {
				liveSourceRaces++

				// V385: machine-fed source boxes are expected to mutate while open.
				// First consume the live InventorySlot/Content update already received
				// from the server and reselect the newest/fullest source stack. Do not
				// fire a full inventory resync on every hopper tick: that was the visible
				// pause/stutter while the machine kept replenishing the box.
				if liveSourceRaces <= 8 {
					logCollectDiagnostic(bot, "processing_source_live_reselect_v385", fmt.Sprintf(
						"target=%s from=%s requested=%d race=%d revision=%d error=%v",
						target, fromRef, moveCount, liveSourceRaces, containerRevisionNow, moveErr,
					))
					if waitErr := processingWaitSourceRevisionV385(ctx, bot, openSeqNow, containerRevisionNow); waitErr != nil {
						return taken, fill, waitErr
					}
					continue
				}

				// Persistent mismatch gets one authoritative player-inventory refresh,
				// then immediately returns to the live reselect path.
				logCollectDiagnostic(bot, "processing_source_live_resync_v385", fmt.Sprintf(
					"target=%s from=%s requested=%d races=%d error=%v",
					target, fromRef, moveCount, liveSourceRaces, moveErr,
				))
				_ = requestBedrockInventoryResync(bot)
				processingRefreshInventoryAfterTradeV170(ctx, bot)
				liveSourceRaces = 0
				if waitErr := processingWaitRetryV176(ctx, 80*time.Millisecond); waitErr != nil {
					return taken, fill, waitErr
				}
				continue
			}
			return taken, fill, fmt.Errorf("從來源箱取出 %s 失敗: %w", target, moveErr)
		}
		liveSourceRaces = 0
		if waitErr := processingWaitSafeCadenceV176(ctx, bot, processingChestTransferGapV328); waitErr != nil {
			return taken, fill, waitErr
		}
		// V174: the accepted ItemStackResponse already updates both container and
		// inventory mirrors. Do not request a full inventory mismatch after every
		// stack; that packet flood was the main reason source-box draining looked
		// extremely slow. Resync once after the whole batch instead.
		taken += moveCount
	}
	if !batchAvailabilityVerified && helperOutputInventoryCountV159(bot, target) < minCount {
		return taken, fill, fmt.Errorf(
			"來源材料尚未形成可交易批次｜%s 目前 %d，需要至少 %d",
			target, helperOutputInventoryCountV159(bot, target), minCount,
		)
	}
	if taken > 0 {
		_ = requestBedrockInventoryResync(bot)
	}
	// V169: return the POST-take fill level. The previous code returned the level
	// measured before draining up to four stacks, which could keep the controller in
	// high-water protection even after the Bot had already freed substantial space.
	bot.mu.Lock()
	fill = processingContainerFillV375(bot.MapArtContainerItems)
	bot.ProcessSourceFill = fill
	bot.mu.Unlock()
	return taken, fill, nil
}

func processingTakeFromBoxStableV176(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, minCount, targetCount int) (int, float64, error) {
	totalTaken := 0
	lastFill := 0.0
	var lastErr error
	for attempt := 1; attempt <= 6; attempt++ {
		if err := processingWaitBotReadyV406(ctx, bot, "來源箱取料"); err != nil {
			return totalTaken, lastFill, err
		}
		taken, fill, err := processingTakeFromBoxV159(ctx, bot, boxPos, target, minCount, targetCount)
		totalTaken += taken
		lastFill = fill
		if err == nil {
			return totalTaken, lastFill, nil
		}
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) || !processingInventoryTransientV176(err) {
			return totalTaken, lastFill, err
		}
		lastErr = err
		delay := processingRetryDelayV176(attempt)
		processingSetStageV159(bot, "來源箱同步重試", fmt.Sprintf("%s｜第 %d/6 次｜%s 後重試", target, attempt, delay.Round(10*time.Millisecond)))
		logCollectDiagnostic(bot, "processing_source_retry_v176", fmt.Sprintf(
			"target=%s taken=%d attempt=%d delay=%s box=%s error=%v", target, totalTaken, attempt, delay, boxPos, err,
		))
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		if err := processingWaitRetryV176(ctx, delay); err != nil {
			return totalTaken, lastFill, err
		}
	}
	return totalTaken, lastFill, fmt.Errorf("來源箱經安全退避重試仍失敗: %w", lastErr)
}

func processingDepositStableV176(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, requested int, allowProcess bool) (int, error) {
	totalMoved := 0
	var lastErr error
	for attempt := 1; attempt <= 5 && totalMoved < requested; attempt++ {
		if err := processingWaitBotReadyV406(ctx, bot, "存箱"); err != nil {
			return totalMoved, err
		}
		moved, err := depositBedrockInventoryItemToBoxV159(ctx, bot, boxPos, target, requested-totalMoved, allowProcess)
		totalMoved += moved
		if err == nil {
			return totalMoved, nil
		}
		// A full machine/output box is authoritative capacity, not a transient
		// inventory mismatch. Return it immediately so the machine-return caller can
		// skip to the second exchange without wasting recovery/reopen attempts.
		if processingBoxFullV182(err) {
			return totalMoved, err
		}
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) || !processingInventoryTransientV176(err) {
			return totalMoved, err
		}
		lastErr = err
		delay := processingRetryDelayV176(attempt + 1)
		processingSetStageV159(bot, "存箱復原", fmt.Sprintf("%s｜已存 %d/%d｜第 %d/5 次軟重置復原", target, totalMoved, requested, attempt))
		logCollectDiagnostic(bot, "processing_deposit_retry_v176", fmt.Sprintf(
			"target=%s moved=%d requested=%d attempt=%d delay=%s box=%s error=%v", target, totalMoved, requested, attempt, delay, boxPos, err,
		))
		if attempt == 1 || attempt == 3 {
			if recoveryErr := bedrockSoftSessionRecoveryV185(ctx, bot, fmt.Sprintf("processing_deposit target=%s attempt=%d error=%v", target, attempt, err), 350*time.Millisecond); recoveryErr != nil {
				if ctx.Err() != nil {
					return totalMoved, ctx.Err()
				}
				logCollectDiagnostic(bot, "processing_soft_relogin_fail_v185", fmt.Sprintf("target=%s attempt=%d error=%v", target, attempt, recoveryErr))
			}
		}
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		if err := processingWaitRetryV176(ctx, delay); err != nil {
			return totalMoved, err
		}
	}
	if totalMoved == requested {
		return totalMoved, nil
	}
	return totalMoved, fmt.Errorf("存箱復原次數已用完，只存入 %d/%d 個 %s: %w", totalMoved, requested, target, lastErr)
}

// processingDepositLotOutputDurableV421 persists every server-confirmed partial
// output move before it reacts to a full box or any transient error. Phase
// "output_flushing" is a write-ahead fence: if the App exits after the server
// accepted items but before the returned moved count was persisted, restart can
// reconcile the missing backpack delta without replaying the whole output batch.
func processingDepositLotOutputDurableV421(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, requested int, label string) (int, error) {
	if bot == nil {
		return 0, errors.New("找不到加工 BOT")
	}
	if requested <= 0 {
		return 0, nil
	}
	target = strings.TrimSpace(target)
	if target == "" {
		return 0, errors.New("成品名稱為空")
	}
	if strings.TrimSpace(label) == "" {
		label = "成品箱"
	}

	totalStored := 0
	for totalStored < requested {
		if err := ctx.Err(); err != nil {
			return totalStored, err
		}

		bot.mu.Lock()
		ledger := bot.ProcessLotLedger
		bot.mu.Unlock()
		ledger.Active = true
		ledger.Phase = "output_flushing"
		ledger.FinalItem = target
		if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
			return totalStored, fmt.Errorf("%s存入前 checkpoint 寫入失敗: %w", label, err)
		}

		stored, storeErr := processingDepositStableV176(ctx, bot, boxPos, target, requested-totalStored, true)
		if stored < 0 {
			stored = 0
		}
		if stored > requested-totalStored {
			stored = requested - totalStored
		}
		if stored > 0 {
			totalStored += stored
			bot.mu.Lock()
			ledger = bot.ProcessLotLedger
			bot.mu.Unlock()
			ledger.Active = true
			ledger.Phase = "output_stored"
			ledger.FinalItem = target
			ledger.OutputStored += stored
			if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
				return totalStored, fmt.Errorf("%s已實際存入 %d 個但 checkpoint 寫入失敗: %w", label, stored, err)
			}
		}

		if storeErr == nil {
			continue
		}
		if errors.Is(storeErr, context.Canceled) || errors.Is(storeErr, context.DeadlineExceeded) {
			return totalStored, storeErr
		}
		if processingBoxFullV182(storeErr) {
			processingSetStageV159(bot, "等待成品箱空位", fmt.Sprintf(
				"成品箱已滿｜本次已存 %d/%d 個 %s｜已寫入 checkpoint，有空位只補剩餘 %d",
				totalStored, requested, target, requested-totalStored,
			))
			if waitErr := processingWaitForBoxSpaceV182(ctx, bot, boxPos, target, "等待成品箱空位"); waitErr != nil {
				return totalStored, waitErr
			}
			continue
		}
		if processingInventoryTransientV176(storeErr) {
			processingSetStageV159(bot, "成品箱自動恢復", fmt.Sprintf(
				"本次已存 %d/%d｜已寫入 checkpoint｜箱子狀態重新同步後只補剩餘 %d",
				totalStored, requested, requested-totalStored,
			))
			_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_output_durable_v421: "+storeErr.Error(), 450*time.Millisecond)
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			if waitErr := processingWaitRetryV176(ctx, 900*time.Millisecond); waitErr != nil {
				return totalStored, waitErr
			}
			continue
		}
		return totalStored, storeErr
	}
	return totalStored, nil
}

func processingTradePartsV159(target string) (helperTradeRequirement, helperTradeOutput, error) {
	_, itemText := splitPurchaseTarget(target)
	req, ok := parseHelperTradeRequirement(itemText)
	if !ok || req.Count <= 0 || strings.TrimSpace(req.Item) == "" || isHelperExperienceName(req.Item) {
		return helperTradeRequirement{}, helperTradeOutput{}, fmt.Errorf("無法從交易文字辨識實體材料批次：%s", itemText)
	}
	out, ok := parseHelperTradeOutput(itemText)
	if !ok || out.Count <= 0 || strings.TrimSpace(out.Item) == "" {
		return helperTradeRequirement{}, helperTradeOutput{}, fmt.Errorf("無法從交易文字辨識產物批次：%s", itemText)
	}
	return req, out, nil
}

func startProcessingHelperTradeV159(ctx context.Context, bot *BotSession, target string) (helperTradeAutoDropJob, uint64, error) {
	if bot == nil {
		return helperTradeAutoDropJob{}, 0, errors.New("找不到 BOT")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	target = strings.TrimSpace(target)
	if target == "" {
		return helperTradeAutoDropJob{}, 0, errors.New("交易項目為空")
	}
	_, itemText := splitPurchaseTarget(target)
	out, _ := parseHelperTradeOutput(itemText)

	for {
		bot.mu.Lock()
		if !bot.ProcessAutomationRunning {
			bot.mu.Unlock()
			return helperTradeAutoDropJob{}, 0, context.Canceled
		}
		waitingFor := ""
		if bot.RootState != "" && bot.RootState != string(botRootIdle) {
			waitingFor = strings.TrimSpace(bot.RootStateLabel)
			if waitingFor == "" {
				waitingFor = "排程任務"
			}
		} else if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" {
			waitingFor = bedrockControlOwnerLabel(owner)
			if kind := strings.TrimSpace(bot.BedrockActionKind); kind != "" {
				waitingFor = kind
			}
		} else if strings.TrimSpace(bot.WantExchangeItem) != "" {
			waitingFor = "上一筆小幫手交易"
		}
		if waitingFor == "" {
			break
		}
		bot.mu.Unlock()
		processingSetStageV159(bot, "等待控制權", waitingFor+" 完成後自動繼續交易")
		if err := processingWaitRetryV176(ctx, 125*time.Millisecond); err != nil {
			return helperTradeAutoDropJob{}, 0, err
		}
	}
	bot.OperationGeneration++
	generation := bot.OperationGeneration
	bot.ProcessInternalTrade = true
	bot.BedrockControlGeneration++
	bot.BedrockControlOwner = "processing"
	bot.BedrockActionKind = "加工循環交易"
	bot.TradeAutoDropEnabled = false
	bot.TradeAutoDropQueue = nil
	bot.TradeAutoDropArmed = false
	bot.TradeAutoDropBefore = nil
	bot.TradeAutoDropArmedAt = time.Time{}
	before := bot.tradeAutoDropInventorySnapshotLocked()
	startedAt := time.Now()
	bot.AutoCrawl = false
	bot.BackgroundScan = false
	bot.HelperOneShotPath = nil
	bot.HelperOneShotIdx = 0
	bot.HelperOneShotSilent = false
	bot.HelperResultPath = nil
	bot.HelperResultSince = time.Time{}
	bot.HelperResultSilent = false
	bot.HelperActionStarted = time.Time{}
	bot.HelperClaim = false
	bot.PendingShunt = 0
	bot.ShuntVerifyTarget = 0
	bot.TeleportVerify = false
	bot.RepeatExchange = false
	bot.clearPurchaseWatchMaterialLocked()
	bot.WantExchangeItem = target
	bot.prepareTradeAutoDropLocked(target)
	bot.setTradeOutcomeLocked("pending", target, "⏳ 加工循環交易中")
	bot.PurchaseLastActionFormID = 0
	bot.PurchaseLastActionSignature = ""
	bot.PurchaseRetryCount = 0
	bot.setPurchasePhaseLocked(purchasePhaseWaitMain)
	bot.FormPathIdx = 0
	bot.FormListIdx = 0
	lastFormID := bot.LastFormID
	bot.LastFormID = 0
	conn := bot.conn
	bot.OperationCurrent = "加工循環：" + target
	bot.OperationResult = "開啟交易選單"
	bot.mu.Unlock()

	if conn == nil {
		err := errors.New("BOT 已離線")
		finishProcessingInternalTradeV159(bot, target, false, err.Error())
		return helperTradeAutoDropJob{}, 0, err
	}
	if lastFormID != 0 {
		closePurchaseForm(conn, lastFormID)
	}
	if err := sendClientMessage(conn, "/menu"); err != nil {
		finishProcessingInternalTradeV159(bot, target, false, "無法開啟交易選單："+err.Error())
		return helperTradeAutoDropJob{}, 0, err
	}
	logCollectDiagnostic(bot, "processing_trade_start_v181", fmt.Sprintf("target=%s generation=%d", target, generation))
	return helperTradeAutoDropJob{Item: out.Item, Count: out.Count, CountExplicit: out.CountExplicit, StrictExpected: true, Target: target, Before: before, StartedAt: startedAt}, generation, nil
}

func finishProcessingInternalTradeV159(bot *BotSession, target string, success bool, result string) {
	if bot == nil {
		return
	}
	var closeID uint32
	var conn *minecraft.Conn
	var releasedControl bool
	bot.mu.Lock()
	bot.ProcessInternalTrade = false
	bot.TradeAutoDropArmed = false
	bot.TradeAutoDropBefore = nil
	bot.TradeAutoDropArmedAt = time.Time{}
	bot.TradeAutoDropWatchSeq++
	if strings.TrimSpace(bot.WantExchangeItem) == strings.TrimSpace(target) {
		// Fence every form/purchase goroutine belonging to this completed trade.
		// Without this increment, a delayed helper page can repopulate one-shot
		// state after the inventory delta has already released the processing loop.
		bot.OperationGeneration++
		bot.WantExchangeItem = ""
		bot.RepeatExchange = false
		bot.resetPurchaseStateLocked()
	}
	clearProcessingHelperStateLockedV184(bot)
	closeID = bot.LastFormID
	bot.LastFormID = 0
	conn = bot.conn
	if success {
		bot.setTradeOutcomeLocked("success", target, result)
	} else if strings.TrimSpace(bot.TradeOutcomeKind) == "pending" {
		bot.setTradeOutcomeLocked("failure", target, result)
	}
	// V406: terminal server-confirmed/verified trade result is the cadence anchor.
	// Failed attempts are also terminal and must not be followed by an immediate
	// /menu retry burst.
	bot.ProcessLastTradeDoneAt = time.Now()
	bot.applyPurchaseOutputModeLockedV159()
	if bot.BedrockControlOwner == "processing" {
		bot.BedrockControlOwner = ""
		bot.BedrockControlGeneration++
		bot.BedrockActionKind = ""
		releasedControl = true
	}
	bot.mu.Unlock()
	if closeID != 0 && conn != nil {
		closePurchaseForm(conn, closeID)
	}
	if releasedControl {
		bedrockResumeDeferredAutoDrop(bot)
	}
}

func waitProcessingHelperTradeV159(ctx context.Context, bot *BotSession, target string, job helperTradeAutoDropJob, generation uint64) (string, int, error) {
	deadline := time.Now().Add(40 * time.Second)
	for time.Now().Before(deadline) {
		if err := ctx.Err(); err != nil {
			finishProcessingInternalTradeV159(bot, target, false, "⏹ 加工循環已停止")
			return "", 0, err
		}
		bot.mu.Lock()
		running := bot.ProcessAutomationRunning
		connected := bot.Connected && bot.PlayerReady && bot.conn != nil && !bot.Respawning.Load()
		kind := strings.TrimSpace(bot.TradeOutcomeKind)
		outcomeTarget := strings.TrimSpace(bot.TradeOutcomeTarget)
		outcomeResult := strings.TrimSpace(bot.TradeOutcomeResult)
		bot.mu.Unlock()
		if !running {
			finishProcessingInternalTradeV159(bot, target, false, "⏹ 加工循環已停止")
			return "", 0, context.Canceled
		}
		if !connected {
			// V406: the transaction is ambiguous, not failed. Return to the stable
			// verifier immediately; it will wait for reconnect, resync the authoritative
			// inventory and compare it with this trade's pre-send snapshot before any
			// new /menu is allowed.
			finishProcessingInternalTradeV159(bot, target, false, "連線中斷，等待重連後驗證本筆交易")
			return "", 0, errors.New("加工交易期間連線中斷，結果待重連後驗證")
		}
		if outcomeTarget == strings.TrimSpace(target) && kind == "failure" {
			finishProcessingInternalTradeV159(bot, target, false, outcomeResult)
			if outcomeResult == "" {
				outcomeResult = "伺服器拒絕交易或材料不足"
			}
			return "", 0, errors.New(outcomeResult)
		}
		if receivedID, delta, ok := bot.findTradeAutoDropReceived(job); ok && delta > 0 {
			time.Sleep(70 * time.Millisecond)
			receivedID, delta, ok = bot.findTradeAutoDropReceived(job)
			if ok && delta > 0 {
				result := fmt.Sprintf("✅ 加工交易成功：%s × %d", receivedID, delta)
				finishProcessingInternalTradeV159(bot, target, true, result)
				logCollectDiagnostic(bot, "processing_trade_success_v181", fmt.Sprintf(
					"target=%s received=%s count=%d elapsed=%s", target, receivedID, delta, time.Since(job.StartedAt).Round(10*time.Millisecond),
				))
				// V173: the positive inventory delta is enough to chain the next helper
				// exchange. Do not force a full mismatch/resync after every fixed batch:
				// machine/output storage already performs an authoritative refresh immediately
				// before touching container slots. This removes a large per-trade stall while
				// preserving the strict-server StackNetworkID protection where it matters.
				return receivedID, delta, nil
			}
		}
		// Explicit server success may arrive a little before InventorySlot/Content.
		// Keep waiting for the real positive delta so routing never guesses a count.
		if outcomeTarget == strings.TrimSpace(target) && kind == "success" && time.Since(job.StartedAt) > 5*time.Second {
			finishProcessingInternalTradeV159(bot, target, false, "伺服器回報成功但未收到可驗證的背包增量")
			return "", 0, errors.New("交易成功訊息已收到，但沒有確認到實際產物")
		}
		_ = generation // generation is retained for diagnostics/state-machine parity.
		time.Sleep(35 * time.Millisecond)
	}
	finishProcessingInternalTradeV159(bot, target, false, "交易逾時")
	return "", 0, errors.New("加工交易逾時")
}

func processingRunTradeV159(ctx context.Context, bot *BotSession, target string) (string, int, error) {
	if ctx == nil {
		ctx = context.Background()
	}

	// V402: every BOT owns an independent Bedrock connection, form state and
	// processing cadence. Do not put all BOTs behind one App-wide transaction lock:
	// with two BOTs at 2000ms it doubled each BOT to roughly 4000ms, and four BOTs
	// could effectively become ~8000ms. Keep the proven anti-spam delay and cooldown
	// on the BOT that is actually trading; other BOTs continue at their own speed.
	if err := processingWaitTradeWindowV180(ctx, bot, target); err != nil {
		return "", 0, err
	}

	// V406: processingWaitTradeWindow already waited for BOT ready, previous trade
	// completion and the per-BOT sustained-rate window. Do not add a tiny fixed
	// sleep here; the next action is now admitted by server-confirmed state.
	job, generation, err := startProcessingHelperTradeV159(ctx, bot, target)
	if err != nil {
		return "", 0, err
	}
	return waitProcessingHelperTradeV159(ctx, bot, target, job, generation)
}

var errProcessingTradeMaterialShortV173 = errors.New("加工交易材料不足")

// processingTradeRejectLikeV224 identifies the failure class that users can
// currently clear by pressing Stop -> Start. These are not inventory-shortage
// decisions: they are stale/rejected helper transaction state where blindly
// retrying the same purchase/form generation can loop forever.

func processingTradeRejectLikeV224(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(strings.TrimSpace(err.Error()))

	// V304: only explicit server/protocol rejection belongs to the heavy reset path.
	// Generic "交易未成功/失敗/逾時/未確認" may merely mean the positive inventory
	// delta arrived late. Treating those as server rejection was a false-positive
	// source that repeatedly inserted long pauses and resets.
	for _, marker := range []string{
		"伺服器拒絕", "server reject", "server rejected", "rejected by server",
		"purchase rejected", "transaction rejected",
	} {
		if strings.Contains(msg, strings.ToLower(marker)) {
			return true
		}
	}
	return false
}

// processingRecoverRejectedTradeV224 performs the useful state reset that a
// manual Stop -> Start previously provided, but preserves the processing worker
// itself. It fences delayed form goroutines, clears the purchase/trade runtime,
// closes stale UI, drops stale stack-response mirrors, requests authoritative
// inventory again and waits long enough for delayed rejection packets to drain.

func processingTradeRetryDelayV304(attempt int, explicitReject bool) time.Duration {
	if attempt < 1 {
		attempt = 1
	}
	if explicitReject {
		delay := time.Duration(attempt) * 260 * time.Millisecond
		if delay > 900*time.Millisecond {
			delay = 900 * time.Millisecond
		}
		return delay
	}
	delay := time.Duration(attempt) * 120 * time.Millisecond
	if delay > 480*time.Millisecond {
		delay = 480 * time.Millisecond
	}
	return delay
}

func processingRecoverRejectedTradeV224(ctx context.Context, bot *BotSession, target string, cause error) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if ctx == nil {
		ctx = context.Background()
	}

	var closeID uint32
	var conn *minecraft.Conn
	releasedControl := false
	bot.mu.Lock()
	if !bot.ProcessAutomationRunning {
		bot.mu.Unlock()
		return context.Canceled
	}
	// This is the critical part of manual Stop -> Start: invalidate every old
	// helper/form callback before starting a fresh transaction generation.
	bot.OperationGeneration++
	bot.ProcessInternalTrade = false
	bot.WantExchangeItem = ""
	bot.RepeatExchange = false
	bot.TradeAutoDropArmed = false
	bot.TradeAutoDropBefore = nil
	bot.TradeAutoDropQueue = nil
	bot.TradeAutoDropArmedAt = time.Time{}
	bot.TradeAutoDropWatchSeq++
	bot.resetPurchaseStateLocked()
	clearProcessingHelperStateLockedV184(bot)
	closeID = bot.LastFormID
	bot.LastFormID = 0
	conn = bot.conn
	// Do not let the old failure remain "recent" and be attributed to the next
	// transaction for the same target. The next trade will create its own pending
	// outcome immediately before /menu is sent.
	bot.TradeOutcomeKind = ""
	bot.TradeOutcomeTarget = ""
	bot.TradeOutcomeResult = ""
	bot.TradeOutcomeAt = time.Time{}
	// Match the useful speed-reset part of manual Stop -> Start without stopping
	// the processing worker. Old rolling timestamps must not poison the fresh trade.
	bot.ProcessTradeStarts = nil
	bot.ProcessLastTradeStartAt = time.Time{}
	bot.ProcessLastActionAt = time.Time{}
	if bot.BedrockControlOwner == "processing" {
		bot.BedrockControlOwner = ""
		bot.BedrockControlGeneration++
		bot.BedrockActionKind = ""
		releasedControl = true
	}
	bot.ProcessStage = "交易狀態自動重置"
	bot.ProcessStatus = fmt.Sprintf("連續收到拒絕｜自動清理本輪交易狀態後繼續：%s", strings.TrimSpace(target))
	bot.OperationCurrent = "加工循環"
	bot.OperationResult = bot.ProcessStatus
	bot.mu.Unlock()

	if closeID != 0 && conn != nil {
		closePurchaseForm(conn, closeID)
	}
	if releasedControl {
		bedrockResumeDeferredAutoDrop(bot)
	}

	// Also clear stale container/stack-request mirrors. This does not disconnect
	// the BOT and preserves ProcessAutomationRunning/generation.
	if err := bedrockSoftSessionRecoveryV185(ctx, bot, "processing_trade_reject_v224: "+fmt.Sprint(cause), 550*time.Millisecond); err != nil {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		logCollectDiagnostic(bot, "processing_trade_recover_soft_fail_v224", fmt.Sprintf("target=%s error=%v", target, err))
	}
	processingRefreshInventoryAfterTradeV170(ctx, bot)

	// The stale form/session has already been fenced and authoritative inventory
	// refreshed above. A short drain is enough; the old fixed 2.2s gap accumulated
	// into visible slowdown whenever a generic timeout was misclassified.
	processingSetStageV159(bot, "交易狀態自動重置", "舊交易已清除｜短暫排空延遲回覆後自動繼續")
	if err := processingWaitRetryV176(ctx, 450*time.Millisecond); err != nil {
		return err
	}
	logCollectDiagnostic(bot, "processing_trade_recovered_v224", fmt.Sprintf("target=%s cause=%v", target, cause))
	return nil
}

// processingRunTradeStableV173 retries a transient helper/menu rejection only
// while the authoritative backpack still has a complete server-defined batch.
// This keeps one noisy form response from stopping the entire production loop.

func processingRunTradeStableV173(ctx context.Context, bot *BotSession, target, material string, need int) (string, int, error) {
	var lastErr error
	explicitRejects := 0
	noChangeRecoveries := 0

	// V333 fallback verification uses the same parsed server-defined output as the
	// processing config. It never guesses an arbitrary positive inventory delta.
	_, expectedOut, expectedOutErr := processingTradePartsV159(target)
	expectedOutputItem := ""
	expectedOutputCount := 0
	if expectedOutErr == nil {
		expectedOutputItem = strings.TrimSpace(expectedOut.Item)
		expectedOutputCount = expectedOut.Count
	}

	for attempt := 1; attempt <= 5; attempt++ {
		if err := processingWaitBotReadyV406(ctx, bot, "交易前確認 BOT 狀態"); err != nil {
			return "", 0, err
		}
		// Snapshot semantic totals immediately before this transaction. This is
		// independent of slot placement, stack merges and StackNetworkID churn.
		materialBefore := helperOutputInventoryCountV159(bot, material)
		outputBefore := 0
		canFallbackVerify := expectedOutputItem != "" && expectedOutputCount > 0 &&
			!strings.EqualFold(strings.TrimSpace(material), expectedOutputItem)
		if canFallbackVerify {
			outputBefore = helperOutputInventoryCountV159(bot, expectedOutputItem)
		}

		receivedID, delta, err := processingRunTradeV159(ctx, bot, target)
		if err == nil {
			return receivedID, delta, nil
		}
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return "", 0, err
		}
		lastErr = err

		// V406: if the connection vanished during this exact transaction, freeze here
		// and let startBot reconnect. Only after the new session is ready do we resync
		// and compare against materialBefore/outputBefore. This proves whether the
		// ambiguous transaction committed before disconnect and avoids double-buying.
		if !processingBotReadyV406(bot) {
			if waitErr := processingWaitBotReadyV406(ctx, bot, "交易結果尚未確認"); waitErr != nil {
				return "", 0, waitErr
			}
		}

		// A failure/outcome timeout can race the final InventorySlot/Content packets.
		// Refresh once, then prove the transaction from BOTH sides:
		//   input decreased by at least one exact requirement batch, AND
		//   the configured output increased by at least its advertised batch.
		//
		// This catches the current "尚未取得可驗證結果" loop without treating a
		// random inventory change as success.
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		materialAfter := helperOutputInventoryCountV159(bot, material)
		outputAfter := 0
		if canFallbackVerify {
			outputAfter = helperOutputInventoryCountV159(bot, expectedOutputItem)
			materialSpent := materialBefore - materialAfter
			outputGained := outputAfter - outputBefore
			if materialBefore >= need &&
				materialSpent >= need &&
				outputGained >= expectedOutputCount {
				verifiedCount := outputGained
				if verifiedCount > expectedOutputCount {
					verifiedCount = expectedOutputCount
				}
				bot.rememberTradeVerifiedItemID(expectedOutputItem, target, expectedOutputItem)
				logCollectDiagnostic(bot, "processing_trade_post_refresh_verified_v333", fmt.Sprintf(
					"target=%s attempt=%d material=%s before=%d after=%d spent=%d need=%d output=%s before=%d after=%d gained=%d expected=%d",
					target, attempt,
					material, materialBefore, materialAfter, materialSpent, need,
					expectedOutputItem, outputBefore, outputAfter, outputGained, expectedOutputCount,
				))
				bot.AddSystemLog(fmt.Sprintf(
					"✅ 交易結果延遲，但已由伺服器背包重同步雙向確認：%s × %d",
					expectedOutputItem, verifiedCount,
				))
				return expectedOutputItem, verifiedCount, nil
			}
		}

		// V341: an immediate "both unchanged" snapshot is not enough to declare
		// failure. This server can deliver the form result before the authoritative
		// InventorySlot/InventoryContent packets are visible to the bot. Re-check the
		// SAME transaction for up to ~1.6s before reopening /menu.
		if canFallbackVerify &&
			materialAfter == materialBefore &&
			outputAfter == outputBefore {

			delayedVerified := false
			verifyWaits := []time.Duration{
				250 * time.Millisecond,
				450 * time.Millisecond,
				900 * time.Millisecond,
			}

			for verifyRound, verifyWait := range verifyWaits {
				processingSetStageV159(bot, "交易延遲確認", fmt.Sprintf(
					"原料/產物暫時都沒變｜等待 %s 後第 %d/%d 次重新讀取伺服器背包",
					verifyWait, verifyRound+1, len(verifyWaits),
				))
				if waitErr := processingWaitRetryV176(ctx, verifyWait); waitErr != nil {
					return "", 0, waitErr
				}

				_ = requestBedrockInventoryResync(bot)
				processingRefreshInventoryAfterTradeV170(ctx, bot)

				lateMaterialAfter := helperOutputInventoryCountV159(bot, material)
				lateOutputAfter := helperOutputInventoryCountV159(bot, expectedOutputItem)
				lateSpent := materialBefore - lateMaterialAfter
				lateGained := lateOutputAfter - outputBefore

				if materialBefore >= need &&
					lateSpent >= need &&
					lateGained >= expectedOutputCount {

					verifiedCount := lateGained
					if verifiedCount > expectedOutputCount {
						verifiedCount = expectedOutputCount
					}

					bot.rememberTradeVerifiedItemID(expectedOutputItem, target, expectedOutputItem)
					logCollectDiagnostic(bot, "processing_trade_delayed_verified_v341", fmt.Sprintf(
						"target=%s attempt=%d verify_round=%d material=%s before=%d after=%d spent=%d need=%d output=%s before=%d after=%d gained=%d expected=%d",
						target, attempt, verifyRound+1,
						material, materialBefore, lateMaterialAfter, lateSpent, need,
						expectedOutputItem, outputBefore, lateOutputAfter, lateGained, expectedOutputCount,
					))
					bot.AddSystemLog(fmt.Sprintf(
						"✅ 交易結果延遲抵達，已重新同步確認：%s × %d",
						expectedOutputItem, verifiedCount,
					))
					return expectedOutputItem, verifiedCount, nil
				}

				// If either side changed but not enough to prove the exact trade,
				// keep the freshest values for the diagnostic below.
				materialAfter = lateMaterialAfter
				outputAfter = lateOutputAfter

				// Once either side has changed, this is no longer the pure
				// "both unchanged" race. Let the normal retry/reject logic below
				// handle it instead of repeatedly reopening the transaction.
				if materialAfter != materialBefore || outputAfter != outputBefore {
					delayedVerified = true
					break
				}
			}

			if !delayedVerified &&
				materialAfter == materialBefore &&
				outputAfter == outputBefore {
				noChangeRecoveries++

				if noChangeRecoveries <= 2 {
					processingSetStageV159(bot, "交易未成立重開", fmt.Sprintf(
						"延遲確認後仍無任何變化｜原料 %d→%d、產物 %d→%d｜%d/2 次重新開啟交易",
						materialBefore, materialAfter, outputBefore, outputAfter,
						noChangeRecoveries,
					))
					logCollectDiagnostic(bot, "processing_trade_nochange_light_retry_v391", fmt.Sprintf(
						"target=%s attempt=%d recovery=%d material=%d->%d output=%d->%d error=%v",
						target, attempt, noChangeRecoveries,
						materialBefore, materialAfter, outputBefore, outputAfter, err,
					))

					// Only a short drain for the first two misses.
					if waitErr := processingWaitRetryV176(ctx, 300*time.Millisecond); waitErr != nil {
						return "", 0, waitErr
					}
					continue
				}

				// V391: three consecutive "sent but absolutely nothing changed" results
				// mean the helper/form transaction state itself is stale, not merely that
				// InventorySlot arrived late. Reusing the same state forever produced the
				// user's "交易未成立重開" loop. Perform the same generation/session reset
				// that previously only ran after explicit server rejects, then retry cleanly.
				processingSetStageV159(bot, "交易狀態強制恢復", fmt.Sprintf(
					"連續 %d 次交易完全無變化｜清除舊表單/交易狀態後重新開始",
					noChangeRecoveries,
				))
				logCollectDiagnostic(bot, "processing_trade_nochange_force_recover_v391", fmt.Sprintf(
					"target=%s attempt=%d nochange=%d material=%d->%d output=%d->%d cause=%v",
					target, attempt, noChangeRecoveries,
					materialBefore, materialAfter, outputBefore, outputAfter, err,
				))
				if recoverErr := processingRecoverRejectedTradeV224(ctx, bot, target, fmt.Errorf(
					"連續交易無背包變化: %w", err,
				)); recoverErr != nil {
					return "", 0, recoverErr
				}
				noChangeRecoveries = 0
				continue
			}
		}

		// Only call it material exhaustion when the refreshed authoritative backpack
		// really cannot perform another batch.
		if materialAfter < need {
			return "", 0, fmt.Errorf("%w: %v", errProcessingTradeMaterialShortV173, err)
		}

		explicitReject := processingTradeRejectLikeV224(err)
		if explicitReject {
			explicitRejects++
		}
		if explicitRejects >= 2 {
			processingSetStageV159(bot, "交易拒絕自動恢復", "確認為伺服器明確拒絕｜自動重置本輪交易狀態")
			if recoverErr := processingRecoverRejectedTradeV224(ctx, bot, target, err); recoverErr != nil {
				return "", 0, recoverErr
			}
			explicitRejects = 0
			continue
		}

		if attempt < 5 {
			wait := processingTradeRetryDelayV304(attempt, explicitReject)
			if explicitReject {
				processingSetStageV159(bot, "交易拒絕重試", fmt.Sprintf(
					"伺服器明確拒絕，第 %d 次｜%s 後重試",
					explicitRejects, wait.Round(10*time.Millisecond),
				))
			} else {
				verifyDetail := "尚未取得可驗證結果"
				if canFallbackVerify {
					verifyDetail = fmt.Sprintf(
						"雙向驗證未成立｜原料 %d→%d｜產物 %d→%d",
						materialBefore, materialAfter, outputBefore, outputAfter,
					)
				}
				processingSetStageV159(bot, "交易確認重試", fmt.Sprintf(
					"%s｜第 %d 次｜%s 後重新確認",
					verifyDetail, attempt, wait.Round(10*time.Millisecond),
				))
			}
			if err := processingWaitRetryV176(ctx, wait); err != nil {
				return "", 0, err
			}
		}
	}
	return "", 0, lastErr
}

// processingRefreshInventoryAfterTradeV170 asks the server for a full authoritative
// inventory after a helper trade and waits for an actual InventoryContent/Slot update.
// The helper trade delta can become visible before the final StackNetworkID settles;
// using that short-lived mirror immediately for a chest request is rejected with
// ItemStackResponse status=1 on strict servers.
func processingRefreshInventoryAfterTradeV170(ctx context.Context, bot *BotSession) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	before := bot.InventoryRevision
	bot.mu.Unlock()
	if err := requestBedrockInventoryResync(bot); err != nil {
		// The trade itself already succeeded. Do not turn a best-effort refresh into
		// a false trade failure; the storage path has its own retry/resync below.
		time.Sleep(90 * time.Millisecond)
		return
	}
	deadline := time.Now().Add(1800 * time.Millisecond)
	for time.Now().Before(deadline) {
		if ctx != nil {
			select {
			case <-ctx.Done():
				return
			default:
			}
		}
		bot.mu.Lock()
		revision := bot.InventoryRevision
		bot.mu.Unlock()
		if revision > before {
			// Allow split hotbar/inventory packets from the same resync to finish.
			time.Sleep(55 * time.Millisecond)
			return
		}
		time.Sleep(25 * time.Millisecond)
	}
	// Some proxies answer the mismatch without changing every mirrored slot. A
	// short grace period is still preferable to firing the store request instantly.
	time.Sleep(90 * time.Millisecond)
}

func processingSetStageV159(bot *BotSession, stage, status string) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	bot.ProcessStage = strings.TrimSpace(stage)
	bot.ProcessStatus = strings.TrimSpace(status)
	bot.OperationCurrent = "加工循環"
	bot.OperationResult = bot.ProcessStatus
	bot.mu.Unlock()
}

var errProcessingMachineStoreTimeoutV379 = errors.New("機器投料箱存入逾時")

func processingStoreToMachineBoxV161(ctx context.Context, bot *BotSession, boxPos Vec3i, target string, count int) (int, error) {
	if count <= 0 {
		return 0, nil
	}
	if err := processingWaitBotReadyV406(ctx, bot, "回機器投料箱"); err != nil {
		return 0, err
	}
	// The machine return target is a real verified container. Reuse the same
	// Bedrock stack-request path as output storage instead of dropping entities
	// on the ground near a remembered player position.
	// V406: do not count a spam-kick/reconnect cooldown against an arbitrary 30s
	// wall-clock deadline. processingDepositStable is bounded while connected, and
	// processingWaitBotReady blocks only until reconnect or user Stop/context cancel.
	storeCtx := processingWithLiveMachineSinkV386(ctx)
	stored, err := processingDepositStableV176(storeCtx, bot, boxPos, target, count, true)
	if err != nil {
		return stored, fmt.Errorf("放入機器投料箱失敗: %w", err)
	}
	return stored, nil
}

// processingMachineRefillTargetV394 calculates the machine refill from the
// SOURCE material that this processing lot actually consumed, not from the first
// helper trade's output count. The physical machine recipe is 2 input -> 4 output,
// so every 4 items taken from the machine's source stream must send 2 items back:
// exactly 50% of source-consumed quantity. This keeps the machine feed neutral even
// when a helper trade has a different output multiplier or an inventory delta is noisy.
func processingMachineRefillTargetV394(sourceConsumed int) (basis int, target int) {
	if sourceConsumed < 0 {
		sourceConsumed = 0
	}
	basis = sourceConsumed
	// Full lots are 1728, therefore exactly 864. If an unusual trade size leaves an
	// incomplete remainder below one trade, only actually consumed source items are
	// counted; no debt/carry is allowed to leak into the next lot.
	target = basis / 2
	return basis, target
}

// processingCanonicalTradeItemV396 resolves helper-visible item text and runtime
// inventory identifiers to one canonical Bedrock item ID. Processing trade forms
// commonly use Traditional Chinese labels (for example "泥土"), while the live
// inventory delta reports "minecraft:dirt". Comparing the raw strings caused the
// fixed-half reserve to be disabled even though both names referred to the same item.
func processingCanonicalTradeItemV396(bot *BotSession, value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}

	// V423: for exact vanilla Chinese names, the static semantic identity is
	// stronger than a learned legacy family ID. This keeps 泥土 and 粗泥 distinct.
	staticKey := strings.ToLower(strings.TrimSpace(clean(value)))
	staticKey = strings.ReplaceAll(staticKey, "　", " ")
	staticKey = strings.Join(strings.Fields(staticKey), " ")
	if staticID, ok := dropChineseItemAliases[staticKey]; ok && strings.TrimSpace(staticID) != "" {
		return strings.ToLower(strings.TrimSpace(staticID))
	}

	// A positive trade receipt is strongest for custom/non-vanilla aliases only.
	if bot != nil {
		if verified, ok := bot.tradeVerifiedItemID(value); ok {
			verified = strings.ToLower(strings.TrimSpace(verified))
			if verified != "" {
				return verified
			}
		}
		if resolved := strings.ToLower(strings.TrimSpace(bot.resolveDropItemTarget(value))); resolved != "" {
			return resolved
		}
	}

	// This also maps the built-in zh-TW aliases, e.g. 泥土 -> minecraft:dirt.
	return strings.ToLower(strings.TrimSpace(normaliseDropItemTarget(value)))
}

func processingSameTradeItemV396(bot *BotSession, left, right string) bool {
	left = strings.TrimSpace(left)
	right = strings.TrimSpace(right)
	if left == "" || right == "" {
		return false
	}
	if strings.EqualFold(left, right) {
		return true
	}
	leftID := processingCanonicalTradeItemV396(bot, left)
	rightID := processingCanonicalTradeItemV396(bot, right)
	return leftID != "" && rightID != "" && leftID == rightID
}

func processingPercentReturnV225(produced, available, percent int) int {
	if produced <= 0 || available <= 0 || percent <= 0 {
		return 0
	}
	if percent > 100 {
		percent = 100
	}
	due := produced * percent / 100
	if due > available {
		due = available
	}
	return due
}

// V401 processing return checkpoint: V378 arithmetic stays unchanged, but the
// already-earned 50% machine share is now a durable restart checkpoint.  The
// value is stored in hundredths so existing math remains exact.  Unlike V379's
// old fractional-only carry, whole owed items are intentionally preserved while
// an interrupted lot is unfinished.  A confirmed FULL machine box still clears
// the checkpoint so no debt leaks into a later lot.
func processingPersistReturnCheckpointV401(bot *BotSession, item string, owedUnits int, phase string) error {
	if bot == nil {
		return errors.New("找不到加工 BOT")
	}
	if owedUnits < 0 {
		owedUnits = 0
	}
	item = strings.TrimSpace(item)
	phase = strings.TrimSpace(phase)
	if owedUnits < 100 {
		owedUnits = 0
		item = ""
		phase = ""
	} else if phase == "" {
		phase = "accruing"
	}
	bot.mu.Lock()
	changed := bot.ProcessReturnOwedUnits != owedUnits ||
		strings.TrimSpace(bot.ProcessReturnOwedItem) != item ||
		strings.TrimSpace(bot.ProcessReturnCheckpointPhase) != phase
	bot.ProcessReturnOwedUnits = owedUnits
	bot.ProcessReturnOwedItem = item
	bot.ProcessReturnCheckpointPhase = phase
	bot.mu.Unlock()
	if !changed {
		return nil
	}
	return saveHelperProcessingConfig(bot)
}

func processingClearReturnCheckpointV401(bot *BotSession) error {
	return processingPersistReturnCheckpointV401(bot, "", 0, "")
}

// Compatibility wrapper for older helpers.  Main V401 processing code uses the
// item-aware checkpoint helper directly; this wrapper preserves the current item
// instead of truncating the durable debt to a 0..99 fractional remainder.
func processingPersistReturnOwedV314(bot *BotSession, owedUnits int) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	item := strings.TrimSpace(bot.ProcessReturnOwedItem)
	phase := strings.TrimSpace(bot.ProcessReturnCheckpointPhase)
	bot.mu.Unlock()
	_ = processingPersistReturnCheckpointV401(bot, item, owedUnits, phase)
}

// processingResumeReturnCheckpointV401 runs before any new source lot. V418 keeps
// the machine share fixed at 864 (= 1728 source × 50%) and only creates this debt
// after the whole first stage has finished. "flushing" is write-ahead: when a crash
// happens after the server accepted some items but before the local file was updated,
// missing backpack items are treated as already stored instead of being charged twice.
func processingResumeReturnCheckpointV401(ctx context.Context, bot *BotSession, machinePos Vec3i, fallbackItem string) error {
	if bot == nil {
		return errors.New("找不到加工 BOT")
	}
	bot.mu.Lock()
	owed := bot.ProcessReturnOwedUnits
	item := strings.TrimSpace(bot.ProcessReturnOwedItem)
	phase := strings.TrimSpace(bot.ProcessReturnCheckpointPhase)
	returnEnabled := bot.ProcessReturnEnabled
	lot := bot.ProcessLotLedger
	bot.mu.Unlock()
	returnTarget := processingFixedMachineReturnItemsV418
	if lot.Active && lot.MachineReturnTarget > 0 {
		returnTarget = lot.MachineReturnTarget
	}
	maxRemainingUnits := (returnTarget - lot.MachineReturned) * 100
	if maxRemainingUnits < 0 {
		maxRemainingUnits = 0
	}
	if lot.Active && owed > maxRemainingUnits {
		owed = maxRemainingUnits
		if err := processingPersistReturnCheckpointV401(bot, item, owed, phase); err != nil {
			return fmt.Errorf("修正舊版回料 debt 失敗: %w", err)
		}
	}
	if owed < 100 {
		if owed != 0 || item != "" || phase != "" {
			if err := processingClearReturnCheckpointV401(bot); err != nil {
				return err
			}
		}
		if lot.Active && lot.SourceRemaining == 0 && lot.MachineReturned >= returnTarget && !lot.MachineReturnDone {
			return processingSetLotMachineReturnV418(bot, returnTarget, returnTarget, true)
		}
		return nil
	}
	if !returnEnabled {
		return fmt.Errorf("仍有中斷前回料 %d 個待補，不能在回機器關閉時繼續；請重新開啟回機器後開始", owed/100)
	}
	if item == "" {
		item = strings.TrimSpace(fallbackItem)
		if item == "" {
			return errors.New("中斷回料有數量但找不到中間產物名稱，請重新選擇原本第一兌換")
		}
		if err := processingPersistReturnCheckpointV401(bot, item, owed, phase); err != nil {
			return fmt.Errorf("補寫中斷回料項目失敗: %w", err)
		}
	}
	if phase == "" {
		phase = "accruing"
	}

	due := owed / 100
	alreadyReturned := returnTarget - due
	if lot.MachineReturned > alreadyReturned {
		alreadyReturned = lot.MachineReturned
	}
	if alreadyReturned < 0 {
		alreadyReturned = 0
	}
	processingSetStageV159(bot, "續接中斷回料", fmt.Sprintf("%s × %d｜固定一盒應回 %d｜先補回機器，再續接原批次", item, due, returnTarget))
	processingRefreshInventoryAfterTradeV170(ctx, bot)
	available := helperOutputInventoryCountV159(bot, item)
	if phase != "flushing" && available < due {
		_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_resume_return_short_v401", 350*time.Millisecond)
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		available = helperOutputInventoryCountV159(bot, item)
		if available < due {
			return fmt.Errorf("中斷回料待續接：應回 %d 個 %s，但背包只有 %d；已停止避免機器補料比例再次縮小", due, item, available)
		}
	}

	// Write-ahead before touching the container.  If the process dies after the
	// server accepts items, the next start knows it was in the ambiguous flush
	// window and will not demand the same missing items twice.
	if err := processingPersistReturnCheckpointV401(bot, item, owed, "flushing"); err != nil {
		return fmt.Errorf("中斷回料續接狀態儲存失敗: %w", err)
	}

	toStore := due
	assumeAlreadyStored := 0
	if phase == "flushing" && available < due {
		assumeAlreadyStored = due - available
		toStore = available
		logCollectDiagnostic(bot, "processing_resume_flush_window_v401", fmt.Sprintf(
			"item=%s due=%d available=%d assume_already_stored=%d", item, due, available, assumeAlreadyStored,
		))
	}
	stored := 0
	var storeErr error
	if toStore > 0 {
		stored, storeErr = processingStoreToMachineBoxV161(ctx, bot, machinePos, item, toStore)
	}
	if stored < 0 {
		stored = 0
	}
	if stored > toStore {
		stored = toStore
	}
	remainingItems := due - assumeAlreadyStored - stored
	if remainingItems < 0 {
		remainingItems = 0
	}
	remainingUnits := remainingItems * 100

	if storeErr == nil {
		if stored != toStore {
			if err := processingPersistReturnCheckpointV401(bot, item, remainingUnits, "flushing"); err != nil {
				return err
			}
			_ = processingSetLotMachineReturnV418(bot, returnTarget, alreadyReturned+assumeAlreadyStored+stored, false)
			return fmt.Errorf("續接中斷回料未完整確認：預計放 %d，伺服器只確認 %d", toStore, stored)
		}
		if err := processingClearReturnCheckpointV401(bot); err != nil {
			return fmt.Errorf("中斷回料已補回，但清除續接紀錄失敗: %w", err)
		}
		totalReturned := alreadyReturned + assumeAlreadyStored + stored
		if totalReturned > returnTarget {
			totalReturned = returnTarget
		}
		if err := processingSetLotMachineReturnV418(bot, returnTarget, totalReturned, true); err != nil {
			return fmt.Errorf("中斷回料已補回，但批次回料 checkpoint 更新失敗: %w", err)
		}
		processingSetStageV159(bot, "中斷回料已續接", fmt.Sprintf("%s｜固定應回 %d｜累計已確認 %d｜繼續原批次", item, returnTarget, totalReturned))
		return nil
	}
	if processingBoxFullV182(storeErr) {
		// User rule: a genuinely full machine input box ends the obligation for this
		// interrupted lot.  Do not carry the skipped remainder into the next box.
		if err := processingClearReturnCheckpointV401(bot); err != nil {
			return err
		}
		totalReturned := alreadyReturned + assumeAlreadyStored + stored
		if totalReturned > returnTarget {
			totalReturned = returnTarget
		}
		if err := processingSetLotMachineReturnV418(bot, returnTarget, totalReturned, true); err != nil {
			return err
		}
		processingSetStageV159(bot, "機器投料箱已滿", fmt.Sprintf("固定應回 %d｜累計已放 %d｜箱滿略過剩餘 %d｜直接下一步", returnTarget, totalReturned, returnTarget-totalReturned))
		return nil
	}
	if err := processingPersistReturnCheckpointV401(bot, item, remainingUnits, "flushing"); err != nil {
		return fmt.Errorf("續接回料失敗且無法保存剩餘數量: %w", err)
	}
	_ = processingSetLotMachineReturnV418(bot, returnTarget, alreadyReturned+assumeAlreadyStored+stored, false)
	return fmt.Errorf("續接中斷回料失敗：已放 %d/%d 個 %s: %w", stored, due, item, storeErr)
}

// processingReturnIntermediateNowV314 implements an exact cumulative ratio for
// every integer percentage 1..100. It first adds produced*percent hundredths to
// the amount owed, then subtracts exactly 100 units only for each item the server
// actually confirms was stored in the machine box. Therefore rounding, partial
// stores, box-full periods and restarts can never turn e.g. 40% into 25%.
//
// Examples for x4 output:
//
//	1%  -> one item every 25 trades (100 produced -> 1 returned)
//	33% -> 33 returned per 100 produced
//	40% -> 8 returned per 20 produced
//	99% -> 99 returned per 100 produced
func processingReturnIntermediateNowV314(
	ctx context.Context,
	bot *BotSession,
	machinePos Vec3i,
	intermediateID string,
	produced int,
	percent int,
	owedUnits *int,
) (returned int, machineFull bool, err error) {
	if bot == nil || produced <= 0 || strings.TrimSpace(intermediateID) == "" {
		return 0, false, nil
	}
	if percent < 0 {
		percent = 0
	}
	if percent > 100 {
		percent = 100
	}

	owed := 0
	if owedUnits != nil && *owedUnits > 0 {
		owed = *owedUnits
	}
	// Add this trade's exact weighted entitlement before looking at available
	// inventory. If anything prevents storage, the debt remains for a later pass.
	owed += produced * percent
	if owedUnits != nil {
		*owedUnits = owed
	}
	processingPersistReturnOwedV314(bot, owed)

	available := helperOutputInventoryCountV159(bot, intermediateID)
	dueItems := owed / 100
	toReturn := dueItems
	if toReturn > available {
		toReturn = available
	}
	if toReturn <= 0 {
		logCollectDiagnostic(bot, "processing_machine_ratio_exact_v314", fmt.Sprintf(
			"item=%s produced=%d percent=%d available=%d due=%d owed_units=%d returned=0 box=%s",
			intermediateID, produced, percent, available, dueItems, owed, machinePos,
		))
		return 0, false, nil
	}

	for returned < toReturn {
		stored, storeErr := processingStoreToMachineBoxV161(ctx, bot, machinePos, intermediateID, toReturn-returned)
		if stored > 0 {
			returned += stored
			owed -= stored * 100
			if owed < 0 {
				owed = 0
			}
			if owedUnits != nil {
				*owedUnits = owed
			}
			// Persist after authoritative storage, not after the requested amount.
			// A crash/Stop at any point therefore resumes from the exact debt.
			processingPersistReturnOwedV314(bot, owed)
		}
		if storeErr == nil {
			continue
		}
		if errors.Is(storeErr, context.Canceled) || errors.Is(storeErr, context.DeadlineExceeded) {
			return returned, false, storeErr
		}
		if processingBoxFullV182(storeErr) {
			logCollectDiagnostic(bot, "processing_machine_full_v314", fmt.Sprintf(
				"item=%s produced=%d percent=%d requested=%d stored=%d owed_units=%d box=%s",
				intermediateID, produced, percent, toReturn, returned, owed, machinePos,
			))
			return returned, true, nil
		}
		if processingInventoryTransientV176(storeErr) {
			processingSetStageV159(bot, "機器箱自動恢復", fmt.Sprintf("已補 %d/%d｜比例帳仍欠 %.2f 個｜重新同步後續補", returned, toReturn, float64(owed)/100.0))
			_ = bedrockCloseContainerControlled(bot)
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			if waitErr := processingWaitRetryV176(ctx, 700*time.Millisecond); waitErr != nil {
				return returned, false, waitErr
			}
			continue
		}
		return returned, false, storeErr
	}
	logCollectDiagnostic(bot, "processing_machine_feed_v314", fmt.Sprintf(
		"item=%s produced=%d percent=%d returned=%d owed_units=%d box=%s",
		intermediateID, produced, percent, returned, owed, machinePos,
	))
	return returned, false, nil
}

// processingFlushReturnLotV380 enforces the V394 source-based fixed-half invariant.
// The caller has already calculated this lot's exact 50% target. This function
// must never silently lower that target because the backpack snapshot is short:
// only an actually FULL machine box may truncate the return and advance directly
// to the second exchange. Transient/timeout errors remain errors so they cannot
// masquerade as a smaller valid percentage.
func processingFlushReturnLotV380(
	ctx context.Context,
	bot *BotSession,
	machinePos Vec3i,
	intermediateID string,
	percent int,
	requested int,
	fractionalCarry int,
) (returned int, machineLimited bool, err error) {
	percent = processingFixedMachineReturnPercentV393
	if bot == nil || requested <= 0 || strings.TrimSpace(intermediateID) == "" {
		if bot != nil {
			_ = processingClearReturnCheckpointV401(bot)
		}
		return 0, false, nil
	}
	intermediateID = strings.TrimSpace(intermediateID)
	owedUnits := requested*100 + func() int {
		if fractionalCarry > 0 {
			return fractionalCarry
		}
		return 0
	}()
	if err := processingPersistReturnCheckpointV401(bot, intermediateID, owedUnits, "flushing"); err != nil {
		return 0, false, fmt.Errorf("回機器前保存續接點失敗: %w", err)
	}

	available := helperOutputInventoryCountV159(bot, intermediateID)
	if available < requested {
		return 0, false, fmt.Errorf(
			"固定 50%% 回料保留量不足：本盒應回 %d，但背包只有 %d 個 %s",
			requested, available, intermediateID,
		)
	}

	processingSetStageV159(bot, "本盒固定 50% 回機器箱", fmt.Sprintf(
		"%s｜固定應回 %d 個｜背包保留 %d｜比例 %d%%",
		intermediateID, requested, available, percent,
	))

	stored, storeErr := processingStoreToMachineBoxV161(ctx, bot, machinePos, intermediateID, requested)
	if stored < 0 {
		stored = 0
	}
	if stored > requested {
		stored = requested
	}
	returned = stored
	remaining := requested - returned
	if remaining < 0 {
		remaining = 0
	}

	if storeErr == nil {
		if returned != requested {
			_ = processingPersistReturnCheckpointV401(bot, intermediateID, remaining*100, "flushing")
			return returned, false, fmt.Errorf(
				"固定 50%% 回料未完整確認：應回 %d，伺服器只確認 %d；不把它當成較小比例繼續",
				requested, returned,
			)
		}
		if err := processingClearReturnCheckpointV401(bot); err != nil {
			return returned, false, fmt.Errorf("回料完成但清除續接點失敗: %w", err)
		}
		logCollectDiagnostic(bot, "processing_machine_fixed50_feed_v401", fmt.Sprintf(
			"item=%s percent=%d requested=%d available=%d stored=%d box=%s",
			intermediateID, percent, requested, available, returned, machinePos,
		))
		return returned, false, nil
	}

	if errors.Is(storeErr, context.Canceled) && ctx.Err() != nil {
		_ = processingPersistReturnCheckpointV401(bot, intermediateID, remaining*100, "flushing")
		return returned, false, ctx.Err()
	}
	if processingBoxFullV182(storeErr) {
		// Full means skip THIS lot's remainder and clear the checkpoint.  This is the
		// user's explicit rule and prevents any debt from leaking into the next lot.
		if err := processingClearReturnCheckpointV401(bot); err != nil {
			return returned, false, err
		}
		_ = bedrockCloseContainerControlled(bot)
		processingSetStageV159(bot, "機器投料箱已滿", fmt.Sprintf(
			"固定應回 %d｜已放 %d｜箱滿略過 %d｜直接下一步",
			requested, returned, remaining,
		))
		logCollectDiagnostic(bot, "processing_machine_fixed50_full_skip_v401", fmt.Sprintf(
			"item=%s percent=%d requested=%d stored=%d skipped=%d box=%s error=%v",
			intermediateID, percent, requested, returned, remaining, machinePos, storeErr,
		))
		return returned, true, nil
	}
	if err := processingPersistReturnCheckpointV401(bot, intermediateID, remaining*100, "flushing"); err != nil {
		return returned, false, fmt.Errorf("回料失敗且無法保存剩餘續接量: %w", err)
	}
	return returned, false, storeErr
}

func runProcessingAutomationV159(ctx context.Context, bot *BotSession, generation uint64) {
	var finalErr error
	defer func() {
		if recovered := recover(); recovered != nil {
			finalErr = fmt.Errorf("加工循環發生未預期錯誤：%v", recovered)
		}
		releasedControl := false
		bot.mu.Lock()
		if bot.ProcessAutomationGeneration == generation {
			bot.ProcessAutomationRunning = false
			bot.ProcessAutomationCancel = nil
			bot.ProcessInternalTrade = false
			bot.TradeAutoDropArmed = false
			bot.TradeAutoDropBefore = nil
			bot.TradeAutoDropQueue = nil
			bot.applyPurchaseOutputModeLockedV159()
			if finalErr != nil && !errors.Is(finalErr, context.Canceled) {
				bot.ProcessStage = "錯誤"
				bot.ProcessStatus = "❌ " + finalErr.Error()
				bot.ProcessLastError = finalErr.Error()
			} else if errors.Is(finalErr, context.Canceled) {
				bot.ProcessStage = "已停止"
				bot.ProcessStatus = "⏹ 已停止"
			} else {
				bot.ProcessStage = "完成"
				bot.ProcessStatus = "等待重新啟動"
			}
			if strings.TrimSpace(bot.WantExchangeItem) != "" {
				bot.OperationGeneration++
				bot.WantExchangeItem = ""
				bot.RepeatExchange = false
				bot.resetPurchaseStateLocked()
			}
			if bot.BedrockControlOwner == "processing" {
				bot.BedrockControlOwner = ""
				bot.BedrockControlGeneration++
				bot.BedrockActionKind = ""
				releasedControl = true
			}
		}
		bot.mu.Unlock()
		if releasedControl {
			bedrockResumeDeferredAutoDrop(bot)
		}
		if finalErr != nil && !errors.Is(finalErr, context.Canceled) {
			bot.AddSystemLog("加工循環停止：" + finalErr.Error())
			discordWebhookEnqueueV414(bot.ID, "processing_failed", "加工失敗", finalErr.Error())
		}
	}()

	bot.mu.Lock()
	sourceBox := bot.ProcessSourceBox
	firstTarget := strings.TrimSpace(bot.ProcessFirstExchange)
	returnEnabled := bot.ProcessReturnEnabled
	returnPercent := processingFixedMachineReturnPercentV393
	resumeOwed := bot.ProcessReturnOwedUnits
	resumeItem := strings.TrimSpace(bot.ProcessReturnOwedItem)
	resumePhase := strings.TrimSpace(bot.ProcessReturnCheckpointPhase)
	bot.ProcessReturnCount = processingFixedMachineReturnPercentV393
	machinePos := bot.ProcessMachinePos
	machineConfigured := bot.ProcessMachinePosConfigured
	secondTarget := strings.TrimSpace(bot.ProcessSecondExchange)
	secondCarryItem := strings.TrimSpace(bot.ProcessSecondCarryItem)
	secondCarryCount := bot.ProcessSecondCarryCount
	if secondCarryCount < 0 {
		secondCarryCount = 0
	}
	outputBox := bot.ProcessOutputBox
	bot.mu.Unlock()

	// Snapshot-only diagnostics run after bot.mu is released.  V401 deliberately
	// keeps a durable interrupted-lot return checkpoint instead of clearing it on
	// every Start/App restart.
	if resumeOwed >= 100 {
		logCollectDiagnostic(bot, "processing_return_resume_pending_v401", fmt.Sprintf(
			"owed_units=%d owed_items=%d item=%q phase=%q fixed_percent=%d",
			resumeOwed, resumeOwed/100, resumeItem, resumePhase, processingFixedMachineReturnPercentV393,
		))
	}

	firstReq, firstOut, err := processingTradePartsV159(firstTarget)
	if err != nil {
		finalErr = err
		return
	}
	hasSecond := secondTarget != ""
	var secondReq helperTradeRequirement
	var secondOut helperTradeOutput
	if hasSecond {
		secondReq, secondOut, err = processingTradePartsV159(secondTarget)
		if err != nil {
			finalErr = err
			return
		}
	}
	if secondCarryCount > 0 {
		if !hasSecond {
			finalErr = fmt.Errorf("上一盒仍保留 %d 個 %s 第二階尾數；不能取消第二兌換，請先沿用原第二兌換完成合併", secondCarryCount, secondCarryItem)
			return
		}
		if secondCarryItem == "" || !processingSameTradeItemV396(bot, secondCarryItem, secondReq.Item) {
			finalErr = fmt.Errorf("上一盒仍保留 %d 個 %s 第二階尾數，但目前第二兌換需要 %s；為避免混料已停止", secondCarryCount, secondCarryItem, secondReq.Item)
			return
		}
	}
	finalStageItem := strings.TrimSpace(firstOut.Item)
	if hasSecond {
		finalStageItem = strings.TrimSpace(secondOut.Item)
	}

	logCollectDiagnostic(bot, "processing_route_plan_v401", fmt.Sprintf(
		"raw=%q source=%s first_out=%q second_enabled=%v second_in=%q return_enabled=%v return_percent=%d machine=%s final=%q output=%s",
		firstReq.Item, sourceBox, firstOut.Item, hasSecond, secondReq.Item, returnEnabled, returnPercent, machinePos, finalStageItem, outputBox,
	))

	// Resume durable V378 machine share before any cleanup/new source acquisition.
	if err := processingResumeReturnCheckpointV401(ctx, bot, machinePos, firstOut.Item); err != nil {
		finalErr = err
		return
	}

	bot.mu.Lock()
	resumeLotPreflight := bot.ProcessLotLedger
	bot.mu.Unlock()
	if !resumeLotPreflight.Active {
		if !hasSecond && !processingSameTradeItemV396(bot, firstReq.Item, firstOut.Item) {
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			if leftover := helperOutputInventoryCountV159(bot, firstOut.Item); leftover > 0 {
				processingSetStageV159(bot, "續接單段成品", fmt.Sprintf("%s × %d｜先清掉中斷前成品，再開始新的來源盒", firstOut.Item, leftover))
				if err := processingPriorityDepositAllV300(ctx, bot, outputBox, firstOut.Item, "成品箱", true); err != nil {
					finalErr = fmt.Errorf("續接單段加工成品失敗: %w", err)
					return
				}
			}
		}
		if err := processingPriorityClearBackpackV300(ctx, bot, sourceBox, machinePos, outputBox, machineConfigured, firstReq.Item, firstOut.Item, finalStageItem); err != nil {
			finalErr = err
			return
		}
	} else {
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		processingSetStageV159(bot, "續接批次對帳", fmt.Sprintf("%s｜phase=%s｜source_remaining=%d｜output_stored=%d", resumeLotPreflight.LotID, resumeLotPreflight.Phase, resumeLotPreflight.SourceRemaining, resumeLotPreflight.OutputStored))
	}
	if !resumeLotPreflight.Active && secondCarryCount > 0 {
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		availableCarry := helperOutputInventoryCountV159(bot, secondCarryItem)
		if availableCarry < secondCarryCount {
			finalErr = fmt.Errorf("上一盒記錄保留 %d 個 %s 第二階尾數，但背包只剩 %d；已停止避免用下一盒材料補帳", secondCarryCount, secondCarryItem, availableCarry)
			return
		}
		processingSetStageV159(bot, "第二階尾數已保留", fmt.Sprintf("%s × %d｜下一盒完成第一階與固定回料後自動合併", secondCarryItem, secondCarryCount))
	}

	// V321: one production lot is exactly 1728 source items (27×64, one box).
	// The full 1728 must exist in source+backpack before the lot starts, but the
	// player's backpack does NOT need to hold all 1728 simultaneously. The same lot
	// is streamed in ACK-paced chunks if unrelated inventory reduces physical space.
	sourceBatchRemaining := 0
	sourceBatchFill := 0.0
	lotFirstProduced := 0
	lotFirstTradeCount := 0
	lotSourceConsumed := 0
	lotReturnOwedUnits := 0 // hundredths of one item; V418 only creates 864×100 after the whole first stage finishes.
	lotIntermediateID := ""
	lotMachineReturnTarget := 0
	lotMachineReturnDone := false
	lotMachineReturned := 0
	lotSecondCarryIn := 0
	lotSecondInputConsumed := 0
	lotSingleOutputDeposited := 0
	lotSecondProduced := 0
	lotOutputStored := 0
	lotExpectedMaxOutput := 0
	lotActive := false
	bot.mu.Lock()
	restoredLot := bot.ProcessLotLedger
	bot.mu.Unlock()
	if restoredLot.Active && (restoredLot.FirstTradePending || restoredLot.SecondTradePending) {
		restoredLot, err = processingReconcilePendingTradesV420(ctx, bot, firstReq, firstOut, hasSecond, secondReq, secondOut)
		if err != nil {
			finalErr = err
			return
		}
	}
	if restoredLot.Active && restoredLot.SourcePlanned == processingAutomationBoxBatchV317 && processingSameTradeItemV396(bot, restoredLot.SourceItem, firstReq.Item) {
		lotActive = true
		sourceBatchRemaining = restoredLot.SourceRemaining
		lotFirstProduced = restoredLot.FirstProduced
		lotFirstTradeCount = restoredLot.FirstTradeCount
		lotSourceConsumed = restoredLot.SourceConsumed
		lotReturnOwedUnits = restoredLot.ReturnOwedUnits
		lotIntermediateID = restoredLot.IntermediateItem
		lotMachineReturnTarget = restoredLot.MachineReturnTarget
		lotMachineReturnDone = restoredLot.MachineReturnDone
		lotMachineReturned = restoredLot.MachineReturned
		lotSecondCarryIn = restoredLot.SecondCarryIn
		lotSecondInputConsumed = restoredLot.SecondInputConsumed
		lotSingleOutputDeposited = restoredLot.SingleOutputDeposited
		lotSecondProduced = restoredLot.SecondProduced
		lotOutputStored = restoredLot.OutputStored
		if returnEnabled && sourceBatchRemaining == 0 && lotMachineReturnTarget <= 0 {
			lotMachineReturnTarget = processingFixedMachineReturnItemsV418
		}
		if !returnEnabled && sourceBatchRemaining == 0 {
			lotMachineReturnDone = true
		}
		// V418 migration: V417 did not persist MachineReturnDone/SecondInputConsumed.
		// If an old active lot had already advanced beyond machine return, do not feed
		// the same 864 again after update. Derive second-stage input only when the
		// configured second trade has an explicit fixed output count.
		if returnEnabled && sourceBatchRemaining == 0 && !lotMachineReturnDone && restoredLot.ReturnOwedUnits == 0 {
			switch strings.TrimSpace(restoredLot.Phase) {
			case "machine_return_confirmed", "second_trade_confirmed", "output_stored":
				lotMachineReturnDone = true
			}
			if restoredLot.SecondProduced > 0 || restoredLot.OutputStored > 0 {
				lotMachineReturnDone = true
			}
		}
		if hasSecond && lotSecondInputConsumed == 0 && restoredLot.SecondProduced > 0 &&
			secondOut.CountExplicit && secondOut.Count > 0 && restoredLot.SecondProduced%secondOut.Count == 0 {
			lotSecondInputConsumed = (restoredLot.SecondProduced / secondOut.Count) * secondReq.Count
		}
		processingSetStageV159(bot, "續接加工批次", fmt.Sprintf("%s｜剩餘原料 %d｜第一產物 %d｜已回機器 %d｜第二階已投入 %d｜已存成品 %d", restoredLot.LotID, sourceBatchRemaining, lotFirstProduced, lotMachineReturned, lotSecondInputConsumed, lotOutputStored))
	}

	if restoredLot.Active && hasSecond && restoredLot.SecondProduced > restoredLot.OutputStored && strings.TrimSpace(restoredLot.FinalItem) != "" {
		pending := restoredLot.SecondProduced - restoredLot.OutputStored
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		available := helperOutputInventoryCountV159(bot, restoredLot.FinalItem)

		// V422: repair both the V420 partial-output hole and V421's over-strict
		// phase gate.  The durable proof is the lot ledger itself: SecondProduced
		// has already been confirmed, any pending second trade has already been
		// reconciled above, FinalItem must match the configured second output, and
		// the final item must be distinct from raw/intermediate inputs.  Under those
		// conditions, a shortage in the backpack is the portion already flushed from
		// this confirmed lot, even if a later checkpoint changed Phase away from
		// second_trade_confirmed/output_stored before the APP was restarted.
		if available < pending {
			phase := strings.TrimSpace(restoredLot.Phase)
			configuredFinal := strings.TrimSpace(secondOut.Item)
			finalMatchesConfigured := configuredFinal != "" && processingSameTradeItemV396(bot, restoredLot.FinalItem, configuredFinal)
			uniqueFinal := !processingSameTradeItemV396(bot, restoredLot.FinalItem, firstReq.Item) &&
				!processingSameTradeItemV396(bot, restoredLot.FinalItem, firstOut.Item) &&
				!processingSameTradeItemV396(bot, restoredLot.FinalItem, secondReq.Item)
			confirmedSecondLedger := restoredLot.SecondProduced > restoredLot.OutputStored &&
				restoredLot.SecondProduced > 0 && lotSecondInputConsumed > 0 && !restoredLot.SecondTradePending
			writeAhead := phase == "output_flushing" && finalMatchesConfigured
			legacyPartial := uniqueFinal && finalMatchesConfigured && confirmedSecondLedger
			if writeAhead || legacyPartial {
				alreadyStored := pending - available
				if alreadyStored > 0 {
					beforeStored := restoredLot.OutputStored
					lotOutputStored += alreadyStored
					restoredLot.OutputStored = lotOutputStored
					restoredLot.Phase = "output_stored"
					if err := processingPersistLotLedgerV412(bot, restoredLot); err != nil {
						finalErr = fmt.Errorf("續接成品缺口已確認但 checkpoint 修復失敗: %w", err)
						return
					}
					logCollectDiagnostic(bot, "processing_output_partial_resume_v422", fmt.Sprintf(
						"lot=%s phase=%s produced=%d previously_stored=%d available=%d inferred_already_stored=%d final_match=%v unique_final=%v",
						restoredLot.LotID, phase, restoredLot.SecondProduced, beforeStored, available, alreadyStored, finalMatchesConfigured, uniqueFinal,
					))
					pending = available
				}
			} else {
				finalErr = fmt.Errorf(
					"中斷批次 %s 有 %d 個已確認第二產物尚未記錄存箱，但背包只有 %d 個 %s；無法安全補帳（phase=%s final_match=%v unique_final=%v second_pending=%v），已停止避免重做",
					restoredLot.LotID, pending, available, restoredLot.FinalItem, phase, finalMatchesConfigured, uniqueFinal, restoredLot.SecondTradePending,
				)
				return
			}
		}

		if pending > 0 {
			processingSetStageV159(bot, "續接未存成品", fmt.Sprintf("%s × %d｜只補 checkpoint 尚未存入部分", restoredLot.FinalItem, pending))
			stored, storeErr := processingDepositLotOutputDurableV421(ctx, bot, outputBox, restoredLot.FinalItem, pending, "續接成品")
			lotOutputStored += stored
			if storeErr != nil || stored != pending {
				if storeErr == nil {
					storeErr = fmt.Errorf("只存入 %d/%d", stored, pending)
				}
				finalErr = fmt.Errorf("續接已確認成品失敗: %w", storeErr)
				return
			}
		}
		bot.mu.Lock()
		restoredLot = bot.ProcessLotLedger
		bot.mu.Unlock()
		lotOutputStored = restoredLot.OutputStored
	}

	// For a fixed-output trade, this is the hard maximum output one 1728-source
	// lot can produce. It prevents a bad delta from ever becoming a machine-return
	// request.
	if firstReq.Count > 0 && firstOut.CountExplicit && firstOut.Count > 0 {
		tradesPerLot := processingAutomationBoxBatchV317 / firstReq.Count
		if processingAutomationBoxBatchV317%firstReq.Count != 0 {
			tradesPerLot++
		}
		lotExpectedMaxOutput = tradesPerLot * firstOut.Count
	}

	// V426: one shared headroom escape for BOTH uninterrupted execution and
	// restart/resume. V421 only ran this after a first-stage sub-pass; a resumed
	// lot with raw=0 and a 36/36 backpack tried to refill the source first and
	// stopped before the escape path was ever reached. This helper consumes only
	// one complete second-stage batch from material ABOVE the still-reserved
	// machine share, then immediately durably stores that fresh final output.
	trySecondStageHeadroomV428 := func(reason string, forceFromSourceFull bool) (bool, error) {
		if !hasSecond || sourceBatchRemaining <= 0 {
			return false, nil
		}

		// V427: the source-box failure path has the freshest authoritative inventory,
		// but the outer controller may still hold a pre-open mirror. Refresh here so
		// a stale 32/36 snapshot can never suppress the headroom escape while the
		// source container later proves the backpack is actually 36/36.
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		beforeUsedAuthoritative := processingBackpackUsedSlotsV300(bot)
		// V428: once processingTakeFromBoxStableV176 has explicitly returned
		// "背包沒有空格", that server/container result is more authoritative than
		// the outer player-inventory mirror.  V427 refreshed the mirror and then
		// accidentally allowed a stale <33 snapshot to veto the escape path, so the
		// exact same full-bag error was returned forever.  In forced mode we skip the
		// occupancy gate and let the second-stage trade's own inventory validation
		// decide whether a complete safe batch actually exists.
		if !forceFromSourceFull && beforeUsedAuthoritative < 33 {
			return false, nil
		}

		// V427: before creating new final output, flush only final items that the
		// durable lot ledger already proves were produced but not yet stored. This is
		// safe at a full backpack and may free a slot without touching raw material,
		// machine reserve, carry items, or unrelated player inventory.
		bot.mu.Lock()
		headroomLedger := bot.ProcessLotLedger
		bot.mu.Unlock()
		pendingConfirmedFinal := headroomLedger.SecondProduced - headroomLedger.OutputStored
		pendingFinalItem := strings.TrimSpace(headroomLedger.FinalItem)
		if pendingConfirmedFinal > 0 && pendingFinalItem != "" &&
			!processingSameTradeItemV396(bot, pendingFinalItem, firstReq.Item) &&
			!processingSameTradeItemV396(bot, pendingFinalItem, secondReq.Item) {
			availablePendingFinal := helperOutputInventoryCountV159(bot, pendingFinalItem)
			toFlush := pendingConfirmedFinal
			if toFlush > availablePendingFinal {
				toFlush = availablePendingFinal
			}
			if toFlush > 0 {
				processingSetStageV159(bot, "背包續取前先補存成品", fmt.Sprintf(
					"%s｜checkpoint 已確認尚有 %d 個 %s 未存｜先補存 %d 個騰位",
					reason, pendingConfirmedFinal, pendingFinalItem, toFlush,
				))
				stored, storeErr := processingDepositLotOutputDurableV421(ctx, bot, outputBox, pendingFinalItem, toFlush, "續取前補存成品")
				lotOutputStored += stored
				if storeErr != nil {
					return stored > 0, fmt.Errorf("續取來源前補存已確認成品失敗: %w", storeErr)
				}
				processingRefreshInventoryAfterTradeV170(ctx, bot)
				if forceFromSourceFull && stored > 0 {
					// The source chest will immediately re-check real headroom. Even if the
					// outer slot-count mirror has not caught up yet, do not suppress the retry.
					return true, nil
				}
				if processingBackpackUsedSlotsV300(bot) < beforeUsedAuthoritative {
					return true, nil
				}
			}
		}
		reserveRemaining := 0
		reserveTarget := lotMachineReturnTarget
		if returnEnabled {
			if reserveTarget <= 0 {
				reserveTarget = processingFixedMachineReturnItemsV418
			}
			reserveRemaining = reserveTarget - lotMachineReturned
			if reserveRemaining < 0 {
				reserveRemaining = 0
			}
		}
		// V426: reserve the machine share against the FINAL deterministic lot output,
		// not against only what has already been produced in the backpack. Using
		// lotFirstProduced here created a deadlock: with a full backpack after the
		// first 64->64 trade, 64-864 is negative, so second stage was forbidden, but
		// no slot existed to load more raw material to ever reach the 864 reserve.
		// The safe invariant is cumulative: second-stage input may never exceed
		// (guaranteed whole-lot output + carry-in - machine reserve). Actual inventory
		// still gates every trade, so this cannot spend material that is not present.
		guaranteedLotOutput := lotFirstProduced
		if firstReq.Count > 0 && firstOut.CountExplicit && firstOut.Count > 0 &&
			processingAutomationBoxBatchV317%firstReq.Count == 0 {
			guaranteedLotOutput = (processingAutomationBoxBatchV317 / firstReq.Count) * firstOut.Count
		}
		secondBudgetRemaining := guaranteedLotOutput + lotSecondCarryIn - lotSecondInputConsumed - reserveRemaining
		if secondBudgetRemaining < 0 {
			secondBudgetRemaining = 0
		}
		secondAvailable := helperOutputInventoryCountV159(bot, secondReq.Item)
		// V427: the configured second requirement and the confirmed first output are
		// semantically the same stage material, but old proxy/alias state may expose
		// only one spelling to inventory search. Use the largest confirmed view only
		// for the availability gate; the actual trade still uses the configured
		// second-stage requirement and its normal authoritative validation.
		if aliasCount := helperOutputInventoryCountV159(bot, firstOut.Item); aliasCount > secondAvailable {
			secondAvailable = aliasCount
		}
		if strings.TrimSpace(lotIntermediateID) != "" {
			if aliasCount := helperOutputInventoryCountV159(bot, lotIntermediateID); aliasCount > secondAvailable {
				secondAvailable = aliasCount
			}
		}
		inputUnique := !processingSameTradeItemV396(bot, secondReq.Item, firstReq.Item)
		outputUnique := !processingSameTradeItemV396(bot, secondOut.Item, firstReq.Item) &&
			!processingSameTradeItemV396(bot, secondOut.Item, secondReq.Item)
		if secondBudgetRemaining < secondReq.Count || secondAvailable < secondReq.Count || !inputUnique || !outputUnique {
			logCollectDiagnostic(bot, "processing_headroom_blocked_v426", fmt.Sprintf(
				"reason=%s force_source_full=%v used=%d source_remaining=%d first_produced=%d guaranteed_lot_output=%d second_available=%d second_budget=%d reserve_remaining=%d need=%d input_unique=%v output_unique=%v",
				reason, forceFromSourceFull, processingBackpackUsedSlotsV300(bot), sourceBatchRemaining, lotFirstProduced, guaranteedLotOutput, secondAvailable, secondBudgetRemaining, reserveRemaining, secondReq.Count, inputUnique, outputUnique,
			))
			return false, nil
		}

		if returnEnabled && lotMachineReturnTarget <= 0 {
			lotMachineReturnTarget = reserveTarget
			bot.mu.Lock()
			reserveLedger := bot.ProcessLotLedger
			bot.mu.Unlock()
			reserveLedger.Active = true
			reserveLedger.MachineReturnTarget = lotMachineReturnTarget
			reserveLedger.SourceRemaining = sourceBatchRemaining
			reserveLedger.SourceConsumed = lotSourceConsumed
			reserveLedger.FirstProduced = lotFirstProduced
			reserveLedger.SecondCarryIn = lotSecondCarryIn
			reserveLedger.SecondInputConsumed = lotSecondInputConsumed
			reserveLedger.SecondProduced = lotSecondProduced
			reserveLedger.OutputStored = lotOutputStored
			if err := processingPersistLotLedgerV412(bot, reserveLedger); err != nil {
				return false, fmt.Errorf("背包騰位前無法鎖定機器保留量: %w", err)
			}
		}

		beforeUsed := processingBackpackUsedSlotsV300(bot)
		processingSetStageV159(bot, "背包將滿｜先換一組成品", fmt.Sprintf(
			"%s｜背包 %d/36 格｜中間產物 %d｜機器保留 %d｜可動用 %d｜先做完整 %d 個第二兌換並立即存箱",
			reason, beforeUsed, secondAvailable, reserveRemaining, secondBudgetRemaining, secondReq.Count,
		))

		secondInputBefore := helperOutputInventoryCountV159(bot, secondReq.Item)
		secondOutputBefore := helperOutputInventoryCountV159(bot, secondOut.Item)
		secondExpectedOut := 0
		if secondOut.CountExplicit {
			secondExpectedOut = secondOut.Count
		}
		if err := processingPrepareTradeCheckpointV420(bot, "second", secondReq.Item, secondOut.Item, secondInputBefore, secondOutputBefore, secondReq.Count, secondExpectedOut); err != nil {
			return false, fmt.Errorf("背包騰位第二兌換送出前 checkpoint 失敗: %w", err)
		}

		producedNow := 0
		finalProductID := strings.TrimSpace(secondOut.Item)
		beforeSecondProduced := lotSecondProduced
		finalID, finalCount, tradeErr := processingRunTradeStableV173(ctx, bot, secondTarget, secondReq.Item, secondReq.Count)
		if tradeErr != nil {
			if errors.Is(tradeErr, context.Canceled) || errors.Is(tradeErr, context.DeadlineExceeded) {
				return false, tradeErr
			}
			reconciled, reconcileErr := processingReconcilePendingTradesV420(ctx, bot, firstReq, firstOut, hasSecond, secondReq, secondOut)
			if reconcileErr != nil {
				return false, reconcileErr
			}
			if reconciled.SecondInputConsumed <= lotSecondInputConsumed || reconciled.SecondProduced <= beforeSecondProduced {
				return false, fmt.Errorf("背包騰位第二兌換未能確認成交: %w", tradeErr)
			}
			lotSecondInputConsumed = reconciled.SecondInputConsumed
			lotSecondProduced = reconciled.SecondProduced
			producedNow = lotSecondProduced - beforeSecondProduced
			finalProductID = strings.TrimSpace(reconciled.FinalItem)
		} else {
			if finalCount <= 0 || strings.TrimSpace(finalID) == "" {
				return false, errors.New("背包騰位第二兌換沒有可驗證的實際產物")
			}
			finalProductID = strings.TrimSpace(finalID)
			producedNow = finalCount
			lotSecondInputConsumed += secondReq.Count
			lotSecondProduced += finalCount
			bot.mu.Lock()
			ledger := bot.ProcessLotLedger
			bot.mu.Unlock()
			ledger.Active = true
			ledger.Phase = "second_trade_confirmed"
			ledger.FinalItem = finalProductID
			ledger.SourceRemaining = sourceBatchRemaining
			ledger.SourceConsumed = lotSourceConsumed
			ledger.FirstProduced = lotFirstProduced
			ledger.ReturnOwedUnits = lotReturnOwedUnits
			ledger.MachineReturnTarget = lotMachineReturnTarget
			ledger.MachineReturnDone = lotMachineReturnDone
			ledger.MachineReturned = lotMachineReturned
			ledger.SecondCarryIn = lotSecondCarryIn
			ledger.SecondInputConsumed = lotSecondInputConsumed
			ledger.SecondProduced = lotSecondProduced
			ledger.OutputStored = lotOutputStored
			processingClearTradePendingFieldsV420(&ledger, "second")
			if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
				return false, fmt.Errorf("背包騰位第二兌換已確認但 checkpoint 寫入失敗: %w", err)
			}
		}

		if producedNow <= 0 || finalProductID == "" {
			return false, errors.New("背包騰位第二兌換沒有可存入的確認產物")
		}
		processingSetStageV159(bot, "背包騰位成品存箱", fmt.Sprintf("%s × %d｜%s｜只存本次第二兌換新產物", finalProductID, producedNow, reason))
		stored, storeErr := processingDepositLotOutputDurableV421(ctx, bot, outputBox, finalProductID, producedNow, "背包騰位成品")
		lotOutputStored += stored
		if storeErr != nil || stored != producedNow {
			if storeErr == nil {
				storeErr = fmt.Errorf("只存入 %d/%d", stored, producedNow)
			}
			return stored > 0, fmt.Errorf("背包騰位成品存箱失敗: %w", storeErr)
		}
		processingRefreshInventoryAfterTradeV170(ctx, bot)
		if forceFromSourceFull {
			// A confirmed complete second-stage batch was consumed and its fresh final
			// output was durably removed from the backpack.  Retry the source chest and
			// let that authoritative operation prove whether a slot is now available;
			// do not require the asynchronous player mirror to change first.
			return true, nil
		}
		return processingBackpackUsedSlotsV300(bot) < beforeUsed, nil
	}

	for {
		if err := ctx.Err(); err != nil {
			finalErr = err
			return
		}
		bot.mu.Lock()
		if !bot.ProcessAutomationRunning || bot.ProcessAutomationGeneration != generation {
			bot.mu.Unlock()
			finalErr = context.Canceled
			return
		}
		bot.mu.Unlock()

		if !lotActive && processingBackpackUsedSlotsV300(bot) >= 32 {
			if err := processingPriorityClearBackpackV300(
				ctx, bot, sourceBox, machinePos, outputBox, machineConfigured,
				firstReq.Item, firstOut.Item, finalStageItem,
			); err != nil {
				finalErr = err
				return
			}
		}

		if !lotActive {
			// V420 write-ahead lot claim: persist the 1728-item lot BEFORE touching the
			// source chest. If the App closes while taking source items, the next Start
			// resumes this same quota instead of creating a fresh 1728 and filling the
			// backpack on top of already-taken material.
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			existingRaw := helperOutputInventoryCountV159(bot, firstReq.Item)
			if existingRaw < 0 {
				existingRaw = 0
			}
			sourceBatchRemaining = processingAutomationBoxBatchV317
			sourceBatchFill = 0
			lotFirstProduced = 0
			lotFirstTradeCount = 0
			lotSourceConsumed = 0
			lotReturnOwedUnits = 0
			lotIntermediateID = ""
			lotMachineReturnTarget = 0
			lotMachineReturnDone = false
			lotMachineReturned = 0
			lotSecondCarryIn = secondCarryCount
			lotSecondInputConsumed = 0
			lotSingleOutputDeposited = 0
			lotSecondProduced = 0
			lotOutputStored = 0
			lotActive = true
			ledger := processingNewLotLedgerV412(firstReq.Item, finalStageItem)
			ledger.Phase = "source_claimed_write_ahead"
			ledger.SecondCarryIn = lotSecondCarryIn
			if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
				finalErr = fmt.Errorf("開始取料前無法建立加工批次 checkpoint: %w", err)
				return
			}

			needFromSource := processingAutomationBoxBatchV317 - existingRaw
			if needFromSource < 0 {
				needFromSource = 0
			}
			processingSetStageV159(bot, "來源箱", fmt.Sprintf(
				"本盒固定 %d｜背包已有 %d 個 %s｜來源只需補 %d｜已有材料直接計入本盒，不重拿",
				processingAutomationBoxBatchV317, existingRaw, firstReq.Item, needFromSource,
			))

			var taken int
			var fill float64
			if needFromSource > 0 {
				for {
					taken, fill, err = processingTakeFromBoxStableV176(
						ctx, bot, sourceBox, firstReq.Item,
						firstReq.Count, processingAutomationBoxBatchV317,
					)
					if err == nil {
						break
					}
					if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
						if ctx.Err() != nil {
							finalErr = ctx.Err()
						} else {
							finalErr = err
						}
						return
					}
					if !processingInventoryTransientV176(err) {
						finalErr = err
						return
					}
					processingSetStageV159(bot, "來源箱自動恢復", fmt.Sprintf("%s｜已保留本盒 checkpoint，不登出軟重置後自動繼續", err.Error()))
					_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_source_outer_v420: "+err.Error(), 450*time.Millisecond)
					processingRefreshInventoryAfterTradeV170(ctx, bot)
					if waitErr := processingWaitRetryV176(ctx, 1200*time.Millisecond); waitErr != nil {
						finalErr = waitErr
						return
					}
				}
			}
			bot.mu.Lock()
			bot.ProcessSourceFill = fill
			bot.ProcessFeedPaused = false
			bot.mu.Unlock()

			loaded := helperOutputInventoryCountV159(bot, firstReq.Item)
			if loaded < firstReq.Count {
				processingSetStageV159(bot, "等待來源", fmt.Sprintf(
					"本盒 checkpoint 已保存｜背包目前 %s %d 個｜至少需要 %d 個才能開始第一兌換",
					firstReq.Item, loaded, firstReq.Count,
				))
				if waitErr := processingWaitRetryV176(ctx, 750*time.Millisecond); waitErr != nil {
					finalErr = waitErr
					return
				}
				continue
			}
			sourceBatchFill = fill
			bot.mu.Lock()
			ledger = bot.ProcessLotLedger
			bot.mu.Unlock()
			ledger.Active = true
			ledger.Phase = "source_loaded"
			ledger.SourceRemaining = sourceBatchRemaining
			ledger.SourceConsumed = lotSourceConsumed
			ledger.SecondCarryIn = lotSecondCarryIn
			if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
				finalErr = fmt.Errorf("來源材料已就緒但 checkpoint 寫入失敗: %w", err)
				return
			}
			processingSetStageV159(bot, "一盒已鎖定", fmt.Sprintf(
				"%s 本盒固定 %d｜啟動前背包已有 %d｜本次來源新增 %d｜目前可直接兌換 %d 個",
				firstReq.Item, sourceBatchRemaining, existingRaw, taken, loaded,
			))
		}
		// V321 one-box fail-safe: sourceBatchRemaining is the accounting quota, not
		// a requirement that all remaining raw items physically sit in the backpack.
		// If this box still has raw material left to process and the backpack chunk
		// has fallen below one trade, reopen the same source and load the next chunk.
		if sourceBatchRemaining > 0 &&
			helperOutputInventoryCountV159(bot, firstReq.Item) < firstReq.Count {
			// V428: this is the exact branch that emitted
			// "同一盒續取來源材料失敗" in V424-V426. Do not rely on an outer
			// occupancy snapshot. Refresh, attempt the safe escape, compact, then open
			// the source. If the source itself proves the backpack is full, close it,
			// run the same escape again, and retry the take instead of stopping first.
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			freed, headroomErr := trySecondStageHeadroomV428("本盒續取前", false)
			if headroomErr != nil {
				finalErr = headroomErr
				return
			}
			if freed {
				processingRefreshInventoryAfterTradeV170(ctx, bot)
			}
			processingSetStageV159(bot, "本盒續取", fmt.Sprintf(
				"同一盒尚有 %d 個原料待處理｜背包先整理，再續取下一批",
				sourceBatchRemaining,
			))
			if err := processingCompactForHeadroomV321(
				ctx, bot, "本盒續取前",
				firstReq.Item, firstOut.Item, finalStageItem,
			); err != nil {
				finalErr = err
				return
			}

			var refillFill float64
			var refillErr error
			for refillAttempt := 1; refillAttempt <= 3; refillAttempt++ {
				_, refillFill, refillErr = processingTakeFromBoxStableV176(
					ctx, bot, sourceBox, firstReq.Item,
					firstReq.Count, sourceBatchRemaining,
				)
				if refillErr == nil {
					break
				}

				refillMsg := refillErr.Error()
				fullBackpack := strings.Contains(refillMsg, "背包沒有空格") ||
					strings.Contains(refillMsg, "背包沒有可用空格")
				if !fullBackpack || refillAttempt >= 3 {
					break
				}

				processingRefreshInventoryAfterTradeV170(ctx, bot)
				freed, headroomErr = trySecondStageHeadroomV428(fmt.Sprintf("來源箱確認滿包後第 %d 次", refillAttempt), true)
				if headroomErr != nil {
					finalErr = headroomErr
					return
				}
				if !freed {
					break
				}
				processingRefreshInventoryAfterTradeV170(ctx, bot)
				if err := processingCompactForHeadroomV321(
					ctx, bot, "來源箱滿包後再整理",
					firstReq.Item, firstOut.Item, finalStageItem,
				); err != nil {
					finalErr = err
					return
				}
			}
			if refillErr != nil {
				finalErr = fmt.Errorf("同一盒續取來源材料失敗: %w", refillErr)
				return
			}
			sourceBatchFill = refillFill
		}
		fill := sourceBatchFill

		intermediateID := lotIntermediateID
		firstTrades := 0
		firstTradeRecoveries := 0
		// V316: do not wait for the old 48-trade mega batch before feeding the
		// machine. That saved container opens but could leave a fast hopper/machine
		// completely dry for a minute or more. Accumulate several trades, then flush
		// the exact owed amount in one container session. This keeps batching (never
		// open once per trade) while bounding the time that machine input can starve.
		for sourceBatchRemaining >= firstReq.Count && helperOutputInventoryCountV159(bot, firstReq.Item) >= firstReq.Count {
			processingSetStageV159(bot, "第一兌換", firstTarget)
			firstInputBefore := helperOutputInventoryCountV159(bot, firstReq.Item)
			firstOutputBefore := helperOutputInventoryCountV159(bot, firstOut.Item)
			firstExpectedOut := 0
			if firstOut.CountExplicit {
				firstExpectedOut = firstOut.Count
			}
			if err := processingPrepareTradeCheckpointV420(bot, "first", firstReq.Item, firstOut.Item, firstInputBefore, firstOutputBefore, firstReq.Count, firstExpectedOut); err != nil {
				finalErr = fmt.Errorf("第一兌換送出前保存交易 checkpoint 失敗: %w", err)
				return
			}
			receivedID, receivedCount, tradeErr := processingRunTradeStableV173(ctx, bot, firstTarget, firstReq.Item, firstReq.Count)
			if tradeErr != nil {
				if errors.Is(tradeErr, context.Canceled) || errors.Is(tradeErr, context.DeadlineExceeded) {
					// Keep the write-ahead pending checkpoint. The next Start will compare
					// the authoritative backpack and decide whether this exact trade committed.
					finalErr = tradeErr
					return
				}
				// V420: before retrying a failed/timeout-looking trade in the same App run,
				// reconcile the write-ahead checkpoint. This prevents a late server commit
				// from being overwritten by the next attempt and double-consuming material.
				reconciled, reconcileErr := processingReconcilePendingTradesV420(ctx, bot, firstReq, firstOut, hasSecond, secondReq, secondOut)
				if reconcileErr != nil {
					finalErr = reconcileErr
					return
				}
				if reconciled.FirstTradeCount > lotFirstTradeCount {
					recoveredProduced := reconciled.FirstProduced - lotFirstProduced
					if recoveredProduced < 0 {
						recoveredProduced = 0
					}
					sourceBatchRemaining = reconciled.SourceRemaining
					lotSourceConsumed = reconciled.SourceConsumed
					lotFirstTradeCount = reconciled.FirstTradeCount
					lotFirstProduced = reconciled.FirstProduced
					lotIntermediateID = reconciled.IntermediateItem
					intermediateID = reconciled.IntermediateItem
					firstTrades++
					firstTradeRecoveries = 0
					processingSetStageV159(bot, "第一兌換中斷續接", fmt.Sprintf("伺服器其實已成交｜補記產出 %d｜本盒剩餘原料 %d", recoveredProduced, sourceBatchRemaining))
					if processingBackpackUsedSlotsV300(bot) >= 33 || sourceBatchRemaining < firstReq.Count || firstTrades >= 256 {
						break
					}
					continue
				}
				// Real material exhaustion ends this batch cleanly. If no trade in this
				// batch has succeeded yet, recover the helper transaction state and retry.
				if errors.Is(tradeErr, errProcessingTradeMaterialShortV173) || firstTrades > 0 {
					break
				}

				firstTradeRecoveries++
				processingSetStageV159(bot, "第一兌換自動恢復", fmt.Sprintf(
					"%s｜第 %d 次清理交易狀態後重試",
					tradeErr.Error(), firstTradeRecoveries,
				))

				// V391: do not loop forever around processingRunTradeStableV173 with an
				// unchanged stale form generation. Each zero-success failure gets one
				// explicit processing-state recovery before the next /menu.
				if recoverErr := processingRecoverRejectedTradeV224(ctx, bot, firstTarget, tradeErr); recoverErr != nil {
					if errors.Is(recoverErr, context.Canceled) || errors.Is(recoverErr, context.DeadlineExceeded) {
						finalErr = recoverErr
						return
					}
					logCollectDiagnostic(bot, "processing_first_trade_outer_recover_fail_v391", fmt.Sprintf(
						"recovery=%d target=%s error=%v",
						firstTradeRecoveries, firstTarget, recoverErr,
					))
				}

				if waitErr := processingWaitRetryV176(ctx, 650*time.Millisecond); waitErr != nil {
					finalErr = waitErr
					return
				}
				continue
			}
			if receivedID != "" {
				intermediateID = receivedID
				lotIntermediateID = receivedID
			}
			if intermediateID == "" {
				intermediateID = firstOut.Item
				lotIntermediateID = intermediateID
			}
			if receivedCount > 0 {
				lotFirstProduced += receivedCount
				// V418: 第一階尚未整盒完成時只記實際產量，不建立回料 debt，
				// 也不允許第二階先吃掉中間產物。整盒 1728 全部第一階完成後，
				// 才一次建立固定 864 的回機器義務。
				if lotExpectedMaxOutput > 0 && lotFirstProduced > lotExpectedMaxOutput {
					finalErr = fmt.Errorf(
						"第一兌換本盒產物計數異常：已累計 %d，依固定交易批次本盒最多應為 %d；已停止避免回機器數量暴增",
						lotFirstProduced, lotExpectedMaxOutput,
					)
					logCollectDiagnostic(bot, "processing_lot_output_overflow_v380", fmt.Sprintf(
						"received_now=%d lot_produced=%d expected_max=%d first_req=%d first_out=%d target=%s",
						receivedCount, lotFirstProduced, lotExpectedMaxOutput, firstReq.Count, firstOut.Count, firstTarget,
					))
					return
				}
			}
			firstTrades++
			lotFirstTradeCount++
			lotSourceConsumed += firstReq.Count
			firstTradeRecoveries = 0
			sourceBatchRemaining -= firstReq.Count
			if sourceBatchRemaining < 0 {
				sourceBatchRemaining = 0
			}
			bot.mu.Lock()
			ledger := bot.ProcessLotLedger
			bot.mu.Unlock()
			ledger.Active = true
			ledger.Phase = "first_trade_confirmed"
			ledger.SourceItem = firstReq.Item
			ledger.IntermediateItem = lotIntermediateID
			ledger.FinalItem = finalStageItem
			ledger.SourcePlanned = processingAutomationBoxBatchV317
			ledger.SourceRemaining = sourceBatchRemaining
			ledger.SourceConsumed = lotSourceConsumed
			ledger.FirstTradeCount = lotFirstTradeCount
			ledger.FirstProduced = lotFirstProduced
			ledger.ReturnOwedUnits = lotReturnOwedUnits
			ledger.MachineReturnTarget = lotMachineReturnTarget
			ledger.MachineReturnDone = lotMachineReturnDone
			ledger.MachineReturned = lotMachineReturned
			ledger.SecondInputConsumed = lotSecondInputConsumed
			ledger.SecondProduced = lotSecondProduced
			ledger.OutputStored = lotOutputStored
			ledger.SingleOutputDeposited = lotSingleOutputDeposited
			processingClearTradePendingFieldsV420(&ledger, "first")
			if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
				finalErr = fmt.Errorf("第一兌換已確認但加工批次 checkpoint 寫入失敗: %w", err)
				return
			}

			// V317 one-box production: never open the machine in the middle of the
			// 1728-source-item lot. When backpack headroom gets low, stop the first
			// exchange sub-pass and let the second exchange consume only the
			// non-reserved intermediate amount. The exact machine share stays reserved
			// in the backpack/ledger until the whole 1728-item source lot is finished.
			// V326: preserve v317's proven trade profile. Never inject backpack
			// ItemStackRequests between successful helper trades. If headroom is low,
			// end this sub-pass and let the normal second-exchange/deposit stages free
			// space; compaction is only allowed at quiet checkpoints.
			if processingBackpackUsedSlotsV300(bot) >= 33 || sourceBatchRemaining < firstReq.Count {
				break
			}
			if firstTrades >= 256 {
				break
			}
		}
		// V426: uninterrupted first-stage headroom uses the same helper as restart/refill.
		if hasSecond && sourceBatchRemaining > 0 && processingBackpackUsedSlotsV300(bot) >= 33 {
			freed, headroomErr := trySecondStageHeadroomV428("第一階背包邊界", false)
			if headroomErr != nil {
				finalErr = headroomErr
				return
			}
			if freed {
				continue
			}
		}

		if sourceBatchRemaining > 0 && sourceBatchRemaining < firstReq.Count {
			finalErr = fmt.Errorf(
				"本盒 1728 無法完整跑完第一階：還剩 %d 個 %s，但第一兌換每次需要 %d；拒絕把未完成的一盒當完成",
				sourceBatchRemaining, firstReq.Item, firstReq.Count,
			)
			return
		}
		if intermediateID == "" {
			intermediateID = firstOut.Item
			lotIntermediateID = intermediateID
		}

		// V418: 回機器永遠以「本盒原料 1728」為基準，不看第一階產量。
		// 實際放入機器只會發生在第一階完整吃完本盒之後；第二階在此之前禁止啟動。
		if sourceBatchRemaining == 0 {
			if returnEnabled && !lotMachineReturnDone {
				if lotMachineReturnTarget <= 0 {
					lotMachineReturnTarget = processingFixedMachineReturnItemsV418
				}
				if lotReturnOwedUnits <= 0 {
					lotReturnOwedUnits = lotMachineReturnTarget * 100
					checkpointItem := strings.TrimSpace(intermediateID)
					if checkpointItem == "" {
						checkpointItem = strings.TrimSpace(firstOut.Item)
					}
					if err := processingPersistReturnCheckpointV401(bot, checkpointItem, lotReturnOwedUnits, "first_stage_complete"); err != nil {
						finalErr = fmt.Errorf("第一階整盒完成，但固定回料 checkpoint 寫入失敗: %w", err)
						return
					}
					bot.mu.Lock()
					ledger := bot.ProcessLotLedger
					bot.mu.Unlock()
					ledger.Active = true
					ledger.Phase = "first_stage_complete"
					ledger.SourceRemaining = sourceBatchRemaining
					ledger.SourceConsumed = lotSourceConsumed
					ledger.FirstProduced = lotFirstProduced
					ledger.FirstTradeCount = lotFirstTradeCount
					ledger.ReturnOwedUnits = lotReturnOwedUnits
					ledger.MachineReturnTarget = lotMachineReturnTarget
					ledger.MachineReturnDone = false
					ledger.MachineReturned = lotMachineReturned
					ledger.IntermediateItem = lotIntermediateID
					if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
						finalErr = fmt.Errorf("第一階整盒完成，但批次 checkpoint 寫入失敗: %w", err)
						return
					}
				}

				processingRefreshInventoryAfterTradeV170(ctx, bot)
				returnAvailable := helperOutputInventoryCountV159(bot, intermediateID)
				if returnAvailable < lotMachineReturnTarget {
					_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_fixed1728_return_short_v418", 350*time.Millisecond)
					processingRefreshInventoryAfterTradeV170(ctx, bot)
					returnAvailable = helperOutputInventoryCountV159(bot, intermediateID)
				}
				if returnAvailable < lotMachineReturnTarget {
					finalErr = fmt.Errorf(
						"固定回料不足：本盒原料 1728，50%% 應回 %d，但第一階完成後背包只有 %d 個 %s；已停止避免機器越做越少",
						lotMachineReturnTarget, returnAvailable, intermediateID,
					)
					return
				}

				processingSetStageV159(bot, "第一階完成｜固定 50% 回機器", fmt.Sprintf(
					"本盒原料 %d｜固定應回 %d｜第一階實際產出 %d｜現在一次放回機器",
					processingAutomationBoxBatchV317, lotMachineReturnTarget, lotFirstProduced,
				))
				returnedBatch, machineFull, returnErr := processingFlushReturnLotV380(
					ctx, bot, machinePos, intermediateID, returnPercent, lotMachineReturnTarget, 0,
				)
				lotMachineReturned += returnedBatch
				if lotMachineReturned > lotMachineReturnTarget {
					lotMachineReturned = lotMachineReturnTarget
				}
				if returnErr != nil {
					_ = processingSetLotMachineReturnV418(bot, lotMachineReturnTarget, lotMachineReturned, false)
					finalErr = fmt.Errorf("整盒固定回料失敗: %w", returnErr)
					return
				}
				lotReturnOwedUnits = 0
				lotMachineReturnDone = true
				if err := processingSetLotMachineReturnV418(bot, lotMachineReturnTarget, lotMachineReturned, true); err != nil {
					finalErr = fmt.Errorf("回機器已確認但批次 checkpoint 更新失敗: %w", err)
					return
				}
				status := fmt.Sprintf(
					"本盒原料 %d｜固定 50%% 應回 %d｜實際放入 %d｜第一階產出 %d",
					processingAutomationBoxBatchV317, lotMachineReturnTarget, lotMachineReturned, lotFirstProduced,
				)
				if machineFull {
					status += "｜機器投料箱已滿，未放入部分本盒略過"
				}
				processingSetStageV159(bot, "第一階完成｜回機器完成", status)
			} else if !returnEnabled {
				lotMachineReturnTarget = 0
				lotMachineReturnDone = true
			}
		}

		secondTrades := 0
		if hasSecond {
			if sourceBatchRemaining == 0 && (!returnEnabled || lotMachineReturnDone) {
				finalProducedThisSubBatch := 0
				finalProductID := strings.TrimSpace(secondOut.Item)

				// V418: 第二階只能吃「本盒第一階產出 - 本盒實際回機器」，
				// 且第一階與回機器未完成前完全不啟動第二階。用 durable consumed
				// 計數限制本盒預算，避免同名物品/重啟時把下一盒或原本背包物吃進來。
				secondInputTarget := lotFirstProduced - lotMachineReturned + lotSecondCarryIn
				if secondInputTarget < 0 {
					secondInputTarget = 0
				}
				for {
					secondAvailable := helperOutputInventoryCountV159(bot, secondReq.Item)
					secondBudgetRemaining := secondInputTarget - lotSecondInputConsumed
					if secondBudgetRemaining < secondReq.Count || secondAvailable < secondReq.Count {
						break
					}
					if secondTrades > 0 && finalProductID != "" &&
						processingBackpackUsedSlotsV300(bot) >= 34 &&
						helperOutputInventoryCountV159(bot, finalProductID) > 0 {
						// V326: same rule as v317—do not compact between trades. End the
						// sub-pass and use the normal bulk output deposit to make headroom.
						processingSetStageV159(bot, "背包將滿先存成品", fmt.Sprintf(
							"背包使用 %d/36 格｜先批次存 %s，再繼續第二兌換",
							processingBackpackUsedSlotsV300(bot), finalProductID,
						))
						break
					}
					processingSetStageV159(bot, "第二兌換", fmt.Sprintf("%s｜本批第 %d 筆", secondTarget, secondTrades+1))
					secondInputBefore := helperOutputInventoryCountV159(bot, secondReq.Item)
					secondOutputBefore := helperOutputInventoryCountV159(bot, secondOut.Item)
					secondExpectedOut := 0
					if secondOut.CountExplicit {
						secondExpectedOut = secondOut.Count
					}
					if err := processingPrepareTradeCheckpointV420(bot, "second", secondReq.Item, secondOut.Item, secondInputBefore, secondOutputBefore, secondReq.Count, secondExpectedOut); err != nil {
						finalErr = fmt.Errorf("第二兌換送出前保存交易 checkpoint 失敗: %w", err)
						return
					}
					finalID, finalCount, tradeErr := processingRunTradeStableV173(ctx, bot, secondTarget, secondReq.Item, secondReq.Count)
					if tradeErr != nil {
						if errors.Is(tradeErr, context.Canceled) || errors.Is(tradeErr, context.DeadlineExceeded) {
							// Keep the pending second-stage receipt for restart reconciliation.
							finalErr = tradeErr
							return
						}
						reconciled, reconcileErr := processingReconcilePendingTradesV420(ctx, bot, firstReq, firstOut, hasSecond, secondReq, secondOut)
						if reconcileErr != nil {
							finalErr = reconcileErr
							return
						}
						if reconciled.SecondInputConsumed > lotSecondInputConsumed {
							recoveredProduced := reconciled.SecondProduced - lotSecondProduced
							if recoveredProduced < 0 {
								recoveredProduced = 0
							}
							lotSecondInputConsumed = reconciled.SecondInputConsumed
							lotSecondProduced = reconciled.SecondProduced
							finalProductID = reconciled.FinalItem
							finalProducedThisSubBatch += recoveredProduced
							secondTrades++
							processingSetStageV159(bot, "第二兌換中斷續接", fmt.Sprintf("伺服器其實已成交｜補記產出 %d｜第二階累計投入 %d", recoveredProduced, lotSecondInputConsumed))
							if secondTrades >= 48 {
								break
							}
							continue
						}
						if errors.Is(tradeErr, errProcessingTradeMaterialShortV173) || secondTrades > 0 {
							break
						}
						processingSetStageV159(bot, "第二兌換自動恢復", fmt.Sprintf("%s｜2 秒後自動重試", tradeErr.Error()))
						if waitErr := processingWaitRetryV176(ctx, 2*time.Second); waitErr != nil {
							finalErr = waitErr
							return
						}
						continue
					}
					if finalCount <= 0 || strings.TrimSpace(finalID) == "" {
						finalErr = errors.New("第二兌換沒有可驗證的實際產物")
						return
					}
					finalProductID = strings.TrimSpace(finalID)
					finalProducedThisSubBatch += finalCount
					lotSecondInputConsumed += secondReq.Count
					lotSecondProduced += finalCount
					secondTrades++
					bot.mu.Lock()
					ledger := bot.ProcessLotLedger
					bot.mu.Unlock()
					ledger.Active = true
					ledger.Phase = "second_trade_confirmed"
					ledger.FinalItem = finalProductID
					ledger.SourceRemaining = sourceBatchRemaining
					ledger.SourceConsumed = lotSourceConsumed
					ledger.FirstProduced = lotFirstProduced
					ledger.ReturnOwedUnits = lotReturnOwedUnits
					ledger.MachineReturnTarget = lotMachineReturnTarget
					ledger.MachineReturnDone = lotMachineReturnDone
					ledger.MachineReturned = lotMachineReturned
					ledger.SecondCarryIn = lotSecondCarryIn
					ledger.SecondInputConsumed = lotSecondInputConsumed
					ledger.SecondProduced = lotSecondProduced
					ledger.OutputStored = lotOutputStored
					processingClearTradePendingFieldsV420(&ledger, "second")
					if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
						finalErr = fmt.Errorf("第二兌換已確認但批次 checkpoint 寫入失敗: %w", err)
						return
					}
					if secondTrades >= 48 {
						break
					}
				}

				// V173: opening/closing the output container after every fixed x64 trade was
				// the main throughput bottleneck. Chain all available second exchanges first,
				// then drain every matching final product in one container session.
				if secondTrades > 0 && finalProductID != "" && finalProducedThisSubBatch > 0 {
					processingRefreshInventoryAfterTradeV170(ctx, bot)
					availableFinal := helperOutputInventoryCountV159(bot, finalProductID)
					finalTotal := finalProducedThisSubBatch
					if availableFinal < finalTotal {
						_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_second_output_short_v401", 350*time.Millisecond)
						processingRefreshInventoryAfterTradeV170(ctx, bot)
						availableFinal = helperOutputInventoryCountV159(bot, finalProductID)
					}
					if availableFinal < finalTotal {
						finalErr = fmt.Errorf("第二兌換成品不足：伺服器已確認產出 %d 個 %s，但背包只有 %d；已停止避免成品數量被靜默縮小", finalTotal, finalProductID, availableFinal)
						return
					}
					if finalTotal > 0 {
						// V317: deposit only what THIS second-exchange sub-batch actually
						// produced. This is critical when second output == first input
						// (e.g. coarse dirt -> dirt): counting every matching dirt stack
						// would dump the still-unprocessed 1728-source-lot dirt into the
						// output box and corrupt the one-box accounting.
						processingSetStageV159(bot, "成品存箱", fmt.Sprintf("%s × %d｜本批實際產物一次存入｜%d 次兌換", finalProductID, finalTotal, secondTrades))
						storedTotal, storeErr := processingDepositLotOutputDurableV421(ctx, bot, outputBox, finalProductID, finalTotal, "成品")
						lotOutputStored += storedTotal
						if storeErr != nil {
							finalErr = storeErr
							return
						}
						if storedTotal != finalTotal {
							finalErr = fmt.Errorf("成品只存入 %d / %d 個 %s", storedTotal, finalTotal, finalProductID)
							return
						}
						bot.mu.Lock()
						ledger := bot.ProcessLotLedger
						bot.mu.Unlock()
						ledger.Active = true
						ledger.Phase = "output_stored"
						ledger.FinalItem = finalProductID
						ledger.SourceRemaining = sourceBatchRemaining
						ledger.SourceConsumed = lotSourceConsumed
						ledger.FirstProduced = lotFirstProduced
						ledger.MachineReturnTarget = lotMachineReturnTarget
						ledger.MachineReturnDone = lotMachineReturnDone
						ledger.MachineReturned = lotMachineReturned
						ledger.SecondCarryIn = lotSecondCarryIn
						ledger.SecondInputConsumed = lotSecondInputConsumed
						ledger.SecondProduced = lotSecondProduced
						ledger.OutputStored = lotOutputStored
						if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
							finalErr = fmt.Errorf("成品已存入但批次 checkpoint 寫入失敗: %w", err)
							return
						}
					}
				}
			}
		} else if sourceBatchRemaining == 0 && (!returnEnabled || lotMachineReturnDone) {
			// V418 single-stage mode also waits for the whole first stage and fixed
			// machine return before any first-stage output may enter the final box.
			// The first exchange output is the final product; after a full-machine skip,
			// only the amount actually returned is deducted from final output.
			processingRefreshInventoryAfterTradeV170(ctx, bot)
			desiredOutputTotal := lotFirstProduced
			if returnEnabled {
				if sourceBatchRemaining >= firstReq.Count {
					desiredOutputTotal -= lotReturnOwedUnits / 100
				} else {
					desiredOutputTotal -= lotMachineReturned
				}
			}
			if desiredOutputTotal < 0 {
				desiredOutputTotal = 0
			}
			toDeposit := desiredOutputTotal - lotSingleOutputDeposited
			if toDeposit < 0 {
				toDeposit = 0
			}
			if toDeposit > 0 {
				available := helperOutputInventoryCountV159(bot, intermediateID)
				if available < toDeposit {
					_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_single_output_short_v401", 350*time.Millisecond)
					processingRefreshInventoryAfterTradeV170(ctx, bot)
					available = helperOutputInventoryCountV159(bot, intermediateID)
				}
				if available < toDeposit {
					finalErr = fmt.Errorf("單段加工成品不足：本輪應存 %d 個 %s，但背包只有 %d；已停止避免帳面產量被縮小", toDeposit, intermediateID, available)
					return
				}
				processingSetStageV159(bot, "單段成品存箱", fmt.Sprintf("%s × %d｜第二兌換未設定，第一兌換產物直接存成品箱", intermediateID, toDeposit))
				storedTotal := 0
				for storedTotal < toDeposit {
					stored, storeErr := processingDepositStableV176(ctx, bot, outputBox, intermediateID, toDeposit-storedTotal, true)
					storedTotal += stored
					if stored > 0 {
						lotSingleOutputDeposited += stored
						lotOutputStored += stored
						bot.mu.Lock()
						ledger := bot.ProcessLotLedger
						bot.mu.Unlock()
						ledger.Active = true
						ledger.Phase = "output_stored"
						ledger.IntermediateItem = intermediateID
						ledger.FinalItem = intermediateID
						ledger.OutputStored = lotOutputStored
						ledger.SingleOutputDeposited = lotSingleOutputDeposited
						if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
							finalErr = fmt.Errorf("單段成品已移動但 checkpoint 寫入失敗: %w", err)
							return
						}
					}
					if storeErr == nil {
						continue
					}
					if errors.Is(storeErr, context.Canceled) || errors.Is(storeErr, context.DeadlineExceeded) {
						finalErr = storeErr
						return
					}
					if processingBoxFullV182(storeErr) {
						processingSetStageV159(bot, "等待成品箱空位", fmt.Sprintf("成品箱已滿｜已存 %d/%d 個 %s｜有空位自動續存", storedTotal, toDeposit, intermediateID))
						if waitErr := processingWaitForBoxSpaceV182(ctx, bot, outputBox, intermediateID, "等待成品箱空位"); waitErr != nil {
							finalErr = waitErr
							return
						}
						continue
					}
					if processingInventoryTransientV176(storeErr) {
						_ = bedrockSoftSessionRecoveryV185(ctx, bot, "processing_single_output_v401: "+storeErr.Error(), 450*time.Millisecond)
						processingRefreshInventoryAfterTradeV170(ctx, bot)
						if waitErr := processingWaitRetryV176(ctx, 900*time.Millisecond); waitErr != nil {
							finalErr = waitErr
							return
						}
						continue
					}
					finalErr = storeErr
					return
				}
				if storedTotal != toDeposit {
					finalErr = fmt.Errorf("單段加工成品只存入 %d/%d 個 %s", storedTotal, toDeposit, intermediateID)
					return
				}
				bot.mu.Lock()
				ledger := bot.ProcessLotLedger
				bot.mu.Unlock()
				ledger.Active = true
				ledger.Phase = "output_stored"
				ledger.IntermediateItem = intermediateID
				ledger.FinalItem = intermediateID
				ledger.SourceRemaining = sourceBatchRemaining
				ledger.SourceConsumed = lotSourceConsumed
				ledger.FirstProduced = lotFirstProduced
				ledger.MachineReturnTarget = lotMachineReturnTarget
				ledger.MachineReturnDone = lotMachineReturnDone
				ledger.MachineReturned = lotMachineReturned
				ledger.OutputStored = lotOutputStored
				ledger.SingleOutputDeposited = lotSingleOutputDeposited
				if err := processingPersistLotLedgerV412(bot, ledger); err != nil {
					finalErr = fmt.Errorf("單段成品已存入但批次 checkpoint 寫入失敗: %w", err)
					return
				}
			}
		}

		firstStageDone := sourceBatchRemaining == 0
		returnStageDone := !returnEnabled || lotMachineReturnDone
		secondStageDone := true
		secondCarryOut := 0
		if hasSecond {
			secondInputTarget := lotFirstProduced - lotMachineReturned + lotSecondCarryIn
			if secondInputTarget < 0 {
				secondInputTarget = 0
			}
			secondRemaining := secondInputTarget - lotSecondInputConsumed
			if secondRemaining < 0 {
				secondRemaining = 0
			}
			if firstStageDone && returnStageDone && secondRemaining > 0 && secondRemaining < secondReq.Count {
				// V419: a remainder smaller than one second-trade batch is a legal carry.
				// Keep the exact intermediate items in the backpack, persist the count,
				// and merge it into the next lot's second-stage budget.
				processingRefreshInventoryAfterTradeV170(ctx, bot)
				availableCarry := helperOutputInventoryCountV159(bot, secondReq.Item)
				if availableCarry < secondRemaining {
					finalErr = fmt.Errorf("第二階合法尾數應保留 %d 個 %s，但背包只剩 %d；已停止避免尾數憑空補帳", secondRemaining, secondReq.Item, availableCarry)
					return
				}
				secondCarryOut = secondRemaining
				secondStageDone = lotOutputStored >= lotSecondProduced
			} else {
				secondStageDone = secondRemaining == 0 && lotOutputStored >= lotSecondProduced
			}
		} else {
			desiredOutputTotal := lotFirstProduced - lotMachineReturned
			if desiredOutputTotal < 0 {
				desiredOutputTotal = 0
			}
			secondStageDone = lotSingleOutputDeposited >= desiredOutputTotal
		}
		if lotActive && firstStageDone && returnStageDone && secondStageDone {
			if hasSecond {
				if err := processingPersistSecondCarryV419(bot, secondReq.Item, secondCarryOut); err != nil {
					finalErr = fmt.Errorf("第二階尾數保存失敗: %w", err)
					return
				}
				secondCarryItem = strings.TrimSpace(secondReq.Item)
				secondCarryCount = secondCarryOut
			} else if secondCarryCount != 0 || secondCarryItem != "" {
				if err := processingPersistSecondCarryV419(bot, "", 0); err != nil {
					finalErr = fmt.Errorf("清除第二階尾數紀錄失敗: %w", err)
					return
				}
				secondCarryItem = ""
				secondCarryCount = 0
			}
			if err := processingClearLotLedgerV412(bot); err != nil {
				finalErr = fmt.Errorf("加工批次完成但完成 checkpoint 寫入失敗: %w", err)
				return
			}
			// V424: this is only a SOURCE lot boundary. It must never emit
			// "加工完成一盒". Physical output-box occupancy is authoritative and
			// processingSyncOutputBoxCompletionV424 emits completion only at 1728/1728.
			logCollectDiagnostic(bot, "processing_source_lot_complete_v424", fmt.Sprintf(
				"source=%s source_planned=%d first=%d returned=%d second=%d stored=%d carry=%d",
				firstReq.Item, processingAutomationBoxBatchV317, lotFirstProduced, lotMachineReturned, lotSecondProduced, lotOutputStored, secondCarryOut,
			))
			lotActive = false
			sourceBatchRemaining = 0
			lotFirstProduced = 0
			lotFirstTradeCount = 0
			lotSourceConsumed = 0
			lotReturnOwedUnits = 0
			lotIntermediateID = ""
			lotMachineReturnTarget = 0
			lotMachineReturnDone = false
			lotMachineReturned = 0
			lotSecondCarryIn = 0
			lotSecondInputConsumed = 0
			lotSingleOutputDeposited = 0
			lotSecondProduced = 0
			lotOutputStored = 0
		}
		processingSetStageV159(bot, "循環", fmt.Sprintf("本盒 1728｜剩餘原料 %d｜第一階產出 %d｜回機器 %d/%d｜第二階已投入 %d｜尾數保留 %d｜本輪第一兌換 %d 次 / 第二兌換 %d 次｜來源箱 %.0f%%", sourceBatchRemaining, lotFirstProduced, lotMachineReturned, lotMachineReturnTarget, lotSecondInputConsumed, secondCarryCount, firstTrades, secondTrades, fill*100))
		select {
		case <-ctx.Done():
			finalErr = ctx.Err()
			return
		case <-time.After(250 * time.Millisecond):
		}
	}
}

func validateProcessingConfigV159(bot *BotSession) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	bot.mu.Lock()
	sourceOK := bot.ProcessSourceBoxConfigured
	sourcePos := bot.ProcessSourceBox
	outputOK := bot.ProcessOutputBoxConfigured
	outputPos := bot.ProcessOutputBox
	first := strings.TrimSpace(bot.ProcessFirstExchange)
	second := strings.TrimSpace(bot.ProcessSecondExchange)
	secondCarryItem := strings.TrimSpace(bot.ProcessSecondCarryItem)
	secondCarryCount := bot.ProcessSecondCarryCount
	returnEnabled := bot.ProcessReturnEnabled
	machineOK := bot.ProcessMachinePosConfigured
	machinePos := bot.ProcessMachinePos
	owedUnits := bot.ProcessReturnOwedUnits
	bot.mu.Unlock()
	if !sourceOK {
		return errors.New("請先設定來源箱")
	}
	if !outputOK {
		return errors.New("請先設定成品箱")
	}
	if first == "" {
		return errors.New("請選擇第一兌換；第二兌換可以留空")
	}
	_, firstOut, err := processingTradePartsV159(first)
	if err != nil {
		return fmt.Errorf("第一兌換無法使用：%w", err)
	}
	if second != "" {
		secondReq, _, err := processingTradePartsV159(second)
		if err != nil {
			return fmt.Errorf("第二兌換無法使用：%w", err)
		}
		if !processingSameTradeItemV396(bot, firstOut.Item, secondReq.Item) {
			return fmt.Errorf("兌換鏈不相容：第一兌換產出 %s，但第二兌換需要 %s", firstOut.Item, secondReq.Item)
		}
		if secondCarryCount > 0 && (secondCarryItem == "" || !processingSameTradeItemV396(bot, secondCarryItem, secondReq.Item)) {
			return fmt.Errorf("上一盒仍保留 %d 個 %s 第二階尾數；請沿用原第二兌換，避免混料", secondCarryCount, secondCarryItem)
		}
	} else if secondCarryCount > 0 {
		return fmt.Errorf("上一盒仍保留 %d 個 %s 第二階尾數；不能取消第二兌換", secondCarryCount, secondCarryItem)
	}
	if owedUnits >= 100 && !returnEnabled {
		return fmt.Errorf("中斷前仍有 %d 個回料待補；請保持回機器開啟，開始後會先續接", owedUnits/100)
	}
	if returnEnabled && !machineOK {
		return errors.New("已開啟回機器，但尚未掃描並選擇機器投料箱")
	}
	if sourceOK && outputOK && sourcePos == outputPos {
		return errors.New("來源箱與成品箱不能是同一個座標；請重新掃描其中一個箱子")
	}
	if returnEnabled && sourceOK && machineOK && sourcePos == machinePos {
		return errors.New("來源箱與機器投料箱不能是同一個座標；否則來源取料會看起來像從機器箱把回料拿走")
	}
	if returnEnabled && machineOK && outputOK && machinePos == outputPos {
		return errors.New("機器投料箱與成品箱不能是同一個座標；否則回料與成品會混在同一箱")
	}
	return nil
}

// V382 note: any helper called from inside bot.mu must be a *Locked helper that
// does not acquire bot.mu again. In particular, logCollectDiagnostic,
// processingStatusV159 and bedrockContainerOpenMatchesTargetV204 must be called
// only after releasing bot.mu.
func processingStatusV159(bot *BotSession) map[string]interface{} {
	if bot == nil {
		return map[string]interface{}{"ok": false, "error": "找不到 BOT"}
	}
	statusStartedAt := time.Now()
	defer func() {
		if elapsed := time.Since(statusStartedAt); elapsed > 750*time.Millisecond {
			logCollectDiagnostic(bot, "processing_status_slow_v378", fmt.Sprintf("elapsed=%s", elapsed.Round(10*time.Millisecond)))
		}
	}()

	// V378: snapshot under one short lock, then release it before calling any helper
	// that may touch the world cache. V375 called bedrockContainerOpenMatchesTargetV204
	// while bot.mu was held; that helper reaches suiteContainerBlockAt(), which locks
	// bot.mu again. The result was a self-deadlock whenever ANY container (machine or
	// output box included) was open: status polling froze and Stop could not acquire
	// bot.mu either.
	bot.mu.Lock()
	running := bot.ProcessAutomationRunning
	sourceBox := bot.ProcessSourceBox
	sourceBoxConfigured := bot.ProcessSourceBoxConfigured
	firstExchange := bot.ProcessFirstExchange
	firstDelayMS := normaliseProcessingTradeDelayMSV372(bot.ProcessTradeDelayMS)
	secondDelayMS := normaliseProcessingTradeDelayMSV372(bot.ProcessSecondTradeDelayMS)
	returnEnabled := bot.ProcessReturnEnabled
	machinePos := bot.ProcessMachinePos
	machineConfigured := bot.ProcessMachinePosConfigured
	returnCount := bot.ProcessReturnCount
	returnOwedUnits := bot.ProcessReturnOwedUnits
	returnOwedItem := strings.TrimSpace(bot.ProcessReturnOwedItem)
	returnCheckpointPhase := strings.TrimSpace(bot.ProcessReturnCheckpointPhase)
	secondExchange := bot.ProcessSecondExchange
	secondCarryItem := strings.TrimSpace(bot.ProcessSecondCarryItem)
	secondCarryCount := bot.ProcessSecondCarryCount
	outputBox := bot.ProcessOutputBox
	outputConfigured := bot.ProcessOutputBoxConfigured
	stage := bot.ProcessStage
	status := bot.ProcessStatus
	lastError := bot.ProcessLastError
	sourceFill := bot.ProcessSourceFill
	feedPaused := bot.ProcessFeedPaused
	containerOpen := bot.MapArtContainerOpen
	containerReady := bot.MapArtContainerItemsReady
	containerPos := bot.MapArtContainerPos
	containerItems := append([]protocol.ItemInstance(nil), bot.MapArtContainerItems...)
	bot.mu.Unlock()

	// Only do the source-box identity check after the mutex is released.
	if sourceBoxConfigured && containerOpen && containerReady &&
		bedrockContainerOpenMatchesTargetV204(bot, sourceBox, containerPos) {
		sourceFill = processingContainerFillV375(containerItems)
	}

	return map[string]interface{}{
		"ok": true, "running": running,
		"source_box": sourceBox, "source_box_configured": sourceBoxConfigured,
		"first_exchange":        firstExchange,
		"trade_delay_ms":        firstDelayMS,
		"first_trade_delay_ms":  firstDelayMS,
		"second_trade_delay_ms": secondDelayMS,
		"return_enabled":        returnEnabled, "machine_pos": machinePos, "machine_pos_configured": machineConfigured,
		"machine_box": machinePos, "machine_box_configured": machineConfigured, "return_count": returnCount, "return_percent": returnCount, "return_owed_units": returnOwedUnits,
		"return_owed_items": returnOwedUnits / 100, "return_owed_item": returnOwedItem, "return_checkpoint_phase": returnCheckpointPhase,
		"second_exchange": secondExchange, "second_enabled": strings.TrimSpace(secondExchange) != "",
		"second_carry_item": secondCarryItem, "second_carry_count": secondCarryCount,
		"output_box": outputBox, "output_box_configured": outputConfigured,
		"stage": stage, "status": status, "last_error": lastError,
		"source_fill": sourceFill, "feed_paused": feedPaused,
	}
}

func parseVec3QueryV159(r *http.Request) (Vec3i, error) {
	if r == nil {
		return Vec3i{}, errors.New("缺少請求")
	}
	x, ex := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("x")))
	y, ey := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("y")))
	z, ez := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("z")))
	if ex != nil || ey != nil || ez != nil {
		return Vec3i{}, errors.New("箱子座標格式錯誤")
	}
	return Vec3i{X: x, Y: y, Z: z}, nil
}

func validateContainerScanBotV205(r *http.Request, expectedBotID int) error {
	if r == nil || expectedBotID <= 0 {
		return nil
	}
	raw := strings.TrimSpace(r.URL.Query().Get("scan_bot_id"))
	if raw == "" {
		return nil
	}
	scanBotID, err := strconv.Atoi(raw)
	if err != nil || scanBotID <= 0 {
		return errors.New("掃描結果的 BOT 身分格式錯誤，請重新掃描")
	}
	if scanBotID != expectedBotID {
		return fmt.Errorf("這筆箱子結果屬於 BOT-%d，目前是 BOT-%d；已拒絕跨 BOT 開箱，請用目前 BOT 重新掃描", scanBotID, expectedBotID)
	}
	return nil
}

// bedrockValidateScannedContainerV207 deliberately reuses the same BedrockFlayer
// navigation + minimal look/click sequence that the material-box automation has
// already proven on this server. Binding is discovery/verification only: one new
// ContainerOpen generated after our exact click is authoritative even if Geyser
// reports the paired half of a double chest or delays InventoryContent.
func bedrockBindingRegionCandidatesV208(bot *BotSession, target Vec3i) []Vec3i {
	out := []Vec3i{target}
	if bot == nil {
		return out
	}
	targetKind, targetOK := suiteContainerBlockAt(bot, target)
	group := ""
	if targetOK {
		group = bedrockDoubleChestGroupV204(targetKind)
	}
	if group == "" {
		return out
	}
	for _, off := range []Vec3i{{X: 1}, {X: -1}, {Z: 1}, {Z: -1}} {
		candidate := Vec3i{X: target.X + off.X, Y: target.Y, Z: target.Z + off.Z}
		kind, ok := suiteContainerBlockAt(bot, candidate)
		if !ok || bedrockDoubleChestGroupV204(kind) != group {
			continue
		}
		out = append(out, candidate)
	}
	return out
}

// bedrockValidateScannedContainerV207 intentionally delegates the whole open
// operation to bedrockOpenContainerAtControlled. That is the exact routine used
// by the material-box automation's per-box scanner, including the V205 safe-side
// obstacle route, strict interaction pose, look/click packet sequence and retry
// policy. The old V207 binder only reused bfGoto and then duplicated the click
// code; on this server that duplicate sequence could reach the chest but never
// receive ContainerOpen.
//
// A double chest may expose two BlockActor coordinates while the proxy accepts
// interaction more reliably on its paired half. Binding therefore verifies a
// tiny horizontal container region: clicked coordinate first, then only adjacent
// same-group chest halves. It never roams to unrelated containers.
func bedrockValidateScannedContainerV207(ctx context.Context, bot *BotSession, target Vec3i) (Vec3i, error) {
	if bot == nil {
		return Vec3i{}, errors.New("找不到 BOT")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if err := waitMapArtRuntimePreflight(ctx, bot, 20*time.Second); err != nil {
		return Vec3i{}, err
	}
	if _, ok := suiteContainerBlockAt(bot, target); !ok {
		if _, loaded := bot.mapArtWorldRuntimeID(target); !loaded {
			return Vec3i{}, fmt.Errorf("容器 %s 所在區塊尚未載入", target)
		}
	}

	candidates := bedrockBindingRegionCandidatesV208(bot, target)
	errs := make([]string, 0, len(candidates))
	for i, candidate := range candidates {
		if err := ctx.Err(); err != nil {
			return Vec3i{}, err
		}
		_ = bedrockCloseContainerControlled(bot)
		bot.mu.Lock()
		beforeSeq := bot.MapArtContainerOpenSeq
		bot.mu.Unlock()
		logCollectDiagnostic(bot, "BIND_AUTOMATION_OPEN_REQ_V208", fmt.Sprintf(
			"requested=%s candidate=%s region_index=%d/%d seq=%d",
			target, candidate, i+1, len(candidates), beforeSeq,
		))

		// Validation only needs a real ContainerOpen; inventory contents are read
		// later by the actual transfer/processing operation. This context flag is
		// consumed inside the same auto-scan open routine.
		openCtx := context.WithValue(ctx, suiteContainerValidationOpenOnlyContextKeyV206{}, true)
		// V213: bedrockOpenContainerAtControlled can legitimately spend more than
		// 9 seconds on one candidate: up to four ContainerOpen waits, three bounded
		// BedrockFlayer re-approaches, held-slot synchronisation and a SubChunk
		// refresh. The old 9s cap canceled the routine itself before its retry policy
		// could finish, producing only "context deadline exceeded" for both halves
		// of a double chest. Give each candidate its own complete budget.
		attemptCtx, cancel := context.WithTimeout(openCtx, 28*time.Second)
		err := bedrockOpenContainerAtControlled(attemptCtx, bot, candidate)
		cancel()
		if err != nil {
			if errors.Is(err, context.DeadlineExceeded) {
				err = fmt.Errorf("候選開箱超過 28 秒完整驗證預算: %w", err)
			}
			errs = append(errs, fmt.Sprintf("%s: %v", candidate, err))
			logCollectDiagnostic(bot, "BIND_AUTOMATION_OPEN_FAIL_V208", fmt.Sprintf(
				"requested=%s candidate=%s region_index=%d/%d error=%v",
				target, candidate, i+1, len(candidates), err,
			))
			continue
		}

		verified := candidate
		bot.mu.Lock()
		opened := bot.MapArtContainerOpen
		openPos := bot.MapArtContainerPos
		openSeq := bot.MapArtContainerOpenSeq
		windowID := bot.MapArtContainerWindowID
		bot.mu.Unlock()
		if opened {
			// Prefer the server's canonical half when it belongs to either the
			// requested chest or the fallback paired half.
			if bedrockContainerOpenMatchesTargetV204(bot, target, openPos) ||
				bedrockContainerOpenMatchesTargetV204(bot, candidate, openPos) {
				verified = openPos
			}
		}
		logCollectDiagnostic(bot, "BIND_AUTOMATION_OPEN_OK_V208", fmt.Sprintf(
			"requested=%s candidate=%s verified=%s region_index=%d/%d window=%d seq_before=%d seq_after=%d",
			target, candidate, verified, i+1, len(candidates), windowID, beforeSeq, openSeq,
		))
		return verified, nil
	}

	if len(errs) == 0 {
		return Vec3i{}, fmt.Errorf("伺服器沒有開啟容器 %s", target)
	}
	return Vec3i{}, fmt.Errorf("區域開箱確認失敗 %s（已用材料箱自動化原生開箱流程驗證 %d 個同箱候選）：%s", target, len(candidates), strings.Join(errs, " ｜ "))
}

func verifyAndBindContainerV159(ctx context.Context, bot *BotSession, pos Vec3i, kind string) (Vec3i, error) {
	// V214: binding is discovery, not an inventory operation.
	//
	// Previous revisions made a scanned container impossible to configure unless
	// the BOT could immediately reproduce a full player interaction and receive a
	// ContainerOpen. On this server that turned a reliable BlockActor/LevelChunk
	// discovery result into a fragile movement/held-slot/runtime-ID test, so users
	// could see a real chest in the scan but still be unable to bind it.
	//
	// A scan candidate already comes from this BOT's server-backed world cache:
	// BlockActorData, LevelChunk/SubChunk block-entity NBT, or a live container
	// runtime identity. Bind directly from that proof. The actual transfer or
	// processing task remains responsible for opening the box when it really needs
	// inventory contents. This deliberately removes movement, ContainerOpen waits,
	// control leases and modal-form interaction from configuration.
	if bot == nil {
		return Vec3i{}, errors.New("找不到 BOT")
	}
	if ctx != nil {
		select {
		case <-ctx.Done():
			return Vec3i{}, ctx.Err()
		default:
		}
	}

	bot.mu.Lock()
	connected := bot.Connected && bot.conn != nil
	ready := bot.PlayerReady && !bot.Respawning.Load()
	dimensionKnown := bot.MapArtDimensionKnown
	hasPlayer := bot.HasPlayerPos
	player := bot.LastPlayerPos
	botID := bot.ID
	bot.mu.Unlock()
	if !connected || !ready {
		return Vec3i{}, errors.New("BOT 尚未完成登入/出生")
	}
	if !dimensionKnown {
		return Vec3i{}, errors.New("世界維度尚未同步，請稍候再掃描")
	}
	if !hasPlayer {
		return Vec3i{}, errors.New("尚未取得 BOT 位置，請稍候再掃描")
	}

	blockName, ok := suiteContainerBlockAt(bot, pos)
	if !ok {
		return Vec3i{}, fmt.Errorf("%s 已不在目前 BOT 的箱子快取中，請重新掃描後再選", pos)
	}

	// Require the selected coordinate to still be present in this BOT's current
	// binding scan view. This prevents a stale UI row from being persisted after
	// the box/chunk changed, while keeping BOT sessions fully independent.
	rows := suiteScanNearbyContainersForBindingV202(bot, 96)
	seen := false
	for _, row := range rows {
		rowPos, posOK := row["position"].(Vec3i)
		if !posOK || rowPos != pos {
			continue
		}
		if rawID, exists := row["bot_id"]; exists {
			switch v := rawID.(type) {
			case int:
				if v != botID {
					continue
				}
			case float64:
				if int(v) != botID {
					continue
				}
			}
		}
		seen = true
		break
	}
	if !seen {
		return Vec3i{}, fmt.Errorf("%s 已不在 BOT %d 目前的掃描結果中，請重新掃描", pos, botID)
	}

	dx := float64(pos.X) + 0.5 - float64(player[0])
	dy := float64(pos.Y) + 0.5 - float64(player[1])
	dz := float64(pos.Z) + 0.5 - float64(player[2])
	distance := math.Sqrt(dx*dx + dy*dy + dz*dz)

	bot.mu.Lock()
	if bot.MapArtContainerHints == nil {
		bot.MapArtContainerHints = map[string]string{}
	}
	key := mapArtDimensionBlockKey(bot.MapArtCurrentDimension, pos)
	if strings.TrimSpace(bot.MapArtContainerHints[key]) == "" {
		name := strings.ToLower(strings.TrimSpace(blockName))
		if name == "" {
			name = "minecraft:container"
		}
		bot.MapArtContainerHints[key] = name
	}
	bot.mu.Unlock()

	logCollectDiagnostic(bot, "BIND_WORLD_PROOF_V214", fmt.Sprintf(
		"bot=%d kind=%q pos=%s block=%s distance=%.2f method=server_world_cache no_open=true",
		botID, strings.TrimSpace(kind), pos, blockName, distance,
	))
	return pos, nil
}

func registerTransferRoutesV183() {
	http.HandleFunc("/api/transport", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		sessionMu.RLock()
		bot := sessions[id]
		sessionMu.RUnlock()
		if bot == nil {
			mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到機器人"})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		switch action {
		case "", "status":
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		case "config":
			interval, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("interval")))
			maxRuns, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("max")))
			if interval < 0 {
				interval = 0
			}
			if maxRuns < 0 {
				maxRuns = 0
			}
			sourceCommand := strings.TrimSpace(r.URL.Query().Get("source_cmd"))
			destinationCommand := strings.TrimSpace(r.URL.Query().Get("destination_cmd"))
			bot.mu.Lock()
			if bot.TransferRunning {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "箱子搬運執行中，請先停止再修改設定"})
				return
			}
			bot.TransferInterval = interval
			bot.TransferMaxRuns = maxRuns
			bot.TransferSourceCommand = sourceCommand
			bot.TransferDestinationCommand = destinationCommand
			if strings.TrimSpace(bot.TransferStatus) == "" {
				bot.TransferStatus = "已停止"
			}
			bot.mu.Unlock()
			if err := saveAllScheduleConfigs(); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "搬運排程儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		case "scan":
			rng, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("range")))
			if rng <= 0 {
				rng = 16
			}
			// V220: Transfer must discover boxes with the exact same floor rule as
			// Automation. The old binding scan returned containers from floors above
			// and below (for example player Y=44 selecting a chest at Y=41), which
			// looked valid in the UI but could never be interacted with through the
			// current floor. Automation has always filtered those out.
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "candidates": suiteScanNearbyContainers(bot, rng)})
		case "bind_source", "bind_destination":
			if err := validateContainerScanBotV205(r, id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bot.mu.Lock()
			running := bot.TransferRunning
			bot.mu.Unlock()
			if running {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "箱子搬運執行中，請先停止再重新綁定箱子"})
				return
			}
			pos, err := parseVec3QueryV159(r)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			label := "驗證搬運來源箱"
			if action == "bind_destination" {
				label = "驗證搬運目的箱"
			}
			verifiedPos, err := verifyAndBindContainerV159(r.Context(), bot, pos, label)
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bot.mu.Lock()
			if action == "bind_source" {
				bot.TransferSourceBox = verifiedPos
				bot.TransferSourceBoxConfigured = true
			} else {
				bot.TransferDestinationBox = verifiedPos
				bot.TransferDestinationBoxConfigured = true
			}
			bot.mu.Unlock()
			if err := saveAllScheduleConfigs(); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "箱子設定儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		case "visit_source", "visit_destination":
			bot.mu.Lock()
			if bot.TransferRunning {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "箱子搬運執行中"})
				return
			}
			command := strings.TrimSpace(bot.TransferSourceCommand)
			if action == "visit_destination" {
				command = strings.TrimSpace(bot.TransferDestinationCommand)
			}
			bot.mu.Unlock()
			if command == "" {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先輸入並儲存傳送指令"})
				return
			}
			release, err := beginBedrockAction(r.Context(), bot, "搬運傳送點測試")
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			err = suiteSendBuildStorageCommandV111(r.Context(), bot, command)
			release()
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
		case "start":
			if err := bot.StartTransferV183(); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		case "stop":
			bot.StopTransferV183()
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		case "clear":
			bot.StopTransferV183()

			// V366: the persisted pending counter can be stale after the user manually
			// removes cargo from the backpack. Reconcile against the real inventory
			// before deciding whether clearing settings is unsafe.
			reconcileCtx, reconcileCancel := context.WithTimeout(r.Context(), 2500*time.Millisecond)
			pending, reconcileErr := transportReconcilePendingWithBackpackV366(reconcileCtx, bot)
			reconcileCancel()
			if reconcileErr != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{
					"ok":    false,
					"error": "無法確認背包待卸貨物狀態：" + reconcileErr.Error(),
				})
				return
			}
			if pending > 0 {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{
					"ok":    false,
					"error": fmt.Sprintf("實際背包仍有 %d 個與待卸貨紀錄相符的物品，不能清除搬運設定", pending),
				})
				return
			}

			bot.mu.Lock()
			bot.TransferInterval = 0
			bot.TransferMaxRuns = 0
			bot.TransferRunCount = 0
			bot.TransferSourceCommand = ""
			bot.TransferDestinationCommand = ""
			bot.TransferSourceBox = Vec3i{}
			bot.TransferDestinationBox = Vec3i{}
			bot.TransferSourceBoxConfigured = false
			bot.TransferDestinationBoxConfigured = false
			bot.TransferPending = nil
			bot.TransferPendingTotal = 0
			bot.TransferStatus = "已清除"
			bot.TransferLastError = ""
			bot.mu.Unlock()
			if err := saveAllScheduleConfigs(); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "搬運排程清除失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, transferStatusV183(bot))
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知搬運操作"})
		}
	})
}

func registerHelperProcessingRoutesV159() {
	http.HandleFunc("/api/helper-output", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		sessionMu.RLock()
		bot := sessions[id]
		sessionMu.RUnlock()
		if bot == nil {
			mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到機器人"})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		switch action {
		case "", "status":
			bot.mu.Lock()
			out := map[string]interface{}{"ok": true, "mode": bot.purchaseOutputModeLocked(), "box": bot.PurchaseOutputBox, "box_configured": bot.PurchaseOutputBoxConfigured, "status": bot.PurchaseOutputStatus}
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, out)
		case "scan":
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			if rng <= 0 {
				rng = 16
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "candidates": suiteScanNearbyContainersForBindingV202(bot, rng)})
		case "mode":
			mode := normalisePurchaseOutputModeV159(r.URL.Query().Get("mode"))
			bot.mu.Lock()
			if bot.ProcessAutomationRunning {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "加工循環執行中，請先停止再修改小幫手輸出方式"})
				return
			}
			if mode == purchaseOutputModeBoxV159 && !bot.PurchaseOutputBoxConfigured {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "請先掃描並選擇存放箱"})
				return
			}
			bot.PurchaseOutputMode = mode
			bot.applyPurchaseOutputModeLockedV159()
			switch mode {
			case purchaseOutputModeBoxV159:
				bot.PurchaseOutputStatus = "兌換成功後只存入本次新增物品"
			case purchaseOutputModeDropV159:
				bot.PurchaseOutputStatus = "兌換成功後只丟棄本次新增物品"
			default:
				bot.PurchaseOutputStatus = "兌換成功後保留在背包"
			}
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "永久儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "mode": mode})
		case "bind_box":
			if err := validateContainerScanBotV205(r, id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, err := parseVec3QueryV159(r)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			verifiedPos, err := verifyAndBindContainerV159(r.Context(), bot, pos, "驗證兌換存放箱")
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bot.mu.Lock()
			bot.PurchaseOutputBox = verifiedPos
			bot.PurchaseOutputBoxConfigured = true
			bot.PurchaseOutputStatus = "已綁定存放箱：" + helperOutputBoxLabelV159(verifiedPos)
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "永久儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "box": verifiedPos})
		case "clear_box":
			bot.mu.Lock()
			bot.PurchaseOutputBoxConfigured = false
			if bot.purchaseOutputModeLocked() == purchaseOutputModeBoxV159 {
				bot.PurchaseOutputMode = purchaseOutputModeBackpackV159
				bot.applyPurchaseOutputModeLockedV159()
			}
			bot.PurchaseOutputStatus = "存放箱已清除"
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "永久儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知操作"})
		}
	})

	http.HandleFunc("/api/processing", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		sessionMu.RLock()
		bot := sessions[id]
		sessionMu.RUnlock()
		if bot == nil {
			mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到機器人"})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		switch action {
		case "", "status":
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		case "scan":
			rng, _ := strconv.Atoi(r.URL.Query().Get("range"))
			if rng <= 0 {
				rng = 16
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "candidates": suiteScanNearbyContainersForBindingV202(bot, rng)})
		case "bind_source", "bind_output", "bind_machine":
			if err := validateContainerScanBotV205(r, id); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			pos, err := parseVec3QueryV159(r)
			if err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			verifiedPos, err := verifyAndBindContainerV159(r.Context(), bot, pos, "驗證加工箱")
			if err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bot.mu.Lock()
			switch action {
			case "bind_source":
				bot.ProcessSourceBox, bot.ProcessSourceBoxConfigured = verifiedPos, true
			case "bind_machine":
				bot.ProcessMachinePos, bot.ProcessMachinePosConfigured = verifiedPos, true
			default:
				bot.ProcessOutputBox, bot.ProcessOutputBoxConfigured = verifiedPos, true
				bot.ProcessOutputBoxFullNotified = false
			}
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "永久儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		case "machine_current":
			// V161 compatibility only: a player position is no longer accepted as the
			// machine target because return items must go into a verified container.
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "機器目標已改為投料箱，請用掃描附近箱子選擇"})
		case "speed":
			// V373: first and second exchange cadence can be adjusted independently
			// while the processing loop is running.
			tradeDelayMS, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("trade_delay_ms")))
			phase := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("phase")))
			bot.mu.Lock()
			if phase == "second" {
				bot.ProcessSecondTradeDelayMS = normaliseProcessingTradeDelayMSV372(tradeDelayMS)
			} else {
				bot.ProcessTradeDelayMS = normaliseProcessingTradeDelayMSV372(tradeDelayMS)
			}
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "兌換速度儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		case "config":
			bot.mu.Lock()
			if bot.ProcessAutomationRunning {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "加工循環執行中，請先停止再修改設定"})
				return
			}
			requestedReturn := r.URL.Query().Get("return_enabled") == "1" || strings.EqualFold(r.URL.Query().Get("return_enabled"), "true")
			if bot.ProcessReturnOwedUnits >= 100 && !requestedReturn {
				pending := bot.ProcessReturnOwedUnits / 100
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": fmt.Sprintf("中斷前仍有 %d 個回料待補，不能直接關閉回機器；按開始會先補完", pending)})
				return
			}
			bot.ProcessFirstExchange = strings.TrimSpace(r.URL.Query().Get("first"))
			bot.ProcessSecondExchange = strings.TrimSpace(r.URL.Query().Get("second"))
			tradeDelayMS, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("trade_delay_ms")))
			secondTradeDelayMS, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("second_trade_delay_ms")))
			bot.ProcessTradeDelayMS = normaliseProcessingTradeDelayMSV372(tradeDelayMS)
			bot.ProcessSecondTradeDelayMS = normaliseProcessingTradeDelayMSV372(secondTradeDelayMS)
			bot.ProcessReturnEnabled = requestedReturn
			bot.ProcessReturnCount = processingFixedMachineReturnPercentV393
			if !requestedReturn && bot.ProcessReturnOwedUnits < 100 {
				bot.ProcessReturnOwedUnits = 0
				bot.ProcessReturnOwedItem = ""
				bot.ProcessReturnCheckpointPhase = ""
			}
			bot.mu.Unlock()
			if err := saveHelperProcessingConfig(bot); err != nil {
				mapArtWriteJSON(w, http.StatusInternalServerError, map[string]interface{}{"ok": false, "error": "永久儲存失敗：" + err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		case "start":
			if err := validateProcessingConfigV159(bot); err != nil {
				mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			bot.mu.Lock()
			if bot.ProcessAutomationRunning {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
				return
			}
			if strings.TrimSpace(bot.WantExchangeItem) != "" || bot.TradeAutoDropRunning || bot.TradeAutoDropArmed || len(bot.TradeAutoDropQueue) > 0 {
				bot.mu.Unlock()
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": "小幫手交易或兌換後處理尚未結束；加工會共用同一交易狀態，請先結束該交易"})
				return
			}
			_ = bedrockYieldHelperScanLocked(bot)
			waitingFor := ""
			if bot.RootState != "" && bot.RootState != string(botRootIdle) {
				waitingFor = strings.TrimSpace(bot.RootStateLabel)
			} else if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" {
				waitingFor = bedrockControlOwnerLabel(owner)
				if kind := strings.TrimSpace(bot.BedrockActionKind); kind != "" {
					waitingFor = kind
				}
			}
			ctx, cancel := context.WithCancel(context.Background())
			bot.ProcessAutomationGeneration++
			generation := bot.ProcessAutomationGeneration
			bot.ProcessAutomationCancel = cancel
			bot.ProcessAutomationRunning = true
			bot.ProcessStage = "準備中"
			bot.ProcessStatus = "正在啟動加工循環"
			if waitingFor != "" {
				bot.ProcessStage = "等待控制權"
				bot.ProcessStatus = waitingFor + " 完成後自動開始加工"
			}
			bot.ProcessLastError = ""
			bot.ProcessLastActionAt = time.Time{}
			bot.ProcessTradeStarts = nil
			bot.ProcessLastTradeStartAt = time.Time{}
			bot.ProcessLastTradeDoneAt = time.Time{}
			bot.OperationCurrent = "加工循環"
			bot.OperationResult = "準備中"
			bot.mu.Unlock()
			go runProcessingAutomationV159(ctx, bot, generation)
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		case "stop":
			stopProcessingAutomationV411(bot, "已停止")
			mapArtWriteJSON(w, http.StatusOK, processingStatusV159(bot))
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知操作"})
		}
	})
}

func registerBedrockActionRoutes() {
	http.HandleFunc("/api/bedrock-action", func(w http.ResponseWriter, r *http.Request) {
		if enableCORS(w, r) {
			return
		}
		id, _ := strconv.Atoi(r.URL.Query().Get("id"))
		sessionMu.RLock()
		bot := sessions[id]
		sessionMu.RUnlock()
		if bot == nil {
			mapArtWriteJSON(w, http.StatusNotFound, map[string]interface{}{"ok": false, "error": "找不到機器人"})
			return
		}
		action := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("action")))
		if action == "status" || action == "" {
			bot.mu.Lock()
			pos := bot.LastPlayerPos
			hasPos := bot.HasPlayerPos
			open := bot.MapArtContainerOpen
			openPos := bot.MapArtContainerPos
			bot.mu.Unlock()
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "has_position": hasPos, "position": pos, "container_open": open, "container_pos": openPos})
			return
		}
		if r.Method != http.MethodPost {
			mapArtWriteJSON(w, http.StatusMethodNotAllowed, map[string]interface{}{"ok": false, "error": "POST only"})
			return
		}
		if action == "close" {
			if err := bedrockCloseContainer(r.Context(), bot); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
			mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true})
			return
		}
		x, ex := strconv.Atoi(r.URL.Query().Get("x"))
		y, ey := strconv.Atoi(r.URL.Query().Get("y"))
		z, ez := strconv.Atoi(r.URL.Query().Get("z"))
		if ex != nil || ey != nil || ez != nil {
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "x/y/z 必須是整數"})
			return
		}
		target := Vec3i{X: x, Y: y, Z: z}
		ctx, cancel := context.WithTimeout(r.Context(), 35*time.Second)
		defer cancel()
		switch action {
		case "walk":
			maxDistance, _ := strconv.ParseFloat(r.URL.Query().Get("max_distance"), 64)
			if maxDistance <= 0 {
				maxDistance = 256
			}
			if err := botRootRun(ctx, bot, botRootEvading, "manual-walk-"+uuid.NewString(), "前往座標 "+target.String(), func(rootCtx context.Context) error {
				return bedrockWalkTo(rootCtx, bot, target, maxDistance)
			}); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
		case "open", "chest", "container":
			if err := botRootRun(ctx, bot, botRootReplenishing, "manual-container-"+uuid.NewString(), "開啟容器 "+target.String(), func(rootCtx context.Context) error {
				return bedrockOpenContainerAt(rootCtx, bot, target)
			}); err != nil {
				mapArtWriteJSON(w, http.StatusConflict, map[string]interface{}{"ok": false, "error": err.Error()})
				return
			}
		default:
			mapArtWriteJSON(w, http.StatusBadRequest, map[string]interface{}{"ok": false, "error": "未知操作；可用 walk/open/close/status"})
			return
		}
		mapArtWriteJSON(w, http.StatusOK, map[string]interface{}{"ok": true, "target": target})
	})
}

func ParseCollectCommand(message, botName string) (CollectCommand, bool, error) {
	fields := strings.Fields(strings.TrimSpace(message))
	if len(fields) == 0 {
		return CollectCommand{}, false, nil
	}
	lower0 := strings.ToLower(fields[0])
	if lower0 == "/m" || lower0 == "/msg" || lower0 == "/tell" || lower0 == "/w" {
		if len(fields) < 3 || (botName != "" && !strings.EqualFold(fields[1], botName)) {
			return CollectCommand{}, false, nil
		}
		fields = fields[2:]
	} else if strings.HasPrefix(fields[0], "@") {
		if botName != "" && !strings.EqualFold(strings.TrimPrefix(fields[0], "@"), botName) {
			return CollectCommand{}, false, nil
		}
		fields = fields[1:]
	}
	if len(fields) == 0 {
		return CollectCommand{}, false, nil
	}
	root := strings.ToLower(fields[0])

	if root == "autodrop" || root == "auto-drop" || fields[0] == "自動丟" || fields[0] == "自動丟棄" {
		if len(fields) < 2 {
			return CollectCommand{Action: "autodrop_status"}, true, nil
		}
		sub := strings.ToLower(strings.TrimSpace(fields[1]))
		switch sub {
		case "on", "enable", "start", "開", "开启", "開啟":
			return CollectCommand{Action: "autodrop_on"}, true, nil
		case "off", "disable", "stop", "關", "关闭", "關閉":
			return CollectCommand{Action: "autodrop_off"}, true, nil
		case "status", "list", "狀態", "状态", "列表":
			return CollectCommand{Action: "autodrop_status"}, true, nil
		case "clear", "清空", "全部刪除":
			return CollectCommand{Action: "autodrop_clear"}, true, nil
		case "remove", "delete", "del", "刪除", "删除", "移除":
			if len(fields) < 3 {
				return CollectCommand{}, true, errors.New("用法：自動丟 刪除 <物品>")
			}
			return CollectCommand{Action: "autodrop_remove", Target: strings.Join(fields[2:], " ")}, true, nil
		case "add", "set", "新增", "加入", "設定", "设置":
			if len(fields) < 3 {
				return CollectCommand{}, true, errors.New("用法：自動丟 新增 <物品> [保留 數量]")
			}
			keep := 0
			end := len(fields)
			if len(fields) >= 5 {
				k := strings.ToLower(fields[len(fields)-2])
				if k == "keep" || k == "保留" {
					n, convErr := strconv.Atoi(fields[len(fields)-1])
					if convErr != nil || n < 0 {
						return CollectCommand{}, true, errors.New("保留數量必須是 0 或正整數")
					}
					keep = n
					end = len(fields) - 2
				}
			}
			target := strings.TrimSpace(strings.Join(fields[2:end], " "))
			if target == "" {
				return CollectCommand{}, true, errors.New("缺少自動丟物品名稱")
			}
			return CollectCommand{Action: "autodrop_add", Target: target, Count: keep}, true, nil
		default:
			// 簡寫：自動丟 <物品> 直接等同新增並全丟。
			target := strings.TrimSpace(strings.Join(fields[1:], " "))
			return CollectCommand{Action: "autodrop_add", Target: target, Count: 0}, true, nil
		}
	}

	if root == "drop" || root == "discard" || fields[0] == "丟" || fields[0] == "丟棄" {
		if len(fields) < 2 {
			return CollectCommand{}, true, errors.New("用法：drop <物品ID|all> [數量]；例如 drop cobblestone 64、drop all")
		}
		count := 0
		if len(fields) >= 3 {
			if strings.EqualFold(fields[2], "all") || fields[2] == "全部" {
				count = 0
			} else {
				n, convErr := strconv.Atoi(fields[2])
				if convErr != nil || n <= 0 {
					return CollectCommand{}, true, errors.New("丟棄數量必須是正整數，或使用 all/全部")
				}
				count = n
			}
		}
		target := strings.TrimSpace(fields[1])
		if strings.EqualFold(target, "all") || target == "全部" {
			target = "*"
		}
		return CollectCommand{Action: "drop", Target: target, Count: count}, true, nil
	}
	return CollectCommand{}, false, nil
}

type BedrockActionCommand struct {
	Action      string
	Target      Vec3i
	MaxDistance float64
}

func ParseBedrockActionCommand(message, botName string) (BedrockActionCommand, bool, error) {
	fields := strings.Fields(strings.TrimSpace(clean(message)))
	if len(fields) == 0 {
		return BedrockActionCommand{}, false, nil
	}
	lower0 := strings.ToLower(fields[0])
	if lower0 == "/m" || lower0 == "/msg" || lower0 == "/tell" || lower0 == "/w" {
		if len(fields) < 3 || (botName != "" && !strings.EqualFold(fields[1], botName)) {
			return BedrockActionCommand{}, false, nil
		}
		fields = fields[2:]
	} else if strings.HasPrefix(fields[0], "@") {
		if botName != "" && !strings.EqualFold(strings.TrimPrefix(fields[0], "@"), botName) {
			return BedrockActionCommand{}, false, nil
		}
		fields = fields[1:]
	}
	if len(fields) == 0 {
		return BedrockActionCommand{}, false, nil
	}

	root := strings.ToLower(strings.TrimSpace(fields[0]))
	switch root {
	case "walk", "走路", "走":
		if len(fields) < 4 || len(fields) > 5 {
			return BedrockActionCommand{}, true, errors.New("用法：walk <X> <Y> <Z> [最大距離]")
		}
		x, ex := strconv.Atoi(fields[1])
		y, ey := strconv.Atoi(fields[2])
		z, ez := strconv.Atoi(fields[3])
		if ex != nil || ey != nil || ez != nil {
			return BedrockActionCommand{}, true, errors.New("walk 的 X/Y/Z 必須是整數")
		}
		maxDistance := 256.0
		if len(fields) == 5 {
			v, err := strconv.ParseFloat(fields[4], 64)
			if err != nil || v <= 0 {
				return BedrockActionCommand{}, true, errors.New("walk 最大距離必須大於 0")
			}
			maxDistance = v
		}
		return BedrockActionCommand{Action: "walk", Target: Vec3i{X: x, Y: y, Z: z}, MaxDistance: maxDistance}, true, nil

	case "open", "chest", "container", "開箱", "开箱":
		if len(fields) != 4 {
			return BedrockActionCommand{}, true, errors.New("用法：open <X> <Y> <Z>")
		}
		x, ex := strconv.Atoi(fields[1])
		y, ey := strconv.Atoi(fields[2])
		z, ez := strconv.Atoi(fields[3])
		if ex != nil || ey != nil || ez != nil {
			return BedrockActionCommand{}, true, errors.New("open 的 X/Y/Z 必須是整數")
		}
		return BedrockActionCommand{Action: "open", Target: Vec3i{X: x, Y: y, Z: z}}, true, nil

	case "close", "關箱", "关箱":
		if len(fields) != 1 {
			return BedrockActionCommand{}, true, errors.New("用法：close")
		}
		return BedrockActionCommand{Action: "close"}, true, nil

	case "status", "狀態", "状态":
		if len(fields) != 1 {
			return BedrockActionCommand{}, true, errors.New("用法：status")
		}
		return BedrockActionCommand{Action: "status"}, true, nil
	}
	return BedrockActionCommand{}, false, nil
}

func sendBedrockActionChatReply(bot *BotSession, recipient, message string) {
	if bot == nil {
		return
	}
	recipient = strings.TrimSpace(clean(recipient))
	message = strings.TrimSpace(clean(message))
	if recipient == "" || message == "" {
		return
	}
	bot.mu.Lock()
	conn := bot.conn
	connected := bot.Connected
	bot.mu.Unlock()
	if !connected || conn == nil {
		return
	}
	if err := sendClientMessage(conn, "/m "+recipient+" [控制Bot] "+message); err != nil {
		bot.AddSystemLog("控制指令回覆失敗：" + err.Error())
		return
	}
	if err := conn.Flush(); err != nil {
		bot.AddSystemLog("控制指令回覆送出失敗：" + err.Error())
	}
}

func handleBedrockActionChatCommand(bot *BotSession, message, replyTo string) bool {
	if bot == nil {
		return false
	}
	bot.mu.Lock()
	botName := bot.Name
	bot.mu.Unlock()
	cmd, matched, err := ParseBedrockActionCommand(message, botName)
	if !matched {
		return false
	}
	if err != nil {
		bot.AddGameLog("[控制Bot] " + err.Error())
		sendBedrockActionChatReply(bot, replyTo, err.Error())
		return true
	}

	switch cmd.Action {
	case "walk":
		sendBedrockActionChatReply(bot, replyTo, "開始走到 "+cmd.Target.String())
		go func(target Vec3i, maxDistance float64, recipient string) {
			ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
			defer cancel()
			if err := botRootRun(ctx, bot, botRootEvading, "chat-walk-"+uuid.NewString(), "前往座標 "+target.String(), func(rootCtx context.Context) error {
				return bedrockWalkTo(rootCtx, bot, target, maxDistance)
			}); err != nil {
				msg := "走路失敗：" + err.Error()
				bot.AddGameLog("[控制Bot] " + msg)
				sendBedrockActionChatReply(bot, recipient, msg)
				return
			}
			msg := "已到達 " + target.String()
			bot.AddGameLog("[控制Bot] " + msg)
			sendBedrockActionChatReply(bot, recipient, msg)
		}(cmd.Target, cmd.MaxDistance, replyTo)

	case "open":
		sendBedrockActionChatReply(bot, replyTo, "開始前往並開啟 "+cmd.Target.String())
		go func(target Vec3i, recipient string) {
			ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
			defer cancel()
			if err := botRootRun(ctx, bot, botRootReplenishing, "chat-container-"+uuid.NewString(), "開啟容器 "+target.String(), func(rootCtx context.Context) error {
				return bedrockOpenContainerAt(rootCtx, bot, target)
			}); err != nil {
				msg := "開箱失敗：" + err.Error()
				bot.AddGameLog("[控制Bot] " + msg)
				sendBedrockActionChatReply(bot, recipient, msg)
				return
			}
			msg := "箱子已開啟 " + target.String()
			bot.AddGameLog("[控制Bot] " + msg)
			sendBedrockActionChatReply(bot, recipient, msg)
		}(cmd.Target, replyTo)

	case "close":
		if err := bedrockCloseContainer(context.Background(), bot); err != nil {
			msg := "關箱失敗：" + err.Error()
			bot.AddGameLog("[控制Bot] " + msg)
			sendBedrockActionChatReply(bot, replyTo, msg)
			return true
		}
		bot.AddGameLog("[控制Bot] 已關閉目前容器")
		sendBedrockActionChatReply(bot, replyTo, "已關閉目前容器")

	case "status":
		bot.mu.Lock()
		pos := bot.LastPlayerPos
		hasPos := bot.HasPlayerPos
		opened := bot.MapArtContainerOpen
		openPos := bot.MapArtContainerPos
		mapArtMode := bot.MapArtMode
		manualRunning := bot.BedrockActionRunning
		manualKind := bot.BedrockActionKind
		bot.mu.Unlock()
		posText := "未知"
		if hasPos {
			posText = fmt.Sprintf("%.1f %.1f %.1f", pos[0], pos[1], pos[2])
		}
		containerText := "關閉"
		if opened {
			containerText = "開啟@" + openPos.String()
		}
		sendBedrockActionChatReply(
			bot,
			replyTo,
			fmt.Sprintf("位置=%s；箱子=%s；地圖繪=%t；手動=%t(%s)", posText, containerText, mapArtMode, manualRunning, manualKind),
		)
	}
	return true
}

// collectCommandTail extracts a command from the decorated chat/whisper strings used by
// Bedrock servers, for example "[Steve -> Bot] collect sand 64 vein". Plain commands are
// returned unchanged. The actual command parser remains strict after this extraction.
func collectCommandTail(message string) string {
	text := strings.TrimSpace(clean(message))
	fields := strings.Fields(text)
	for i, field := range fields {
		token := strings.ToLower(strings.Trim(field, "[]<>(){}:：,，;；!！?？'\"「」『』【】"))
		if token == "drop" || token == "discard" || token == "丟" || token == "丟棄" || token == "autodrop" || token == "auto-drop" || token == "自動丟" || token == "自動丟棄" ||
			token == "walk" || token == "走路" || token == "走" || token == "open" || token == "chest" || token == "container" || token == "開箱" || token == "开箱" || token == "close" || token == "關箱" || token == "关箱" || token == "status" || token == "狀態" || token == "状态" {
			return strings.Join(fields[i:], " ")
		}
	}
	return text
}

var collectSystemWhisperPattern = regexp.MustCompile(`^\[\s*(.+?)\s*(-\s*>|→|➜|»)\s*(.+?)\s*\]\s*(.*)$`)

// collectCanonicalWhitelistName returns the spelling stored in the whitelist.
// Replies use this canonical value rather than server-added ranks or decorations.
func collectCanonicalWhitelistName(bot *BotSession, name string) string {
	name = strings.TrimSpace(clean(name))
	if bot == nil || name == "" {
		return ""
	}
	cfg := tpaPolicySnapshotV407(bot.ID)
	for _, raw := range cfg.Whitelist {
		candidate := strings.TrimSpace(clean(raw))
		if strings.EqualFold(candidate, name) {
			return candidate
		}
	}
	return ""
}

func collectTextPacketRawValues(pk *packet.Text) []string {
	if pk == nil {
		return nil
	}
	values := make([]string, 0, 1+len(pk.Parameters))
	if message := strings.TrimSpace(clean(pk.Message)); message != "" {
		values = append(values, message)
	}
	for _, raw := range pk.Parameters {
		if value := strings.TrimSpace(clean(raw)); value != "" {
			values = append(values, value)
		}
	}
	return values
}

func collectTextIsCommand(text, botName string) bool {
	cleaned := strings.TrimSpace(clean(text))
	if _, matched, _ := ParseCollectCommand(cleaned, botName); matched {
		return true
	}
	_, matched, _ := ParseBedrockActionCommand(cleaned, botName)
	return matched
}

func collectEnvelopeRecipientIsBot(recipient, botName string) bool {
	recipient = strings.TrimSpace(clean(recipient))
	if recipient == "您" || recipient == "你" || strings.EqualFold(recipient, "you") {
		return true
	}
	return botName != "" && strings.EqualFold(recipient, strings.TrimSpace(clean(botName)))
}

// collectWhitelistedTextCommand authenticates the sender and returns only the exact
// command text tied to that sender. It deliberately does not search a combined packet
// string: doing so could mistake the recipient in "[您 -> Ryan]" for the sender and
// make the bot execute its own reply.
func collectWhitelistedTextCommand(bot *BotSession, pk *packet.Text) (sender, command string, ok bool) {
	if bot == nil || pk == nil {
		return "", "", false
	}
	bot.mu.Lock()
	botName := strings.TrimSpace(clean(bot.Name))
	bot.mu.Unlock()
	values := collectTextPacketRawValues(pk)

	// A private-message envelope carries both direction and identity. It takes
	// precedence over every fallback, including SourceName.
	for _, text := range values {
		match := collectSystemWhisperPattern.FindStringSubmatch(text)
		if len(match) < 5 || !collectTextIsCommand(match[4], botName) {
			continue
		}
		rawSender := strings.TrimSpace(clean(match[1]))
		if rawSender == "您" || rawSender == "你" || strings.EqualFold(rawSender, "you") ||
			(botName != "" && strings.EqualFold(rawSender, botName)) ||
			!collectEnvelopeRecipientIsBot(match[3], botName) {
			return "", "", false
		}
		canonical := collectCanonicalWhitelistName(bot, rawSender)
		if canonical == "" {
			return "", "", false
		}
		return canonical, strings.TrimSpace(clean(match[4])), true
	}

	// Some servers use a native Whisper packet instead of a formatted envelope.
	// SourceName is trusted only for whisper packet types: accepting it on Chat
	// would allow a public "collect ..." message to trigger a bot.
	switch pk.TextType {
	case packet.TextTypeWhisper, packet.TextTypeObjectWhisper:
		source := strings.TrimSpace(clean(pk.SourceName))
		if source == "" {
			return "", "", false
		}
		for _, text := range values {
			if !collectTextIsCommand(text, botName) {
				continue
			}
			canonical := collectCanonicalWhitelistName(bot, source)
			if canonical == "" {
				return "", "", false
			}
			return canonical, text, true
		}
	}
	return "", "", false
}

type collectTextPacketLogEntry struct {
	Time             string   `json:"time"`
	BotID            int      `json:"bot_id"`
	BotName          string   `json:"bot_name"`
	TextType         byte     `json:"text_type"`
	NeedsTranslation bool     `json:"needs_translation"`
	SourceName       string   `json:"source_name"`
	Message          string   `json:"message"`
	Parameters       []string `json:"parameters,omitempty"`
}

type tpaTextPacketLogEntry struct {
	Time             string   `json:"time"`
	BotID            int      `json:"bot_id"`
	BotName          string   `json:"bot_name"`
	TextType         byte     `json:"text_type"`
	NeedsTranslation bool     `json:"needs_translation"`
	SourceName       string   `json:"source_name"`
	Message          string   `json:"message"`
	Parameters       []string `json:"parameters,omitempty"`
	Matched          string   `json:"matched"`
	Respawning       bool     `json:"respawning"`
}

type collectDiagnosticLogEntry struct {
	Time           string `json:"time"`
	Event          string `json:"event"`
	BotID          int    `json:"bot_id"`
	BotName        string `json:"bot_name"`
	Connected      bool   `json:"connected"`
	CollectRunning bool   `json:"collect_running"`
	CollectStatus  string `json:"collect_status,omitempty"`
	CollectError   string `json:"collect_error,omitempty"`
	Detail         string `json:"detail,omitempty"`
}

type collectWirePacketLogEntry struct {
	Time            string `json:"time"`
	BotID           int    `json:"bot_id"`
	BotName         string `json:"bot_name"`
	Direction       string `json:"direction"`
	PacketID        uint32 `json:"packet_id"`
	PacketName      string `json:"packet_name"`
	SenderSubClient byte   `json:"sender_sub_client"`
	TargetSubClient byte   `json:"target_sub_client"`
	Source          string `json:"source,omitempty"`
	Destination     string `json:"destination,omitempty"`
	PayloadLength   int    `json:"payload_length"`
	PayloadBase64   string `json:"payload_base64"`
	Truncated       bool   `json:"truncated,omitempty"`
}

var (
	collectWireLogOnce sync.Once
	collectWireLogCh   = make(chan []byte, 8192)
)

func startCollectDiagnosticWriter() {
	collectDiagnosticLogOnce.Do(func() {
		go func() {
			if err := os.MkdirAll(botDataDir, 0755); err != nil {
				return
			}
			path := filepath.Join(botDataDir, "collect-diagnostics.log")
			f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
			if err != nil {
				return
			}
			defer func() { _ = f.Close() }()
			var size int64
			if info, statErr := f.Stat(); statErr == nil {
				size = info.Size()
			}
			for line := range collectDiagnosticLogCh {
				writeBytes := int64(len(line) + 1)
				if collectDiagnosticNeedsRotation(size, writeBytes) {
					_ = f.Close()
					backupPath := path + ".1"
					_ = os.Remove(backupPath)
					if renameErr := os.Rename(path, backupPath); renameErr != nil {
						// If another scanner briefly prevents a Windows rename, truncating
						// the generated diagnostic is safer than allowing unbounded growth.
						f, err = os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
					} else {
						f, err = os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
					}
					if err != nil {
						return
					}
					size = 0
				}
				n, writeErr := f.Write(append(line, '\n'))
				if writeErr == nil {
					size += int64(n)
				}
			}
		}()
	})
}

const collectDiagnosticMaxBytes int64 = 16 << 20

func collectDiagnosticNeedsRotation(currentSize, nextWrite int64) bool {
	if nextWrite < 0 {
		nextWrite = 0
	}
	return currentSize > 0 && currentSize+nextWrite > collectDiagnosticMaxBytes
}

func logCollectDiagnostic(bot *BotSession, event, detail string) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	entry := collectDiagnosticLogEntry{
		Time:           time.Now().Format(time.RFC3339Nano),
		Event:          strings.TrimSpace(event),
		BotID:          bot.ID,
		BotName:        clean(bot.Name),
		Connected:      bot.Connected,
		CollectRunning: bot.CollectRunning,
		CollectStatus:  bot.CollectStatus,
		CollectError:   bot.CollectLastError,
		Detail:         strings.TrimSpace(detail),
	}
	bot.mu.Unlock()
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	startCollectDiagnosticWriter()
	select {
	case collectDiagnosticLogCh <- line:
	default:
		// Diagnostic I/O must never stall packet reading, collection movement or UI.
	}
}

// logTPATextPacket records only messages already identified as TPA/TPAHERE.
// It avoids logging unrelated chat while preserving the server's exact Text layout.
func logTPATextPacket(bot *BotSession, pk *packet.Text, matched string) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	botID := bot.ID
	botName := bot.Name
	bot.mu.Unlock()
	params := make([]string, 0, len(pk.Parameters))
	for _, param := range pk.Parameters {
		params = append(params, clean(param))
	}
	entry := tpaTextPacketLogEntry{
		Time:             time.Now().Format(time.RFC3339Nano),
		BotID:            botID,
		BotName:          clean(botName),
		TextType:         pk.TextType,
		NeedsTranslation: pk.NeedsTranslation,
		SourceName:       clean(pk.SourceName),
		Message:          clean(pk.Message),
		Parameters:       params,
		Matched:          clean(matched),
		Respawning:       bot.Respawning.Load(),
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	tpaPacketLogMu.Lock()
	defer tpaPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "tpa-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

func logTPAResponse(bot *BotSession, matched, action string, responseErr error) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	botID, botName := bot.ID, bot.Name
	bot.mu.Unlock()
	entry := map[string]any{
		"time":     time.Now().Format(time.RFC3339Nano),
		"event":    "response",
		"bot_id":   botID,
		"bot_name": clean(botName),
		"matched":  clean(matched),
		"action":   strings.TrimSpace(action),
	}
	if responseErr != nil {
		entry["error"] = responseErr.Error()
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	tpaPacketLogMu.Lock()
	defer tpaPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "tpa-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

// logCollectTextPacket writes only packets that contain an actual collect command.
// Keeping the raw fields makes server-specific whisper/translation formats diagnosable
// without logging unrelated player chat.
func logCollectTextPacket(bot *BotSession, pk *packet.Text) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	botID := bot.ID
	botName := bot.Name
	bot.mu.Unlock()
	found := false
	for _, raw := range tpaTextPacketCandidates(pk) {
		candidate := collectCommandTail(raw)
		if _, matched, _ := ParseCollectCommand(candidate, botName); matched {
			found = true
			break
		}
		if _, matched, _ := ParseBedrockActionCommand(candidate, botName); matched {
			found = true
			break
		}
	}
	if !found {
		return
	}
	entry := collectTextPacketLogEntry{
		Time:             time.Now().Format(time.RFC3339Nano),
		BotID:            botID,
		BotName:          clean(botName),
		TextType:         pk.TextType,
		NeedsTranslation: pk.NeedsTranslation,
		SourceName:       clean(pk.SourceName),
		Message:          clean(pk.Message),
		Parameters:       append([]string(nil), pk.Parameters...),
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	collectPacketLogMu.Lock()
	defer collectPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "collect-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

func sendCollectChatReply(bot *BotSession, recipient, message string) {
	if bot == nil {
		return
	}
	recipient = strings.TrimSpace(clean(recipient))
	message = strings.TrimSpace(clean(message))
	if recipient == "" || message == "" {
		return
	}
	bot.mu.Lock()
	conn := bot.conn
	connected := bot.Connected
	bot.mu.Unlock()
	if !connected || conn == nil {
		return
	}
	if err := sendClientMessage(conn, "/m "+recipient+" [背包Bot] "+message); err != nil {
		bot.AddSystemLog("背包指令回覆失敗：" + err.Error())
		return
	}
	if err := conn.Flush(); err != nil {
		bot.AddSystemLog("背包指令回覆送出失敗：" + err.Error())
	}
}

// handleCollectTextPacket reads every field in packet.Text. Some servers put a private
// message in Message, while translated chat formats put the sender/command in Parameters.
func handleCollectTextPacket(bot *BotSession, pk *packet.Text) bool {
	if bot == nil || pk == nil {
		return false
	}
	logCollectTextPacket(bot, pk)
	replyTo, command, authorised := collectWhitelistedTextCommand(bot, pk)
	if !authorised {
		return false
	}
	if handleBedrockActionChatCommand(bot, command, replyTo) {
		bot.AddSystemLog(fmt.Sprintf("已接受白名單控制指令（TextType=%d，發送者=%s）", pk.TextType, replyTo))
		return true
	}
	if handleCollectChatCommand(bot, command, replyTo) {
		bot.AddSystemLog(fmt.Sprintf("已接受白名單背包指令（TextType=%d，發送者=%s）", pk.TextType, replyTo))
		return true
	}
	return false
}

// dropChineseItemAliases 讓遠端 drop/丟 指令可直接使用繁體中文物品名稱。
// 值統一使用 Bedrock item identifier；英文 ID / minecraft:ID 仍照舊可用。
// 這裡同時收常見台灣譯名、玩家常用簡稱與少數同義詞。

// vanillaZhTWTranslationNames comes from Mojang's official Bedrock vanilla
// resource_pack/texts/zh_TW.lang. It is matched against the server's live
// GameData().Items registry at login, so only item IDs that actually exist on
// the connected server are enabled.
var vanillaZhTWTranslationNames = loadStaticStringMap("vanilla_zh_tw.json")

func dropNameWords(value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return nil
	}
	// Split legacy language keys such as muttonCooked and cooked_beef into
	// comparable word sets.
	var b strings.Builder
	var prev rune
	for i, r := range value {
		if i > 0 && unicode.IsUpper(r) && (unicode.IsLower(prev) || unicode.IsDigit(prev)) {
			b.WriteByte('_')
		}
		switch r {
		case '.', ':', '-', '/', '\\', ' ':
			b.WriteByte('_')
		default:
			b.WriteRune(unicode.ToLower(r))
		}
		prev = r
	}
	raw := strings.FieldsFunc(b.String(), func(r rune) bool {
		return r == '_' || r == '.' || r == ':' || r == '-' || r == '/'
	})
	out := make([]string, 0, len(raw))
	for _, word := range raw {
		word = strings.TrimSpace(word)
		switch word {
		case "", "minecraft", "item", "tile", "name":
			continue
		}
		out = append(out, word)
	}
	return out
}

func dropWordsSignature(value string, removeBlock bool) string {
	words := dropNameWords(value)
	if removeBlock {
		filtered := words[:0]
		for _, word := range words {
			if word == "block" {
				continue
			}
			filtered = append(filtered, word)
		}
		words = filtered
	}
	sort.Strings(words)
	return strings.Join(words, "|")
}

func dropCompactName(value string) string {
	words := dropNameWords(value)
	return strings.Join(words, "")
}

func translationBody(key string) string {
	key = strings.TrimSpace(key)
	key = strings.TrimPrefix(key, "item.")
	key = strings.TrimPrefix(key, "tile.")
	key = strings.TrimSuffix(key, ".name")
	return key
}

// addOfficialVanillaZhTWAliases binds Mojang's official Traditional-Chinese
// names to the exact runtime item registry sent by the current Bedrock server.
// It uses several conservative matching passes and only accepts fuzzy matches
// that resolve to exactly one registered item ID.
func normaliseLegacyTranslationWords(words []string) []string {
	if len(words) == 0 {
		return nil
	}

	out := make([]string, 0, len(words)+2)
	for i := 0; i < len(words); i++ {
		word := strings.ToLower(strings.TrimSpace(words[i]))
		if word == "" {
			continue
		}

		// Old Bedrock language keys used "cloth" for wool.
		if word == "cloth" {
			out = append(out, "wool")
			continue
		}

		// Older translation keys used "silver" for what modern IDs call
		// light_gray.
		if word == "silver" {
			out = append(out, "light", "gray")
			continue
		}

		// stained_hardened_clay.* / hardened_clay.* are modern terracotta IDs.
		if word == "stained" && i+2 < len(words) &&
			strings.EqualFold(words[i+1], "hardened") &&
			strings.EqualFold(words[i+2], "clay") {
			out = append(out, "terracotta")
			i += 2
			continue
		}
		if word == "hardened" && i+1 < len(words) &&
			strings.EqualFold(words[i+1], "clay") {
			out = append(out, "terracotta")
			i++
			continue
		}

		// Common old names.
		switch word {
		case "wooden":
			out = append(out, "wood")
		case "reeds":
			out = append(out, "sugar", "cane")
		default:
			out = append(out, word)
		}
	}
	return out
}

func removeLegacyTranslationStateWords(words []string) []string {
	if len(words) == 0 {
		return nil
	}
	out := make([]string, 0, len(words))
	for _, word := range words {
		switch strings.ToLower(strings.TrimSpace(word)) {
		// These are legacy localisation-state suffixes, not item identity.
		case "", "dry", "normal", "default", "plain":
			continue
		default:
			out = append(out, word)
		}
	}
	return out
}

func wordsSignature(words []string, removeBlock bool) string {
	if len(words) == 0 {
		return ""
	}
	copyWords := make([]string, 0, len(words))
	for _, word := range words {
		word = strings.ToLower(strings.TrimSpace(word))
		if word == "" || (removeBlock && word == "block") {
			continue
		}
		copyWords = append(copyWords, word)
	}
	sort.Strings(copyWords)
	return strings.Join(copyWords, "|")
}

func joinWordsUnderscore(words []string) string {
	cleaned := make([]string, 0, len(words))
	for _, word := range words {
		word = strings.ToLower(strings.TrimSpace(word))
		if word != "" {
			cleaned = append(cleaned, word)
		}
	}
	return strings.Join(cleaned, "_")
}

func uniqueRegisteredID(matches []string) (string, bool) {
	seen := map[string]bool{}
	unique := ""
	for _, id := range matches {
		id = strings.ToLower(strings.TrimSpace(id))
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		if unique == "" {
			unique = id
			continue
		}
		if unique != id {
			return "", false
		}
	}
	return unique, unique != ""
}

// legacyTranslationFallbackID bridges old Bedrock localisation keys to the
// modern server item registry. It intentionally accepts only unique matches.
func legacyTranslationFallbackID(
	body string,
	exactShort map[string]string,
	sigIDs map[string][]string,
	reducedSigIDs map[string][]string,
) (string, bool) {
	words := normaliseLegacyTranslationWords(dropNameWords(body))
	if len(words) == 0 {
		return "", false
	}

	trySignature := func(candidate []string) (string, bool) {
		if sig := wordsSignature(candidate, false); sig != "" {
			if id, ok := uniqueRegisteredID(sigIDs[sig]); ok {
				return id, true
			}
		}
		if sig := wordsSignature(candidate, true); sig != "" {
			if id, ok := uniqueRegisteredID(reducedSigIDs[sig]); ok {
				return id, true
			}
		}
		return "", false
	}

	// First normalise legacy vocabulary without dropping any state.
	if id, ok := trySignature(words); ok {
		return id, true
	}

	// "tile.sponge.dry.name" -> minecraft:sponge.
	withoutState := removeLegacyTranslationStateWords(words)
	if id, ok := trySignature(withoutState); ok {
		return id, true
	}
	if direct := joinWordsUnderscore(withoutState); direct != "" {
		if id, ok := exactShort[direct]; ok {
			return id, true
		}
	}

	// Old keys frequently used a family prefix plus the real modern item name:
	// tile.stone.granite.name -> minecraft:granite.
	// Prefer the longest suffix, then longest prefix, and only exact IDs.
	for length := len(withoutState) - 1; length >= 1; length-- {
		suffix := joinWordsUnderscore(withoutState[len(withoutState)-length:])
		if id, ok := exactShort[suffix]; ok {
			return id, true
		}
	}
	for length := len(withoutState) - 1; length >= 1; length-- {
		prefix := joinWordsUnderscore(withoutState[:length])
		if id, ok := exactShort[prefix]; ok {
			return id, true
		}
	}

	// Single-token fallback is only safe if it is itself an exact registered
	// short ID. This catches sponge.dry -> sponge without fuzzy guessing.
	if len(withoutState) > 0 {
		for i := len(withoutState) - 1; i >= 0; i-- {
			token := withoutState[i]
			switch token {
			case "block", "item", "tile", "wood", "stone", "brick", "planks",
				"log", "door", "slab", "stairs", "wall", "fence":
				continue
			}
			if id, ok := exactShort[token]; ok {
				return id, true
			}
		}
	}

	return "", false
}

// addOfficialVanillaZhTWAliases binds Mojang's official Traditional-Chinese
// names to the exact runtime item registry sent by the current Bedrock server.
// It supports both modern keys and older metadata/family-style localisation
// keys, while refusing ambiguous fuzzy matches.
func addOfficialVanillaZhTWAliases(aliases map[string]string, registeredIDs map[string]bool) {
	if aliases == nil || len(registeredIDs) == 0 {
		return
	}

	exactShort := make(map[string]string, len(registeredIDs))
	sigIDs := map[string][]string{}
	reducedSigIDs := map[string][]string{}
	compactIDs := map[string][]string{}

	for id := range registeredIDs {
		id = strings.ToLower(strings.TrimSpace(id))
		if id == "" {
			continue
		}
		short := strings.TrimPrefix(id, "minecraft:")
		exactShort[short] = id
		if sig := dropWordsSignature(short, false); sig != "" {
			sigIDs[sig] = append(sigIDs[sig], id)
		}
		if sig := dropWordsSignature(short, true); sig != "" {
			reducedSigIDs[sig] = append(reducedSigIDs[sig], id)
		}
		if compact := dropCompactName(short); compact != "" {
			compactIDs[compact] = append(compactIDs[compact], id)
		}
	}

	// Pass 1: direct/current IDs.
	for key, zh := range vanillaZhTWTranslationNames {
		body := strings.ToLower(strings.TrimSpace(translationBody(key)))
		if body == "" || zh == "" {
			continue
		}
		if id, ok := exactShort[body]; ok {
			addDropAlias(aliases, zh, id)
			continue
		}
		direct := strings.ReplaceAll(body, ".", "_")
		if id, ok := exactShort[direct]; ok {
			addDropAlias(aliases, zh, id)
			continue
		}
	}

	// Pass 2: token reordering and compact-name matches.
	for key, zh := range vanillaZhTWTranslationNames {
		if zh == "" {
			continue
		}
		if existing := aliases[normaliseDropAliasKey(zh)]; existing != "" {
			continue
		}
		body := translationBody(key)
		if sig := dropWordsSignature(body, false); sig != "" {
			if id, ok := uniqueRegisteredID(sigIDs[sig]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
		if compact := dropCompactName(body); compact != "" {
			if id, ok := uniqueRegisteredID(compactIDs[compact]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
		if sig := dropWordsSignature(body, true); sig != "" {
			if id, ok := uniqueRegisteredID(reducedSigIDs[sig]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
	}

	// Pass 3: bridge old Bedrock localisation vocabulary/metadata keys.
	for key, zh := range vanillaZhTWTranslationNames {
		if zh == "" {
			continue
		}
		if existing := aliases[normaliseDropAliasKey(zh)]; existing != "" {
			continue
		}
		if id, ok := legacyTranslationFallbackID(
			translationBody(key),
			exactShort,
			sigIDs,
			reducedSigIDs,
		); ok {
			addDropAlias(aliases, zh, id)
		}
	}
}

