func suiteCloneLibraryItemToBot(sourceBotID, targetBotID int, itemID string) (suiteLibraryItem, error) {
	if sourceBotID == targetBotID {
		_, item, err := suiteLoadBlueprintArtifact(sourceBotID, itemID)
		return item, err
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	if existing, _ := suiteFindLibraryItemLocked(targetBotID, itemID); existing != nil {
		item := *existing
		suitePortState.Unlock()
		return item, nil
	}
	source, _ := suiteFindLibraryItemLocked(sourceBotID, itemID)
	if source == nil {
		suitePortState.Unlock()
		return suiteLibraryItem{}, errors.New("找不到來源藍圖")
	}
	copyItem := *source
	copyItem.BotID = targetBotID
	copyItem.GroupID = ""
	copyItem.UpdatedAt = time.Now()
	sourceArtifact := filepath.Join(suiteLibraryDir(), source.Artifact)
	targetArtifact := fmt.Sprintf("%s-bot-%d.json.gz", regexp.MustCompile(`[^a-zA-Z0-9_-]+`).ReplaceAllString(itemID, "_"), targetBotID)
	copyItem.Artifact = targetArtifact
	suitePortState.Unlock()
	data, err := os.ReadFile(sourceArtifact)
	if err != nil {
		return suiteLibraryItem{}, err
	}
	if copyItem.SHA256 == "" || copyItem.SizeBytes != int64(len(data)) {
		hash, registerErr := suiteRegisterArtifact(sourceArtifact, "blueprint", "application/gzip", data)
		if registerErr != nil {
			return suiteLibraryItem{}, registerErr
		}
		copyItem.SHA256 = hash
		copyItem.SizeBytes = int64(len(data))
	}
	if err := os.MkdirAll(suiteLibraryDir(), 0755); err != nil {
		return suiteLibraryItem{}, err
	}
	if err := os.WriteFile(filepath.Join(suiteLibraryDir(), targetArtifact), data, 0644); err != nil {
		return suiteLibraryItem{}, err
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	suitePortState.data.Library[targetBotID] = append(suitePortState.data.Library[targetBotID], copyItem)
	err = suiteSavePortStateLocked()
	suitePortState.Unlock()
	if err != nil {
		_ = os.Remove(filepath.Join(suiteLibraryDir(), targetArtifact))
		return suiteLibraryItem{}, err
	}
	return copyItem, nil
}

