func patchDashboardWebViewCompositionV189(html string) string {
	const style = `<style id="app-webview2-composition-v189">
/* WebView2/Chromium can leave a stale black rectangle when a large scrolling
   surface remains promoted because of transform + opacity animations. Keep the
   host GPU path enabled, but do not promote the app shell itself. */
.command-deck,
.bot-rail,
#sidebar,
#view-helpers,
#view-dashboard,
#view-chat,
.main-content,
.workspace{
  animation:none!important;
  transform:none!important;
  will-change:auto!important;
  backface-visibility:visible!important;
}
html.app-pre-reveal .bot-rail,
html.app-pre-reveal #sidebar,
html.app-pre-reveal .command-deck,
html.app-pre-reveal #view-dashboard,
html.app-pre-reveal #view-helpers,
html.app-pre-reveal #view-chat,
html.app-pre-reveal .main-content,
html.app-pre-reveal .workspace{
  transform:none!important;
}
html.app-revealed .bot-rail,
html.app-revealed #sidebar,
html.app-revealed .command-deck,
html.app-revealed #view-dashboard,
html.app-revealed #view-helpers,
html.app-revealed #view-chat,
html.app-revealed .main-content,
html.app-revealed .workspace{
  transform:none!important;
  transition:opacity .12s ease-out!important;
}
</style>`
	const script = `<script id="app-webview2-repaint-v189">
(function(){
  let raf=0;
  function repaintShell(){
    if(raf) cancelAnimationFrame(raf);
    raf=requestAnimationFrame(function(){
      raf=requestAnimationFrame(function(){
        raf=0;
        try{
          const body=document.body;
          const root=document.documentElement;
          if(body) void body.offsetHeight;
          if(root) void root.offsetHeight;
        }catch(e){}
      });
    });
  }
  window.addEventListener('resize',repaintShell,{passive:true});
  window.addEventListener('pageshow',repaintShell,{passive:true});
  document.addEventListener('visibilitychange',function(){if(!document.hidden)repaintShell();});
})();
</script>`
	if strings.Contains(html, `id="app-webview2-composition-v189"`) {
		return html
	}
	return strings.Replace(html, "</head>", style+script+"</head>", 1)
}

