func patchDashboardFullAuditV193(html string) string {
	const script = `<script id="app-full-audit-v193">
(function(){
  'use strict';
  function byId(id){ return document.getElementById(id); }

  // 更新器在 Go build 階段顯示「編譯中」與後端 heartbeat，不再把 48/49
  // 這種經過秒數誤認成真實完成百分比。
  function patchUpdateProgress(){
    if(typeof window.setInlineUpdateProgress!=='function' || window.setInlineUpdateProgress.v193) return;
    var original=window.setInlineUpdateProgress;
    var wrapped=function(value,title,isError){
      original(value,title,isError);
      var t=String(title||'');
      var building=!isError && /編譯|Go 編譯器|建立新版 App/.test(t) && !/完成|失敗|驗證/.test(t);
      var box=byId('inline-update-progress');
      var pct=byId('inline-update-percent');
      if(box) box.classList.toggle('building',building);
      if(pct && building) pct.textContent='編譯中';
    };
    wrapped.v193=true;
    window.setInlineUpdateProgress=wrapped;
  }

  // 舊小幫手表單控制已從目前版面移除，但舊函式仍可能被快捷操作或舊狀態呼叫。
  // 不讓不存在的 DOM id 造成整條 update() / click handler 中斷。
  function patchLegacyHelperGuards(){
    if(typeof window.saveFormPaths==='function' && !window.saveFormPaths.v193){
      var oldSave=window.saveFormPaths;
      var safeSave=function(){
        if(!byId('form-paths') || !byId('form-opencmd') || !byId('form-loopsec') || !byId('form-escsec')){
          return Promise.resolve(false);
        }
        return oldSave.apply(this,arguments);
      };
      safeSave.v193=true;
      window.saveFormPaths=safeSave;
    }
    if(typeof window.manualOpen==='function' && !window.manualOpen.v193){
      var oldOpen=window.manualOpen;
      var safeOpen=function(){
        if(!byId('form-opencmd')) return Promise.resolve(false);
        return oldOpen.apply(this,arguments);
      };
      safeOpen.v193=true;
      window.manualOpen=safeOpen;
    }
  }

  // V200：若未來有人改 Dashboard 組裝時誤刪手動更新卡，直接在既有設定頁
  // 原位復原唯一一張卡；不建立 overlay、不阻擋其他按鈕。
  function ensureManualUpdateCardV200(){
    var card=byId('settings-main-update-card'),file=byId('main-go-file'),confirm=byId('confirm-main-update');
    if(card&&file&&confirm)return true;
    if(card)card.remove();
    var view=byId('view-app-settings');if(!view)return false;
    var host=view.querySelector('.ui-settings-grid-full,.settings-grid,.surface-grid')||view;
    card=document.createElement('div');card.id='settings-main-update-card';card.className='surface';
    card.innerHTML='<div class="surface-title"><strong>手動更新 main.go / 介面資源</strong><small>只在你主動選檔後套用</small></div><div class="setting-row"><input id="main-go-file" type="file" accept=".go,text/plain"><button id="confirm-main-update" type="button" class="action primary">套用 main.go</button></div><div id="main-go-stage-status" class="ui-settings-note">尚未選擇 main.go</div>';
    host.appendChild(card);
    file=byId('main-go-file');confirm=byId('confirm-main-update');
    if(file)file.onchange=function(){if(typeof window.stageMainSource==='function')window.stageMainSource(file);};
    if(confirm)confirm.onclick=function(){if(typeof window.confirmMainSourceUpdate==='function')window.confirmMainSourceUpdate();};
    return !!(card&&file&&confirm);
  }

  // 無副作用的 runtime 結構檢查。它只回報與 console 診斷，不建立阻擋層。
  window.appRuntimeAuditV193=function(){
    var main=byId('main');
    var requiredViews=['view-dashboard','view-suite-dashboard','view-helpers','view-helper-automation','view-inventory','view-chat','view-settings','view-app-settings','view-suite-build','view-suite-explosion','view-suite-tasks','view-suite-creator','view-suite-gallery','view-suite-maps','view-suite-history','view-suite-toolbox','view-mapart','view-debug','view-whitelist','view-automation'];
    var requiredIds=['settings-main-update-card','main-go-file','confirm-main-update','schedule-bot-select','cron1-sec','cron1-max','cron1-cmd','cron1-start-btn','cron1-stop-btn','cron2-sec','cron2-max','cron2-cmd','cron2-start-btn','cron2-stop-btn','v159-processing-card','v159-process-start','v159-process-stop','v183-transfer-main','v183-start','v183-stop'];
    var requiredFns=['switchUIPage','selectBot','startCron','stopCron','stageMainSource','confirmMainSourceUpdate','refreshInventorySnapshot'];
    var missingViews=requiredViews.filter(function(id){var n=byId(id);return !n||!main||n.parentElement!==main;});
    var missingIds=requiredIds.filter(function(id){return !byId(id);});
    var missingFns=requiredFns.filter(function(name){return typeof window[name]!=='function';});
    var duplicate=[],seen=Object.create(null);document.querySelectorAll('[id]').forEach(function(node){var id=node.id;if(seen[id])duplicate.push(id);else seen[id]=1;});
    var navBroken=[];document.querySelectorAll('.ui-nav-btn[data-ui-view]').forEach(function(btn){var id=btn.getAttribute('data-ui-view');var target=id&&byId(id);if(!target||!main||target.parentElement!==main)navBroken.push(id||'(empty)');});
    var handlerBroken=[];['v159-process-start','v159-process-stop','v183-start','v183-stop','confirm-main-update'].forEach(function(id){var node=byId(id);if(node&&typeof node.onclick!=='function'&&!node.getAttribute('onclick'))handlerBroken.push(id);});
    var blocking=[];document.querySelectorAll('.modal-shade.open,.modal.open,.overlay.open,.update-shade.open,[data-blocking="true"]').forEach(function(node){var cs=null;try{cs=getComputedStyle(node);}catch(e){}if(!node.hidden&&(!cs||cs.display!=='none')&&(!cs||cs.visibility!=='hidden'))blocking.push(node.id||node.className||node.tagName);});
    var scheduleSelect=byId('schedule-bot-select');var scheduleTargetValid=!!(scheduleSelect&&scheduleSelect.value&&Array.from(scheduleSelect.options||[]).some(function(o){return o.value===scheduleSelect.value;}));
    return {ok:missingViews.length===0&&missingIds.length===0&&missingFns.length===0&&duplicate.length===0&&navBroken.length===0&&handlerBroken.length===0&&blocking.length===0&&scheduleTargetValid,missingViews:missingViews,missingIds:missingIds,missingFns:missingFns,duplicate:duplicate,navBroken:navBroken,handlerBroken:handlerBroken,blocking:blocking,scheduleTargetValid:scheduleTargetValid};
  };

  function boot(){
    patchUpdateProgress();
    patchLegacyHelperGuards();
    ensureManualUpdateCardV200();
    // V159/V183 同樣在 DOMContentLoaded 安裝；排到下一個 task 再驗，避免把載入順序誤報成缺頁。
    setTimeout(function(){try{var result=window.appRuntimeAuditV193();if(!result.ok){console.error('App runtime audit v200',result);if(typeof window.setDebugMessage==='function')window.setDebugMessage('UI 結構檢查發現異常，請看 Debug / console');}}catch(e){console.error('App runtime audit v200 failed',e);}},0);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true});
  else boot();
})();
</script>`
	if strings.Contains(html, `id="app-full-audit-v193"`) {
		return html
	}
	return strings.Replace(html, "</body>", script+"</body>", 1)
}

