	const script = `<script id="discord-webhook-v414-script">
(function(){
'use strict';
var selectedBot=0,loading=false,botSnapshot={},applying=false,saveTimer=0,saveSeq=0;
var eventRows=[
 ['bot_online','BOT 上線'],['bot_offline','BOT 斷線'],['bot_reconnected','BOT 重連'],
 ['processing_complete','加工一盒完成'],['processing_failed','加工失敗'],
 ['transfer_complete','搬運完成'],['transfer_failed','搬運失敗'],
 ['schedule_run','排程執行'],['task_complete','任務完成'],['task_failed','任務錯誤']
];
function currentBotID(){try{if(typeof window.suiteCurrentBotID==='function')return Number(window.suiteCurrentBotID())||1;}catch(_){}var n=Number(window.sid||1);return n>0?n:1;}
function botID(){return selectedBot>0?selectedBot:currentBotID();}
function esc(v){return String(v??'').replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function toast(msg,bad){try{if(typeof window.showToast==='function'){window.showToast(msg,!!bad);return;}}catch(_){}if(bad)console.error(msg);else console.log(msg);}
function card(){return document.getElementById('discord-webhook-card');}
function botName(id){var b=botSnapshot&&botSnapshot[id];return String(b&&b.name||('BOT '+id));}
function looksLikeWebhook(v){v=String(v||'').trim();return /^https:\/\/(?:www\.|canary\.|ptb\.)?(?:discord(?:app)?\.com)\/api\/webhooks\/[^\/\s]+\/[^\/\s?#]+(?:\?[^#\s]*)?$/i.test(v);}
function setStatus(msg,bad){var st=document.getElementById('discord-webhook-status');if(!st)return;st.textContent=String(msg||'');st.style.color=bad?'#fca5a5':'';}
function updateEventCount(){
 var total=0,on=0;document.querySelectorAll('#discord-webhook-events [data-discord-event]').forEach(function(x){total++;if(x.checked)on++;});
 var out=document.getElementById('discord-webhook-event-count');if(out)out.textContent='已選 '+on+'/'+total;
}
function renderBotPicker(){
 var grid=document.getElementById('discord-webhook-bots');if(!grid)return;var rows=[];
 for(var id=1;id<=4;id++){
  var b=botSnapshot&&botSnapshot[id]||{},active=id===botID(),online=!!b.connected,name=String(b.name||('BOT '+id));
  rows.push('<button type="button" class="ui-discord-bot'+(active?' active':'')+'" data-discord-bot="'+id+'" title="'+esc(name)+'">'+
   '<strong>'+esc(name)+'</strong><small><i class="ui-discord-dot'+(online?' online':'')+'"></i>'+(online?'已連線':'未連線')+'</small></button>');
 }
 grid.innerHTML=rows.join('');
}
async function refreshBotPicker(){
 try{var r=await fetch('/api/status?selected='+encodeURIComponent(String(botID())),{cache:'no-store'});if(!r.ok)return;var data=await r.json();botSnapshot=data||{};renderBotPicker();}catch(_){}
}
function collectEvents(){var out={};document.querySelectorAll('#discord-webhook-events [data-discord-event]').forEach(function(x){out[x.getAttribute('data-discord-event')]=!!x.checked;});return out;}
async function post(action,idOverride){
 var id=Number(idOverride||botID()),url=document.getElementById('discord-webhook-url'),enabled=document.getElementById('discord-webhook-enabled');
 var body={action:action,url:String(url&&url.value||'').trim(),enabled:!!(enabled&&enabled.checked),events:collectEvents()};
 var r=await fetch('/api/discord-webhook?id='+encodeURIComponent(String(id)),{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
 var j=await r.json().catch(function(){return{};});if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j;
}
async function autoSaveNow(showError){
 if(applying||!card())return true;clearTimeout(saveTimer);saveTimer=0;
 var id=botID(),url=document.getElementById('discord-webhook-url'),typed=String(url&&url.value||'').trim();
 if(typed&&!looksLikeWebhook(typed)){setStatus('Webhook URL 尚未輸入完整',false);return false;}
 var seq=++saveSeq;setStatus('自動儲存中…',false);
 try{var j=await post('save',id);if(seq!==saveSeq)return true;if(url&&typed)url.value='';apply(j,id,true);setStatus((j.enabled?'已啟用 · ':'已停用 · ')+String(j.masked_url||'尚未設定 Webhook')+' · 已自動儲存',false);return true;}
 catch(e){if(seq!==saveSeq)return false;setStatus('自動儲存失敗：'+String(e&&e.message||e),true);if(showError)toast('Discord 自動儲存失敗：'+String(e&&e.message||e),true);return false;}
}
function scheduleAutoSave(delay,showError){
 if(applying)return;clearTimeout(saveTimer);saveTimer=setTimeout(function(){autoSaveNow(!!showError);},Math.max(80,Number(delay)||120));
}
function apply(data,id,preserveURL){
 applying=true;
 try{
  var label=document.getElementById('discord-webhook-bot-label'),selected=document.getElementById('discord-webhook-selected-name'),status=document.getElementById('discord-webhook-status'),enabled=document.getElementById('discord-webhook-enabled'),url=document.getElementById('discord-webhook-url');
  if(label)label.textContent='全部 BOT 共用 Webhook';if(selected)selected.textContent=botName(id);if(enabled)enabled.checked=!!data.enabled;
  if(url&&!preserveURL&&document.activeElement!==url){url.value='';url.placeholder=data.configured?'全部 BOT 已共用：'+String(data.masked_url||'Webhook 已設定'):'貼上一次，全部 BOT 共用';}
  if(status)status.textContent=data.configured?((data.enabled?'已啟用 · ':'已停用 · ')+String(data.masked_url||'URL 已隱藏')+' · 自動儲存'):'尚未設定共用 Webhook · 自動儲存';
  var events=data.events||{};document.querySelectorAll('#discord-webhook-events [data-discord-event]').forEach(function(x){var k=x.getAttribute('data-discord-event');x.checked=events[k]!==false;});
  updateEventCount();renderBotPicker();
 }finally{applying=false;}
}
async function load(force){
 install();if(!card()||loading)return;var id=botID();loading=true;
 try{var r=await fetch('/api/discord-webhook?id='+encodeURIComponent(String(id)),{cache:'no-store'});var j=await r.json().catch(function(){return{};});if(!r.ok)throw new Error(j.error||('HTTP '+r.status));if(id===botID())apply(j,id,false);}
 catch(e){setStatus('讀取失敗：'+String(e&&e.message||e),true);}finally{loading=false;}
}
function install(){
 if(card())return;var wl=document.querySelector('#view-settings .ui-whitelist-setting-card');if(!wl)return;var grid=wl.closest('.ui-robot-settings-grid');if(!grid)return;
 var stack=grid.querySelector('.ui-settings-right-stack');if(!stack){stack=document.createElement('div');stack.className='ui-settings-right-stack';wl.insertAdjacentElement('beforebegin',stack);stack.appendChild(wl);}
 selectedBot=currentBotID();var el=document.createElement('div');el.id='discord-webhook-card';el.className='surface ui-setting-card ui-discord-setting-card';
 el.innerHTML='<div class="surface-title"><strong>Discord 通知</strong><small id="discord-webhook-bot-label">全部 BOT 共用 Webhook</small></div>'+
 '<p>Webhook URL 只要輸入一次，BOT 1～4 全部共用；下方選 BOT 只調整該 BOT 要不要通知與通知事件。修改後會自動儲存。</p>'+
 '<label class="ui-discord-field"><small>共用 Webhook URL</small><input id="discord-webhook-url" type="password" autocomplete="off" spellcheck="false" placeholder="貼上一次，全部 BOT 共用"></label>'+
 '<div class="ui-discord-bot-head"><small>通知設定 BOT</small><small id="discord-webhook-selected-name">—</small></div>'+
 '<div id="discord-webhook-bots" class="ui-discord-bot-grid"></div>'+
 '<div class="ui-discord-state-row"><label class="ui-discord-toggle"><input id="discord-webhook-enabled" type="checkbox"><span>啟用這隻 BOT 的 Discord 通知</span></label><div id="discord-webhook-status" class="ui-discord-status">讀取設定中...</div></div>'+
 '<details class="ui-discord-advanced"><summary><span>通知事件</span><small id="discord-webhook-event-count" class="ui-discord-event-count">已選 0/0</small></summary>'+
 '<div id="discord-webhook-events" class="ui-discord-event-grid">'+eventRows.map(function(r){return '<label class="ui-discord-event"><input type="checkbox" data-discord-event="'+esc(r[0])+'"><span>'+esc(r[1])+'</span></label>';}).join('')+'</div></details>'+
 '<div class="ui-discord-actions"><button class="action discord-test" type="button" onclick="discordTestWebhookV414()">送出測試通知</button><button class="action ui-discord-remove" type="button" onclick="discordClearWebhookV414()">清除共用 Webhook</button></div>';
 stack.appendChild(el);
 el.addEventListener('click',async function(ev){var btn=ev.target&&ev.target.closest?ev.target.closest('[data-discord-bot]'):null;if(!btn)return;var id=Number(btn.getAttribute('data-discord-bot')||0);if(id<1||id>4||id===botID())return;await autoSaveNow(false);selectedBot=id;renderBotPicker();load(true);});
 el.addEventListener('input',function(ev){if(ev.target&&ev.target.id==='discord-webhook-url'){var v=String(ev.target.value||'').trim();if(!v){setStatus('輸入新的 Webhook URL 後會自動套用全部 BOT',false);return;}if(looksLikeWebhook(v))scheduleAutoSave(650,true);else setStatus('Webhook URL 尚未輸入完整',false);}});
 el.addEventListener('change',function(ev){if(applying)return;var t=ev.target;if(!t)return;if(t.id==='discord-webhook-url'){var v=String(t.value||'').trim();if(v&&looksLikeWebhook(v))scheduleAutoSave(80,true);return;}if(t.id==='discord-webhook-enabled'||(t.hasAttribute&&t.hasAttribute('data-discord-event'))){updateEventCount();scheduleAutoSave(100,true);}});
 el.addEventListener('focusout',function(ev){if(ev.target&&ev.target.id==='discord-webhook-url'){var v=String(ev.target.value||'').trim();if(v&&looksLikeWebhook(v))scheduleAutoSave(80,true);}});
 refreshBotPicker();load(true);
}
window.discordSaveWebhookV414=function(){return autoSaveNow(true);};
window.discordTestWebhookV414=async function(){try{await autoSaveNow(true);var j=await post('test');toast(String(j.message||'測試通知已送出'));await load(true);}catch(e){toast('Discord 測試失敗：'+String(e&&e.message||e),true);}};
window.discordClearWebhookV414=async function(){try{if(!confirm('確定清除全部 BOT 共用的 Discord Webhook？清除後所有 BOT 通知都會停用。'))return;clearTimeout(saveTimer);var j=await post('clear');var url=document.getElementById('discord-webhook-url');if(url)url.value='';toast('共用 Discord Webhook 已清除');apply(j,botID(),false);}catch(e){toast('清除失敗：'+String(e&&e.message||e),true);}};
function boot(){install();setInterval(refreshBotPicker,4000);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else setTimeout(boot,0);
})();
</script>`
